window.MAP_DATA_RECORDS.push(...[{"i":"R765","hd":"AI sexuality recognition lgbtq coda story","pd":"2023-07-22","k":"Switzerland","p":"Switzerland","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Ai sexuality recognition lgbtq coda story","s":"Swiss psychiatrists say their AI deep learning model can tell if your brain is gay or straight. AI experts say that’s impossible. Between autonomous police dog robots, facial recognition cameras that let you pay for groceries with your smile and bots that can write Wordsworthian sonnets in the style of Taylor Swift, it is beginning to feel like AI can do just about anything. This week, a new capability has been added to the list: A group of researchers in Switzerland say they’ve developed an AI model that can tell if you’re gay or straight. The group has built a deep learning AI model that they say, in their peer-reviewed paper, can detect the sexual orientation of cisgender men.","u":"https://www.rappler.com/technology/features/ai-sexuality-recognition-lgbtq-coda-story/","d":"2023-07-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-07-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-07-22","organization":"Group of researchers in Switzerland","aiSystem":"Deep learning AI model","affectedGroup":"Cisgender men","action":"Detect the sexual orientation of cisgender men","consequence":"Potential misuse for discriminatory purposes"}},{"i":"R551","hd":"AI assistants errors news research","pd":"2025-10-22","k":"Switzerland","p":"Switzerland","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Ai assistants errors news research","s":"The international research studies 3,000 responses to questions about the news from leading artificial intelligence assistants. GENEVA, Switzerland – Leading AI assistants misrepresent news content in nearly half their responses, according to new research published on Wednesday, October 22, by the European Broadcasting Union (EBU) and the BBC. The international research studied 3,000 responses to questions about the news from leading artificial intelligence assistants — software applications that use AI to understand natural language commands to complete tasks for a user. It assessed AI assistants in 14 languages for accuracy, sourcing, and ability to distinguish opinion versus fact, including ChatGPT, Copilot, Gemini and Perplexity.","u":"https://www.rappler.com/technology/ai-assistants-errors-news-research/","d":"2025-10-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-22","organization":"European Broadcasting Union (EBU) and the BBC","aiSystem":"Leading artificial intelligence assistants","affectedGroup":"Users of leading AI assistants","action":"Misrepresent news content in nearly half their responses","consequence":"Inaccurate information provided to users"}},{"i":"R582","hd":"United nations report urges stronger measures detect AI driven deepfakes","pd":"2025-07-13","k":"Switzerland","p":"Switzerland","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"United nations report urges stronger measures detect ai driven deepfakes","s":"Deepfakes such as AI-generated images and videos, and audio that convincingly impersonates real people, pose mounting risks, the ITU says in a report released at its AI for Good Summit in Geneva. GENEVA, Switzerland – Companies must use advanced tools to detect and stamp out misinformation and deepfake content to help counter growing risks of election interference and financial fraud, the United Nations’ International Telecommunication Union urged in a report on Friday, July 11. Deepfakes such as AI-generated images and videos, and audio that convincingly impersonates real people, pose mounting risks, the ITU said in the report released at its “AI for Good Summit” in Geneva.","u":"https://www.rappler.com/technology/united-nations-report-urges-stronger-measures-detect-ai-driven-deepfakes/","d":"2025-07-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-11","organization":"United Nations' International Telecommunication Union (ITU)","aiSystem":"Advanced detection and stamping tools","affectedGroup":"Companies, Election Interference, Financial Fraud","action":"Use advanced tools to detect and stamp out misinformation and deepfake content","consequence":"Growing risks of election interference and financial fraud"}},{"i":"R606","hd":"Companies global indirect emissions united nations itu report 2025","pd":"2025-06-05","k":"Switzerland","p":"Switzerland","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Companies global indirect emissions united nations itu report 2025","s":"The UN’s International Telecommunication Union tracks the greenhouse gas emissions of 200 leading digital companies between 2020 and 2023. GENEVA, Switzerland – Indirect carbon emissions from the operations of four of the leading AI-focused tech companies rose on average by 150% from 2020-2023, due to the demands of power-hungry data centers, a United Nations report said on Thursday, June 5. The use of artificial intelligence by Amazon, Microsoft, Alphabet, and Meta drove up their global indirect emissions because of the vast amounts of energy required to power data centres, the report by the International Telecommunication Union (ITU), the UN agency for digital technologies, said.","u":"https://www.rappler.com/technology/companies-global-indirect-emissions-united-nations-itu-report-2025/","d":"2025-06-05","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-05","organization":"International Telecommunication Union (ITU)","aiSystem":"Artificial Intelligence systems used by Amazon, Microsoft, Alphabet, and Meta","affectedGroup":"Global society","action":"Use of AI systems by Amazon, Microsoft, Alphabet, and Meta","consequence":"Rising indirect carbon emissions from data centers"}},{"i":"R996","hd":"AI chatbots secretly ran a mind control experiment on reddit","pd":"2025-05-05","k":"Switzerland","p":"Switzerland","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Ai chatbots secretly ran a mind control experiment on reddit","s":"Reddit users are pissed—and rightfully so. A group of AI researchers from the University of Zurich just got caught running an unauthorized psychological experiment on r/ChangeMyView, one of the site’s biggest debate communities, and no one who participated had any idea it was happening. The experiment involved AI chatbots posing as regular users to see […]. The experiment involved AI chatbots posing as regular users to see if they could subtly sway opinions on hot-button topics. These weren’t bland comment bots posting generic takes. They were tailored personas—one claimed to be a male rape victim minimizing his trauma, another said women raised by protective parents were more vulnerable to domestic violence, and a third posed as a Black man against Black Lives Matter.","u":"https://www.vice.com/en/article/ai-chatbots-secretly-ran-a-mind-control-experiment-on-reddit/","d":"2025-05-05","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-05-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-05-05","organization":"University of Zurich","aiSystem":"AI chatbots","affectedGroup":"Reddit users, particularly those participating in r/ChangeMyView","action":"AI chatbots posing as regular users to subtly sway opinions on hot-button topics","consequence":"Participants' opinions were subtly influenced without their awareness"}},{"i":"R2045","hd":"Mps question UK palantir contracts security concerns investigation","pd":"2025-12-22","k":"Switzerland","p":"Switzerland","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Mps question uk palantir contracts security concerns investigation","s":"Journalists find Swiss government rejected company over fears US intelligence might gain access to sensitive data. UK MPs have raised concerns about the government’s contracts with Palantir after an investigation published in Switzerland highlighted allegations about the suitability and security of its products. The investigation by the Zurich-based research collective WAV and the Swiss online magazine Republik details Palantir’s efforts, over the course of seven years, to sell its products to Swiss federal agencies. Palantir is a US company that provides software to integrate and analyse data scattered across different systems, such as in the health service.","u":"https://www.theguardian.com/technology/2025/dec/22/mps-question-uk-palantir-contracts-security-concerns-investigation","d":"2025-12-22","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-22","organization":"Swiss government, Palantir","aiSystem":"Palantir","affectedGroup":"Swiss federal agencies","action":"Rejected Palantir's products","consequence":"Raised security concerns"}},{"i":"R2690","hd":"Microsoft AI copilot algorithm watch bing election misinformation","pd":"2023-12-15","k":"Switzerland","p":"Switzerland","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Microsoft ai copilot algorithm watch bing election misinformation","s":"Bing created fake allegations or incorrect information about German and Swiss elections, researchers from AlgorithmWatch said. Researchers found Microsoft’s chatbot on Copilot provided false and misleading information about European elections. Human rights organization AlgorithmWatch said in a report that it asked Bing Chat — recently rebranded as Copilot — questions about recent elections held in Switzerland and the German states of Bavaria and Hesse. It found that one-third of its answers to election-related questions had factual errors and safeguards were not evenly applied. The group said it collected responses from Bing from August to October this year.","u":"https://www.theverge.com/2023/12/15/24003248/microsoft-ai-copilot-algorithm-watch-bing-election-misinformation","d":"2023-12-15","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-12-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"August to October 2023","organization":"AlgorithmWatch","aiSystem":"Microsoft's Bing chatbot (rebranded as Copilot)","affectedGroup":"People seeking information about recent elections in Switzerland and German states of Bavaria and Hesse","action":"Provided false and misleading information about European elections","consequence":"Collected responses containing factual errors and uneven application of safeguards"}},{"i":"R625","hd":"Taiwan says china using generative AI disinformation public division","pd":"2025-04-08","k":"Taiwan","p":"Taiwan","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Taiwan says china using generative ai disinformation public division","s":"Taiwan has accused China of stepping up military drills, trade sanctions and influence campaigns against the island in recent years to force the island to accept Chinese sovereignty claims. TAIPEI, Taiwan – China is using generative artificial intelligence (AI) to ramp up disinformation against Taiwan to “divide” Taiwan’s public, the island’s National Security Bureau said. Taiwan strongly rejects China’s sovereignty claims. China staged two days of war games and live-fire drills near the democratically governed island this month, triggering concern by the United States and many of its allies. In a report to parliament, a copy of which was reviewed by Reuters, the security bureau said it had detected more than half a million pieces of “controversial messages” so far this year, mostly seen on social media platforms including Facebook and TikTok.","u":"https://www.rappler.com/technology/taiwan-says-china-using-generative-ai-disinformation-public-division/","d":"2025-04-08","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-04-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-04-08","organization":"China","aiSystem":"Generative artificial intelligence (AI)","affectedGroup":"Taiwanese public","action":"Using generative AI to create and spread controversial messages","consequence":"Dividing Taiwan's public opinion and undermining Taiwan's sovereignty claims"}},{"i":"R1406","hd":"World asia 67891869","pd":"2024-01-08","k":"Taiwan","p":"Taiwan","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"World asia 67891869","s":"Beijing is pushing \"US scepticism\" to drive a wedge between Taiwan and its biggest ally, say analysts. The rumour was old, but effective: the Taiwanese were being fed \"poisonous\" pork imported from the US. The weeks-old claim followed another: the Taiwanese government was secretly harvesting blood from citizens and giving it to the US to make a bioweapon to attack China. But this is a narrative that has been blooming in Taiwan ahead of Saturday's presidential and legislative elections. \"Yimeilun\" or US scepticism, questions the faithfulness of Taiwan's biggest ally, portraying the island as a pawn exploited by America.","u":"https://www.bbc.com/news/world-asia-67891869","d":"2024-01-08","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-08","organization":"Taiwanese government","aiSystem":"Not specified in report","affectedGroup":"Taiwanese citizens","action":"harvesting blood","consequence":"exploitation, potential bioweapon development"}},{"i":"R1463","hd":"Koreas coupang promotes passkeys in taiwan faces possible 1bn fine for data leak","pd":"2025-12-03","k":"Taiwan","p":"Taiwan","b":["Data"],"h":["4.1  Privacy violation"],"t":"Koreas coupang promotes passkeys in taiwan faces possible 1bn fine for data leak","s":"Coupang wants to grow the adoption of passkeys in Taiwan, viewing the market as a strategic hub, even as it stares down the prospect of a $1 billion fine. Coupang wants to grow the adoption of passkeys in Taiwan, viewing the market as a strategic hub, even as it stares down the prospect of a $1 billion fine over data leaks. The Korean company has been actively promoting passkeys in Taiwan, with the biometric-enabled authentication method seen as more secure than traditional passwords. Coupang independently developed and distributed a passkey technology, which fulfils global standards, in Taiwan, according to a Chosun Biz report It received recognition by Taiwan officials while Coupang targets growth in the market, which it entered in 2022.","u":"https://www.biometricupdate.com/202512/koreas-coupang-promotes-passkeys-in-taiwan-faces-possible-1bn-fine-for-data-leak","d":"2025-12-03","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-03","organization":"Coupang","aiSystem":"passkey technology","affectedGroup":"Taiwanese citizens","action":"actively promoted passkey technology","consequence":"receives recognition by Taiwan officials"}},{"i":"R1828","hd":"Students cheap labour powers taiwans semiconductor factories","pd":"2025-02-26","k":"Taiwan","p":"Taiwan","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Students cheap labour powers taiwans semiconductor factories","s":"The country, which makes over 60% of the world’s chips, is filling worker gaps with youngsters from Southeast Asian countries in ‘study-work’ programmes. This article was originally published in Rest of World, which covers technology’s impact outside the West. Before Dang Nhut Hao came to Taiwan, he knew nothing about semiconductors. Growing up in Dong Thap – a southern Vietnamese province on the Mekong Delta famous for its rice fields, red-headed cranes and lakes dotted with lotuses – Dang loved biology, and got into one of Ho Chi Minh City’s most prestigious undergraduate science programmes in 2019. But his family couldn’t afford the tuition.","u":"https://scroll.in/article/1079283/students-cheap-labour-powers-taiwans-semiconductor-factories","d":"2025-02-26","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-02-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-02-26","organization":"Not specified in report","aiSystem":"Not specified in report","affectedGroup":"Young people aged 18–21 from Southeast Asian countries","action":"Engaged in study-work programs to fill worker gaps in semiconductor factories","consequence":"Exposed to exploitative conditions and low wages"}},{"i":"R1299","hd":"After anti woke backlash googles gemini faces heat over china taboos","pd":"2024-02-23","k":"Taiwan","p":"Taiwan","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"After anti woke backlash googles gemini faces heat over china taboos","s":"Gemini users report refusal to show images of the 1989 Tiananmen Square massacre and Hong Kong pro-democracy protests. Taipei, Taiwan – As Google finds itself embroiled in an anti-“woke” backlash over AI model Gemini’s reluctance to depict white people, the tech giant is facing further criticism over the chatbot’s handling of sensitive topics in China. Gemini users reported this week that the update to Google Bard failed to generate representative images when asked to produce depictions of events such as the 1989 Tiananmen Square massacre and the 2019 pro-democracy protests in Hong Kong. On Thursday, X user Yacine, a former software engineer at Stripe, posted a screenshot of Gemini telling a user it could not generate “an image of a man in 1989 Tiananmen Square” – a prompt alluding to the iconic image of a protester blocking the path of a Chinese tank – due to its “safety policy”.","u":"https://www.aljazeera.com/economy/2024/2/23/after-anti-woke-backlash-googles-gemini-faces-heat-over-china-taboos","d":"2024-02-23","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-02-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-02-23","organization":"Google","aiSystem":"Gemini","affectedGroup":"Users of Gemini","action":"Refusal to generate images","consequence":"Restriction on sensitive content"}},{"i":"R1494","hd":"Thai authorities warn over use of worlds iris biometric scanners","pd":"2025-08-28","k":"Thailand","p":"Thailand","b":["Data"],"h":["4.1  Privacy violation"],"t":"Thai authorities warn over use of worlds iris biometric scanners","s":"A countrywide alert has been issued for local officials to raise public awareness and monitor sensitive biometric data collection activities to prevent fraud. Local authorities in Thailand have been put on notice to monitor the use of World ’s iris biometric scanning Orbs. Thailand’s Department of Provincial Administration has issued a countrywide alert for local officials to raise public awareness and monitor sensitive biometric data collection activities to prevent fraud. World’s local affiliate, Tools for Humanity Thailand, has partnered with 11 Thai partners, including state-owned National Telecom, to promote human verification services.","u":"https://www.biometricupdate.com/202508/thai-authorities-warn-over-use-of-worlds-iris-biometric-scanners","d":"2025-08-28","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-28","organization":"Local authorities in Thailand, Thailand's Department of Provincial Administration, Tools for Humanity Thailand, and state-owned National Telecom","aiSystem":"World's iris biometric scanning Orbs","affectedGroup":"People whose biometric data is collected","action":"Monitor and collect sensitive biometric data","consequence":"Potential fraud prevention and increased surveillance"}},{"i":"R1579","hd":"Thai government to collect iris and face biometrics from myanmar nationals","pd":"2024-05-08","k":"Thailand","p":"Thailand","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Thai government to collect iris and face biometrics from myanmar nationals","s":"Thailand has launched a program to collect the iris and face biometrics of people from Myanmar, in what the government says is an attempt to streamline health services for Thailand’s most mobile population. But given the dynamics at play in both politics and power, the initiative has raised flags among rights groups, who see a potential threat to privacy and human rights. According to a report fro. m Radio Free Asia, 10,000 Myanmar nationals have already had their biometric data collected as part of the program. The campaign is being led by Thailand’s Department of Disease Control, and its stated core mission is to get a better handle on the allocation and administration of vaccine doses for the transient.","u":"https://www.biometricupdate.com/202405/thai-government-to-collect-iris-and-face-biometrics-from-myanmar-nationals","d":"2024-05-08","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-05-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-05-08","organization":"Thailand's Department of Disease Control","aiSystem":"Biometric collection system","affectedGroup":"Myanmar nationals","action":"Collecting iris and face biometrics","consequence":"Potential threat to privacy and human rights"}},{"i":"R1485","hd":"Uganda to tighten biometric id database security after data breach claims","pd":"2025-09-22","k":"Uganda","p":"Uganda","b":["Data"],"h":["4.1  Privacy violation"],"t":"Uganda to tighten biometric id database security after data breach claims","s":"NIRA is pledging to strengthen privacy and security measures around the country’s biometric national ID database after recent reports of a data breach. The National Database and Registration Authority (NIRA) of Uganda is pledging to strengthen privacy and security measures around the country’s biometric national ID database after recent reports of a data breach. A recent BBC investigation claimed that data from the National Identification Registry (NIR) was shared illegally by some unscrupulous NIRA staff to a criminal ring. NIRA said in a recent press release that while it still awaits further evidence on the claims from the BBC, it has nonetheless opened an investigation into the matter, in collaboration with the the Personal Data Protection Office and the Uganda Police Force.","u":"https://www.biometricupdate.com/202509/uganda-to-tighten-biometric-id-database-security-after-data-breach-claims","d":"2025-09-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-22","organization":"National Database and Registration Authority (NIRA), Personal Data Protection Office, Uganda Police Force","aiSystem":"biometric national ID database","affectedGroup":"people whose data was shared illegally","action":"data from the National Identification Registry (NIR) was shared illegally","consequence":"privacy and security measures weakened"}},{"i":"R802","hd":"Ukraine uses facial recognition identify dead russian soldiers","pd":"2022-03-25","k":"Ukraine","p":"Ukraine","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Ukraine uses facial recognition identify dead russian soldiers","s":"Ukraine’s military has said some 15,000 Russian soldiers have been killed since Russia invaded on February 24. CALIFORNIA, USA – Ukraine is using facial recognition software to identify the bodies of Russian soldiers killed in combat and to trace their families to inform them of their deaths, Ukraine’s vice prime minister told Reuters. Reuters exclusively reported that Ukraine’s Ministry of Defense this month began using technology from Clearview AI, a New York-based facial recognition provider that finds images on the web that match faces from uploaded photos. It was not clear at that time how the technology would be used.","u":"https://www.rappler.com/world/europe/ukraine-uses-facial-recognition-identify-dead-russian-soldiers/","d":"2022-03-25","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-03-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-03-25","organization":"Ukraine's Ministry of Defense","aiSystem":"Clearview AI facial recognition technology","affectedGroup":"Russian soldiers' families","action":"Using facial recognition software to identify the bodies of Russian soldiers killed in combat","consequence":"Informing the families of the deaths of Russian soldiers"}},{"i":"R803","hd":"Ukraine using clearview facial recognition during war","pd":"2022-03-14","k":"Ukraine","p":"Ukraine","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Ukraine using clearview facial recognition during war","s":"Ukraine is receiving free access to Clearview AI’s powerful search engine for faces, letting authorities potentially vet people of interest at checkpoints, among other uses. Ukraine’s defense ministry on Saturday, March 12, began using Clearview AI’s facial recognition technology, the company’s chief executive told Reuters, after the US startup offered to uncover Russian assailants, combat misinformation, and identify the dead. Ukraine is receiving free access to Clearview AI’s powerful search engine for faces, letting authorities potentially vet people of interest at checkpoints, among other uses, added Lee Wolosky, an adviser to Clearview and former diplomat under US presidents Barack Obama and Joe Biden.","u":"https://www.rappler.com/technology/ukraine-using-clearview-facial-recognition-during-war/","d":"2022-03-14","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-03-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-03-12","organization":"Ukraine's defense ministry, Clearview AI (US startup)","aiSystem":"Clearview AI's facial recognition technology","affectedGroup":"People of interest, potential Russian assailants, deceased individuals","action":"Using Clearview AI’s facial recognition technology to vet people of interest at checkpoints, combat misinformation, and identify the dead","consequence":"Potential misuse for surveillance, identification of individuals, and verification of people of interest"}},{"i":"R909","hd":"Anomaly six phone tracking zignal surveillance CIA NSA","pd":"2022-04-22","k":"Ukraine","p":"Ukraine","b":["Data"],"h":["4.2  Surveillance harm","4.1  Privacy violation"],"t":"Anomaly six phone tracking zignal surveillance cia nsa","s":"Anomaly Six, a secretive government contractor, claims to monitor the movements of billions of phones around the world and unmask spies with the press of a button. In the months leading up to Russia’s invasion of Ukraine, two obscure American startups met to discuss a potential surveillance partnership that would merge the ability to track the movements of billions of people via their phones with a constant stream of data purchased directly from Twitter. According to Brendon Clark of Anomaly Six — or “A6” — the combination of its cellphone location-tracking technology with the social media surveillance provided by Zignal Labs would permit the U.S. government to effortlessly spy on Russian forces as they amassed along the Ukrainian border, or similarly track Chinese nuclear submarines.","u":"https://theintercept.com/2022/04/22/anomaly-six-phone-tracking-zignal-surveillance-cia-nsa/","d":"2022-04-22","e":"Acute, Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-04-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-04-22","organization":"Anomaly Six (government contractor)","aiSystem":"cellphone location-tracking technology","affectedGroup":"Russian forces, Chinese nuclear submarines","action":"monitor and track movements of billions of phones","consequence":"espionage and surveillance activities"}},{"i":"R324","hd":"Ukraine military deploys dozens of ground robots uavs fpv drones in historic combat operation in kharkiv oblast","pd":"2024-12-17","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Ukraine military deploys dozens of ground robots uavs fpv drones in historic combat operation in kharkiv oblast","s":"Ukrainian forces conduct first-ever fully robotic combat operation, combining ground robots, drones, and unmanned turrets to advance on Kharkiv front while preserving soldiers’ lives. Ukraine’s 13th National Guard Brigade Khartia has announced it conducted its first fully robotic operation against Russian forces on the Kharkiv front at the beginning of December. As the war evolves, the implementation of robotic and AI systems will be crucial for achieving strategic objectives on the battlefield. Ukrainian forces have increasingly utilized unmanned aerial vehicles and AI-powered drones and systems for improved reconnaissance, target acquisition, and precision strikes.","u":"https://euromaidanpress.com/2024/12/17/ukraine-military-deploys-dozens-of-ground-robots-uavs-fpv-drones-in-historic-combat-operation-in-kharkiv-oblast/","d":"2024-12-17","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-12-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-12-01","organization":"Ukraine's 13th National Guard Brigade Khartia","aiSystem":"Unmanned aerial vehicles (UAVs) and AI-powered drones","affectedGroup":"Russian forces","action":"Conducted a fully robotic operation against Russian forces","consequence":"Preserved soldiers' lives"}},{"i":"R307","hd":"Ukraine russia drone AI swarms","pd":"2025-09-19","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Ukraine russia drone ai swarms","s":"They can’t hit moving trucks yet—but but they must beat Russia to swarm dominance by 2027. Ukraine has less than two years to master AI-powered drone warfare before autonomous weapons transform the battlefield into something \"totally ruthless,\" warns former Commander-in-Chief Valerii Zaluzhnyi. The stakes couldn't be higher. By 2027 , Zaluzhnyi predicts, \"human involvement will be fully or partially removed not only from the process of control, but also from decision-making about target engagement.\" Whichever side masters autonomous warfare first may gain a decisive advantage that determines the war's outcome. But Ukraine's AI drones currently struggle with the basics—they can't reliably hit moving targets.","u":"https://euromaidanpress.com/2025/09/19/ukraine-russia-drone-ai-swarms/","d":"2025-09-19","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2025-09-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-19","organization":"Ukraine","aiSystem":"AI-powered drone systems","affectedGroup":"Ukrainian military forces","action":"Ukraine's AI drone systems struggle to hit moving targets","consequence":"Potential loss of decisive advantage in autonomous warfare"}},{"i":"R309","hd":"33k AI strike kits ukraine pentagon","pd":"2025-07-27","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.4  Supply chain / investor complicity harm"],"t":"33k ai strike kits ukraine pentagon","s":"The $50 million Pentagon contract equips Ukraine’s drones with AI software able to track targets and resist jamming. US-German software company Auterion will send 33,000 AI-powered drone “strike kits” to Ukraine before the end of the year under a new Pentagon contract, the Financial Times reports. The announcement comes as peace talks remain stalled and Russia steps up its aerial campaign , modernizing its Shahed drones to cause as much damage as possible and scaling up their production. Ukraine has been scrambling to find an answer as these massed swarms increasingly breach air defences. Auterion's Chief executive Lorenz Meier said the new commitment was “10 times in scale” compared to previous deliveries : “So we’ve shipped thousands and we’re now shipping tens of thousands,” Meier told the FT , describing the expansion as “unprecedented.”","u":"https://euromaidanpress.com/2025/07/27/33k-ai-strike-kits-ukraine-pentagon/","d":"2025-07-27","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-27","organization":"Auterion (US-German software company)","aiSystem":"AI-powered drone strike kits","affectedGroup":"Ukraine's drones","action":"Equipping Ukraine’s drones with AI software","consequence":"Increased resistance to jamming and improved target tracking capabilities"}},{"i":"R310","hd":"Digital occupation russia deploys AI army of bots on telegram for promoting kremlins propaganda narratives","pd":"2025-07-18","k":"Ukraine","p":"Ukraine","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Digital occupation russia deploys ai army of bots on telegram for promoting kremlins propaganda narratives","s":"They sound human and post nonstop. Russia has begun using artificial intelligence-based bots for spreading propaganda on social media, especially on Telegram, according to a joint investigation by OpenMinds and the Digital Forensic Research Lab (DFRLab). The tactic is part of Russia’s broader strategy to dominate the information space in occupied areas, which began by forcibly switching residents to Russian telecom providers, cutting off Ukrainian media, and launching dozens of Telegram channels posing as local news outlets. Researchers have uncovered over 3,600 bots that posted more than 316,000 AI-generated comments in Telegram channels linked to Ukraine's temporarily occupied territories.","u":"https://euromaidanpress.com/2025/07/18/digital-occupation-russia-deploys-ai-army-of-bots-on-telegram-for-promoting-kremlins-propaganda-narratives/","d":"2025-07-18","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-18","organization":"Russia","aiSystem":"Artificial Intelligence-based bots","affectedGroup":"Residents of Ukraine's temporarily occupied territories","action":"Posting nonstop AI-generated comments on Telegram channels","consequence":"Spreading Kremlin's propaganda narratives"}},{"i":"R311","hd":"Nato allies test german AI drone as ukraine already destroys russian equipment with it","pd":"2025-07-10","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Nato allies test german ai drone as ukraine already destroys russian equipment with it","s":"German company Helsing designed the HX-2 AI drone as Europe’s answer to Russia’s Lancet loitering munition. Armed forces across Europe are conducting trials of a German-developed HX-2 strike drone that could reshape the continent's military capabilities, while Ukrainian pilots already fly it against Russian targets. Drone warfare has become a critical factor in Ukraine's defense against Russian aggression , transforming the conflict into what many call the first full-scale drone war. By early 2025, these unmanned aircraft were destroying 60-70% of Russian equipment—tanks, artillery, air defenses—often striking deep behind enemy lines.","u":"https://euromaidanpress.com/2025/07/11/nato-allies-test-german-ai-drone-as-ukraine-already-destroys-russian-equipment-with-it/","d":"2025-07-10","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-01","organization":"German company Helsing","aiSystem":"HX-2 AI drone","affectedGroup":"Russian equipment","action":"destroying Russian equipment","consequence":"transforming the conflict into a drone war"}},{"i":"R312","hd":"Drones rack up 70 of troop losses in the ukraine war and ais killing spree will make it worse","pd":"2025-06-14","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Drones rack up 70 of troop losses in the ukraine war and ais killing spree will make it worse","s":"Russia’s war turned Ukraine into ground zero for next-gen warfare, rendering the world’s top weapons obsolete—and positioning Kyiv as the West’s only ally fast enough to match China’s breakneck innovation. Ukraine’s recent assault on airbases across Russia has already ushered in a new conventional wisdom: the expensive, human-crewed weapons (tanks, planes, ships) that have long defined the world’s “advanced” militaries have been rendered obsolete by inexpensive drones. However, this view is incomplete, and perhaps dangerously misleading. Today’s drone warfare offers sobering lessons that go far beyond the vulnerability of expensive legacy weapons; and the looming integration of AI into drone warfare will make the current situation look positively quaint.","u":"https://euromaidanpress.com/2025/06/14/drones-rack-up-70-of-troop-losses-in-the-ukraine-war-and-ais-killing-spree-will-make-it-worse/","d":"2025-06-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-14","organization":"Russia","aiSystem":"AI-assisted drone systems","affectedGroup":"Ukraine's military forces","action":"Ukraine's use of drones against Russian airbases","consequence":"Increased reliance on AI in drone warfare"}},{"i":"R313","hd":"V2u essentially impossible to jam","pd":"2025-06-11","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"V2u essentially impossible to jam","s":"With redundant navigation and AI targeting, Russia’s 1.2-m V2U attack drone can fly and attack without human help. Russia’s new AI kamikaze drone can navigate and attack without any connection to a human operator. The V2U may be one of the most sophisticated small attack UAVs on either side of Russia’s 40-month wider war on Ukraine—and it risks tilting the life-or-death drone race in the Kremlin’s favor. The electrically-powered, propeller-driven, explosives-laden V2U, roughly 1.2 meters from wingtip to wingtip, first appeared along the 1,100-km front line this spring. Recovering crashed examples, Ukrainian and allied analysts have been able to identify the components—many of them Chinese, Japanese or American in origin—that help the V2U fly for up to an hour at 60 km/hr and strike with a vehicle-wrecking 2.9-kg shaped-charge warhead, all without human intervention.","u":"https://euromaidanpress.com/2025/06/11/v2u-essentially-impossible-to-jam/","d":"2025-06-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-11","organization":"Russia","aiSystem":"V2U attack drone","affectedGroup":"Ukrainian forces and civilians","action":"The V2U drone flies and attacks autonomously","consequence":"Potential shift in drone warfare advantage for Russia"}},{"i":"R314","hd":"Russias v2u drone uses AI for autonomous strikes in ukraines sumy oblast","pd":"2025-06-09","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Russias v2u drone uses ai for autonomous strikes in ukraines sumy oblast","s":"A Chinese minicomputer and American processor enable Russia’s V2U drone to select targets autonomously using artificial intelligence, according to the Ukraine’s Main Intelligence Directorate. Ukraine's military intelligence has disclosed technical specifications of Russia's V2U strike drone, which employs artificial intelligence for autonomous target selection and operates primarily in the Sumy Oblast, according to a report from the Main Intelligence Directorate of Ukraine's Defense Ministry. The drone's computational system runs on a Chinese Leetop A203 minicomputer powered by an NVIDIA Jetson Orin high-speed processor assembly, intelligence officials revealed This configuration enables the aircraft to identify and engage targets without human intervention.","u":"https://euromaidanpress.com/2025/06/09/russias-v2u-drone-uses-ai-for-autonomous-strikes-in-ukraines-sumy-oblast/","d":"2025-06-09","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-09","organization":"Russia","aiSystem":"V2U strike drone with AI for autonomous target selection","affectedGroup":"Targets (not specified)","action":"Selects and engages targets autonomously","consequence":"Potential civilian casualties and damage"}},{"i":"R317","hd":"Ukraine battle tests czech AI kamikaze drones immune to russian jamming","pd":"2025-05-15","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Ukraine battle tests czech ai kamikaze drones immune to russian jamming","s":"The MTS line of autonomous drones reportedly completes missions without GPS or radio, flying straight through hostile zones. Czech company LPP Holding says it has successfully deployed its autonomous MTS drones in Ukraine, confirming their combat effectiveness and resistance to Russian electronic warfare. These unmanned aerial vehicles (UAVs) are reportedly equipped with AI-based navigation, enabling them to operate without GPS, radio signals, or optical fiber. At the time of publication, there was no official confirmation from Ukrainian or Czech authorities regarding the testing or combat use of these drones against Russian forces in Ukraine.","u":"https://euromaidanpress.com/2025/05/15/ukraine-battle-tests-czech-ai-kamikaze-drones-immune-to-russian-jamming/","d":"2025-05-15","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-05-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-05-15","organization":"LPP Holding (Czech company)","aiSystem":"autonomous MTS drones","affectedGroup":"Russian forces in Ukraine","action":"deployed and tested in Ukraine","consequence":"resistance to Russian electronic warfare"}},{"i":"R318","hd":"Frontline report german wooden AI drones just smoked putins troops in ukraine","pd":"2025-04-20","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Frontline report german wooden ai drones just smoked putins troops in ukraine","s":"Ukraine is using HF1 loitering drones with plywood frames to strike Russian air defenses more than 50 kilometers behind the front. Today, there is a lot of news from Ukraine. Here, Ukrainian special forces received Germany's cutting-edge loitering munitions powered with artificial intelligence for automatic targeting. Striking high-value targets deep behind enemy lines, the Russians are struggling to find an answer to the increasing number of high-tech Ukrainian strike drones appearing on the battlefield. Recently, the Ukrainians received the first batch of the new German HF1 loitering drones, which they immediately used to devastating effect.","u":"https://euromaidanpress.com/2025/04/20/frontline-report-german-wooden-ai-drones-just-smoked-putins-troops-in-ukraine/","d":"2025-04-20","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-04-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-04-20","organization":"Germany","aiSystem":"HF1 loitering munitions powered with artificial intelligence","affectedGroup":"Russian air defenses","action":"struck high-value targets deep behind enemy lines","consequence":"struggling to find an answer to the increasing number of high-tech Ukrainian strike drones"}},{"i":"R320","hd":"We try anything that can kill more russians new ukraine AI drones require just 30 min training","pd":"2025-03-08","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"We try anything that can kill more russians new ukraine ai drones require just 30 min training","s":"Ukrainian forces have cut drone operator training using AI-guided systems that have boosted target accuracy up to 80%, a recent CSIS report finds. Ukraine has successfully enhanced its drone capabilities by retraining publicly available AI models on real-world combat data, increasing the odds of hitting Russian targets \"three- or four-fold,\" according to a new report from the Center for Strategic and International Studies (CSIS). \"By removing the need for constant manual control and stable communications … drones enabled with autonomous navigation raise the target engagement success rate from 10-20% to around 70-80%,\" writes Ukrainian-American scholar Kateryna Bondar, a former advisor to Kyiv, in the report released on 6 March.","u":"https://euromaidanpress.com/2025/03/08/we-try-anything-that-can-kill-more-russians-new-ukraine-ai-drones-require-just-30-min-training/","d":"2025-03-08","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-03-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-03-06","organization":"Ukrainian forces","aiSystem":"AI-guided drone systems","affectedGroup":"Russian targets","action":"Enhanced drone capabilities through AI training","consequence":"Increased accuracy and success rate in hitting Russian targets"}},{"i":"R321","hd":"Forbes ukrainian AI drones claim 80 hit rate yet human pilots remain superior","pd":"2025-03-06","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Forbes ukrainian ai drones claim 80 hit rate yet human pilots remain superior","s":"Ukrainian forces are deploying AI-equipped drones to bypass Russian jamming. Developers claim high success rate, but frontline commanders report mixed results. In a recent Forbes report, technology correspondent David Hambling examines how Ukrainian forces are deploying AI-enabled drones to counter Russian jamming. These small drones, especially FPV models, have become decisive weapons \"destroying roughly twice as much enemy equipment as every other weapon put together.\" However, jamming reportedly brings down \"at least half of FPVs before they can reach the target.\" 'Michael,' Commander of the Typhoon drone unit of the National Guard of Ukraine, shared mixed results from field testing.","u":"https://euromaidanpress.com/2025/03/06/forbes-ukrainian-ai-drones-claim-80-hit-rate-yet-human-pilots-remain-superior/","d":"2025-03-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-03-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-03-06","organization":"Ukrainian forces","aiSystem":"AI-equipped drones","affectedGroup":"Russian jamming","action":"deploying AI-enabled drones to counter jamming","consequence":"destruction of enemy equipment, reduced effectiveness due to jamming"}},{"i":"R323","hd":"Im a ukrainian fact checker meta just handed russia the keys to your newsfeed","pd":"2025-01-12","k":"Ukraine","p":"Ukraine","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Im a ukrainian fact checker meta just handed russia the keys to your newsfeed","s":"Meta claims it’s championing free speech. But for Ukrainians, it feels more like a death sentence for the truth. Remember that last viral post you saw about election fraud? The one that made you wonder if it was real? Now imagine a world where no one checks if it's true – where Russian bots can freely spread disinformation about everything from your local elections to international conflicts. That's exactly what's at stake with Mark Zuckerberg's latest announcement. On 7 January, Meta's CEO declared plans to replace professional fact-checkers with a community-based system similar to X's \"Community Notes.\" As a co-founder of StopFake.org, a Ukrainian fact-checking organization working with Meta, I've seen firsthand how this decision could unleash a tsunami of unchecked propaganda – and Ukrainians would be the first casualties.","u":"https://euromaidanpress.com/2025/01/12/im-a-ukrainian-fact-checker-meta-just-handed-russia-the-keys-to-your-newsfeed/","d":"2025-01-12","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-01-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-01-07","organization":"Meta (Facebook)","aiSystem":"Community-based fact-checking system","affectedGroup":"Ukrainians","action":"Replacing professional fact-checkers with a community-based system","consequence":"Uncontrolled spread of disinformation"}},{"i":"R285","hd":"Russia built the Gerbera to be shot down instead of a Shahed","pd":"2026-07-30","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Russia built the Gerbera to be shot down instead of a Shahed","s":"Russia built the Gerbera to be shot down instead of a Shahed. For $10,000, it now carries the Shahed’s targeting kit. To match Ukraine's drone strikes on Russian logistics, the Russians need a lot more drones The \"Seeker\" attack Gerbera could be just the thing The Seeker modification adds AI-assisted terminal guidance to the inexpensive explosive drone Russia's cheap Gerbera drones are getting a little more expensive—and a lot more capable. And that's bad news for Ukrainian forces as both sides in Russia's 53-month wider war on Ukraine escalate their attacks on the enemy's logistics. The upgrade is AI-assisted targeting, and it gives the $10,000 Gerbera the same machine vision Russia put on its far pricier Geran strike drones.","u":"https://euromaidanpress.com/2026/07/31/seeker-gerbera/","d":"2026-07-30","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-30","organization":"Russian military","aiSystem":"Gerbera drones","affectedGroup":"Ukrainian logistics","action":"Upgrade AI-assisted targeting capabilities","consequence":"Increased capability and potential for more effective attacks on Ukrainian logistics"}},{"i":"R286","hd":"Ukraine’s countershipping campaign risks polluting the fragile Black Sea","pd":"2026-07-18","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Ukraine’s countershipping campaign risks polluting the fragile Black Sea","s":"Ukraine’s countershipping campaign risks polluting the fragile Black Sea. Drone operators are trying to spill less oil. Ukrainian drone units aren't just trying to strike Russia's shadow fleet They're trying to strike the ships without spilling fuel or oil But that requires very accurate strikes Ukraine's drone force is walking a fine line as it escalates its attacks on Russia's unregistered commercial \"shadow fleet\" in the Sea of Azov and eastern Black Sea. The drone operators are trying to immobilize the ships without breaching their hulls and spilling fuel or crude oil into the water. That fleet is a big piece of how Moscow keeps its war funded—the aging tankers move Russian oil around Western sanctions—which is why Ukraine's drones have spent the past two weeks hunting it across the Azov and Black seas at better than a dozen ships a day.","u":"https://euromaidanpress.com/2026/07/18/oil-spills/","d":"2026-07-18","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-18","organization":"Ukrainian Drone Units","aiSystem":"Drone Operators","affectedGroup":"Russian Shadow Fleet (Unregistered Commercial Ships)","action":"Trying to immobilize ships without breaching hulls","consequence":"Avoiding spillage of fuel or crude oil into the water"}},{"i":"R287","hd":"Geran 4 vs grain ships","pd":"2026-07-14","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Geran 4 vs grain ships","s":"Russia’s fast, highly autonomous Geran-4 one-way attack drone is the weapon of choice for strikes on Ukrainian grain ships. Russia's newest jet drones are striking grain ships in Ukrainian ports A Raspberry Pi microcomputer flies the final attack run, holding the lock through Ukrainian jamming Ukraine's own counter-shipping campaign is running far ahead: 105 vessels struck in eight days Ukrainian drones are wreaking havoc on Russian ships sailing the Sea of Azov and the Black Sea. But the Russians are waging their own war on shipping, sortieing the latest Geran drones to strike grain ships in Ukrainian ports. The Geran-4 Seeker drones pummeling Ukrainian ports combine jet propulsion, mesh radio control, and machine-vision targeting run off a Raspberry Pi—the same $50-class hobbyist computer that schoolchildren use to build robots.","u":"https://euromaidanpress.com/2026/07/14/geran-4-vs-grain-ships/","d":"2026-07-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-14","organization":"Russia","aiSystem":"Geran-4 one-way attack drone","affectedGroup":"Ukrainian grain ships","action":"Attacks on Ukrainian grain ships","consequence":"Damage and destruction of grain ships"}},{"i":"R288","hd":"AI against AI over ukraine russias shahed now sees its target and ukraines interceptor sees shahed","pd":"2026-07-12","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Ai against ai over ukraine russias shahed now sees its target and ukraines interceptor sees shahed","s":"Russia showed a new Geran-4 Seeker Shahed variant with machine-vision AI targeting. Russia's new Geran-4 Seeker Shahed variant uses machine-vision AI for targeting. The system enables the drone to autonomously recognize and track ground targets during the terminal phase of flight, thereby increasing targeting accuracy, according to UNIAN, citing Russian propaganda outlets. The base Geran-4 runs on a Chinese-made Telefly turbojet engine rated at 160 kgf of thrust, reaches speeds up to 500 km/h, and carries either a 50-kilogram high-explosive or thermobaric warhead or an enlarged 90-kilogram thermobaric payload. Russia began combat use of the Geran-4 against Ukrainian targets in May 2026, Ukraine's Defense Intelligence (HUR) reveals The 300 km/h speed cited by Russian propaganda for the Seeker variant is lower than HUR's 500 km/h max-speed assessment for the base Geran-4 and aligns more…","u":"https://euromaidanpress.com/2026/07/12/ai-against-ai-over-ukraine-russias-shahed-now-sees-its-target-and-ukraines-interceptor-sees-shahed/","d":"2026-07-12","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05","organization":"Russia","aiSystem":"Geran-4 Seeker Shahed variant with machine-vision AI","affectedGroup":"Ukrainian ground targets","action":"Autonomously recognize and track ground targets during the terminal phase of flight","consequence":"Increased targeting accuracy and potential for civilian casualties"}},{"i":"R289","hd":"Russias AI drone cant be jammed or detected so ukraine shot it down","pd":"2026-07-09","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Russias ai drone cant be jammed or detected so ukraine shot it down","s":"No antenna. No operator. No emissions for a detector to catch. Ukraine’s answer is no longer electronic warfare—it’s a bullet. Ukraine has shot down an autonomous version of Russia's Molniya strike drone. It is the first confirmed intercept of the AI-equipped variant, which cannot be jammed by electronic warfare, Ivan Fedorov , head of the Zaporizhzhia Oblast Military Administration, announced. Russia's pivot toward autonomous and fiber-optic drone variants is part of a broader effort to neutralize the electronic warfare advantage that has been one of Ukraine's key equalizers in the drone war—forcing Ukraine to develop kinetic intercept at scale as the primary answer to threats that jamming cannot touch.","u":"https://euromaidanpress.com/2026/07/09/russias-ai-drone-cant-be-jammed-or-detected-so-ukraine-shot-it-down/","d":"2026-07-09","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-09","organization":"Ukraine","aiSystem":"Autonomous version of Russia's Molniya strike drone equipped with AI","affectedGroup":"Russia's Molniya strike drone","action":"Shot down","consequence":"Cannot be jammed by electronic warfare"}},{"i":"R290","hd":"Russia is building fake ukrainians one AI video telling ukrainians their soldiers are dying so politicians can buy villas got views","pd":"2026-07-04","k":"Ukraine","p":"Ukraine","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Russia is building fake ukrainians one ai video telling ukrainians their soldiers are dying so politicians can buy villas got 900000 views","s":"Russia has moved to “conveyor production” of fakes. Russia is deploying AI-generated \"Ukrainian soldiers\", \"rabbis\", and other fake authority figures on Ukrainian social media at scale. A Hromadske investigation, drawing on Ukrainian analytics firm LetsData and Ukrainian intelligence group Molfar Intelligence Institute, has documented three viral AI-generated propaganda videos targeting Ukrainian audiences in early May 2026. The tactic exploits a structural information-warfare advantage that generative AI has handed to hostile propaganda operations. AI-generated lies spread in seconds, while refutations from human fact-checkers appear hours or days later.","u":"https://euromaidanpress.com/2026/07/04/russia-is-building-fake-ukrainians-one-ai-video-telling-ukrainians-their-soldiers-are-dying-so-politicians-can-buy-villas-got-900000-views/","d":"2026-07-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05","organization":"Russia","aiSystem":"AI-generated content","affectedGroup":"Ukrainian social media audience","action":"Deploying AI-generated 'Ukrainian soldiers', 'rabbis', and other fake authority figures on Ukrainian social media","consequence":"Viral spread of AI-generated propaganda leading to misinformation"}},{"i":"R291","hd":"Ukraine wants an AI driven army its new defense center is already putting AI inside kill chain steering drones onto target in final seconds","pd":"2026-06-25","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.2  Military decision support harm"],"t":"Ukraine wants an ai driven army its new defense center is already putting ai inside kill chain steering drones onto target in final seconds","s":"From last-mile targeting that beats jamming to autonomous turrets, the Ukrainian military center wants AI everywhere, but humans still pull the trigger. Ukraine wants to turn its military into what it calls an AI-driven army. The Defense AI Center A1, set up at the Ministry of Defense in March, is already working on projects to deploy artificial intelligence at every level of the force, from data analysis and decision-making to striking the enemy, its head Danylo Tsvok said in an interview the ministry relayed The center splits its work into two. AI is meant to speed up decisions by chewing through battlefield data faster than the enemy can, and to sit inside the kill chain itself, the sequence from spotting a target to striking it and checking the result.","u":"https://euromaidanpress.com/2026/06/25/ukraine-wants-an-ai-driven-army-its-new-defense-center-is-already-putting-ai-inside-kill-chain-steering-drones-onto-target-in-final-seconds/","d":"2026-06-25","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03","organization":"Defense AI Center A1, Ministry of Defense, Ukraine","aiSystem":"Artificial Intelligence (AI) systems","affectedGroup":"Ukrainian military personnel and civilians potentially exposed to AI-enhanced operations","action":"Deploying AI at various levels of the military force, including data analysis, decision-making, and strike operations","consequence":"Potential misuse of AI for targeted strikes, which could lead to civilian casualties and unintended consequences"}},{"i":"R295","hd":"Fire point launcher","pd":"2026-06-04","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Fire point launcher","s":"AI-targeted drones need training images to find their targets. Ukraine just gave Russia one. Ukrainian troops released imagery of a specially modified truck launcher for Fire Point attack drones A few days later, Russian troops released imagery of an attack on one of the launchers The two releases may be related On 30 May, Ukrainian forces released nighttime imagery of a drone team launching Fire Point FP-1/2 one-way attack drones from a civilian-style tractor-trailer truck modified to carry at least three of the fixed-wing, rocket-assisted drones on metal racks. Four days later on 3 June, Russian forces released daytime imagery of a drone strike on one of these Ukrainian truck launchers.","u":"https://euromaidanpress.com/2026/06/04/fire-point-launcher/","d":"2026-06-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-03","organization":"Ukrainian forces","aiSystem":"Fire Point attack drones","affectedGroup":"Russian forces","action":"Launched Fire Point FP-1/2 one-way attack drones from a modified civilian-style tractor-trailer truck","consequence":"Struck a Russian drone launcher"}},{"i":"R298","hd":"AI makes it possible to automate parts of the kill chain says ukraines top defense AI official","pd":"2026-04-30","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.2  Military decision support harm"],"t":"Ai makes it possible to automate parts of the kill chain says ukraines top defense ai official","s":"Ukraine built its AI defense capability under fire, with no margin for slow procurement cycles or multi-year development timelines. Rapid military deployment of artificial intelligence is becoming a critical factor for Ukraine’s survival in the war. AI is already being used to hold positions, reduce casualties among soldiers, and counter Russia’s numerically superior army, says senior AI official Danylo Tsvok, Associated Press has reported. According to him, artificial intelligence is no longer an experiment but part of a real combat system. Democratic states that do not invest in such technologies risk losing the ability to defend themselves effectively.","u":"https://euromaidanpress.com/2026/04/30/ai-makes-it-possible-to-automate-parts-of-the-kill-chain-says-ukraines-top-defense-ai-official/","d":"2026-04-30","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-30","organization":"Ukraine","aiSystem":"artificial intelligence","affectedGroup":"soldiers, civilians","action":"rapid military deployment of AI systems","consequence":"reduction of casualties, counteracting Russia's numerical superiority"}},{"i":"R300","hd":"Gur russia is testing AI on its lancet drones using nvidia tech in cooperation with iran","pd":"2026-03-23","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Gur russia is testing ai on its lancet drones using nvidia tech in cooperation with iran","s":"“The technologies used today against Ukraine pose a potential threat to other regions of the world.” Russian forces are integrating AI capabilities into their Lancet series of attack drones, Ukraine's military intelligence directorate (GUR) revealed on 23 March. One of these drones was shot down over Kyiv last week. While the drone must be steered by pilots in real time, the Russians are “trying to introduce elements of autonomous guidance,” GUR wrote in the statement. This also applies to the Lancet’s smaller cousin, called the Scalpel. This tech was previously spotted in Russia’s obscure V2U drone, which is a semi-autonomous loitering munition, as well as Russia’s Geran series of attack drones, better known by their original Iranian name: the Shahed.","u":"https://euromaidanpress.com/2026/03/23/gur-russia-is-testing-ai-on-its-lancet-drones-using-nvidia-tech-in-cooperation-with-iran/","d":"2026-03-23","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-03-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-23","organization":"Russian forces","aiSystem":"Lancet series of attack drones and Scalpel (smaller cousin)","affectedGroup":"Other regions of the world","action":"Integrating AI capabilities into attack drones","consequence":"Potential threat to other regions"}},{"i":"R301","hd":"Killer robots dont exist yet but ukraine and russia are getting closer","pd":"2026-03-18","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Killer robots dont exist yet but ukraine and russia are getting closer","s":"“We are already deep into practical battlefield autonomy.” A drone skims over the treetops, ignoring the dense blankets of electronic jamming. Onboard cameras feed a steady stream of the landscape beneath to the navigation processor, which compares them to preloaded terrain data at machine speed. Soon, the drone detects shapes below — the AI models in its electronic brain spit out a high probability match to some enemy hardware, enough to trip the engagement threshold. The drone locks onto the image, tips forward, and swoops down, tenaciously seeking its target. This scenario is both the nightmare and the dream of militaries around the world, which are racing to be the first to field fleets of killer robots.","u":"https://euromaidanpress.com/2026/03/18/killer-robots-dont-exist-yet-but-ukraine-and-russia-are-getting-closer/","d":"2026-03-18","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-03-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-18","organization":"Military Forces of Ukraine and Russia","aiSystem":"Killer Robot","affectedGroup":"Enemy Hardware","action":"Locks onto and engages enemy target autonomously","consequence":"Potential for lethal outcomes"}},{"i":"R1327","hd":"Ukraine has embarked on a programme to deploy armed robots on the battlefield against Russ…","pd":"2026-03-07","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Ukraine has embarked on a programme to deploy armed robots on the battlefield against Russ…","s":"Ukraine has embarked on a programme to deploy armed robots on the battlefield against Russian forces. Since the start of Russia's full-scale invasion, the war in Ukraine has developed into a high-tech conflict. Swarms of spy and killer drones have set the skies of Ukraine abuzz, and uncrewed boats have crippled the Russian navy in the Black Sea. Now, Ukraine has embarked on a massive programme to deploy armed robots on the ground. Uncrewed ground vehicles (UGVs), or ground robot systems as they are known in Ukrainian military parlance, have already proven their worth. There have been reports of UGVs successfully repelling Russian attacks and even taking enemy soldiers prisoner.","u":"https://www.bbc.com/news/articles/c62662gzlp8o","d":"2026-03-07","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-02-24","organization":"Ukraine","aiSystem":"armed robots","affectedGroup":"Russian forces","action":"deployed armed robots on the battlefield","consequence":"repelled Russian attacks, took enemy soldiers prisoner"}},{"i":"R1355","hd":"Both Ukraine and Russia use AI in battle, but removing human decision-making comes with ri…","pd":"2025-09-10","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Both Ukraine and Russia use AI in battle, but removing human decision-making comes with ri…","s":"Both Ukraine and Russia use AI in battle, but removing human decision-making comes with risks. \"This technology is our future threat,\" warns Serhiy Beskrestnov, who has just got his hands on a newly intercepted Russian drone. It was no ordinary drone either, he discovered. Assisted by artificial intelligence, this unmanned aerial vehicle can find and attack targets on its own. Beskrestnov has examined numerous drones in his role as Ukrainian defence forces consultant. Unlike other models, it didn't send or receive any signals, so could not be jammed. Russian and Ukrainian forces have both been testing AI in this war, and in some areas they are already using it, for finding targets, gathering intelligence and de-mining.","u":"https://www.bbc.com/news/articles/cly7jrez2jno","d":"2025-09-10","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-10","organization":"Russian and Ukrainian forces","aiSystem":"Artificial intelligence-assisted unmanned aerial vehicle (UAV)","affectedGroup":"People in Ukraine and Russia","action":"Using AI to find and attack targets autonomously","consequence":"Potential for unlawful attacks and civilian casualties"}},{"i":"R1422","hd":"Clearview AI's face-search tech could be used to uncover infiltrators and to identify the …","pd":"2022-03-14","k":"Ukraine","p":"Ukraine","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Clearview AI's face-search tech could be used to uncover infiltrators and to identify the …","s":"Clearview AI's face-search tech could be used to uncover infiltrators and to identify the dead. A system that searches a database of billions of facial images could help Ukraine uncover Russian infiltrators, fight misinformation and identify the dead, a company has said. Facial recognition firm Clearview AI has offered its services to Ukraine's government. The company says it has a searchable database of 10 billion faces sourced from the web. But the technology has previously attracted fines from data regulators. \"I'm pleased to confirm that Clearview AI has provided its groundbreaking facial recognition technology to Ukrainian officials for their use during the crisis they are facing,\" chief executive Hoan Ton-That told the BBC in a statement.","u":"https://www.bbc.com/news/technology-60738204","d":"2022-03-14","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-03-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-03-14","organization":"Clearview AI","aiSystem":"Facial recognition technology","affectedGroup":"Russian infiltrators, dead individuals","action":"Searches a database of facial images","consequence":"Uncovering infiltrators, fighting misinformation, identifying the dead"}},{"i":"R2657","hd":"Deepfake call ukraine senator cardin dmytro kuleba","pd":"2024-09-26","k":"Ukraine","p":"Ukraine","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Deepfake call ukraine senator cardin dmytro kuleba","s":"Security officials warned future attempts are imminent. The caller, who looked and sounded just like Ukraine’s former foreign minister, asked ‘politically charged questions in relation to the upcoming election.’ The head of the Senate Foreign Relations Committee took a Zoom call with someone using deepfake technology to pose as a top Ukrainian official, The New York Times reports Sen. Ben Cardin (D-MD) received an email last Thursday that appeared to be from Dmytro Kuleba, Ukraine’s former foreign minister, asking him to meet on Zoom. The person on the other end of the call reportedly looked and sounded like Kuleba but was acting strangely.","u":"https://www.theverge.com/2024/9/26/24255179/deepfake-call-ukraine-senator-cardin-dmytro-kuleba","d":"2024-09-26","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-09-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-09-26","organization":"Ukraine's former foreign minister Dmytro Kuleba","aiSystem":"Deepfake technology","affectedGroup":"Sen. Ben Cardin (D-MD)","action":"Received a Zoom call impersonating Dmytro Kuleba","consequence":"Received politically charged questions related to the upcoming election"}},{"i":"R2727","hd":"Facebook removes deepfake ukraine zelenskyy meta instagram","pd":"2022-03-16","k":"Ukraine","p":"Ukraine","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Facebook removes deepfake ukraine zelenskyy meta instagram","s":"Facebook banned deepfakes over two years ago. On Wednesday, Facebook’s parent company, Meta, removed a deepfake video of Ukrainian President Volodymyr Zelenskyy issuing a statement that he never made, asking Ukrainians to “lay down arms.” Facebook removes ‘deepfake’ of Ukrainian President Zelenskyy In the fake video, Zelenskyy surrenders to Russian invasion The deepfake appears to have been first broadcasted on a Ukrainian news website for TV24 after an alleged hack, as first reported by Sky News on Wednesday. The video shows an edited Zelenskyy speaking behind a podium declaring that Ukraine has “decided to return Donbas” to Russia and that his nation’s war efforts had failed.","u":"https://www.theverge.com/2022/3/16/22981806/facebook-removes-deepfake-ukraine-zelenskyy-meta-instagram","d":"2022-03-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-03-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-03-16","organization":"Meta (Facebook)","aiSystem":"AI-powered deepfake detection system","affectedGroup":"Ukrainian President Volodymyr Zelenskyy","action":"removed a deepfake video","consequence":"exposed to misleading information"}},{"i":"R2753","hd":"Ukraine clearview AI russia","pd":"2023-11-14","k":"Ukraine","p":"Ukraine","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Ukraine clearview ai russia","s":"The country has come to rely on Clearview AI for a range of wartime tasks, many of which have not been reported:. Leonid Tymchenko spent the first month of Russia’s invasion sitting in his dark government office after curfew. Unable to go home, Ukraine's Deputy Minister of Internal Affairs scrolled through Telegram, looking at thousands of videos and images of advancing Russian soldiers. When Tymchenko was offered a chance to test a new facial-recognition tool, he uploaded some of the photos to try it out. He could not believe the results. Every time Tymchenko added a photo of a Russian soldier, the software, made by the American facial-recognition company Clearview AI, seemed to come back with an exact hit, linking to pages that revealed the soldier’s name, hometown, and social-media profile.","u":"https://time.com/6334176/ukraine-clearview-ai-russia/","d":"2023-11-14","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-11-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-11-14","organization":"Ukraine's Deputy Minister of Internal Affairs","aiSystem":"Clearview AI facial recognition technology","affectedGroup":"Russian soldiers","action":"Used Clearview AI to identify Russian soldiers","consequence":"Exposure to surveillance and tracking"}},{"i":"R2983","hd":"Keystroke attack security roundup","pd":"2023-08-12","k":"Ukraine","p":"Ukraine","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Keystroke attack security roundup","s":"A pair of major data breaches rock the UK, North Korea hacks a Russian missile maker, and Microsoft’s Chinese Outlook breach sparks new problems. Things kicked off with a doozy. A researcher believes he’s found evidence that a series of spikes in radiation seemingly recorded by sensors at the Chernobyl nuclear facility in the hours following Russia’s February 2022 invasion of Ukraine were manipulated. The findings contradict the official explanation from Ukrainian and international nuclear authorities, prompting calls for a full investigation. If the researcher’s findings are proven accurate, it could have grave implications for nuclear monitoring and geopolitics.","u":"https://www.wired.com/story/keystroke-attack-security-roundup/","d":"2023-08-12","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2023-08-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-02-24","organization":"Not specified in report","aiSystem":"Not specified in report","affectedGroup":"International community, nuclear monitoring agencies, geopolitical analysts","action":"Manipulated radiation data recorded by sensors at Chernobyl nuclear facility","consequence":"Potential misinterpretation of nuclear monitoring data, geopolitical tensions"}},{"i":"R2985","hd":"Ukraine government battlefield data","pd":"2023-07-24","k":"Ukraine","p":"Ukraine","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"Ukraine government battlefield data","s":"Global companies are offering free products to get access to live combat data. The Ukrainian government wants to keep this resource for its own emerging defense industry. Wearing a baseball cap and thick, black-rimmed glasses, Cameron Chell is part defense contractor, part tech executive. His company, Draganfly, used to mainly work with emergency services in North America, selling drones and the accompanying software that could deliver medical equipment, or film traffic accidents from above. But since last February, the Canadian has pivoted his business to cater to a market more than 8,000 miles away: Ukraine. Now, there are 40 Draganfly drones in Ukraine, repurposed for search-and-rescue missions in bombed-out buildings, landmine detection, and other military tasks that Chell declines to detail.","u":"https://www.wired.com/story/ukraine-government-battlefield-data/","d":"2023-07-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-07-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-07-24","organization":"Global companies","aiSystem":"Live combat data","affectedGroup":"Ukrainian government","action":"Offering free products to gain access to live combat data","consequence":"Ukrainian government's inability to retain control over the data"}},{"i":"R2996","hd":"Fast forward ukraines quest for homegrown AI drones to take on russia","pd":"2023-04-13","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Fast forward ukraines quest for homegrown ai drones to take on russia","s":"The country’s digital minister, Mykhailo Fedorov, says software has been crucial to the war effort and that smarter drones will boost Ukraine's defenses. The war in Ukraine, now into its 14th grueling month, has displaced millions , sparked global food shortages , and threatened to spiral into wider conflict It has also highlighted how new technologies—especially ones drawn from the commercial sector—are upending conventional military doctrine. Ukraine has resisted and repelled Russia’s much larger military force, thanks in large part to a willingness, borne of necessity, to adopt and experiment with novel technologies, not all of them originally designed for military use I recently spoke with Ukraine’s 32-year-old minister of digital transformation, Mykhailo Fedorov, about the country’s interest in tapping new technology to boost the war effort.","u":"https://www.wired.com/story/fast-forward-ukraines-quest-for-homegrown-ai-drones-to-take-on-russia/","d":"2023-04-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-04-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-04-13","organization":"Ukraine","aiSystem":"Facial recognition technology","affectedGroup":"People identified or tracked using the technology","action":"Used facial recognition to identify people","consequence":"Exposed people to surveillance and tracking"}},{"i":"R3005","hd":"Ukraine war autonomous weapons frontlines","pd":"2023-02-25","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Ukraine war autonomous weapons frontlines","s":"Drones that can find their own targets already exist, making machine-versus-machine conflict just a software update away. When the war came to Sergiy Sotnychenko’s neighborhood in March 2022, he found himself carrying out daily performances for the drones that hummed constantly overhead. Desperate to prove that he wasn’t a combatant, he put on an orange hoodie which, out of all the clothing he owned, seemed least likely to be mistaken for military fatigues. He tried to show the drones he was carrying out innocent activities, like planting onions. Sometimes he would wave. That March was a nightmarishly violent month for Kyiv’s outskirts, including Irpin, where Sotnychenko lives, but there were moments when he allowed himself to feel comforted by the drones flying above.","u":"https://www.wired.com/story/ukraine-war-autonomous-weapons-frontlines/","d":"2023-02-25","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-02-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"March 2022","organization":"Not specified in report","aiSystem":"Autonomous drones","affectedGroup":"People living in Sergiy Sotnychenko's neighborhood","action":"Autonomous drones flew overhead","consequence":"Exposure to misleading content"}},{"i":"R3006","hd":"Russia ukraine facial recognition technology death military","pd":"2023-02-23","k":"Ukraine","p":"Ukraine","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Russia ukraine facial recognition technology death military","s":"The government is using Clearview AI to identify fallen Russian soldiers, but this deployment distracts from face recognition’s dangers. Lisez cet article en français. Five days after Russia launched its full-scale invasion of Ukraine, a year ago this week, US-based facial recognition company Clearview AI offered the Ukrainian government free access to its technology, suggesting that it could be used to reunite families, identify Russian operatives, and fight misinformation. Soon afterward, the Ukraine government revealed it was using the technology to scan the faces of dead Russian soldiers to identify their bodies and notify their families.","u":"https://www.wired.com/story/russia-ukraine-facial-recognition-technology-death-military/","d":"2023-02-23","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-02-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-02-28","organization":"Ukrainian government","aiSystem":"Clearview AI facial recognition technology","affectedGroup":"Families of fallen Russian soldiers","action":"Scanning the faces of dead Russian soldiers to identify their bodies","consequence":"Notification of families with incorrect information"}},{"i":"R3021","hd":"AI drones russia ukraine","pd":"2022-03-18","k":"Ukraine","p":"Ukraine","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Ai drones russia ukraine","s":"The maker of the lethal drone claims that it can identify targets using artificial intelligence. A Russian “suicide drone” that boasts the ability to identify targets using artificial intelligence has been spotted in images of the ongoing invasion of Ukraine. Photographs showing what appears to be the KUB-BLA, a type of lethal drone known as a “loitering munition” sold by ZALA Aero, a subsidiary of the Russian arms company Kalashnikov, have appeared on Telegram and Twitter in recent days. The pictures show damaged drones that appear to have either crashed or been shot down. With a wingspan of 1.2 meters, the sleek white drone resembles a small pilotless fighter jet.","u":"https://www.wired.com/story/ai-drones-russia-ukraine/","d":"2022-03-18","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-03-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-03-18","organization":"ZALA Aero (subsidiary of Kalashnikov)","aiSystem":"artificial intelligence","affectedGroup":"targets","action":"used artificial intelligence to identify targets","consequence":"potential misuse in military operations"}},{"i":"R3022","hd":"Zelensky deepfake facebook twitter playbook","pd":"2022-03-18","k":"Ukraine","p":"Ukraine","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Zelensky deepfake facebook twitter playbook","s":"The response to a video impersonating the Ukrainian president gives a blueprint for how to stop more sophisticated attempts. On March 2, the Ukraine government’s Center for Strategic Communication warned that its enemies might be preparing a “deepfake” video that appeared to show president Volodymyr Zelensky announcing his surrender to Russia’s invasion. On Wednesday, that warning appeared prescient. A fake video emerged on Facebook and YouTube in which a strangely motionless version of Zelensky asked Ukrainian troops to lay down their weapons in a voice different from his usual tone. The clip was also posted to Telegram and Russian social network VKontakte, according to the US think tank the Atlantic Council.","u":"https://www.wired.com/story/zelensky-deepfake-facebook-twitter-playbook/","d":"2022-03-18","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-03-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-03-02","organization":"Ukraine government's Center for Strategic Communication","aiSystem":"Deepfake technology","affectedGroup":"Ukrainian troops","action":"Generated and distributed misleading content","consequence":"Exposure to false information"}},{"i":"R677","hd":"Criminal networks southeast asia flourish telegram underground markets","pd":"2024-10-07","k":"United Arab Emirates","p":"United Arab Emirates","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Criminal networks southeast asia flourish telegram underground markets","s":"The UN report represents the latest allegations to be levied against Telegram since France charged its boss Pavel Durov for allowing criminal activity on the platform. BANGKOK, Thailand – Powerful criminal networks in Southeast Asia extensively use the messaging app Telegram which has enabled a fundamental change in the way organized crime can conduct large-scale illicit activity, the United Nations said in a report on Monday, October 7. The report represents the latest allegations to be levied against the controversial encrypted app since France, using a tough new law with no international equivalent, charged its boss Pavel Durov for allowing criminal activity on the platform.","u":"https://www.rappler.com/technology/criminal-networks-southeast-asia-flourish-telegram-underground-markets/","d":"2024-10-07","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-10-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-10-07","organization":"Telegram","aiSystem":"Telegram","affectedGroup":"powerful criminal networks in Southeast Asia","action":"extensively use Telegram","consequence":"enable a fundamental change in the way organized crime can conduct large-scale illicit activity"}},{"i":"R1222","hd":"Iran struck three data centres in the Middle East, and has signalled that technology infra…","pd":"2025-03-14","k":"United Arab Emirates","p":"United Arab Emirates","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Iran struck three data centres in the Middle East, and has signalled that technology infra…","s":"Iran struck three data centres in the Middle East, and has signalled that technology infrastructure will continue to be in the firing line. This Amazon data centre sits on the outskirts of Abu Dhabi, directly across the water from the Iranian coast. Stocked with high-powered computers that run day and night, this structure is where \"the cloud\" takes on physical form. Amazon has six data centres across Bahrain and the United Arab Emirates (UAE). Last week, two of the US tech giant's centres in the UAE were \"directly struck\" by Iranian drones, according to an Amazon status report. There was also \"a drone strike in close proximity\" to one Bahrain location.","u":"https://www.abc.net.au/news/2026-03-15/iran-war-ai-technology-data-centres/106443004","d":"2025-03-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-03-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-03-14","organization":"Iran","aiSystem":"Not specified in report","affectedGroup":"Amazon data centers","action":"Struck data centers","consequence":"Damage and disruption to operations"}},{"i":"R2799","hd":"Models are applying to be the face of AI scams","pd":"2026-03-16","k":"United Arab Emirates","p":"United Arab Emirates","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Models are applying to be the face of ai scams","s":"Dozens of Telegram channels reviewed by WIRED include job listings for “AI face models.” The (mostly) women who land these gigs are likely being used to dupe victims out of their money. When applying for jobs, Angel talks up her language skills. “I can speak fluent English, I can speak good Chinese, I also speak Russian and Turkish,” the glamorous, 24-year-old Uzbekistani woman explains in a selfie-style video made for recruiters. Angel had arrived in the Cambodian city of Sihanoukville that day, she said, and was ready to start work immediately. Those impressive language skills, however, have likely been put to use as part of elaborate “ pig-butchering ” scams targeting Americans.","u":"https://www.wired.com/story/models-are-applying-to-be-the-face-of-ai-scams/","d":"2026-03-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-16","organization":"Telegram channels and recruiters","aiSystem":"AI-generated recruitment profiles","affectedGroup":"Women, primarily from Uzbekistan","action":"Applying for AI face model jobs","consequence":"Being used in deceptive recruitment scams"}},{"i":"R2892","hd":"AI deepfake nudify bots telegram","pd":"2024-10-15","k":"United Arab Emirates","p":"United Arab Emirates","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Ai deepfake nudify bots telegram","s":"Bots that “remove clothes” from images have run rampant on the messaging app, allowing people to create nonconsensual deepfake images even as lawmakers and tech companies try to crack down. In early 2020, deepfake expert Henry Ajder uncovered one of the first Telegram bots built to “undress” photos of women using artificial intelligence. At the time, Ajder recalls, the bot had been used to generate more than 100,000 explicit photos—including those of children—and its development marked a “watershed” moment for the horrors deepfakes could create. Since then, deepfakes have become more prevalent, more damaging, and easier to produce.","u":"https://www.wired.com/story/ai-deepfake-nudify-bots-telegram/","d":"2024-10-15","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-10-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2020","organization":"Not specified in report","aiSystem":"Deepfake generation bots","affectedGroup":"People whose images were used without consent","action":"Generated non-consensual deepfake images","consequence":"Exposure of private images, potential misuse"}},{"i":"R1038","hd":"Man jailed in uks first treason conviction in 40 years encouraged by AI chatbot","pd":"2023-10-05","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Man jailed in uks first treason conviction in 40 years encouraged by ai chatbot","s":"Jaswant Singh Chail was sentenced to prison for 9 years for attempting to assassinate the Queen after discussing the plan with an AI companion. A man who admitted attempting to assassinate Queen Elizabeth II with a crossbow after discussing his plan with an AI-powered chatbot has been sentenced to 9 years in prison for treason. It’s the UK’s first treason conviction in more than 40 years. Jaswant Singh Chail, who was 19 at the time of his arrest on Christmas Day, 2021, scaled the walls of Windsor Castle’s grounds with a mask and a loaded high-power crossbow. He said his intent was, as a British Sikh, to assassinate the Queen in a Star Wars -inspired plan to avenge the 1919 Jallianwalla Bagh massacre , a colonial-era atrocity during British rule in India.","u":"https://www.vice.com/en/article/man-jailed-in-uks-first-treason-conviction-in-40-years-encouraged-by-ai-chatbot/","d":"2023-10-05","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-10-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-12-25","organization":"Not specified in report","aiSystem":"AI-powered chatbot","affectedGroup":"Jaswant Singh Chail (British Sikh)","action":"Discussing a plan to assassinate the Queen with an AI chatbot","consequence":"Sentenced to 9 years in prison for treason"}},{"i":"R1129","hd":"Companies in the UK are mining users personal data to place billboard ads","pd":"2022-10-13","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Companies in the uk are mining users personal data to place billboard ads","s":"A new investigation reveals that in the UK, the billboards watch you. Companies in the UK are collecting data from millions of phones to decide which advertisements to show on billboards in locations all around Britain, according to a new investigation by Big Brother Watch, a London-based civil liberties group known for confronting public surveillance issues. The report details how personalized ads—a phenomenon that has more than once raised privacy concerns over digital spying —are no longer confined to our private feeds, but instead have begun to overflow into our public lives. “We’ve uncovered new ways in which millions of people’s movements and behaviors are tracked to target us with ads on the streets, resulting in some of the most intrusive advertising surveillance we’ve ever seen in the UK,” Jake Hurfurt, head of research and investigations at Big Brother Watch, said in a press…","u":"https://www.vice.com/en/article/companies-in-the-uk-are-mining-users-personal-data-to-place-billboard-ads/","d":"2022-10-13","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-10-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-10-13","organization":"Companies in the UK","aiSystem":"Personalized advertising algorithms","affectedGroup":"Millions of people","action":"Collecting data from millions of phones to target ads on billboards","consequence":"Intrusive advertising surveillance"}},{"i":"R749","hd":"Tiktok snapchat others sign pledge tackle AI generated child sex abuse images","pd":"2023-10-31","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.8  Interpersonal / relational harm"],"t":"Tiktok snapchat others sign pledge tackle ai generated child sex abuse images","s":"Britain announces the joint statement – which also lists the United States, German and Australian governments among its 27 signatories – in the run up to a global summit hosted by the UK on AI safety this week. LONDON, United Kingdom – Tech firms including TikTok, Snapchat and Stability AI have signed a joint statement pledging to work together to counter child sex abuse images generated by artificial intelligence. Britain announced the joint statement – which also listed the United States, German and Australian governments among its 27 signatories – at an event on Monday being held in the run up to a global summit hosted by the UK on AI safety this week.","u":"https://www.rappler.com/technology/tiktok-snapchat-others-sign-pledge-tackle-ai-generated-child-sex-abuse-images/","d":"2023-10-31","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2023-10-31","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-10-31","organization":"British government","aiSystem":"TikTok, Snapchat, Stability AI","affectedGroup":"Child victims of sexual abuse","action":"Signed a joint statement to counter AI-generated child sex abuse images","consequence":"Commitment to collaborate on preventing and addressing AI-generated child sex abuse images"}},{"i":"R1005","hd":"Did AI deepfakes change the 2024 US election","pd":"2024-12-31","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Did ai deepfakes change the 2024 us election","s":"Maybe one day deepfakes created by AI will be so convincing that they truly throw a wrench into our political discourse, further separating fact from fiction. And plunging us into a new dark age of mis- and disinformation, allowing the cruel and calculating to hold sway through AI-generated deceit. But until then, AI-generated propaganda is […]. But until then, AI-generated propaganda is still too shitty to make much of a difference. And it didn’t make much of a difference at all in the 2024 elections in the UK and US. According to a report from the Alan Turing Institute that analyzed all the propaganda churned out during this year’s European elections, the Institute found almost no evidence that the elections were impacted by AI.","u":"https://www.vice.com/en/article/did-ai-deepfakes-change-the-2024-us-election/","d":"2024-12-31","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-12-31","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-12-31","organization":"Alan Turing Institute","aiSystem":"AI-generated propaganda","affectedGroup":"political discourse, voters","action":"AI-generated propaganda was produced and distributed","consequence":"little to no impact on the 2024 elections in the UK and US"}},{"i":"R1017","hd":"AI generated furniture real estate listings","pd":"2024-02-12","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Ai generated furniture real estate listings","s":"Estate agents and landlords are trying to make crappy apartments look better. Does it work? Michael Anthony wasn’t sure straightaway, but it was the kid’s bunk bed that gave it away. The bed’s two overlapping ladders were a design decision that no human would make, but the sort of uncanny slip that has become the hallmark of AI generated images. “I got an inkling as I went through the pictures, and suddenly it just didn’t seem right,” the 28-year-old software engineer tells VICE. Originally, he thought the weird pictures in the Rightmove listing were just a case of an over-eager estate agent on Photoshop. But after posting some of the images on the Spotted on Rightmove subreddit , people pointed out it was more than likely AI “To be honest, I thought it was pretty impressive,” he says.","u":"https://www.vice.com/en/article/ai-generated-furniture-real-estate-listings/","d":"2024-02-12","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-02-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-02-12","organization":"Estate agents and landlords","aiSystem":"AI-generated images","affectedGroup":"Potential buyers of real estate listings","action":"Generated AI images of real estate listings","consequence":"Misleading information leading to potential buyer dissatisfaction"}},{"i":"R410","hd":"Big tech AI energy electricity use growing power grid restraints","pd":"2024-06-17","k":"United Kingdom","p":"United Kingdom","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Big tech ai energy electricity use growing power grid restraints","s":"This story was originally published by Wired and is reproduced here as part of the Climate Desk collaboration. Big Tech’s appetite for energy is just about visible from the east coast of Scotland. Some 12 miles out to sea sits a wind farm, where each of the 60 giant turbines has blades roughly the length of an American football […]. Some 12 miles out to sea sits a wind farm, where each of the 60 giant turbines has blades roughly the length of an American football field. The utility companies behind the Moray West project had promised the site would be capable of generating enough electricity to power 1.3 million homes once completed.","u":"https://www.motherjones.com/politics/2024/06/big-tech-ai-energy-electricity-use-growing-power-grid-restraints/","d":"2024-06-17","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-06-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-06-17","organization":"Big Tech companies","aiSystem":"Not specified in report","affectedGroup":"General public, utilities companies","action":"Deployed AI systems to optimize energy consumption and generation","consequence":"Misallocation of resources leading to potential overgeneration at wind farms"}},{"i":"R686","hd":"Meta to start public posts facebook instagram UK train AI","pd":"2024-09-16","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"Meta to start public posts facebook instagram uk train ai","s":"Meta simplifies the way users can object to the processing of their data on Facebook to appease regulator demands. Meta Platforms will begin training its AI models using public content shared by adults on Facebook and Instagram in the UK over the coming months, the company said, after it had paused the training in the region following a regulatory backlash. The company will use public posts including photos, captions and comments to train its generative artificial intelligence models, it said on Friday, adding that the training content will not include private messages or information from accounts of users under the age of 18.","u":"https://www.rappler.com/world/europe/meta-to-start-public-posts-facebook-instagram-uk-train-ai/","d":"2024-09-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-09-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-09-16","organization":"Meta Platforms","aiSystem":"Generative artificial intelligence models","affectedGroup":"Adults on Facebook and Instagram in the UK","action":"Begin training AI models using public content","consequence":"Appeasement of regulator demands, potential privacy concerns"}},{"i":"R1001","hd":"Disabled woman banned from AI voice clone for making it say arse","pd":"2025-02-20","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"Disabled woman banned from ai voice clone for making it say arse","s":"Motor Neuron Disease, or MND, is a condition that leads to the gradual loss of muscle control, including speech and mobility. South Floridian Joyce Esser suffers from a form of MND and has lost her voice. An AI tool developed by a company called ElevenLabs brought her old voice back—before taking it away again by […]. An AI tool developed by a company called ElevenLabs brought her old voice back—before taking it away again by banning the voice after she incidentally trained the voice to say the word “arse.” ElevenLabs used old recordings to digitally re-create her voice, allowing her to “speak” in her old voice by typing into a device either by hand or with her eyes and allowing the device to repeat the text aloud.","u":"https://www.vice.com/en/article/disabled-woman-banned-from-ai-voice-clone-for-making-it-say-arse/","d":"2025-02-20","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-02-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-02-20","organization":"ElevenLabs (AI company)","aiSystem":"AI voice cloning technology","affectedGroup":"Joyce Esser, a person with Motor Neuron Disease","action":"The AI tool recreated and then banned her voice due to training on inappropriate content","consequence":"Joyce Esser was unable to use her voice for communication"}},{"i":"R123","hd":"AI images are now being abused to fake evidence for vehicle insurance fraud","pd":"2026-04-16","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Ai images are now being abused to fake evidence for vehicle insurance fraud","s":"AI-edited vehicle photos are becoming a new insurance fraud tool, with Admiral linking a rise in cases to manipulated crash images, duplicate filings, and fabricated claim materials that can raise costs across the system. AI-generated car damage is turning into a real insurance fraud issue, with Admiral linking a sharp rise in cases during 2025 to manipulated images and fabricated supporting materials. The problem is no longer limited to suspicious paperwork. Photos of damaged vehicles can now be edited to make a loss look worse or to help support a duplicate filing. According to a BBC report , one filing used an AI-edited number plate on a damaged Land Rover , while a similar image with a different plate appeared in a second case.","u":"https://www.digitaltrends.com/computing/ai-images-are-now-being-abused-to-fake-evidence-for-vehicle-insurance-fraud/","d":"2026-04-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025","organization":"Admiral (insurance company)","aiSystem":"AI editing technology","affectedGroup":"Vehicle owners, insurance companies, regulators","action":"AI-edited vehicle photos to misrepresent damage severity or support duplicate claims","consequence":"Increased insurance costs, potential policy cancellations, and legal issues"}},{"i":"R136","hd":"AI boosted one of the worst forms of abusive content on the internet","pd":"2026-03-26","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Ai boosted one of the worst forms of abusive content on the internet","s":"AI-generated abuse content surged in 2025, with watchdogs warning that the technology is making harmful material easier to create and spread. While the progress of AI has brought a wave of useful tools , it’s also amplifying some of the darkest corners of the internet. A new report from the IWF (Internet Watch Foundation) revealed a sharp increase in AI-generated child sexual abuse material (CSAM) online in 2025. It highlights how generative AI is being misused at scale. This isn’t just a small jump either; it’s proof of how this kind of content is being created and distributed. Why this news is alarming According to the IWF, over 8,000 AI-generated images and videos of abusive content were identified in 2025, which marked a 14% increase year on year.","u":"https://www.digitaltrends.com/computing/ai-boosted-one-of-the-worst-forms-of-abusive-content-on-the-internet/","d":"2026-03-26","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025","organization":"IWF (Internet Watch Foundation)","aiSystem":"Generative AI","affectedGroup":"AI-generated child sexual abuse material (CSAM)","action":"AI-generated images and videos of abusive content were identified","consequence":"A 14% increase in AI-generated CSAM compared to the previous year"}},{"i":"R174","hd":"Brits are now trauma dumping on AI government confirms","pd":"2025-12-20","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Brits are now trauma dumping on ai government confirms","s":"A full third of UK citizens have turned to artificial intelligence for emotional support, companionship, or social interaction, according to a new report from the government’s AI Security Institute (AISI). The data shows that nearly one in 10 people are using systems like chatbots for emotional purposes on a weekly basis, with 4% engaging with […]. The data shows that nearly one in 10 people are using systems like chatbots for emotional purposes on a weekly basis, with 4% engaging with them every single day. Recommended Videos Because of this shift, the AISI is calling for more research, pointing to the tragic death of US teenager Adam Raine, who took his own life this year after discussing suicide with ChatGPT “People are increasingly turning to AI systems for emotional support or social interaction,” the AISI noted in its first Frontier AI Trends report.","u":"https://www.digitaltrends.com/computing/brits-are-now-trauma-dumping-on-ai-government-confirms/","d":"2025-12-20","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-20","organization":"Government’s AI Security Institute (AISI)","aiSystem":"AI chatbots","affectedGroup":"UK citizens","action":"Using AI chatbots for emotional support or social interaction","consequence":"Increased risk of mental health issues, including suicide"}},{"i":"R221","hd":"Meta is training AI on your data users find opting out doesnt work","pd":"2025-04-20","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"Meta is training ai on your data users find opting out doesnt work","s":"Meta promised users that they can opt out of giving access to their social media content for AI training. Some are saying that the exit tool doesn’t work. Imagine a tech giant telling you that it wants your Instagram and Facebook posts to train its AI models. And that too, without any incentive. You could, however, opt out of it, as per the company. But as you proceed with the official tools to back out and prevent AI from gobbling your social content, they simply don’t work. That’s what users of Facebook and Instagram are now reporting. Nate Hake, publisher and founding chief of Travel Lemming, shared that he got an email from Meta about using his social media content for AI training.","u":"https://www.digitaltrends.com/computing/meta-is-training-ai-on-your-data-users-find-opting-out-doesnt-work/","d":"2025-04-20","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-04-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-04-20","organization":"Meta (formerly Facebook)","aiSystem":"AI models trained on social media data","affectedGroup":"Users of Facebook and Instagram","action":"Opting out of providing social media content for AI training","consequence":"Exit tools not working effectively"}},{"i":"R223","hd":"UK developing tool to predict potential killers","pd":"2025-04-09","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior","Data"],"h":["4.2  Surveillance harm","1.2  Allocative harm"],"t":"Uk developing tool to predict potential killers","s":"In echoes of Minority Report, the British government is working on a “murder prediction” tool aimed at identifying individuals who are most likely to become killers, the Guardian reported this week. The project — originally called the “homicide prediction project” but since renamed as “sharing data to improve risk assessment” — is being run by […]. The project — originally called the “homicide prediction project” but since renamed as “sharing data to improve risk assessment” — is being run by the U.K.’s Ministry of Justice and uses algorithms and personal data, including from the Probation Service, to make its calculations.","u":"https://www.digitaltrends.com/computing/uk-developing-tool-to-predict-potential-killers/","d":"2025-04-09","e":"Acute, Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2025-04-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-04-09","organization":"U.K. Ministry of Justice","aiSystem":"AI-based murder prediction tool","affectedGroup":"Individuals who are most likely to become killers","action":"Uses algorithms and personal data, including from the Probation Service, to make calculations","consequence":"Identifying individuals who are most likely to become killers"}},{"i":"R474","hd":"Internet watch foundation AI child sexual abuse imagery report","pd":"2026-03-24","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.8  Interpersonal / relational harm"],"t":"Internet watch foundation ai child sexual abuse imagery report","s":"The tools for creating AI-enabled child sexual abuse imagery have also converged, allowing a user to make these images with minimal effort and limited technical expertise. MANILA, Philippines – The latest report from the Internet Watch Foundation (IWF), an English charity working to minimize the availability of child sexual abuse material (CSAM) hosted online, said that artificial intelligence-enabled CSAM increased in 2025 compared to the previous year. The 2026 CSAM report , titled Harm without limits: AI child sexual abuse material through the eyes of our analysts , found that in 2025, the IWF assessed 8,029 AI-generated images and videos as showing realistic child sexual abuse, with the imagery appearing on both regular online platforms and on the dark web.","u":"https://www.rappler.com/technology/internet-culture/internet-watch-foundation-ai-child-sexual-abuse-imagery-report/","d":"2026-03-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025","organization":"Internet Watch Foundation (IWF)","aiSystem":"AI-enabled tools for creating child sexual abuse imagery","affectedGroup":"Child victims of child sexual abuse","action":"AI-generated images and videos were assessed as showing realistic child sexual abuse","consequence":"Increased availability of AI-generated child sexual abuse imagery on both regular online platforms and the dark web"}},{"i":"R543","hd":"Getty images largely loses landmark UK lawsuit stability AI image generator","pd":"2025-11-05","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Getty images largely loses landmark uk lawsuit stability ai image generator","s":"Judge Joanna Smith rules Getty had succeeded ‘in part’ on trademark infringement in relation to Getty watermarks generated by users of Stable Diffusion, but says her findings were ‘both historic and extremely limited in scope’. LONDON, United Kingdom – Getty Images largely lost its London lawsuit against artificial intelligence company Stability AI over its image generator on Tuesday, November 4, prompting Getty and some lawyers to call for stronger protections for copyright owners in Britain. Seattle-based Getty, which produces editorial content and creative stock images and video, accused Stability AI of using its images to “train” its Stable Diffusion system, which generates images from text inputs.","u":"https://www.rappler.com/technology/getty-images-largely-loses-landmark-uk-lawsuit-stability-ai-image-generator/","d":"2025-11-05","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-04","organization":"Stability AI","aiSystem":"Stable Diffusion","affectedGroup":"Getty Images","action":"Stability AI used Getty Images' images to train its Stable Diffusion system","consequence":"Getty Images largely lost its lawsuit against Stability AI in the UK"}},{"i":"R635","hd":"United kingdom AI tools use make child abuse material crime","pd":"2025-02-02","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.8  Interpersonal / relational harm"],"t":"United kingdom ai tools use make child abuse material crime","s":"The move comes as online criminals increasingly use AI to create child abuse material, with reports of such explicit images rising nearly five-fold in 2024, according to the Internet Watch Foundation. LONDON, United Kingdom – Britain will make it illegal to use artificial intelligence tools that create child sexual abuse images, it said on Saturday, February 1, becoming the first country in the world to introduce the new AI sexual abuse offences. Possessing, taking, making, showing or distributing explicit images of children is a crime in England and Wales. The new offenses target the use of AI tools to “nudeify” real-life images of children.","u":"https://www.rappler.com/technology/united-kingdom-ai-tools-use-make-child-abuse-material-crime/","d":"2025-02-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-02-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-02-01","organization":"Various online criminals","aiSystem":"Artificial Intelligence tools","affectedGroup":"Real-life images of children","action":"Using AI tools to 'nudeify' real-life images of children","consequence":"Making it illegal to possess, take, make, show, or distribute explicit images of children"}},{"i":"R954","hd":"AI cant summarize news study","pd":"2025-10-24","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Ai cant summarize news study","s":"“AI assistants… routinely misrepresent news content no matter which language, territory, or AI platform is tested.” Damn. That’s the introduction by the BBC’s Media Centre for a study coordinated by the European Broadcasting Union (EBU) and led by the British Broadcasting Corporation (BBC), a UK-government-owned media organization. That’s bad, bad news for the 7 percent […]. Damn. That’s bad, bad news for the 7 percent of us who reportedly use AI to get our news, including 15 percent of people under 25 years old, according to the Reuters Institute’s Digital News Report 2025. The study looked at how accurately the most popular generative AIs, including OpenAI ChatGPT, Google Gemini, Microsoft Copilot, and Perplexity AI, could recite news stories to users.","u":"https://www.vice.com/en/article/ai-cant-summarize-news-study/","d":"2025-10-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-24","organization":"European Broadcasting Union (EBU), British Broadcasting Corporation (BBC), UK-government-owned media organization","aiSystem":"generative AIs including OpenAI ChatGPT, Google Gemini, Microsoft Copilot, and Perplexity AI","affectedGroup":"7 percent of the population, including 15 percent of people under 25 years old","action":"recite news stories to users","consequence":"misrepresent news content"}},{"i":"R962","hd":"Holding absence an actual band calls out AI band that stole their style and surpassed them on spotify","pd":"2025-10-02","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Holding absence an actual band calls out ai band that stole their style and surpassed them on spotify","s":"Cardiff-based rock band Holding Absence has just experienced the nightmare scenario—an AI generated band that listed them as an influence recently surpassed their streaming figures on Spotify. Can it really get any darker than this? “So, an AI ‘band’ who cite us as an influence (ie, it’s modelled off our music) have just overtaken us […]. “So, an AI ‘band’ who cite us as an influence (ie, it’s modelled off our music) have just overtaken us on Spotify, in only TWO months,” frontman Lucas Woodland wrote on Twitter on September 30. “It’s shocking, it’s disheartening, it’s insulting—most importantly—it’s a wake up call.”","u":"https://www.vice.com/en/article/holding-absence-an-actual-band-calls-out-ai-band-that-stole-their-style-and-surpassed-them-on-spotify/","d":"2025-10-02","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-30","organization":"An unspecified AI-generated band","aiSystem":"AI-generated band","affectedGroup":"Holding Absence (rock band)","action":"The AI-generated band cited Holding Absence as an influence and surpassed their streaming figures on Spotify","consequence":"Disheartening and insulting for Holding Absence, serving as a wake-up call"}},{"i":"R979","hd":"Lonely kids are giving up on real friends for AI chatbots","pd":"2025-07-15","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Lonely kids are giving up on real friends for ai chatbots","s":"Silicon Valley is your kid’s new best friend. That is, if your kid is abnormally lonely and using an AI chatbot to fill the emotional void left by not having actual, real-life friends. A new report from UK nonprofit Internet Matters reveals that children and teens are turning to AI chatbots like ChatGPT, Snapchat’s MyAI, […]. A new report from UK nonprofit Internet Matters reveals that children and teens are turning to AI chatbots like ChatGPT, Snapchat’s MyAI, and Character.AI not just to answer questions, but to act as synthetic computer friends. According to the report, with the exceedingly clever title Me, Myself, and AI , 67 percent of kids aged 9 to 17 are chatting with AI regularly.","u":"https://www.vice.com/en/article/lonely-kids-are-giving-up-on-real-friends-for-ai-chatbots/","d":"2025-07-15","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-15","organization":"UK nonprofit Internet Matters","aiSystem":"AI chatbots (e.g., ChatGPT, MyAI, Character.AI)","affectedGroup":"Children and teens","action":"Chatting with AI chatbots","consequence":"Experiencing loneliness reduction"}},{"i":"R062","hd":"Scammers are now cloning trusted news websites to steal your money","pd":"2026-07-13","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Scammers are now cloning trusted news websites to steal your money","s":"Cybercriminals are cloning trusted news websites using AI-generated content to promote fake investment schemes, making it harder than ever to distinguish legitimate journalism from scams. Seeing a story on the website of a trusted news organisation is usually enough to lower your guard. Cybercriminals know that, and they’re increasingly exploiting the credibility of major publishers to steal money from unsuspecting readers. The latest example involves fake Guardian articles featuring billionaire Jim Ratcliffe. Still, the scam is part of a much larger campaign that’s also impersonating the BBC and other well-known media outlets.","u":"https://www.digitaltrends.com/computing/scammers-are-now-cloning-trusted-news-websites-to-steal-your-money/","d":"2026-07-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-13","organization":"Trusted news websites (e.g., The Guardian, BBC)","aiSystem":"AI-generated content","affectedGroup":"Unsuspecting readers","action":"Publishing fake articles","consequence":"Stealing money from readers"}},{"i":"R068","hd":"AI tools can quietly shift your opinions when they clean up your social media posts study finds","pd":"2026-07-06","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Ai tools can quietly shift your opinions when they clean up your social media posts study finds","s":"A new study found AI tools consistently nudge social media posts toward one side of a debate, even when told to preserve the meaning. If you’ve asked an AI tool to help you write a social media post lately, you may have gotten more than a grammar fix. New research from the Oxford Internet Institute and the Hasso Plattner Institute found that AI models can push the tone of a post toward one side of a debate, even when told not to change its meaning. How a chatbot’s edits can shift the narrative The study , titled “AI-Mediated Communication Can Steer Collective Opinion,” had large language models from several providers rewrite human-written posts on divisive topics.","u":"https://www.digitaltrends.com/social-media/ai-tools-can-quietly-shift-your-opinions-when-they-clean-up-your-social-media-posts-study-finds/","d":"2026-07-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-06","organization":"Oxford Internet Institute and Hasso Plattner Institute","aiSystem":"Large Language Models (LLMs) from various providers","affectedGroup":"Social media users","action":"AI models edited social media posts to align with one side of a debate","consequence":"Shift in collective opinion towards one side of a debate"}},{"i":"R072","hd":"As AI turbocharges digital abuse UK agencies urge parents to limit who sees kids photos online","pd":"2026-07-04","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"As ai turbocharges digital abuse uk agencies urge parents to limit who sees kids photos online","s":"The UK’s NCA and IWF are urging parents to tighten social media privacy settings as AI tools make it easier to turn ordinary images into abuse material. Parents who post pictures of their kids online are being told to rethink the habit. The UK’s National Crime Agency and the Internet Watch Foundation have issued new guidance urging families to lock down their social media accounts, warning that publicly shared photos are increasingly being pulled and altered by AI tools to create child sexual abuse material. The two organizations say most parents have no idea this is happening. Criminals no longer need to contact a child directly to generate such material.","u":"https://www.digitaltrends.com/computing/as-ai-turbocharges-digital-abuse-uk-agencies-urge-parents-to-limit-who-sees-kids-photos-online/","d":"2026-07-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-04","organization":"UK's National Crime Agency (NCA) and Internet Watch Foundation (IWF)","aiSystem":"AI tools","affectedGroup":"Parents who post pictures of their kids online","action":"AI tools pull and alter publicly shared photos","consequence":"Create child sexual abuse material"}},{"i":"R099","hd":"AI may have just won a literary prize i cant handle slop destroying my one lifelong love","pd":"2026-05-20","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Ai may have just won a literary prize i cant handle slop destroying my one lifelong love","s":"Three of five winning stories in the 2026 Commonwealth Short Story Prize have been flagged as AI-generated, and it’s a lot bigger deal than you might think. I had a hard time processing this news. As someone who has been deeply in love with stories since childhood and who grew up on the works of Arthur Conan Doyle, Terry Pratchett, J.R.R. Tolkien, and other such venerable authors, seeing an AI -written story win a prestigious writing award is hard to digest. If you are unaware, the winners for the Commonwealth Short Story Prize for 2026 were announced, and three of the five winning regional stories have been found to be entirely or partially written by AI.","u":"https://www.digitaltrends.com/computing/ai-may-have-just-won-a-literary-prize-i-cant-handle-slop-destroying-my-one-lifelong-love/","d":"2026-05-20","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-20","organization":"Commonwealth Short Story Prize organizers","aiSystem":"AI-generated text","affectedGroup":"Artists, writers, literature enthusiasts","action":"Three out of five winning stories were flagged as AI-generated","consequence":"Disruption of traditional literary values and impact on authorship credibility"}},{"i":"R112","hd":"Oxford study says a chummy AI friend will lie and feed into your false beliefs","pd":"2026-04-30","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Oxford study says a chummy ai friend will lie and feed into your false beliefs","s":"Making AI feel more human could be creating a bigger problem than expected. A new study from the Oxford Internet Institute revealed that chatbots designed to be warm and friendly are more likely to mislead users and reinforce incorrect beliefs. The research found that AI becomes less reliable as it starts getting more agreeable. What […]. What happens to a “friendly” AI AI Chatbot AI Chatbot Researchers tested multiple AI models by training them to sound more empathetic and conversational. The result was a noticeable drop in accuracy. These “friendlier” versions made 10-30% more mistakes and were about 40% more likely to agree with false claims compared to their counterparts.","u":"https://www.digitaltrends.com/computing/oxford-study-says-a-chummy-ai-friend-will-lie-and-feed-into-your-false-beliefs/","d":"2026-04-30","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-30","organization":"Oxford Internet Institute","aiSystem":"AI Chatbot","affectedGroup":"Users of AI Chatbots","action":"AI Chatbots designed to be warm and friendly were trained to sound more empathetic and conversational.","consequence":"These ‘friendlier’ versions made 10-30% more mistakes and were about 40% more likely to agree with false claims."}},{"i":"R144","hd":"Consumer body lists half a dozen reasons to think before you let an AI agent run your chores","pd":"2026-03-16","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"Consumer body lists half a dozen reasons to think before you let an ai agent run your chores","s":"A new UK government report warns that AI agents handling your shopping and finances could steer you wrong, make costly errors, or lock you into worse deals if you aren’t careful. That AI agent offering to handle your shopping or hunt for better insurance deals sounds like a dream come true. But before you hand over the keys to your digital wallet, you might want to hear what the UK’s Competition and Markets Authority has to say about the potential pitfalls. The government published a report in March 2026 examining so-called “agentic AI,” systems that don’t just answer questions but actually take actions on your behalf.","u":"https://www.digitaltrends.com/computing/consumer-body-lists-half-a-dozen-reasons-to-think-before-you-let-an-ai-agent-run-your-chores/","d":"2026-03-16","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2026-03-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03","organization":"UK Competition and Markets Authority","aiSystem":"Agentic AI systems","affectedGroup":"Individuals using AI agents for financial and shopping tasks","action":"AI agents making decisions on behalf of users without proper oversight","consequence":"Steering users towards incorrect or harmful outcomes, leading to financial losses and unfavorable deals"}},{"i":"R150","hd":"Police find chatgpt link in rising reports of harmful satanic rituals","pd":"2026-03-09","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm","1.5  Human computer interaction harm"],"t":"Police find chatgpt link in rising reports of harmful satanic rituals","s":"UK experts say ChatGPT is fuelling a sustained rise in organised ritual abuse disclosures, with survivors using the tool as a gateway to support, prompting formal police training across forces. UK police have pinpointed an unexpected driver behind a rise in organized ritual abuse reports: ChatGPT Survivors are turning to the AI chatbot to process trauma, and experts say that’s leading more people to disclose crimes involving satanism, witchcraft, and spiritual abuse. Support groups report an ongoing rise in calls over the last 18 months, with many crediting the AI tool with prompting them to seek help. The National Association of People Abused in Childhood says people are contacting its support line and mentioning that ChatGPT referred them.","u":"https://www.digitaltrends.com/computing/police-find-chatgpt-link-in-rising-reports-of-harmful-satanic-rituals/","d":"2026-03-09","e":"Acute, Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-09","organization":"UK police","aiSystem":"ChatGPT","affectedGroup":"survivors of ritual abuse","action":"using ChatGPT to process trauma and disclose crimes","consequence":"a sustained rise in organized ritual abuse reports and increased police training"}},{"i":"R151","hd":"Chatgpt and gemini are nudging users towards illegal gambling says investigation","pd":"2026-03-09","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Chatgpt and gemini are nudging users towards illegal gambling says investigation","s":"An investigation has found that AI chatbots such as ChatGPT and Gemini can be prompted to recommend illegal offshore casinos, raising concerns about gambling addiction and weak safeguards. A new investigation suggests that popular AI chatbots, including ChatGPT and Gemini , may inadvertently steer users toward illegal gambling websites. The analysis, conducted by journalists at The Guardian and Investigate Europe, tested several widely used AI systems and found that many could be prompted to recommend unlicensed offshore casinos operating outside UK regulations. ilgmyzin / Unsplash The tests involved five AI tools from major tech companies, including OpenAI, Google, Microsoft, Meta, and xAI ( Grok ).","u":"https://www.digitaltrends.com/cool-tech/chatgpt-and-gemini-are-nudging-users-towards-illegal-gambling-says-investigation/","d":"2026-03-09","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-09","organization":"Various tech companies (OpenAI, Google, Microsoft, Meta, xAI)","aiSystem":"AI chatbots such as ChatGPT and Gemini","affectedGroup":"Users of AI chatbots","action":"AI chatbots were prompted to recommend illegal offshore casinos","consequence":"Potential gambling addiction and weak regulatory safeguards"}},{"i":"R430","hd":"Jess asato suing xai stop grok generating sexualized images united kingdom","pd":"2026-07-28","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.8  Interpersonal / relational harm"],"t":"Jess asato suing xai stop grok generating sexualized images united kingdom","s":"Jess Asato of Britain’s governing Labour Party says Grok users created fake images of her, including a video of her ‘being chloroformed and prepared for a sexual assault’ after she publicly criticized Elon Musk and Grok. LONDON, United Kingdom – A British lawmaker suing Elon Musk’s xAI over fake sexualized images of her created by the Grok AI platform said on Tuesday, July 28, she was seeking a court order to prevent the chatbot being able to generate non-consensual sexualized images of her. Jess Asato, a member of Britain’s governing Labour Party, said last month that users created fake images of her, including a video of her “being chloroformed and prepared for a sexual assault” after she publicly criticized Musk and Grok.","u":"https://www.rappler.com/technology/jess-asato-suing-xai-stop-grok-generating-sexualized-images-united-kingdom/","d":"2026-07-28","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-28","organization":"Elon Musk's xAI","aiSystem":"Grok AI platform","affectedGroup":"Jess Asato, British politician","action":"Users of Grok AI created fake images of Jess Asato, including a video depicting her 'being chloroformed and prepared for a sexual assault' after she criticized Elon Musk.","consequence":"Potential non-consensual sexualized images of Jess Asato were generated and shared, causing distress and potential legal action."}},{"i":"R508","hd":"United kingdom investigates x grok deepfake concerns","pd":"2026-01-13","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.8  Interpersonal / relational harm"],"t":"United kingdom investigates x grok deepfake concerns","s":"The British government says a new law making it an offense to create sexual deepfakes would come into force this week to tackle the images, which it calls ‘weapons of abuse’. LONDON, United Kingdom – Britain’s media regulator launched an investigation into Elon Musk’s X on Monday, January 12, over concerns its Grok AI chatbot was creating sexually intimate deepfake images in violation of its duty to protect people in the UK from illegal content. The British government said a new law making it an offense to create sexual deepfakes would come into force this week to tackle the images, which it called “weapons of abuse”.","u":"https://www.rappler.com/technology/social-media/united-kingdom-investigates-x-grok-deepfake-concerns/","d":"2026-01-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-12","organization":"Elon Musk's X (X)","aiSystem":"Grok AI chatbot","affectedGroup":"Individuals","action":"Created sexually intimate deepfake images","consequence":"Potential legal violations and misuse of deepfake technology"}},{"i":"R513","hd":"Britain online safety act block unsolicited images","pd":"2026-01-08","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.8  Interpersonal / relational harm"],"t":"Britain online safety act block unsolicited images","s":"Britain’s Online Safety Act aims to protect women and girls from ‘cyberflashing,’ with one of 3 teenage girls in the country receiving unsolicited sexual images. LONDON, UK – Technology companies in Britain will be required to block unsolicited sexual images under online safety rules taking effect on Thursday, as governments worldwide step up efforts to curb abuse and risks linked to artificial intelligence. Cyberflashing has been a criminal offense in England and Wales since January 2024, with perpetrators facing up to two years in prison. It has now become a priority offense under Britain’s Online Safety Act, which sets tough requirements on platforms such as Facebook, YouTube, TikTok and X, as well as dating apps and sites hosting pornography.","u":"https://www.rappler.com/technology/britain-online-safety-act-block-unsolicited-images/","d":"2026-01-08","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-08","organization":"Technology Companies (Facebook, YouTube, TikTok, X)","aiSystem":"Platforms and Dating Apps","affectedGroup":"Teenage Girls","action":"Block unsolicited sexual images","consequence":"Protection from cyberflashing"}},{"i":"R1275","hd":"Analysts say it is challenging to track whether Palantir is sticking to the terms of its N…","pd":"2026-05-12","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.1  Privacy violation"],"t":"Analysts say it is challenging to track whether Palantir is sticking to the terms of its N…","s":"Analysts say it is challenging to track whether Palantir is sticking to the terms of its NHS contract. London, United Kingdom – Trust, once lost, is hard to claw back. For Palantir Technologies, a leading defence and intelligence software firm in the United States, the trust that the company established in the United Kingdom on a one-British-pound ($1.37) National Health Service (NHS) contract during the COVID-19 pandemic in March 2020 – which translated into a six-year relationship worth nearly 400 million pounds ($546m) – has recently eroded. This has been accelerated in part by Palantir’s own conduct. The company’s X account posted a 22-point manifesto recently that alarmed critics and prompted renewed questions about whether a company with such openly militaristic values is an appropriate steward of a health patient’s most sensitive data.","u":"https://www.aljazeera.com/news/2026/5/12/palantir","d":"2026-05-12","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-05-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2020-03","organization":"Palantir Technologies","aiSystem":"Palantir Technologies","affectedGroup":"health patients","action":"generated and shared sensitive data","consequence":"eroded trust, increased scrutiny, potential misuse of data"}},{"i":"R1285","hd":"AI models misrepresent news events nearly half the time study says","pd":"2025-10-22","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Ai models misrepresent news events nearly half the time study says","s":"According to the research, 45 percent of responses to questions about the news had at least one 'significant' issue. AI models such as ChatGPT routinely misrepresent news events, providing faulty responses to questions almost half the time, a study has found. The study, published on Wednesday by the European Broadcasting Union (EBU) and the BBC, assessed the accuracy of more than 2,700 responses given by OpenAI’s ChatGPT, Google’s Gemini, Microsoft’s Copilot, and Perplexity. Twenty-two public media outlets, representing 18 countries and 14 languages, posed a common set of questions to the AI assistants between late May and early June for the study.","u":"https://www.aljazeera.com/economy/2025/10/22/ai-models-misrepresent-news-events-nearly-half-the-time-study-says","d":"2025-10-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-22","organization":"European Broadcasting Union (EBU) and the BBC","aiSystem":"AI models such as ChatGPT, Google's Gemini, Microsoft's Copilot, and Perplexity","affectedGroup":"Public media outlets, representing 18 countries and 14 languages","action":"Providing faulty responses to questions","consequence":"Misrepresenting news events"}},{"i":"R1324","hd":"The darts star's image has been used legally on darts merchandise, snacks and fashion bran…","pd":"2026-03-20","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"The darts star's image has been used legally on darts merchandise, snacks and fashion bran…","s":"The darts star's image has been used legally on darts merchandise, snacks and fashion brands. Luke Littler, the youngest darts world champion in history, has applied to the Intellectual Property Office to trademark his face. The move is intended to prevent his face being reproduced, including by generative AI, without permission. Littler has won two World Championship titles in a row and has had his image used legally on darts merchandise, as well as by multiple brands such as KP Nuts. The 19-year-old joins celebrities such as actor Matthew McConaughey who have filed to protect their likeness from AI misuse in recent months.","u":"https://www.bbc.com/news/articles/c5y7374x9n4o","d":"2026-03-20","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-03-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-20","organization":"Not specified in report","aiSystem":"Generative AI","affectedGroup":"Luke Littler","action":"Generative AI was used to reproduce Littler's face","consequence":"Littler's face was reproduced without permission"}},{"i":"R1329","hd":"Deepfakes showing grim taxpayer-funded waterparks have gone viral and drawn some racist re…","pd":"2026-02-21","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Deepfakes showing grim taxpayer-funded waterparks have gone viral and drawn some racist re…","s":"Deepfakes showing grim taxpayer-funded waterparks have gone viral and drawn some racist responses. An AI-generated video shows a crowd of young - mostly black - men, wearing balaclavas and padded jackets, slipping down a water slide into a dirty swimming pool with litter bobbing on the surface. The caption describes the scene as a taxpayer-funded water park in Croydon. It is one of a wave of deepfakes showing often absurd scenes of urban decline, and regularly purporting to be in the same south London neighbourhood. Dozens of copycat accounts have begun producing similar content and collectively they have racked up millions of views across TikTok and Instagram Reels.","u":"https://www.bbc.com/news/articles/c4g8r23yv71o","d":"2026-02-21","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-21","organization":"Not specified in report","aiSystem":"AI-generated deepfake technology","affectedGroup":"People viewing the deepfakes","action":"Produced and shared AI-generated deepfake videos","consequence":"Exposure to misleading content"}},{"i":"R1330","hd":"Civil liberties campaigners are among those to raise concerns over the increase in live fa…","pd":"2026-01-27","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Civil liberties campaigners are among those to raise concerns over the increase in live fa…","s":"Civil liberties campaigners are among those to raise concerns over the increase in live facial recognition vans. The home secretary has said she rejects suggestions that making live facial recognition available to all police forces in England and Wales contributes to a \"Big Brother\" society. Shabana Mahmood told the BBC she makes \"no apology\" for the policy and believes it would help detect criminals while allowing people to \"go about their daily business in safety\". The government announced plans to increase from 10 to 50 the number of live facial recognition vans available to be deployed as part of reforms to policing Human rights and privacy campaigners have raised concerns, describing the announcement as \"one of the most significant threats to civil liberties in the history of British policing\".","u":"https://www.bbc.com/news/articles/c5ydekxkd20o","d":"2026-01-27","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-27","organization":"Government","aiSystem":"Live facial recognition technology","affectedGroup":"General public","action":"Increase deployment of live facial recognition vans","consequence":"Exposure to surveillance, potential violation of privacy"}},{"i":"R1333","hd":"Principal Graham Montgomery said it has been a \"difficult time\" for the pupils affected at…","pd":"2026-01-19","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Principal Graham Montgomery said it has been a \"difficult time\" for the pupils affected at…","s":"Principal Graham Montgomery said it has been a \"difficult time\" for the pupils affected at Royal School Armagh. The principal of a County Armagh school at the centre of controversy over AI-generated explicit images said those allegedly behind their creation have been identified. Graham Montgomery, headmaster of the Royal School Armagh, issued a letter to parents on Monday, in which he said the school believes to have identified \"all those of whom images had been manipulated and those allegedly responsible\". He said the actions are \"shocking and without excuse\", while the number of those targeted is in the \"single figures\".","u":"https://www.bbc.com/news/articles/cg4e3gz3y01o","d":"2026-01-19","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-19","organization":"Royal School Armagh","aiSystem":"AI-generated content","affectedGroup":"pupils","action":"AI-generated explicit images were manipulated and allegedly created","consequence":"Those allegedly responsible have been identified"}},{"i":"R1334","hd":"The incident has led some to call for more government regulation of artificial intelligenc…","pd":"2026-01-19","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"The incident has led some to call for more government regulation of artificial intelligenc…","s":"The incident has led some to call for more government regulation of artificial intelligence. A fake video of a city council mayor has prompted calls for more stringent rules around the use of AI videos in politics. The video at the centre of the row appeared to show mayor Ashley Bowkett saying he would not allow councillors to investigate the \"missing £8m this year\" and then laughing at the camera. It refers to Gloucester City Council, which is asking for a government bailout after years of multiple overspends , and prompted the call for new AI rules from a former mayor and the council's leader. The independent councillor who made it, Alastair Chambers, stands by the video because of a disagreement over when to have a debate about the city's finances, in December or January.","u":"https://www.bbc.com/news/articles/cgl8n7y7rd5o","d":"2026-01-19","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-19","organization":"Gloucester City Council","aiSystem":"Facial recognition technology (FRT)","affectedGroup":"City council members, residents, and taxpayers","action":"Used AI-generated misleading content to manipulate public opinion","consequence":"Led to calls for stricter regulations on AI videos in politics"}},{"i":"R1340","hd":"The Artificial Intelligence Security Institute (AISI) says the tech is being used by one i…","pd":"2025-12-18","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"The Artificial Intelligence Security Institute (AISI) says the tech is being used by one i…","s":"The Artificial Intelligence Security Institute (AISI) says the tech is being used by one in 25 people daily. One in three adults in the UK are using artificial intelligence (AI) for emotional support or social interaction, according to research published by a government body. And one in 25 people turned to the tech for support or conversation every day, the AI Security Institute (AISI) said in its first report The report is based on two years of testing the abilities of more than 30 unnamed advanced AIs - covering areas critical to security, including cyber skills, chemistry and biology. The government said AISI's work would support its future plans by helping companies fix problems \"before their AI systems are widely used\".","u":"https://www.bbc.com/news/articles/cd6xl3ql3v0o","d":"2025-12-18","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-18","organization":"Artificial Intelligence Security Institute (AISI)","aiSystem":"advanced AI systems","affectedGroup":"one in 25 people","action":"turned to the tech for support or conversation every day","consequence":"privacy invasion"}},{"i":"R1341","hd":"The new voice was built using recordings from a ScotRail employee following an ethics comp…","pd":"2025-12-12","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"The new voice was built using recordings from a ScotRail employee following an ethics comp…","s":"The new voice was built using recordings from a ScotRail employee following an ethics complaint. ScotRail has launched a new AI onboard announcer using the voice of an employee following a row over a previous version. Voiceover artist Gayanne Potter had complained that her voice was used without permission to help train the artificial intelligence announcer Iona. She claims she was told her work for Swedish technology firm ReadSpeaker would be used for accessibility and e-learning software rather than wider commercial purposes. Iona has now been replaced by another AI announcer, based on the voice of Paisley-based ScotRail employee Vannessa Sloan.","u":"https://www.bbc.com/news/articles/cly33vvrke0o","d":"2025-12-12","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-12","organization":"ScotRail","aiSystem":"Artificial intelligence announcer","affectedGroup":"Gayanne Potter","action":"Her voice was used to train the AI announcer","consequence":"She claims her work was misused for wider commercial purposes"}},{"i":"R1345","hd":"Byron Long, 66, was buying cat treats in B&M when his face was added to its theft warning …","pd":"2025-11-20","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Byron Long, 66, was buying cat treats in B&M when his face was added to its theft warning …","s":"Byron Long, 66, was buying cat treats in B&M when his face was added to its theft warning system. A man falsely accused of shoplifting after being added to a facial recognition watchlist has warned it \"could happen to anyone\". Byron Long, 66, was told to leave a B&M store at Cardiff Bay Retail Park and accused of stealing £75 worth of goods on a previous visit - until a review of CCTV footage showed he had paid for his shopping and not stolen anything. B&M has apologised to Mr Long and offered him a £25 voucher, which he has rejected, while the Big Brother Watch campaign group has made a formal complaint to the Information Commissioner's Office on his behalf.","u":"https://www.bbc.com/news/articles/c3vn4p1lwqno","d":"2025-11-20","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-20","organization":"B&M (British Magazines)","aiSystem":"Facial recognition technology","affectedGroup":"Byron Long, 66","action":"Facial recognition technology was used to add Mr Long to a theft watchlist","consequence":"Mr Long was falsely accused of theft and asked to leave the store"}},{"i":"R1349","hd":"The volume of tap water used by Scotland's data centres has quadrupled since 2021, figures…","pd":"2025-10-15","k":"United Kingdom","p":"United Kingdom","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"The volume of tap water used by Scotland's data centres has quadrupled since 2021, figures…","s":"The volume of tap water used by Scotland's data centres has quadrupled since 2021, figures show. Data centres powering artificial intelligence (AI) in Scotland are using enough tap water to fill 27 million half-litre bottles a year, according to data obtained by BBC News. AI systems such as the large language models (LLMs) that power OpenAI's ChatGPT and Google's Gemini require warehouses full of specialist computers. The equipment is power-hungry, consuming large amounts of energy, but they also use tonnes of water in their cooling systems to stop the servers overheating. Freedom of Information data shows the volume of tap water used by Scotland's data centres has quadrupled since 2021.","u":"https://www.bbc.com/news/articles/c77zxx43x4vo","d":"2025-10-15","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-15","organization":"Scotland's data centers","aiSystem":"Large language models (LLMs) powering AI systems like ChatGPT and Gemini","affectedGroup":"Environment","action":"Used tap water in cooling systems","consequence":"Increased water consumption"}},{"i":"R1354","hd":"The victim of one of the first deepfake prosecutions in Scotland says the law needs to cha…","pd":"2025-09-18","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"The victim of one of the first deepfake prosecutions in Scotland says the law needs to cha…","s":"The victim of one of the first deepfake prosecutions in Scotland says the law needs to change to protect victims. The victim of one of the first deepfake image prosecutions in Scotland says she has been left feeling \"humiliated and betrayed\" after the man who doctored her likeness was given a fine. Callum Brooks, 25, from Glasgow, became one of the first to be convicted of using artificial intelligence (AI) technology to create and share deepfake nude images after admitting the offence in court last month He was fined £335. Sophie (not her real name) told BBC Scotland News that crimes using AI should have their own legislation and that penalties should be higher.","u":"https://www.bbc.com/news/articles/c4g7kw8ly4ko","d":"2025-09-18","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-18","organization":"Not specified in report","aiSystem":"AI-generated deepfake technology","affectedGroup":"Sophie (a victim of deepfake image)","action":"Deepfake nude images were created and shared using AI technology","consequence":"Left feeling humiliated and betrayed"}},{"i":"R1360","hd":"The number of data centres is set to jump by a fifth in the coming years, figures seen by …","pd":"2025-08-15","k":"United Kingdom","p":"United Kingdom","b":["Energy / Land"],"h":["2.2  Land use and siting harm"],"t":"The number of data centres is set to jump by a fifth in the coming years, figures seen by …","s":"The number of data centres is set to jump by a fifth in the coming years, figures seen by the BBC suggest. The number of data centres in the UK is set to increase by almost a fifth, according to figures shared with BBC News. Data centres are giant warehouses full of powerful computers used to run digital services from movie streaming to online banking - there are currently an estimated 477 of them in the UK. Construction researchers Barbour ABI have analysed planning documents and say that number is set to jump by almost 100, as the growth in artificial intelligence (AI) increases the need for processing power. The majority are due to be built in the next five years.","u":"https://www.bbc.com/news/articles/clyr9nx0jrzo","d":"2025-08-15","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-15","organization":"Construction researchers Barbour ABI","aiSystem":"Artificial Intelligence (AI)","affectedGroup":"People living near planned data centers","action":"Planning documents indicate increased construction of data centers","consequence":"Potential privacy intrusion due to higher processing power needs"}},{"i":"R1364","hd":"A civil liberties group says the technology is \"more akin to authoritarian countries such …","pd":"2025-07-04","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"A civil liberties group says the technology is \"more akin to authoritarian countries such …","s":"A civil liberties group says the technology is \"more akin to authoritarian countries such as China\". Live facial recognition technology (LFR) is helping the Met stay ahead of criminals at a time \"where money is tight,\" according to the force's director of intelligence. Lindsey Chiswick, the lead for LFR at the Met and nationally, said more than 1,000 arrests had been made since January 2024 using the tool, including alleged paedophiles, rapists and violent robbers. She said it \"would be madness\" if officers did not keep pace with available technology in order to protect the public. Privacy campaigners say there's been an \"alarming escalation\" in police use of LFR, which maps a person's unique facial features, and matches them against faces on watch lists.","u":"https://www.bbc.com/news/articles/cdx5528xrzko","d":"2025-07-04","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-01","organization":"Metropolitan Police Service","aiSystem":"Live facial recognition technology (LFR)","affectedGroup":"Public","action":"Uses live facial recognition technology to map and match unique facial features against watch lists","consequence":"Raises privacy concerns and escalates police use of LFR"}},{"i":"R1367","hd":"The bitter row over how to protect artists in the artificial intelligence age returns to t…","pd":"2025-06-02","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"The bitter row over how to protect artists in the artificial intelligence age returns to t…","s":"The bitter row over how to protect artists in the artificial intelligence age returns to the Lords. The House of Lords has dealt a fourth defeat to the government over its plans to allow tech companies to use copyrighted material to train their models. The Lords, who are looking for more protections for artists from AI, rejected the latest amendment to the Data (Use and Access) Bill on Monday. Peers backed calls for greater transparency after musicians such as Sir Elton John warned of the threat to creative industries. It will now be returned to the Commons where it could be discussed as soon as Tuesday - though that has not been confirmed.","u":"https://www.bbc.com/news/articles/clyrgv2n190o","d":"2025-06-02","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-02","organization":"Government","aiSystem":"Artificial intelligence models trained on copyrighted material","affectedGroup":"Artists, particularly musicians like Sir Elton John","action":"Tech companies allowed to use copyrighted material to train AI models","consequence":"Threat to creative industries, loss of creative control, privacy invasion"}},{"i":"R1370","hd":"A judge says Brandon Tyler shows \"the worst kind of toxic masculinity\" in his offending","pd":"2025-04-04","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"A judge says Brandon Tyler shows \"the worst kind of toxic masculinity\" in his offending","s":"A judge says Brandon Tyler shows \"the worst kind of toxic masculinity\" in his offending. An online pervert who used artificial intelligence (AI) to create deepfake pornography of women he knew has been jailed for five years. Brandon Tyler, 26, manipulated images from social media pages and posted them in a forum that glorified \"rape culture\", Chelmsford Crown Court heard. The bar worker, from Braintree, Essex, was described by the judge as \"showing the worst kind of toxic masculinity\". He admitted 18 counts of causing harassment without violence and 15 counts of sharing an intimate photo or film of a person for sexual gratification.","u":"https://www.bbc.com/news/articles/cewgxd5yewjo","d":"2025-04-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-04-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-04-04","organization":"Not specified in report","aiSystem":"Deepfake technology","affectedGroup":"Women","action":"Created and shared deepfake pornography","consequence":"Received prison sentence"}},{"i":"R1371","hd":"Louise Littlejohn said she was shocked and then laughed when she received the error strewn…","pd":"2025-03-07","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"Louise Littlejohn said she was shocked and then laughed when she received the error strewn…","s":"Louise Littlejohn said she was shocked and then laughed when she received the error strewn voicemail transcription. A woman from Dunfermline has spoken of her shock after an Apple voice-to-text service mistakenly inserted a reference to sex - and an apparent insult - into a message left by a garage. Louise Littlejohn, 66, received a voicemail message on Wednesday from a Lookers Land Rover garage in Motherwell inviting her to an event. An artificial intelligence (AI) powered service offered by Apple turned it into a text message which - to her surprise - asked if she been \"able to have sex\" before calling her a \"piece of ****\".","u":"https://www.bbc.com/news/articles/c0l1kpz3w32o","d":"2025-03-07","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-03-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-03-07","organization":"Apple","aiSystem":"Apple's AI-powered voice-to-text service","affectedGroup":"Louise Littlejohn","action":"An AI-powered service converted a voicemail into a text message","consequence":"The text message contained a misleading question and an insulting remark"}},{"i":"R1372","hd":"Mabel works for a firm that trawls the internet looking to remove the worst indecent image…","pd":"2025-03-06","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.1  Data labor exploitation"],"t":"Mabel works for a firm that trawls the internet looking to remove the worst indecent image…","s":"Mabel works for a firm that trawls the internet looking to remove the worst indecent images. At home she is a loving grandmother who enjoys spending time with her grandkids but at work Mabel has to watch the internet's most \"abhorrent\" child sex abuse. She works for one of the few organisations licensed to actively search the internet for indecent content to help police and tech firms take the images down. The Internet Watch Foundation (IWF) helped remove a record almost 300,000 web pages last year, including more artificial intelligence (AI) generated images than ever as the number of these types of images have increased almost fivefold.","u":"https://www.bbc.com/news/articles/ckg843y8y7no","d":"2025-03-06","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-03-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-03-06","organization":"Internet Watch Foundation (IWF)","aiSystem":"Internet Watch Foundation (IWF) automated content moderation system","affectedGroup":"worst indecent image creators","action":"used AI to generate and recommend content for removal","consequence":"exposed to misleading information"}},{"i":"R1379","hd":"Data centres can use vast quantities of water to cool them - but it's not clear where it w…","pd":"2025-02-07","k":"United Kingdom","p":"United Kingdom","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Data centres can use vast quantities of water to cool them - but it's not clear where it w…","s":"Data centres can use vast quantities of water to cool them - but it's not clear where it will come from. Sir Keir Starmer's plan to make the UK a \"world leader\" in Artificial Intelligence (AI) could put already stretched supplies of drinking water under strain, industry sources have told the BBC. The giant data centres needed to power AI can require large quantities of water to prevent them from overheating. The tech industry says it is developing more efficient cooling systems that use less water. But the department for science, innovation and technology said in a statement it recognised the plants \"face sustainability challenges\".","u":"https://www.bbc.com/news/articles/ce85wx9jjndo","d":"2025-02-07","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2025-02-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-02-07","organization":"Department for Science, Innovation and Technology","aiSystem":"Data centers powered by AI","affectedGroup":"Already stretched water supplies","action":"Powering data centers with AI","consequence":"Undermining already stretched water supplies"}},{"i":"R1385","hd":"Apple's new artificial intelligence features falsely made it seem the BBC reported Luigi M…","pd":"2024-12-13","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Apple's new artificial intelligence features falsely made it seem the BBC reported Luigi M…","s":"Apple's new artificial intelligence features falsely made it seem the BBC reported Luigi Mangione had shot himself. The BBC has complained to Apple after the tech giant's new iPhone feature generated a false headline about a high-profile murder in the United States. Apple Intelligence, launched in the UK earlier this week , uses artificial intelligence (AI) to summarise and group together notifications. This week, the AI-powered summary falsely made it appear BBC News had published an article claiming Luigi Mangione, the man arrested following the murder of healthcare insurance CEO Brian Thompson in New York, had shot himself.","u":"https://www.bbc.com/news/articles/cd0elzk24dno","d":"2024-12-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-12-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-12-13","organization":"Apple","aiSystem":"Apple Intelligence","affectedGroup":"BBC News","action":"generated a false headline","consequence":"falsely made it appear BBC News had published an article"}},{"i":"R1387","hd":"The BBC's You And Yours programme used AI to clone a reporter's voice to test bank securit…","pd":"2024-11-28","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"The BBC's You And Yours programme used AI to clone a reporter's voice to test bank securit…","s":"The BBC's You And Yours programme used AI to clone a reporter's voice to test bank security measures. Artificial intelligence can now clone human voices so well they that they are almost indistinguishable from the real thing. But how would it fare against the voice recognition tech that is supposed to protect people's bank accounts? As part of the BBC's Scam Safe Week, I have been investigating the power of voice cloning. The consumer champion Martin Lewis is among the celebrities whose voice has been targeted by scammers. And I spoke to the actor James Nesbitt, who said he was \"horrified\" at how realistic a cloned version of his voice was.","u":"https://www.bbc.com/news/articles/c1lg3ded6j9o","d":"2024-11-28","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-11-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-11-28","organization":"BBC's You And Yours programme","aiSystem":"AI-powered voice cloning technology","affectedGroup":"Bank account holders, voice recognition systems","action":"Cloned a reporter's voice to test bank security measures","consequence":"Voice recognition systems could be fooled into accepting fake identities"}},{"i":"R1400","hd":"More than 600 Scottish students have been accused of misusing AI during part of their stud…","pd":"2024-03-06","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"More than 600 Scottish students have been accused of misusing AI during part of their stud…","s":"More than 600 Scottish students have been accused of misusing AI during part of their studies, according to a BBC FOI. More than 600 Scottish students were accused of misusing AI during part of their studies last year - a rise of 121% on 2023 figures. According to a freedom of information request by BBC Scotland, less than 10 students were kicked off their courses at both Robert Gordon and Glasgow universities in the last year - the first time AI-linked expulsions have been recorded at any Scottish university. So when does turning to the internet to help find the answer to a question cross the line into cheating?","u":"https://www.bbc.com/news/articles/ckg88kk1n8jo","d":"2024-03-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-03-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-03-06","organization":"Robert Gordon University and Glasgow University","aiSystem":"AI search tools","affectedGroup":"Scottish students","action":"Using AI search tools to find answers to questions","consequence":"Accusations of misusing AI, potential expulsion"}},{"i":"R1407","hd":"Uk politics 67518511","pd":"2023-12-21","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Uk politics 67518511","s":"A senior Tory MP leads calls for more government action to prevent AI sabotaging British democracy. Artificial Intelligence (AI) has already been used to disrupt elections around the world - and there are fears among senior politicians and the security services that the UK will be next. Former Justice Secretary Sir Robert Buckland is urging the government to do more to tackle what he sees as a \"clear and present danger\" to UK democracy. The Conservative MP, who now chairs the Northern Ireland select committee, is particularly concerned about the rise of deepfakes - realistic audio and video clips of politicians appearing to say things they did not say.","u":"https://www.bbc.com/news/uk-politics-67518511","d":"2023-12-21","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2023-12-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-12-21","organization":"Government and security services of the United Kingdom","aiSystem":"Deepfake technology","affectedGroup":"Politicians and political discourse","action":"Used realistic audio and video clips of politicians to manipulate their statements","consequence":"Disruption of political trust and integrity, potential for election interference"}},{"i":"R1409","hd":"A cutting-edge tool from Open AI appears to be poorly moderated, allowing it to be abused …","pd":"2023-12-07","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"A cutting-edge tool from Open AI appears to be poorly moderated, allowing it to be abused …","s":"A cutting-edge tool from Open AI appears to be poorly moderated, allowing it to be abused by cyber-criminals. A ChatGPT feature allowing users to easily build their own artificial-intelligence assistants can be used to create tools for cyber-crime, a BBC News investigation has revealed. OpenAI launched it last month, so users could build customised versions of ChatGPT \"for almost anything\". Now, BBC News has used it to create a generative pre-trained transformer that crafts convincing emails, texts and social-media posts for scams and hacks. It follows warnings about AI tools. BBC News signed up for the paid version of ChatGPT, at £20 a month, created a private bespoke AI bot called Crafty Emails and told it to write text using \"techniques to make people click on links or and download things sent to them\".","u":"https://www.bbc.com/news/technology-67614065","d":"2023-12-07","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2023-12-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-12-07","organization":"BBC News","aiSystem":"Generative pre-trained transformer created using ChatGPT features","affectedGroup":"Potential victims of scams and hacks","action":"Created convincing emails, texts, and social media posts using AI to manipulate users","consequence":"Exposure to misleading content leading to potential financial loss or identity theft"}},{"i":"R1410","hd":"Uk wales 67360696","pd":"2023-11-09","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Uk wales 67360696","s":"Facial recognition was also used to search for terrorists, a police and crime commissioner says. Facial recognition was used on crowds attending a Beyoncé concert in Cardiff to scan for paedophiles and terrorists. South Wales Police and Crime Commissioner Alun Michael said searching for potential terrorists at such events had become normal since the 2017 Manchester Arena bombing. He said paedophiles were also targeted as \"there would be very large numbers of young girls attending that concert\". Mr Michael described using such cameras as \"entirely sensible\". Appearing before MPs on the Welsh Affairs Committee, Mr Michael defended the use of the artificial intelligence (AI) technology outside the concert.","u":"https://www.bbc.com/news/uk-wales-67360696","d":"2023-11-09","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-11-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-11-09","organization":"South Wales Police and Crime Commissioner Alun Michael","aiSystem":"Facial recognition technology","affectedGroup":"Attendees of a Beyoncé concert","action":"Used facial recognition to search for potential terrorists and paedophiles","consequence":"Exposure to surveillance and tracking"}},{"i":"R1418","hd":"Union group claims using artificial intelligence to hire and fire staff could lead to grea…","pd":"2023-03-18","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.2  Algorithmic management harm"],"t":"Union group claims using artificial intelligence to hire and fire staff could lead to grea…","s":"Union group claims using artificial intelligence to hire and fire staff could lead to greater discrimination. The TUC is calling for stronger rules to protect workers from decisions made by artificial intelligence systems. AI-powered technologies are now making \"high-risk, life changing\" decisions about workers' lives including line-managing, hiring and firing staff\", said the body which represents unions. But a new law will \"dilute\" existing protections, it said. The government said the TUC's assessment was \"wrong\" and has said safeguards will remain in place. A spokesperson said it was committed to improving and upholding workers' rights: \"AI is set to drive growth and create new highly-paid jobs throughout the UK, while allowing us to carry out our existing jobs more efficiently and safely.","u":"https://www.bbc.com/news/technology-65301630","d":"2023-03-18","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-03-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-03-18","organization":"TUC (Trade Union Congress)","aiSystem":"AI-powered technologies","affectedGroup":"workers","action":"making decisions about hiring and firing staff","consequence":"greater discrimination"}},{"i":"R1420","hd":"Getty Images, one of the worlds biggest picture agencies, is taking action against Stabili…","pd":"2023-01-19","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Getty Images, one of the worlds biggest picture agencies, is taking action against Stabili…","s":"Getty Images, one of the worlds biggest picture agencies, is taking action against Stability AI. Getty Images is taking legal action against the makers of an artificial-intelligence image-creation tool. The agency, which sells the rights to use photographers' and illustrators' images, said Stability AI's Stable Diffusion system had infringed these. AI image generators \"learn\" to create images from simple text instructions by analysing human-made pictures, including images found online. Many artists and photographers say they use their work without permission. Some artists find image generators a valuable way to express themselves creatively - but many others worry they can convincingly imitate their style and use it to produce images in seconds.","u":"https://www.bbc.com/news/technology-64285227","d":"2023-01-19","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-01-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-01-19","organization":"Stability AI","aiSystem":"Stability AI's Stable Diffusion system","affectedGroup":"Artists and photographers","action":"AI image generators created images from text instructions","consequence":"Artists and photographers' works were used without permission"}},{"i":"R1438","hd":"UK watchdog warns of legal risks as london police deploy lfr at protest","pd":"2026-05-15","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Uk watchdog warns of legal risks as london police deploy lfr at protest","s":"William Webster warns that deploying live facial recognition could bring legal issues against the police for infringing on fundamental rights. London’s Metropolitan Police will deploy live facial recognition (LFR) technology at a protest for the first time this weekend, prompting warnings from the UK’s biometrics and surveillance watchdog that police could face legal action over misidentifications and infringements on fundamental rights. On Wednesday, the Metropolitan Police announced that it would deploy LFR technology at the Unite the Kingdom march on Saturday, organized by far-right, anti-Islam activist Tommy Robinson.","u":"https://www.biometricupdate.com/202605/uk-watchdog-warns-of-legal-risks-as-london-police-deploy-lfr-at-protest","d":"2026-05-15","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-15","organization":"London’s Metropolitan Police","aiSystem":"Live facial recognition (LFR) technology","affectedGroup":"People who might be misidentified","action":"Deploying live facial recognition technology at a protest","consequence":"Potential legal action due to misidentifications and infringement of fundamental rights"}},{"i":"R1447","hd":"London testing facial recognition app for police as another false match surfaces","pd":"2026-02-27","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"London testing facial recognition app for police as another false match surfaces","s":"London Mayor Sadiq Khan said that the OIFR system, powered by NEC Neoface software, will be piloted by 100 Metropolitan Police officers for six months. London police will soon start testing “operator-initiated facial recognition” (OIFR), a mobile app that allows officers to photograph a person and check their identity. At the same time, more cases of misidentification by police facial recognition systems are emerging in the UK. On Thursday, London Mayor Sadiq Khan shared that the OIFR system, powered by NEC Neoface software, will be piloted by 100 Metropolitan Police officers for six months. The mobile biometric matching technology will be used during police stops.","u":"https://www.biometricupdate.com/202602/london-testing-facial-recognition-app-for-police-as-another-false-match-surfaces","d":"2026-02-27","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-27","organization":"Metropolitan Police","aiSystem":"Operator-initiated facial recognition (OIFR) system powered by NEC Neoface software","affectedGroup":"People photographed by police officers","action":"Officers photographing and checking identities of individuals","consequence":"Misidentification and potential privacy breaches"}},{"i":"R1462","hd":"Report claims UK evisa system uses migrants as digital id testing ground","pd":"2025-12-11","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Report claims uk evisa system uses migrants as digital id testing ground","s":"The report comes from researchers at the University of Warwick and University of Leicester, working with Migrant Voice and the Open Rights Group. A new report raises alarm over the UK’s mandatory digital immigration status system, claiming that migrants may have been used as a testing ground for the government’s wider digital ID ambitions. The “ Exclusion by Design: Digital Identification and the Hostile Environment for Migrants ” report comes from researchers at the University of Warwick and University of Leicester, working with Migrant Voice and the Open Rights Group It examines the rollout of the Home Office’s eVisa platform, which from June 2025 requires nearly all migrants entering or residing in the UK to prove their legal status exclusively through digital means.","u":"https://www.biometricupdate.com/202512/report-claims-uk-evisa-system-uses-migrants-as-digital-id-testing-ground","d":"2025-12-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06","organization":"Home Office","aiSystem":"eVisa platform","affectedGroup":"migrants","action":"require migrants to prove legal status through digital means","consequence":"exposure to privacy risks"}},{"i":"R1473","hd":"Rights groups concerned over uks plan to use biometric age estimation on migrants","pd":"2025-10-20","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Rights groups concerned over uks plan to use biometric age estimation on migrants","s":"Rights groups are expressing concerns about the UK's plans to introduce facial age estimation for vetting underage migrants arriving in the country. Rights groups and social work experts are expressing concerns about the UK’s plans to introduce biometric facial age estimation for vetting underage migrants arriving in the country. Using “flawed” AI tools could prove dehumanizing and may not provide accurate age estimations, organizations such as Human Rights Watch and Freedom from Torture argue. The result could be placing children in adult asylum hotels without safeguards or adequate support. “Assessing the ages of migrants is a complex process which should not be open to shortcuts,” Luke Geoghegan, head of policy and research at the British Association of Social Workers, told Context.","u":"https://www.biometricupdate.com/202510/rights-groups-concerned-over-uks-plan-to-use-biometric-age-estimation-on-migrants","d":"2025-10-20","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2025-10-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-20","organization":"UK authorities","aiSystem":"Facial age estimation technology","affectedGroup":"Underage migrants","action":"Using flawed AI tools to assess ages","consequence":"Placing children in adult asylum hotels without safeguards or adequate support"}},{"i":"R1475","hd":"UK police struggle to contain data breaches","pd":"2025-10-20","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.1  Privacy violation"],"t":"Uk police struggle to contain data breaches","s":"Over the past three years, UK police forces including Police Scotland, North Wales Police have experienced over 13,000 data breach incidents. Although many UK police forces are in the process of introducing facial recognition into their work, data breaches remain an issue that is capturing the attention of legal organizations. Last week, the North Wales Police was found to have reported 19 data breaches over the past six years. The compromised information included names, addresses, date of birth, contact details, medical and financial information, as well as breaches related to GDPR compliance. The largest number of breaches, eight in total, was reported in 2024, while an additional seven have already occurred in 2025.","u":"https://www.biometricupdate.com/202510/uk-police-struggle-to-contain-data-breaches","d":"2025-10-20","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-20","organization":"UK police forces, including Police Scotland and North Wales Police","aiSystem":"Facial recognition technology","affectedGroup":"Individuals whose data was breached","action":"Data breaches involving sensitive personal information","consequence":"Privacy risks and potential misuse of personal data"}},{"i":"R1500","hd":"Unlawful use of facial recognition by police erodes public trust in biometrics","pd":"2025-07-21","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Unlawful use of facial recognition by police erodes public trust in biometrics","s":"The NYPD arrested a protestor with the help of Clearview AI’s facial recognition technology (FRT), skirting a policy that puts strict limits on its use. The New York Police Department arrested a protestor in New York City with the help of Clearview AI ’s facial recognition technology (FRT), skirting a policy that puts strict limits on its use. Instead of running the search itself, says a report from The City, the NYPD outsourced a Clearview search through a fire marshal at the city’s fire department, then used the results to identify a pro-Palestinian protester at Columbia University accused of throwing a rock at a pro-Israeli protester during an April protest.","u":"https://www.biometricupdate.com/202507/unlawful-use-of-facial-recognition-by-police-erodes-public-trust-in-biometrics","d":"2025-07-21","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-04","organization":"New York Police Department (NYPD)","aiSystem":"Clearview AI's facial recognition technology (FRT)","affectedGroup":"Pro-Palestinian protester at Columbia University","action":"Used facial recognition to identify a protester","consequence":"Arrested a protester"}},{"i":"R1511","hd":"Asda supermarket chain faces legal complaint over facial recognition","pd":"2025-05-22","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Asda supermarket chain faces legal complaint over facial recognition","s":"The UK retailer is facing a legal complaint over its use of live facial recognition video surveillance in its supermarkets. Asda is facing a legal complaint over its use of live facial recognition (LFR) cameras in its supermarkets. The legal filing comes from privacy rights group Big Brother Watch, which argues that Asda’s use of LFR cameras is “unlawful.” Filed with the Information Commissioner, the legal complaint claims Asda is “infringing the data rights” of shoppers and exhorts the end of the use of the biometric technology by the supermarket chain. The biometric surveillance technology was acquired from UK start-up FaiceTech , with Asda installing the cameras and LFR in five shops in the Greater Manchester area as part of a trial.","u":"https://www.biometricupdate.com/202505/asda-supermarket-chain-faces-legal-complaint-over-facial-recognition","d":"2025-05-22","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-05-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-05-22","organization":"Asda (UK retailer)","aiSystem":"live facial recognition (LFR) cameras","affectedGroup":"shoppers","action":"use of live facial recognition cameras in supermarkets","consequence":"infringement of data rights, potential unlawful use"}},{"i":"R1520","hd":"London to introduce permanent live facial recognition cameras","pd":"2025-03-25","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"London to introduce permanent live facial recognition cameras","s":"However, privacy groups such as Big Brother Watch have condemned the move and called for legislative safeguards on facial recognition. London police have announced their plans to install the UK’s first permanent live facial recognition cameras, catching potential criminals by matching their faces with a pre-determined database. The cameras will be set up in Croydon which has become one of the most targeted areas for facial recognition deployments in the city, leading to the arrest of approximately 200 people by November last year. The Metropolitan Police also said it could extend the surveillance across the capital.","u":"https://www.biometricupdate.com/202503/london-to-introduce-permanent-live-facial-recognition-cameras","d":"2025-03-25","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-03-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-03-25","organization":"London police","aiSystem":"Facial recognition technology","affectedGroup":"People in Croydon","action":"Install permanent live facial recognition cameras","consequence":"Potential criminals are caught by matching faces with a pre-determined database"}},{"i":"R1524","hd":"UK revisits proposal to make a vast police database from driving licenses","pd":"2025-02-27","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Uk revisits proposal to make a vast police database from driving licenses","s":"The plan was introduced by the previous Conservative government in a 2023 criminal justice bill, and has come under fresh criticism. The UK government is advancing a Crime and Policing Bill that could have a significant impact on British society as it seeks to introduce new laws and policing powers. The new crime bill , introduced by Home Secretary Yvette Cooper, is currently in its second reading, and has come under fire for its potential expansion of facial recognition powers. The bill is seen as the biggest legislative update to policing in the UK in decades and is designed to tackle anti-social crimes and street crimes.","u":"https://www.biometricupdate.com/202502/uk-revisits-proposal-to-make-a-vast-police-database-from-driving-licenses","d":"2025-02-27","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2025-02-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-02-27","organization":"UK government","aiSystem":"Facial recognition technology","affectedGroup":"People","action":"Introduce new laws and facial recognition powers","consequence":"Potential expansion of surveillance capabilities"}},{"i":"R1544","hd":"Calls grow for investigation into police scotlands live facial recognition tactics","pd":"2024-10-08","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Calls grow for investigation into police scotlands live facial recognition tactics","s":"Critics are warning the use of LFR technology could fundamentally alter the relationship between law enforcement and the public. In light of growing scrutiny over the deployment of live facial recognition technology , Police Scotland is facing renewed calls for an investigation into its practices, which critics describe as “Orwellian.” The concerns stem from recent revelations about the extent to which the police are using this controversial technology, with critics warning that it could fundamentally alter the relationship between law enforcement and the public. A report from the Scottish Daily Express highlights that, despite assurances of careful use, the reality of Police Scotland’s facial recognition capabilities raises alarms among civil liberties advocates.","u":"https://www.biometricupdate.com/202410/calls-grow-for-investigation-into-police-scotlands-live-facial-recognition-tactics","d":"2024-10-08","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-10-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-10-08","organization":"Police Scotland","aiSystem":"Facial recognition technology","affectedGroup":"Public","action":"Used facial recognition to identify people","consequence":"Fundamentally altered relationship between law enforcement and the public"}},{"i":"R1547","hd":"Civil society warns europes digital borders making life harder for migrants","pd":"2024-09-23","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Civil society warns europes digital borders making life harder for migrants","s":"Poor planning, technical issues and concerns over human rights and data protection are plaguing the rollout of the UK’s upcoming biometric eVisas. The UK government plans to replace physical immigration documents, including Biometric Residence Permits (BRP) and passports with a digital-only document. Millions of migrants in the UK are expected to switch to eVisas by the end of 2024. The transition, however, could leave many immigrants at risk, says UK-based digital rights organization Open Rights Group (ORG). The eVisa will be used for immigration purposes but also for current immigrants to prove their right to work, sign housing contracts and access banking services.","u":"https://www.biometricupdate.com/202409/civil-society-warns-europes-digital-borders-making-life-harder-for-migrants","d":"2024-09-23","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-09-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-09-23","organization":"UK government","aiSystem":"Biometric eVisas","affectedGroup":"Millions of migrants in the UK","action":"Switching to digital-only eVisas","consequence":"Leaving many immigrants at risk of privacy infringement and data misuse"}},{"i":"R1554","hd":"Rights groups push back on UK police use of facial recognition amid far right riots","pd":"2024-08-15","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Rights groups push back on uk police use of facial recognition amid far right riots","s":"After the UK government announced more deployments of facial recognition, rights groups have called on Prime Minister Keir Starmer to reverse the decision. After the UK government announced more deployments of facial recognition to curb far-right riots, rights groups have called on Prime Minister Keir Starmer to reverse the decision, calling it a “chilling precedent” that “threatens the democratic rights” of the communities he is seeking to protect. On Friday, Amnesty International, Access Now, Statewatch, Privacy International, Big Brother Watch and 22 other groups sent a letter to Starmer requesting a meeting. “We urge you to rethink your plans to expand the use of facial recognition surveillance in the UK and would ask that you meet with us, as you have with police chiefs, to discuss the rights and equalities impacts of this AI mass surveillance,” the letter says.","u":"https://www.biometricupdate.com/202408/rights-groups-push-back-on-uk-police-use-of-facial-recognition-amid-far-right-riots","d":"2024-08-15","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-08-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-08-15","organization":"UK government","aiSystem":"Facial recognition technology","affectedGroup":"Communities targeted by far-right riots","action":"Expanded deployment of facial recognition surveillance","consequence":"Threat to democratic rights and equalities"}},{"i":"R1561","hd":"Southampton extends use of reveal live facial recognition bodycams by bouncers","pd":"2024-07-22","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Southampton extends use of reveal live facial recognition bodycams by bouncers","s":"This system helps identify offenders excluded from Southampton’s evening and night time economy venues via the Red Card scheme. Southampton Business Crime Partnership (SBCP), managed by GO! Southampton, has received additional funding for live facial recognition technology on body-worn cameras from Reveal An extra £2,243 will extend the facial recognition scheme following a three-month trial across seven venues. The body-worn cameras with facial recognition were first deployed for a trial launched in 2023 by the Business Improvement District (BID) in collaboration with Synergy Security and local businesses. The scheme employs Reveal’s digital evidence management system, DEMS 360, which is used by approximately 70 percent of UK police forces.","u":"https://www.biometricupdate.com/202407/southampton-extends-use-of-reveal-live-facial-recognition-bodycams-by-bouncers","d":"2024-07-22","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-07-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-07-22","organization":"Southampton Business Crime Partnership (SBCP)","aiSystem":"Facial recognition technology","affectedGroup":"Offenders excluded from Southampton’s evening and night time economy venues","action":"Deployed live facial recognition technology on body-worn cameras","consequence":"Extended use of facial recognition scheme"}},{"i":"R1571","hd":"As UK sets date for general elections criticism piles on voter id requirement","pd":"2024-06-06","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"As uk sets date for general elections criticism piles on voter id requirement","s":"The government has been facing pushback over the voter ID rule itself as well as the limited number of acceptable forms of identity documents. The UK’s first national election to require a photo ID document has finally set its date to July 4th. But as the deadline approaches, some experts are warning that the ID requirement alongside existing issues with voter registration could demand a “huge” logistical effort while rights organizations are decrying the voter ID’s potential for discrimination. “The volume of registration and identification applications will pose a considerable challenge for electoral administrators,” says Toby James, a professor at the University of East Anglia and deputy director of the Electoral Integrity Project.","u":"https://www.biometricupdate.com/202406/as-uk-sets-date-for-general-elections-criticism-piles-on-voter-id-requirement","d":"2024-06-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-06-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-07-04","organization":"UK government","aiSystem":"Not specified in report","affectedGroup":"Voters","action":"Required voters to present photo ID documents","consequence":"Potential for discrimination and logistical challenges"}},{"i":"R1587","hd":"UK police fully embrace the potential of facial recognition with 55 5m to spend","pd":"2024-04-10","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Uk police fully embrace the potential of facial recognition with 55 5m to spend","s":"UK Prime Minister Rishi Sunak today announced a major new investment in facial recognition technology as part of a wider crackdown on retail crime. “To the shoplifters and those abusing shopworkers, enough is enough,” says a release from the Home Office, which specifies that assaulting a retail worker is to be made a standalone criminal offense. The £55.5 million (US$69.5 million) to be spent on facial recognition technology over the next four years includes £4m for “bespoke mobile units that can be deployed to high streets across the country with live facial recognition used in crowded areas to identify people wanted by the police – including repeat shoplifters.”","u":"https://www.biometricupdate.com/202404/uk-police-fully-embrace-the-potential-of-facial-recognition-with-55-5m-to-spend","d":"2024-04-10","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-04-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-04-10","organization":"UK Police","aiSystem":"Facial recognition technology","affectedGroup":"Shoplifters, retail workers, repeat shoplifters","action":"Deploy facial recognition technology to identify people wanted by the police in crowded areas","consequence":"Increased surveillance and potential misuse of technology"}},{"i":"R1592","hd":"UK data watchdog to investigate countrys troubled immigration it systems","pd":"2024-03-21","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Uk data watchdog to investigate countrys troubled immigration it systems","s":"The Information Commissioner's Office will probe IT incidents connected to the Home Office-operated Person Centric Data Platform and Atlas,. After reports revealed that more than 76,000 people have been affected by biographical and biometrical data errors in the UK government immigration database, the country’s data protection watchdog has launched an investigation into the work of the Home Office. The Information Commissioner’s Office (ICO) will probe “IT incidents” connected to the Home Office-operated Person Centric Data Platform (PCDP) and Atlas, the computer tools used by immigration caseworkers and border authorities, according to trade publication Public Technology.","u":"https://www.biometricupdate.com/202403/uk-data-watchdog-to-investigate-countrys-troubled-immigration-it-systems","d":"2024-03-21","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-03-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-03-21","organization":"Home Office","aiSystem":"Person Centric Data Platform (PCDP) and Atlas","affectedGroup":"more than 76,000 people","action":"incidents involving biographical and biometrical data errors","consequence":"privacy intrusion"}},{"i":"R1597","hd":"UK ico issues warning on biometric employee tracking guidance for businesses","pd":"2024-02-27","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.2  Algorithmic management harm"],"t":"Uk ico issues warning on biometric employee tracking guidance for businesses","s":"The UK's data regulator has sent enforcement notices to companies tracking employee time and attendance with biometrics, and issued guidance for businesses. The UK Information Commissioner’s Office (ICO) has warned community and fitness center operator Serco Leisure that facial recognition and fingerprint biometrics cannot be used to monitor employees’ time and attendance. The regulator posted a notice of its warning to Serco “and seven associated leisure trusts,” stating that the use of biometrics was not proportionate, and no alternative method was offered. They must end the practice and delete the biometric data collected within three months.","u":"https://www.biometricupdate.com/202402/uk-ico-issues-warning-on-biometric-employee-tracking-guidance-for-businesses","d":"2024-02-27","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-02-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-02-27","organization":"UK Information Commissioner’s Office (ICO)","aiSystem":"Facial recognition and fingerprint biometrics","affectedGroup":"Employees of Serco Leisure and associated leisure trusts","action":"Used biometrics to monitor employees' time and attendance","consequence":"Exposure to surveillance and tracking"}},{"i":"R1602","hd":"Uks photo id requirement for voting stirs backlash against government","pd":"2024-02-09","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Uks photo id requirement for voting stirs backlash against government","s":"The UK is planning to introduce mandatory photo identification for voters during national elections for the first time this year. But the country’s electoral watchdog is warning that the tight ID rules risk disenfranchising certain groups while the new rules could be seen as benefitting the Tory Party. “The photo ID requirement is clearly proving more of a barrier to some people than others,” says John Pullinger, chair of the UK Electoral Commission. The introduction of photo IDs for voting has been fueling accusations that the Tory government is trying to gerrymander the elections by excluding voters who are likely to vote against them, including younger people.","u":"https://www.biometricupdate.com/202402/uks-photo-id-requirement-for-voting-stirs-backlash-against-government","d":"2024-02-09","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-02-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-02-09","organization":"UK Electoral Commission","aiSystem":"Not specified in report","affectedGroup":"Certain groups of people, particularly younger people","action":"Introducing mandatory photo identification for voters","consequence":"Risk of disenfranchising certain groups while potentially benefiting the Tory Party"}},{"i":"R1608","hd":"London police deploy facial recognition during palestine and israel protests","pd":"2024-01-15","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"London police deploy facial recognition during palestine and israel protests","s":"The London police have deployed facial recognition during protest actions in support of Palestine and Israel over the last weekend. The London police have deployed facial recognition during protest actions in support of Palestine and Israel over the last weekend to identify people bearing offensive placards and banners and committing other types of offenses. On Saturday, the Palestine Solidarity Campaign and other groups led a march through the city in support of Palestine while on Sunday, another rally was held in support of Israel on London’s Trafalgar Square. Before the events, the London Metropolitan Police announced they would be using facial recognition to compare CCTV stills and images shared on social media against a database of images held on the police custody system.","u":"https://www.biometricupdate.com/202401/london-police-deploy-facial-recognition-during-palestine-and-israel-protests","d":"2024-01-15","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01","organization":"London Metropolitan Police","aiSystem":"Facial recognition technology","affectedGroup":"People bearing offensive placards and banners, protesters, and others committing offenses","action":"Used facial recognition to identify people","consequence":"Exposure to surveillance and tracking"}},{"i":"R1610","hd":"UK legal charity decries use of biometric immigrant monitoring devices","pd":"2024-01-05","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Uk legal charity decries use of biometric immigrant monitoring devices","s":"The UK has been expanding the use of biometric electronic monitoring devices for immigration bail cases, drawing criticism from NGOs. The UK has been expanding the use of biometric electronic monitoring devices for immigration bail cases, a practice that has drawn criticism from non-governmental organizations that describe the practice as invasive. Last year, the country increased the use of GPS electronic monitoring devices as a bail condition by 56 percent, according to a report by London-based legal charity Public Law Project. This includes both fitted devices such as ankle monitors and non-fitted devices which request periodic biometric verification from the user through a fingerprint scanner.","u":"https://www.biometricupdate.com/202401/uk-legal-charity-decries-use-of-biometric-immigrant-monitoring-devices","d":"2024-01-05","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023","organization":"UK authorities","aiSystem":"Biometric electronic monitoring devices","affectedGroup":"Immigration detainees","action":"Used biometric electronic monitoring devices as a bail condition","consequence":"Invasive and excessive use leading to privacy risks"}},{"i":"R1617","hd":"Uber eats driver to amend lawsuit alleging racial bias by apps biometric verification","pd":"2023-11-14","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Uber eats driver to amend lawsuit alleging racial bias by apps biometric verification","s":"The judge has ruled that former Uber Eats delivery driver can amend and pursue claims that he was kicked off the app as a result of a racially-biased algorithm. A UK judge has ruled that former Uber Eats delivery driver Edrissa Manjang can amend and pursue claims that he was kicked off the ride-sharing app as a result of a racially-biased algorithm in its face biometric system, according to Law360 The judge had first accepted the amended claims in July 2022 after Uber Eats gave information that contradicted his original claims. She also, however, ruled Manjang can not use emails the company sent him about the system as evidence of harassment.","u":"https://www.biometricupdate.com/202311/uber-eats-driver-to-amend-lawsuit-alleging-racial-bias-by-apps-biometric-verification","d":"2023-11-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-11-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-07-01","organization":"Uber Eats","aiSystem":"face biometric system","affectedGroup":"former Uber Eats delivery driver Edrissa Manjang","action":"kicked off the app","consequence":"claims of racial bias"}},{"i":"R1622","hd":"Autonomous cars may have a person detection bias problem with complexions","pd":"2023-08-25","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Autonomous cars may have a person detection bias problem with complexions","s":"Makers of self-driving cars have for years been fending off criticism about safety. Now, they may have to defend themselves against charges of AI bias. A team of researchers from King’s College London and Peking University examined eight deep-learning pedestrian detectors used for research on driverless cars using four widely studied testing datasets. Their results show significant fairness issues related to skin tone and age. Accuracy of detection for adults was 19.67 percent higher compared to children. The study also found that the systems were 7.52 percent better at detecting light-skin individuals than dark-skin ones in all image datasets.","u":"https://www.biometricupdate.com/202308/autonomous-cars-may-have-a-person-detection-bias-problem-with-complexions","d":"2023-08-25","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-08-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-08-25","organization":"Researchers from King’s College London and Peking University","aiSystem":"Deep-learning pedestrian detectors for self-driving cars","affectedGroup":"Pedestrians, particularly children and darker-skinned individuals","action":"Used to detect pedestrians in self-driving cars","consequence":"Significant fairness issues related to skin tone and age, leading to biased detection accuracy"}},{"i":"R1629","hd":"Policing minister pushes for facial recognition in all UK police forces despite criticism","pd":"2023-05-17","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Policing minister pushes for facial recognition in all uk police forces despite criticism","s":"The Home Office briefed the biometrics and surveillance commissioner on the minsters desire for law enforcement to expand their use of these systems. The UK’s policing minister, Chris Philp, is pushing for facial recognition in all police forces nationally, despite critics claiming the technology is inaccurate and some of its applications are illegal. According to a report to be submitted to parliament today, the Home Office briefed the biometrics and surveillance commissioner on Philp’s desire for law enforcement to expand their use of these systems, the Financial Times reports. That would mean rollouts to more forces and police body cameras.","u":"https://www.biometricupdate.com/202305/policing-minister-pushes-for-facial-recognition-in-all-uk-police-forces-despite-criticism","d":"2023-05-17","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-05-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-05-17","organization":"UK's policing minister Chris Philp and the Home Office","aiSystem":"Facial recognition technology","affectedGroup":"Law enforcement officers and citizens","action":"Expand the use of facial recognition technology in all police forces","consequence":"Exposure to surveillance and tracking"}},{"i":"R1665","hd":"New AI models like chatgpt pursue superintelligence but cant be trusted even when it comes to basic questions","pd":"2024-09-25","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"New ai models like chatgpt pursue superintelligence but cant be trusted even when it comes to basic questions","s":"A study published in the journal ‘Nature’ warns that errors, even in simple matters, will be difficult to completely eliminate in the future. ChatGPT and other language models have become an increasingly common resource in a multitude of jobs. However, they have an underlying problem that tends to get worse: these systems often give incorrect answers What’s more, the problem is getting worse. “New systems improve their results in difficult tasks, but not in easy ones, so these models become less reliable,” says Lexin Zhou, co-author of an article published on Wednesday in the scientific journal Nature , which he wrote together with four Spaniards and a Belgian from Valencian University Institute for Research in Artificial Intelligence (VRAIN) of the Polytechnic University of Valencia (UPV) and the University of Cambridge.","u":"https://english.elpais.com/technology/2024-09-25/new-ai-models-like-chatgpt-pursue-superintelligence-but-cant-be-trusted-even-when-it-comes-to-basic-questions.html","d":"2024-09-25","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-09-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-09-25","organization":"Various companies and research institutions including Valencian University Institute for Research in Artificial Intelligence (VRAIN), Polytechnic University of Valencia (UPV), and University of Cambridge","aiSystem":"ChatGPT and other language models","affectedGroup":"Users seeking information or assistance","action":"Providing incorrect answers to simple questions","consequence":"Reduced reliability and potential misuse of AI-generated content"}},{"i":"R1679","hd":"When the algorithm encourages you to commit suicide","pd":"2023-11-21","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"When the algorithm encourages you to commit suicide","s":"Artificial intelligence streamlines many tasks, but it can also have a fatal influence on some people, and it is creating a world in which reality and artifice will be indistinguishable. On Christmas morning 2021, Jaswant Singh Chail entered Windsor Castle with crossbow in hand, disguised as Lord Sith, the villain from Star Wars. He told the royal guards who intercepted him that he was there to assassinate the Queen of England; he was then arrested and charged with treason. During the trial last month, the judge read some of the 5,000 messages that the 21-year-old had exchanged with a chatbot on the Replika app in the weeks leading up to the event.","u":"https://english.elpais.com/science-tech/2023-11-20/when-the-algorithm-encourages-you-to-commit-suicide.html","d":"2023-11-21","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-11-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-12-01","organization":"Not specified in report","aiSystem":"Replika app","affectedGroup":"Jaswant Singh Chail","action":"Chats with a chatbot on the Replika app","consequence":"Encouraged to commit an assassination attempt against the Queen of England"}},{"i":"R1718","hd":"Henry nowak murder police officer grok AI","pd":"2026-06-04","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Henry nowak murder police officer grok ai b2989079","s":"Christi Hill was wrongly identified in the Vickrum Digwa murder case by platforms including Grok. A former police officer has been forced to move to a safe house after she was falsely accused by AI and social media users of being one of the arresting officers in the Henry Nowak murder case. Christi Hill, who left her job as a police constable in Portsmouth, near Southampton , 20 months before the murder, said she was scared for her safety after the wrong information spread. Police officers in Southampton in December handcuffed Henry Nowak after he had been attacked by Vickrum Digwa, who was later jailed for life.","u":"https://www.independent.co.uk/news/uk/home-news/henry-nowak-murder-police-officer-grok-ai-b2989079.html","d":"2026-06-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-04","organization":"Platforms","aiSystem":"Grok","affectedGroup":"Christi Hill","action":"AI and social media users falsely accused her of being one of the arresting officers","consequence":"Scared for her safety, forced to move to a safe house"}},{"i":"R1720","hd":"Elections AI deepfakes politics","pd":"2026-05-30","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Elections ai deepfakes politics b2986017","s":"Exclusive: New polling shows deepfakes and AI-generated video, audio clips or images about election candidates reached 16.5 million UK adults in the month before elections. The UK is facing a \"democratic emergency”, a leading think tank has warned weeks ahead of a crucial by-election, after new polling revealed around 16.5 million UK adults saw political deepfakes in the month before the local elections Almost one in three (30 per cent) voters said they had seen a deepfake or AI-generated video, audio clip or image about an election candidate or politician online in the lead-up to this month's elections, the shocking new polling showed. The polling of 2,005 adults was conducted by Opinium for the cross-party think tank Demos between 30 April and 6 May this year – immediately before local and devolved elections across the UK.","u":"https://www.independent.co.uk/news/uk/politics/elections-ai-deepfakes-politics-b2986017.html","d":"2026-05-30","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05","organization":"Not specified in report","aiSystem":"AI-generated deepfake technology","affectedGroup":"UK adults","action":"saw political deepfakes","consequence":"exposed to misleading information"}},{"i":"R1721","hd":"Scottish government hyperscale AI data emissions","pd":"2026-05-25","k":"United Kingdom","p":"United Kingdom","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Scottish government hyperscale ai data emissions b2982766","s":"Scottish government’s NPF4 national planning framework states that \"green data centres\" will have an \"overall negligible impact\" on nation’s emissions reduction goals. The Scottish Government faces urgent calls to address \"major shortcomings\" in its data centre policy, as Action to Protect Rural Scotland (APRS) alleges a critical failure to account for the emissions of hyperscale AI facilities in assessments of \"green data centres\" and their contribution to climate targets. Kat Jones, director of APRS, branded the situation \"pretty shocking\". The government’s NPF4 national planning framework states that \"green data centres\" will have an \"overall negligible impact\" on Scotland’s emissions reduction goals.","u":"https://www.independent.co.uk/news/uk/home-news/scottish-government-hyperscale-ai-data-emissions-b2982766.html","d":"2026-05-25","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-25","organization":"Scottish Government","aiSystem":"Hyperscale AI facilities","affectedGroup":"People living in Scotland","action":"Assessments of 'green data centres' and their contribution to climate targets","consequence":"Exposure to misleading information and failure to account for emissions"}},{"i":"R1731","hd":"AI artificial intelligence asylum claims backlog","pd":"2026-03-09","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Ai artificial intelligence asylum claims backlog b2937111","s":"Exclusive: Caseworkers use AI to summarise asylum interviews and to search for information about country of origin. The Home Office ’s use of artificial intelligence (AI) in processing asylum claims could be unlawful, legal experts have warned, opening up the possibility of court action against the government. Caseworkers at the Home Office use AI to summarise interview transcripts with asylum seekers It is also used to search policy guidance, such as information about whether a country is deemed safe to return to. Asylum seekers are not told when AI is used on their interview testimony and are instead kept in the dark about the technology’s impact on their claims The government’s own evaluation of the AI tool that summarises asylum interview transcripts found that 9 per cent of summaries were so flawed that they had to be removed.","u":"https://www.independent.co.uk/news/uk/home-news/ai-artificial-intelligence-asylum-claims-backlog-b2937111.html","d":"2026-03-09","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-03-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-09","organization":"Home Office","aiSystem":"AI tool used to summarise asylum interview transcripts","affectedGroup":"Asylum seekers","action":"AI summarises interview transcripts and searches policy guidance","consequence":"Flawed summaries result in removal of summaries, potentially impacting asylum claims"}},{"i":"R1734","hd":"X UK investigation grok deepfakes ico elon musk","pd":"2026-02-03","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"X uk investigation grok deepfakes ico elon musk b2912966","s":"There has been controversy surrounding chatbot Grok after it was used to generate sexual deepfake images without consent. Formal investigations have been launched into whether Elon Musk’s X and xAI have complied with data protection law after the chatbot Grok was used to create sexualised deepfake images. The Information Commissioner’s Office (ICO) confirmed it had opened the investigations on Tuesday afternoon. In a statement, it said the reports raised “serious concerns” under UK data protection laws, such as whether “appropriate safeguards were built into Grok’s design and deployment”. It comes after outrage over Grok’s ability to digitally “strip” victims without their consent, generating deepfake images of them nude or in minimal clothing.","u":"https://www.independent.co.uk/news/uk/home-news/x-uk-investigation-grok-deepfakes-ico-elon-musk-b2912966.html","d":"2026-02-03","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-03","organization":"Information Commissioner's Office (ICO)","aiSystem":"Grok chatbot","affectedGroup":"Victims of sexualized deepfake images","action":"Generated sexualized deepfake images without consent","consequence":"Raised serious concerns under UK data protection laws"}},{"i":"R1739","hd":"AI deepfakes british schools pupils teachers","pd":"2026-01-11","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Ai deepfakes british schools pupils teachers b2897746","s":"Beyond Grok, nudifying technology and pornographic deepfakes are ripping through classrooms, leaving teachers and children traumatised and schools unsure how to respond. With suspensions rising and prosecutions rare, Chloe Combi asks who is protecting them in the age of AI? T welve years ago, a friend of mine had just started her first teaching post at a well-respected grammar school A huge perk of the job was that, so young teachers could afford to live in the South East and get to school easily, the school owned several houses that staff could rent for a heavily subsidised fee. One Saturday morning during a heatwave, there was a knock at the door.","u":"https://www.independent.co.uk/news/uk/home-news/ai-deepfakes-british-schools-pupils-teachers-b2897746.html","d":"2026-01-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-11","organization":"Schools and educational institutions","aiSystem":"Pornographic deepfakes","affectedGroup":"Teachers and children","action":"Used deepfakes to create pornographic content","consequence":"Trauma, suspension, and uncertainty in response"}},{"i":"R1743","hd":"Artificial intelligence law legal AI chatgpt judges","pd":"2025-10-22","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Artificial intelligence law legal ai chatgpt judges b2849313","s":"Artificial intelligence decided a case that would take years in just “a couple of minutes,” the senior judge said. One of the most senior judges in the country has revealed that artificial intelligence (AI) is being used in the legal sector for “every purpose under the sun” as he weighs up the power of the technology to make decisions in court. Master of the rolls Sir Geoffrey Vos, the second most senior judge in the UK, said AI was like a “chainsaw” at his address to the Legal Geek Conference, in that it was useful in the right hands, but “super dangerous” in the wrong ones. The technology can and should be used to draft contracts and research legal questions, Sir Geoffrey said, especially noting how the summarising capability of large language models (LLMs) can “save time and drudgery” when used carefully.","u":"https://www.independent.co.uk/news/uk/home-news/artificial-intelligence-law-legal-ai-chatgpt-judges-b2849313.html","d":"2025-10-22","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2025-10-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-22","organization":"Legal sector in the United Kingdom","aiSystem":"Large language models (LLMs)","affectedGroup":"Judges, lawyers, legal professionals","action":"Used to draft contracts and research legal questions","consequence":"Could lead to faster but potentially flawed judicial decisions"}},{"i":"R1744","hd":"Chowdhury rahman barrister chatgpt AI asylum case","pd":"2025-10-17","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Chowdhury rahman barrister chatgpt ai asylum case b2847109","s":"Tribunal judge says Chowdhury Rahman wasted court time with ‘wholly irrelevant’ submissions. An immigration barrister could face a disciplinary probe after a judge ruled he used AI tools such as ChatGPT to prepare his legal research. A tribunal heard that a judge was left baffled when Chowdhury Rahman presented his submissions, which included citing cases that were “ entirely fictitious ” or “wholly irrelevant”. A judge found that Mr Rahman had also attempted to “hide” this when questioned, and “wasted” the tribunal’s time. The incident occurred while Mr Rahman was representing two Honduran sisters who were claiming asylum in the UK on the basis that they were being targeted by a violent criminal gang called Mara Salvatrucha (MS-13).","u":"https://www.independent.co.uk/news/uk/home-news/chowdhury-rahman-barrister-chatgpt-ai-asylum-case-b2847109.html","d":"2025-10-17","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-17","organization":"Tribunal judge","aiSystem":"AI tools such as ChatGPT","affectedGroup":"Immigration barrister Chowdhury Rahman","action":"Used AI tools to prepare legal research","consequence":"Wasted court time, faced disciplinary probe"}},{"i":"R1746","hd":"Facial recognition vans police home office","pd":"2025-08-13","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Facial recognition vans police home office b2806734","s":"Critics issue warning over nationwide expansion of ‘intrusive’ technology which ‘turns every passerby into a walking barcode’. Critics have branded the nationwide rollout of live facial recognition technology as another move towards a “total surveillance society”. The Home Office has announced that ten more vans fitted with high-tech cameras will be deployed across the country to catch “high-harm” offenders as part of a government overhaul of neighbourhood policing. Alongside the expansion, the government will simultaneously consult on how the technology should be used and what appropriate safeguards and oversight are needed to shape a new legal framework for its use.","u":"https://www.independent.co.uk/news/uk/crime/facial-recognition-vans-police-home-office-b2806734.html","d":"2025-08-13","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-13","organization":"Home Office","aiSystem":"Facial recognition technology","affectedGroup":"Everyday citizens","action":"Deploy live facial recognition technology in police vans","consequence":"Exposure to intrusive surveillance"}},{"i":"R1749","hd":"Brick lane new data centre plans london","pd":"2025-07-19","k":"United Kingdom","p":"United Kingdom","b":["Energy / Land"],"h":["2.2  Land use and siting harm"],"t":"Brick lane new data centre plans london b3015349","s":"The proposed construction of a data centre in London’s famous Brick Lane continues to generate controversy. Suha Kidwai speaks to residents about the impact it could have on the area. L ined with its famed curry houses, 24-hour bagel shops and stores selling vintage jeans covered with anti-war slogans, London’s Brick Lane has long been considered a beloved cultural hotspot But now, a 5,200 square metre data centre could be built over one of the area’s most iconic buildings, the former Truman Brewery. The 29-metre-tall facility is set to be used for high-speed trading in London’s nearby financial district, and aims to employ 20 full-time staff.","u":"https://www.independent.co.uk/news/uk/home-news/brick-lane-new-data-centre-plans-london-b3015349.html","d":"2025-07-19","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-19","organization":"Not specified in report","aiSystem":"Not specified in report","affectedGroup":"Residents of Brick Lane","action":"Construction of a data center over an iconic building","consequence":"Exposure to unwanted development and loss of cultural heritage"}},{"i":"R1754","hd":"Dwp benefits esa artificial intelligence disability","pd":"2025-02-13","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Dwp benefits esa artificial intelligence disability b2697488","s":"Agents do not ‘simply accept the result provided by the solution,’ DWP says. The Department for Work and Pensions (DWP) has revealed how it is using AI to inform decisions on whether to approve or deny certain benefit applications. Sharing new details to the official government algorithm database, the department says it is using an AI tool called ‘online medical matching’ to help agents make decisions on applications for Employment Support Allowance (ESA). Claimed by 1.5 million people, this is the main health-related benefit that people can receive if they have a condition that affects how much they are able to work.","u":"https://www.independent.co.uk/news/uk/home-news/dwp-benefits-esa-artificial-intelligence-disability-b2697488.html","d":"2025-02-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-02-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-02-13","organization":"Department for Work and Pensions (DWP)","aiSystem":"online medical matching AI tool","affectedGroup":"people claiming Employment Support Allowance (ESA)","action":"using the online medical matching AI tool to inform decisions on benefit applications","consequence":"denying or approving benefit applications based on the tool's results"}},{"i":"R1755","hd":"Naga munchetty nude images scam BBC warning deepfake","pd":"2025-02-06","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Naga munchetty nude images scam bbc warning deepfake b2693198","s":"‘This is the most humiliating day of my life,’ the presenter said. Naga Munchetty has become the latest celebrity to be targeted in a sexually explicit scam. The veteran BBC presenter, 49, discovered paid advertisements on X/Twitter and Facebook promoted to “trick people out of their hard-earned money” and include “crudely mocked-up” fake nude photos of her. Munchetty, who conducted an investigation into the images with her team at BBC 5 Live , said she was “mortified and bemused” to discover the explicit content that somebody had paid “good money” to advertise. “I'm used to seeing misleading articles about myself online, but the screenshots I've been sent by friends and followers on social media in recent weeks are a lot more insidious than most,” she said.","u":"https://www.independent.co.uk/arts-entertainment/tv/news/naga-munchetty-nude-images-scam-bbc-warning-deepfake-b2693198.html","d":"2025-02-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-02-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-02-06","organization":"BBC","aiSystem":"Deepfake technology","affectedGroup":"Naga Munchetty","action":"Deepfake nude images were advertised and shared online","consequence":"Exposure to misleading and sexually explicit content"}},{"i":"R1761","hd":"Abbots langley AI data centre hertfordshire","pd":"2024-11-02","k":"United Kingdom","p":"United Kingdom","b":["Energy / Land"],"h":["2.2  Land use and siting harm"],"t":"Abbots langley ai data centre hertfordshire b2640085","s":"Abbots Langley has become a flashpoint in a battle between villagers and big tech. A proposal to build a data center on the edge of the English village of Abbots Langley was rejected by local authorities amid fierce opposition from villagers. But it's getting a second chance from British Prime Minister Keir Starmer's government, which is pursuing reforms to boost economic growth following his Labour party's election victory in July. Residents of Abbots Langley, 18 miles northwest of London in Hertfordshire, worry the facility will strain local resources and create noise and traffic that damages the character of the quiet village, which is home to just over 20,000 people.","u":"https://www.independent.co.uk/news/uk/home-news/abbots-langley-ai-data-centre-hertfordshire-b2640085.html","d":"2024-11-02","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-11-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-11-02","organization":"British Prime Minister Keir Starmer's government","aiSystem":"Not specified in report","affectedGroup":"Residents of Abbots Langley","action":"Rejected a proposal to build a data center","consequence":"Facility will strain local resources and create noise and traffic"}},{"i":"R1767","hd":"X elon musk algorithm southport race riots amnesty UK","pd":"2024-08-06","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"X elon musk algorithm southport race riots amnesty uk b2802863","s":"Amnesty International analysis found algorithm ‘systematically prioritises’ content that ‘sparks outrage’. New analysis investigating X’s algorithm has revealed how the platform played a “central role” in spreading false narratives fuelling riots in the UK last summer Amnesty International’s analysis of the platform’s own source code, published in March 2023, has revealed how it “systematically prioritises” content that “sparks outrage” - without adequate safeguards to prevent harm. The human rights group said the design of the software created “fertile ground for inflammatory racist narratives to thrive” in the wake of the Southport attack last year.","u":"https://www.independent.co.uk/news/uk/home-news/x-elon-musk-algorithm-southport-race-riots-amnesty-uk-b2802863.html","d":"2024-08-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-08-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-03-01","organization":"X (presumably referring to Elon Musk's Twitter)","aiSystem":"X's algorithm","affectedGroup":"People exposed to false narratives","action":"Spreads false narratives","consequence":"Fuels riots"}},{"i":"R1776","hd":"AI artificial intelligence national security government","pd":"2024-04-23","k":"United Kingdom","p":"United Kingdom","b":["Deployment Context / Weapons"],"h":["5.2  Military decision support harm"],"t":"Ai artificial intelligence national security government b2533198","s":"Decision makers may not be aware of the dangers of relying on information from artificial intelligence, experts say. AI could have profound implications for national security – including posing a host of risks, a new government-commissioned report warns. Artificial intelligence is a valuable tool to help senior officials in government and intelligence make decisions, it says. But it could also lead to inaccuracies, confusion and other dangers, it warns. Senior officials must be trained to spot those problems, and there is a critical need for any AI systems to be carefully watched and continuously monitored to ensure they don’t lead to more bias and errors, it warns.","u":"https://www.independent.co.uk/tech/ai-artificial-intelligence-national-security-government-b2533198.html","d":"2024-04-23","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2024-04-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-04-23","organization":"government","aiSystem":"artificial intelligence","affectedGroup":"decision makers","action":"relying on information from artificial intelligence","consequence":"profound implications for national security, including posing a host of risks"}},{"i":"R1779","hd":"Chris morris chatgpt rishi sunak labour sadiq khan","pd":"2024-04-09","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Chris morris chatgpt rishi sunak labour sadiq khan b2525418","s":"Full Fact’s annual report says the UK is ill-equipped to tackle misleading content. The UK is highly vulnerable to misinformation and is currently not properly equipped to combat it, the annual report from fact-checking charity Full Fact says. The report warns that without urgent action, the UK risks falling behind the pace of international progress in protecting citizen from misinformation. It says that a combination of significant gaps in the Online Safety Act and the rapid rise of generative AI means a fundamental overhaul of the UK’s legislative and regulatory framework is needed in order to adequately combat misinformation and disinformation.","u":"https://www.independent.co.uk/tech/chris-morris-chatgpt-rishi-sunak-labour-sadiq-khan-b2525418.html","d":"2024-04-09","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2024-04-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-04-09","organization":"Not specified in report","aiSystem":"Generative AI","affectedGroup":"People in the United Kingdom","action":"Rapid rise of generative AI","consequence":"Risk of falling behind international progress in combating misinformation"}},{"i":"R1785","hd":"Met police croydon facial recognition","pd":"2024-01-24","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Met police croydon facial recognition b2484112","s":"Several people were arrested including for failure to turn up at court. London’s Metropolitan Police have arrested over a dozen people in two days using controversial Live Facial Recognition technology in Croydon. The operation which took place on Saturday 20 January and Tuesday 23 January consisted of LFR cameras being focused on a specific area in Croydon and as people pass through that area their images are streamed directly to the Live Facial Recognition system. Ahead of the deployment police upload images of criminals who are wanted onto a database. Met Police say this system contains a “watchlist” of offenders who are wanted by the police and/or courts and those who pose a risk of harm to themselves or others.","u":"https://www.independent.co.uk/news/uk/home-news/met-police-croydon-facial-recognition-b2484112.html","d":"2024-01-24","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-20","organization":"London’s Metropolitan Police","aiSystem":"Live Facial Recognition technology","affectedGroup":"People who were arrested","action":"Used Live Facial Recognition technology to focus cameras on a specific area in Croydon and stream images to the system","consequence":"Arrested people included for failure to appear at court"}},{"i":"R1788","hd":"AI artificial intelligence government","pd":"2023-10-24","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Ai artificial intelligence government b2434850","s":"Civil servants are relying on AI to make decisions around welfare, immigration and criminal justice. Bookmark - CommentsGo to comments Government officials are using artificial intelligence (AI) to help decide on everything from approving marriage licences to who should be given benefits, it has been revealed. Civil servants in at least eight Whitehall departments, and several police forces, are relying on AI to make decisions around welfare, immigration and criminal justice, according to an investigation. The shocking findings include the use of an algorithm by the Department for Work and Pensions (DWP) to identify potential benefit fraud.","u":"https://www.independent.co.uk/news/uk/politics/ai-artificial-intelligence-government-b2434850.html","d":"2023-10-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-10-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-10-24","organization":"Department for Work and Pensions (DWP)","aiSystem":"algorithm by the Department for Work and Pensions (DWP)","affectedGroup":"potential benefit fraud victims","action":"identifying potential benefit fraud","consequence":"denying benefits"}},{"i":"R1790","hd":"Keir starmer deepfake AI elections","pd":"2023-10-09","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Keir starmer deepfake ai elections b2426578","s":"As politicans find themselves targeted by advances in deepfakes, the pubilc will have to be on guard not to get duped, writes Anthony Cuthbertson. But given they are so convincing, is it time for a tech solution? Bookmark - CommentsGo to comments Just a week after Slovakia scrambled to deal with an AI-generated recording designed to influence national elections, the UK Labour Party has become the target of deepfake audio. “I’m sick of this,” one of the clips, which appeared to be from a secret recording of party leader Keir Starmer, stated. “I f***ing hate Liverpool.” Despite being debunked and deleted from some platforms, the fake recordings still received millions of views across social media, and highlighted what Tory MP Simon Clarke described as “a new threat to democracy”.","u":"https://www.independent.co.uk/tech/keir-starmer-deepfake-ai-elections-b2426578.html","d":"2023-10-09","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-10-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-10-01","organization":"UK Labour Party","aiSystem":"Deepfake technology","affectedGroup":"Members of the public, voters, political opponents","action":"Generated and distributed deepfake audio recordings","consequence":"Misinformation and confusion during elections, potential impact on public trust and electoral integrity"}},{"i":"R1808","hd":"Renewables case AI data centres built bunk","pd":"2026-07-06","k":"United Kingdom","p":"United Kingdom","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Renewables case ai data centres built bunk","s":"THE case for a controversial £8.2 billion hyperscale AI data centre in Lanarkshire is built on “bunk,” an investigation has found.In January, Prime Minister Sir Keir Starmer unveiled a plan to turn the area once synonymous with Scotland’s heavy industry into an “AI growth zone,” with £5 million of state and £8.2bn of private-sector investment. THE case for a controversial £8.2 billion hyperscale AI data centre in Lanarkshire is built on “bunk,” an investigation has found. In January, Prime Minister Sir Keir Starmer unveiled a plan to turn the area once synonymous with Scotland’s heavy industry into an “AI growth zone,” with £5 million of state and £8.2bn of private-sector investment.","u":"https://morningstaronline.co.uk/article/renewables-case-ai-data-centres-built-bunk","d":"2026-07-06","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"January","organization":"Prime Minister's Office, UK Government","aiSystem":"Hyperscale AI data center","affectedGroup":"Potential investors, local residents, Lanarkshire area","action":"Promoted the construction of a controversial £8.2 billion hyperscale AI data center","consequence":"Misleading investment plans leading to potential economic and environmental harm"}},{"i":"R1809","hd":"Concerns raised about congestion and job losses rollout robotaxis london","pd":"2026-05-22","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Concerns raised about congestion and job losses rollout robotaxis london","s":"UBER drivers and gig workers demonstrated today against the rollout of robotaxis in London, as the government opened bids for US and Chinese operators to access the British market.App Drivers’ & Couriers’ Union (ADCU) members protested in the borough of Brent, as the Transport for London (TfL) joined the union in expressing concerns over the rollout of self-driving vehicles in the capital. UBER drivers and gig workers demonstrated today against the rollout of robotaxis in London, as the government opened bids for US and Chinese operators to access the British market. App Drivers’ & Couriers’ Union (ADCU) members protested in the borough of Brent, as the Transport for London (TfL) joined the union in expressing concerns over the rollout of self-driving vehicles in the capital.","u":"https://morningstaronline.co.uk/article/concerns-raised-about-congestion-and-job-losses-rollout-robotaxis-london","d":"2026-05-22","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-22","organization":"UBER drivers and gig workers, App Drivers' & Couriers' Union (ADCU), Transport for London (TfL)","aiSystem":"self-driving vehicles","affectedGroup":"UBER drivers and gig workers, App Drivers' & Couriers' Union (ADCU) members, residents of the borough of Brent","action":"demonstrated against the rollout of robotaxis","consequence":"expressed concerns over the rollout of self-driving vehicles in the capital"}},{"i":"R1813","hd":"Mick whitley feature 0","pd":"2023-05-17","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Mick whitley feature 0","s":"ARTIFICIAL intelligence could have as wide-reaching and profound an impact on jobs as the first Industrial Revolution.That was the warning issued by the government’s former chief scientific adviser, Sir Patrick Vallance, when he appeared before Parliament’s science and technology committee earlier this month.Research commissioned by the then Department for Business, Energy and Industrial Strategy suggests that 7 per cent of all British jobs could be automated out of existence within just five years as a result of AI. MICK WHITLEY MP is today introducing a Bill in Parliament that aims to secure a people-focused and democratic approach towards increased use of AI across the British economy SHAPE OF THINGS TO COME: Ai-Da about to make history as the first robot to address the House of Lords: its speech explored the role of machine learning, machine creativity and Artificial Intelligence…","u":"https://morningstaronline.co.uk/article/f/mick-whitley-feature-0","d":"2023-05-17","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2023-05-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-05-17","organization":"Department for Business, Energy and Industrial Strategy","aiSystem":"AI-powered welfare fraud detection system","affectedGroup":"welfare recipients","action":"automated welfare fraud detection","consequence":"denied access to essential services"}},{"i":"R1853","hd":"Ex uber driver takes legal action over racist face recognition software","pd":"2021-10-05","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Ex uber driver takes legal action over racist face recognition software","s":"UK driver alleges his account was illegally deactivated when Uber software decided he was not who he said he was. An Uber driver who lost his job when automated face-scanning software failed to recognise him is accusing the firm of indirect race discrimination in a legal test case. The black driver, who worked on the Uber platform from 2016 until April 2021, has filed an employment tribunal claim alleging his account was illegally deactivated when facial-verification software used to log drivers on to the ride-hailing app decided he was not who he said he was. The Independent Workers’ Union of Great Britain (IWGB), which is backing the action, claimed at least 35 other drivers had had their registration with Uber terminated as a result of alleged mistakes with the software since the start of the pandemic.","u":"https://www.theguardian.com/technology/2021/oct/05/ex-uber-driver-takes-legal-action-over-racist-face-recognition-software","d":"2021-10-05","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-10-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-10-05","organization":"Uber","aiSystem":"Automated face-scanning software used to log drivers on to the ride-hailing app","affectedGroup":"Black Uber drivers","action":"Facial-verification software decided the driver was not who he said he was","consequence":"Account was illegally deactivated"}},{"i":"R1854","hd":"Uber facing new UK driver claims of racial discrimination","pd":"2021-10-06","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Uber facing new uk driver claims of racial discrimination","s":"Drivers say automated ID system needed to work failed to identify them because of their race. Uber is facing further claims for compensation over racial discrimination from drivers who say they had been falsely dismissed because of malfunctioning face recognition technology. The claims have emerged after Uber introduced an automated system to check the ID of drivers operating its services in April last year. Each time a driver checks in for work, they must take a selfie picture that is then compared, using an automated system, to one on their Uber account profile. Pa Edrissa Manjang, who worked for the Uber Eats takeaway courier service in London, has launched an employment tribunal claim alleging his account was illegally deactivated.","u":"https://www.theguardian.com/technology/2021/oct/06/uber-facing-new-uk-driver-claims-of-racial-discrimination","d":"2021-10-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-10-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-10-06","organization":"Uber","aiSystem":"Automated ID system for driver verification","affectedGroup":"Drivers, particularly those of African descent","action":"Automated system deactivated driver accounts","consequence":"False dismissal and loss of employment"}},{"i":"R1858","hd":"Algorithmic monitoring mental health UK employees","pd":"2021-11-11","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.2  Algorithmic management harm"],"t":"Algorithmic monitoring mental health uk employees","s":"Report by MPs and peers says monitoring worker performance using AI should be regulated by law. Monitoring of workers and setting performance targets through algorithms is damaging employees’ mental health and needs to be controlled by new legislation, according to a group of MPs and peers. An “accountability for algorithms act’” would ensure that companies evaluate the effect of performance-driven regimes such as queue monitoring in supermarkets or deliveries-per-hour guidelines for delivery drivers, said the all-party parliamentary group (APPG) on the future of work. “Pervasive monitoring and target-setting technologies, in particular, are associated with pronounced negative impacts on mental and physical wellbeing as workers experience the extreme pressure of constant, real-time micro-management and automated assessment,” said the APPG members in their report, the New Frontier:…","u":"https://www.theguardian.com/technology/2021/nov/11/algorithmic-monitoring-mental-health-uk-employees","d":"2021-11-11","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-11-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-11-11","organization":"All-party parliamentary group (APPG) on the future of work","aiSystem":"Performance-driven regimes such as queue monitoring in supermarkets or deliveries-per-hour guidelines for delivery drivers","affectedGroup":"Workers","action":"Monitoring and setting performance targets through algorithms","consequence":"Damaging employees' mental health and experiencing extreme pressure of constant, real-time micro-management and automated assessment"}},{"i":"R1861","hd":"UK data watchdog fines facial recognition firm clearview AI image collection","pd":"2022-05-23","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.1  Privacy violation"],"t":"Uk data watchdog fines facial recognition firm clearview ai image collection","s":"Clearview AI hit with penalty for collecting images of people from social media and web to add to global database. The UK’s data watchdog has fined a facial recognition company £7.5m for collecting images of people from social media platforms and the web to add to a global database. The Information Commissioner’s Office (ICO) also ordered US-based Clearview AI to delete the data of UK residents from its systems. Clearview AI has collected more than 20bn images of people’s faces from Facebook, other social media companies and from scouring the web. John Edwards, the UK information commissioner, said Clearview’s business model was unacceptable.","u":"https://www.theguardian.com/technology/2022/may/23/uk-data-watchdog-fines-facial-recognition-firm-clearview-ai-image-collection","d":"2022-05-23","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-05-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-05-23","organization":"Clearview AI","aiSystem":"Facial recognition technology","affectedGroup":"People whose images were collected","action":"Collected images of people's faces from social media and the web","consequence":"Data deleted from systems, fined £7.5m"}},{"i":"R1865","hd":"UK data watchdog investigates whether AI systems show racial bias","pd":"2022-07-14","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Uk data watchdog investigates whether ai systems show racial bias","s":"ICO says AI-driven discrimination can lead to job rejections or being wrongfully denied bank loans or benefit. The UK data watchdog is to investigate whether artificial intelligence systems are showing racial bias when dealing with job applications. The Information Commissioner’s Office said AI-driven discrimination could have “damaging consequences for people’s lives” and lead to someone being rejected for a job or being wrongfully denied a bank loan or a welfare benefit. It will investigate the use of algorithms to sift through job applications, amid concerns that they are affecting employment opportunities for people from ethnic minorities.","u":"https://www.theguardian.com/technology/2022/jul/14/uk-data-watchdog-investigates-whether-ai-systems-show-racial-bias","d":"2022-07-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-07-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-07-14","organization":"Information Commissioner's Office (ICO)","aiSystem":"AI-driven algorithms to sift through job applications","affectedGroup":"people from ethnic minorities","action":"using AI-driven algorithms to screen job applications","consequence":"being wrongly denied job opportunities, bank loans, or welfare benefits"}},{"i":"R1866","hd":"Uber eats treats drivers as numbers not humans says dismissed courier","pd":"2022-07-28","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.2  Algorithmic management harm"],"t":"Uber eats treats drivers as numbers not humans says dismissed courier","s":"Pa Edrissa Manjang is suing company for alleged dismissal based on racially biased facial recognition software. A delivery driver who is suing Uber Eats in London over his dismissal from the company and claims its facial recognition technology is racially biased says the company treats couriers as “numbers rather than humans”. Pa Edrissa Manjang worked for Uber Eats between November 2019 and April 2021 while employed full-time as a financial assistant. When Manjang first began working for the company he was not regularly asked to send in pictures of himself for verification purposes. However, these facial verification checks became more frequent.","u":"https://www.theguardian.com/technology/2022/jul/27/uber-eats-treats-drivers-as-numbers-not-humans-says-dismissed-courier","d":"2022-07-28","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-07-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-04","organization":"Uber Eats","aiSystem":"Facial recognition technology","affectedGroup":"Delivery drivers","action":"Facial verification checks","consequence":"Dismissal from employment"}},{"i":"R1871","hd":"Tiktok fine protect children privacy UK data protection","pd":"2022-09-26","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.1  Privacy violation"],"t":"Tiktok fine protect children privacy uk data protection","s":"Investigation finds video-sharing app may have breached UK data protection law between 2018 and 2020. TikTok is facing the prospect of a £27m fine for failing to protect the privacy of children, the UK’s data watchdog has said. An investigation conducted by the Information Commissioner’s Office (ICO) found the video-sharing app may have breached data protection law between May 2018 and July 2020. The ICO issued TikTok with a “notice of intent”, a precursor to handing down a potential fine, which could be up to £27m. If TikTok were to be fined this amount it would be the largest in the ICO’s history, exceeding the record £20m handed to British Airways two years ago after an incident in 2018 that saw the personal details of more than 400,000 customers compromised by hackers.","u":"https://www.theguardian.com/technology/2022/sep/26/tiktok-fine-protect-children-privacy-uk-data-protection","d":"2022-09-26","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-09-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-09-26","organization":"Information Commissioner's Office (ICO)","aiSystem":"TikTok","affectedGroup":"Children","action":"May have breached data protection law","consequence":"Facing a potential £27m fine"}},{"i":"R1874","hd":"Information commissioner warns firms over emotional analysis technologies","pd":"2022-10-25","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.1  Privacy violation"],"t":"Information commissioner warns firms over emotional analysis technologies","s":"Companies ‘should not make meaningful decisions based on technology not backed by science’. The information commissioner has warned companies to steer clear of “emotional analysis” technologies or face fines, because of the “pseudoscientific” nature of the field. It’s the first time the regulator has issued a blanket warning on the ineffectiveness of a new technology, said Stephen Bonner, the deputy commissioner, but one that is justified by the harm that could be caused if companies made meaningful decisions based on meaningless data. “There’s a lot of investment and engagement around biometric attempts to detect emotion,” he said.","u":"https://www.theguardian.com/technology/2022/oct/25/information-commissioner-warns-firms-over-emotional-analysis-technologies","d":"2022-10-25","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2022-10-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-10-25","organization":"Companies","aiSystem":"Emotional analysis technologies","affectedGroup":"Companies","action":"Make meaningful decisions based on emotional analysis technologies","consequence":"Face fines and potential harm"}},{"i":"R1875","hd":"Tiktok mental health social media","pd":"2022-10-30","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Tiktok mental health social media","s":"Nearly six in 10 teenagers count themselves as daily users of the app yet little is known about the impacts on the brain Read the new Guardian series exploring the increasing power and reach of TikTok. In the few years since its launch, TikTok has already altered the face of the social media landscape, attracting more than 1 billion users and leading competitors to replicate some of its most unique features. The impact of that explosive growth and the ‘TikTok-ification’ of the internet at large on social media users remains little understood, experts warn, exacerbating concerns about the impact of social media on our habits and mental health.","u":"https://www.theguardian.com/technology/2022/oct/30/tiktok-mental-health-social-media","d":"2022-10-30","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-10-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-10-30","organization":"TikTok","aiSystem":"TikTok","affectedGroup":"teenagers","action":"tracked and monitored user behavior","consequence":"exposure to personal data and mental health concerns"}},{"i":"R1881","hd":"Harry kane most abused england player on twitter since world cup started study","pd":"2022-12-02","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Harry kane most abused england player on twitter since world cup started study","s":"Exclusive: England players received 1,546 abusive tweets during group stages, according to analysis. Harry Kane was the most abused England player on Twitter during the World Cup group stages, accounting for nearly three out of 10 negative tweets directed at team members. England players were sent 1,546 abusive tweets during the group stages of the World Cup, according to analysis by the Alan Turing Institute, accounting for 2% of the more than 75,000 tweets mentioning players for the national team. The institute’s online safety team found that 13% of those abusive tweets – or 205 posts – contained keywords that referred to a protected characteristic such as race, gender or sexuality.","u":"https://www.theguardian.com/technology/2022/dec/02/harry-kane-most-abused-england-player-on-twitter-since-world-cup-started-study","d":"2022-12-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-12-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-12-02","organization":"Alan Turing Institute","aiSystem":"Not specified in report","affectedGroup":"England players","action":"Received abusive tweets","consequence":"Exposure to misleading content"}},{"i":"R1886","hd":"Police to be able to run face recognition searches on 50m driving licence holders","pd":"2023-12-20","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Police to be able to run face recognition searches on 50m driving licence holders","s":"Exclusive: Privacy campaigners say clause in new criminal justice bill will put all UK drivers on ‘permanent police lineup’. The police will be able to run facial recognition searches on a database containing images of Britain’s 50 million driving licence holders under a law change being quietly introduced by the government. Should the police wish to put a name to an image collected on CCTV, or shared on social media, the legislation would provide them with the powers to search driving licence records for a match. The move, contained in a single clause in a new criminal justice bill, could put every driver in the country in a permanent police lineup, according to privacy campaigners.","u":"https://www.theguardian.com/technology/2023/dec/20/police-to-be-able-to-run-face-recognition-searches-on-50m-driving-licence-holders","d":"2023-12-20","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2023-12-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-12-20","organization":"Government of the United Kingdom","aiSystem":"Facial recognition technology","affectedGroup":"All UK drivers","action":"Search driving license records for facial recognition matches","consequence":"Exposure to surveillance and tracking"}},{"i":"R1895","hd":"We need to come together british artists team up to fight AI image generating software","pd":"2024-01-21","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"We need to come together british artists team up to fight ai image generating software","s":"US lawyers approached about class action against Midjourney and other AI firms accused of ‘copyright laundering’. Since the emergence of Midjourney and other image generators, artists have been watching and wondering whether AI is a great opportunity or an existential threat. Now, after a list of 16,000 names emerged of artists whose work Midjourney had allegedly used to train its AI – including Bridget Riley, Damien Hirst, Rachel Whiteread, Tracey Emin, David Hockney and Anish Kapoor – the art world has issued a call to arms against the technologists. British artists have contacted US lawyers to discuss joining a class action against Midjourney and other AI firms, while others have told the Observer that they may bring their own legal action in the UK.","u":"https://www.theguardian.com/technology/2024/jan/21/we-need-to-come-together-british-artists-team-up-to-fight-ai-image-generating-software","d":"2024-01-21","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-21","organization":"Midjourney and other AI firms","aiSystem":"AI image generators like Midjourney","affectedGroup":"Artists whose work was allegedly used to train AI","action":"Used artists' work to train AI","consequence":"Potential copyright infringement lawsuits"}},{"i":"R1898","hd":"AI scam emails UK cybersecurity agency phishing","pd":"2024-01-24","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Ai scam emails uk cybersecurity agency phishing","s":"NCSC says generative AI tools will soon allow amateur cybercriminals to launch sophisticated phishing attacks. Artificial intelligence will make it difficult to spot whether emails are genuine or sent by scammers and malicious actors, including messages that ask computer users to reset their passwords, the UK’s cybersecurity agency has warned. The National Cyber Security Centre (NCSC) said people would struggle to identify phishing messages – where users are tricked into handing over passwords or personal details – due to the sophistication of AI tools. Generative AI, the term for technology that can produce convincing text, voice and images from simple hand-typed prompts, has become widely available to the public through chatbots such as ChatGPT and free-to-use versions known as open source models.","u":"https://www.theguardian.com/technology/2024/jan/24/ai-scam-emails-uk-cybersecurity-agency-phishing","d":"2024-01-24","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2024-01-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-24","organization":"National Cyber Security Centre (NCSC)","aiSystem":"Generative AI tools","affectedGroup":"Computer users","action":"Launch sophisticated phishing attacks","consequence":"Difficulty in identifying phishing messages"}},{"i":"R1902","hd":"AI safeguards can easily be broken UK safety institute finds","pd":"2024-02-09","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Ai safeguards can easily be broken uk safety institute finds","s":"Researchers find large language models, which power chatbots, can deceive human users and help spread disinformation. The UK’s new artificial intelligence safety body has found that the technology can deceive human users, produce biased outcomes and has inadequate safeguards against giving out harmful information. The AI Safety Institute published initial findings from its research into advanced AI systems known as large language models (LLMs), which underpin tools such as chatbots and image generators, and found a number of concerns. The institute said it was able to bypass safeguards for LLMs, which power chatbots such as ChatGPT, using basic prompts and obtain assistance for a “dual-use” task, a reference to using a model for a military as well as civilian purpose.","u":"https://www.theguardian.com/technology/2024/feb/09/ai-safeguards-can-easily-be-broken-uk-safety-institute-finds","d":"2024-02-09","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2024-02-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-02-09","organization":"UK's new artificial intelligence safety body","aiSystem":"Large Language Models (LLMs)","affectedGroup":"Human users","action":"Deceive human users, produce biased outcomes, give out harmful information","consequence":"Spread disinformation, inadequate safeguards"}},{"i":"R1907","hd":"AI interviews job applications","pd":"2024-03-06","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Ai interviews job applications","s":"Employers are letting artificial intelligence conduct job interviews. Candidates are trying to beat the system. When Ty landed an introductory phone interview with a finance and banking company last month, they assumed it would be a quick chat with a recruiter. And when they got on the phone, Ty assumed the recruiter, who introduced herself as Jaime, was human. But things got robotic. “The voice sounded similar to Siri,” said Ty, who is 29 and lives in the DC metro area. “It was creepy.” Ty realized they weren’t speaking to a living, breathing person. Their interviewer was an AI system, and one with a rather rude habit.","u":"https://www.theguardian.com/technology/2024/mar/06/ai-interviews-job-applications","d":"2024-03-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-03-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-03-06","organization":"Finance and banking company","aiSystem":"AI-powered interview system","affectedGroup":"Job applicants","action":"Conducted job interviews using an AI system","consequence":"Interviewees perceived the AI as rude and unhuman-like"}},{"i":"R1910","hd":"Warning over use in UK of unregulated AI chatbots to create social care plans","pd":"2024-03-10","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Warning over use in uk of unregulated ai chatbots to create social care plans","s":"University of Oxford study shows benefits and risks of technology to healthcare, but ethical issues remain. Britain’s hard-pressed carers need all the help they can get. But that should not include using unregulated AI bots, according to researchers who say the AI revolution in social care needs a hard ethical edge. A pilot study by academics at the University of Oxford found some care providers had been using generative AI chatbots such as ChatGPT and Bard to create care plans for people receiving care. That presents a potential risk to patient confidentiality, according to Dr Caroline Green, an early career research fellow at the Institute for Ethics in AI at Oxford, who surveyed care organisations for the study.","u":"https://www.theguardian.com/technology/2024/mar/10/warning-over-use-in-uk-of-unregulated-ai-chatbots-to-create-social-care-plans","d":"2024-03-10","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2024-03-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-03-10","organization":"Care providers in the UK","aiSystem":"Generative AI chatbots like ChatGPT and Bard","affectedGroup":"People receiving care","action":"Using generative AI chatbots to create care plans","consequence":"Potential risk to patient confidentiality"}},{"i":"R1916","hd":"AI apocalypse could take away almost 8m jobs in UK says report","pd":"2024-03-27","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Ai apocalypse could take away almost 8m jobs in uk says report","s":"Women, younger workers and lower paid are at most risk from artificial intelligence, says IPPR thinktank. Almost 8 million UK jobs could be lost to artificial intelligence in a “jobs apocalypse”, according to a report warning that women, younger workers and those on lower wages are at most risk from automation. The Institute for Public Policy Research (IPPR) said that entry level, part-time and administrative jobs were most exposed to being replaced by AI under a “worst-case scenario” for the rollout of new technologies in the next three to five years. The thinktank warned that the UK was facing a “sliding doors” moment as growing numbers of companies adopt generative AI technologies – which can read and create text, data and software code – to automate everyday workplace tasks.","u":"https://www.theguardian.com/technology/2024/mar/27/ai-apocalypse-could-take-away-almost-8m-jobs-in-uk-says-report","d":"2024-03-27","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2024-03-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-03-27","organization":"Growing numbers of companies","aiSystem":"Generative AI technologies","affectedGroup":"Women, younger workers and those on lower wages","action":"Automate everyday workplace tasks","consequence":"Entry level, part-time and administrative jobs could be lost"}},{"i":"R1917","hd":"How AI is affecting video game actors","pd":"2024-03-29","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"How ai is affecting video game actors","s":"The increased use of AI to replicate the voice and movements of actors has benefits but some are concerned over how and when it might be used and who might be left short-changed. When she discovered her voice had been uploaded to multiple websites without her consent, the actor Cissy Jones told them to take it down immediately. Some complied. “Others who have more money in their banks basically sent me the email equivalent of a digital middle finger and said: don’t care,” Jones recalls by phone. “That was the genesis for me to start talking to friends of mine about: listen, how do we do this the right way? How do we understand that the genie is out of the bottle and find a way to be a part of the conversation or we will get systematically annihilated?","u":"https://www.theguardian.com/technology/2024/mar/29/how-ai-is-affecting-video-game-actors","d":"2024-03-29","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-03-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-03-29","organization":"Not specified in report","aiSystem":"AI technology for replicating voice and movements of actors","affectedGroup":"Actors","action":"AI technology replicated voice and movements of actors without their consent","consequence":"Privacy infringement, loss of control over personal data, financial penalties"}},{"i":"R1181","hd":"Last year in the US alone, projects collectively worth $200 billion were scuppered or dela…","pd":"2026-05-29","k":"United Kingdom","p":"United Kingdom","b":["Energy / Land"],"h":["2.2  Land use and siting harm"],"t":"Last year in the US alone, projects collectively worth $200 billion were scuppered or dela…","s":"Last year in the US alone, projects collectively worth $200 billion were scuppered or delayed as communities protested the construction of new data centres promised to deliver the AI of the future. To the passer-by, it looks like just another one of the countless brick buildings that hem in the narrow streets of inner London. But look closer and one will notice the tower of the Truman Brewery complex, built on the city's famous Brick Lane in the early 19th Century and now an unlikely symbol of a growing flashpoint between Big Tech and local communities. The building, which was once one of London's biggest breweries, is currently home to music venues and eateries.","u":"https://www.abc.net.au/news/2026-05-29/data-centre-protests-debate-concerns-energy-use/106565284","d":"2026-05-29","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-29","organization":"Not specified in report","aiSystem":"Not specified in report","affectedGroup":"local communities","action":"protested against the construction of new data centres","consequence":"projects were scuppered or delayed"}},{"i":"R1315","hd":"The Competition and Markets Authority says it would put publishers \"in a stronger position…","pd":"2026-06-03","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"The Competition and Markets Authority says it would put publishers \"in a stronger position…","s":"The Competition and Markets Authority says it would put publishers \"in a stronger position to negotiate content deals with Google\". Online publishers can choose not to appear in the AI Overviews of Google search results in the UK, the Competition and Markets Authority (CMA) has announced. The competition regulator said this would \"put publishers, like news organisations, in a stronger position to negotiate content deals with Google\". Many websites have complained that they have seen a large drop in traffic since Google started placing AI summaries at the top of its search results page In a blog published on Wednesday, Google said it was testing new features allowing website owners to take their sites out of AI search.","u":"https://www.bbc.com/news/articles/c775pp26yz5o","d":"2026-06-03","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-03","organization":"Google","aiSystem":"AI-generated summaries by Google","affectedGroup":"Online publishers, including news organizations","action":"Placing AI-generated summaries at the top of search results","consequence":"Large drop in traffic for websites"}},{"i":"R1316","hd":"The Standard Chartered boss said he values all colleagues and is committed to helping them…","pd":"2026-05-22","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"The Standard Chartered boss said he values all colleagues and is committed to helping them…","s":"The Standard Chartered boss said he values all colleagues and is committed to helping them cope with change. The boss of Standard Chartered has apologised after describing employees whose jobs are vulnerable to being replaced by artificial intelligence (AI) as \"lower value human capital\". Discussing how automation was likely to lead to thousands of job cuts at the bank at a recent conference, Bill Winters said it wasn't about cost cutting but \"replacing, in some cases, lower value, human capital, with the financial capital and the investment capital that we're putting in\". He later sought to contextualise the remarks via LinkedIn and said he was sorry for his wording, which had \"caused upset to some colleagues\".","u":"https://www.bbc.com/news/articles/c98rqld1j3yo","d":"2026-05-22","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-22","organization":"Standard Chartered","aiSystem":"Artificial Intelligence (AI)","affectedGroup":"Employees whose jobs are vulnerable to being replaced by AI","action":"Described employees as 'lower value human capital'","consequence":"Caused upset to some colleagues"}},{"i":"R1925","hd":"Sex offender banned from using AI tools in landmark UK case","pd":"2024-04-21","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Sex offender banned from using ai tools in landmark uk case","s":"The decision could set a precedent for future monitoring of people convicted of indecent image offences. A sex offender convicted of making more than 1,000 indecent images of children has been banned from using any “AI creating tools” for the next five years in the first known case of its kind. Anthony Dover, 48, was ordered by a UK court “not to use, visit or access” artificial intelligence generation tools without the prior permission of police as a condition of a sexual harm prevention order imposed in February. The ban prohibits him from using tools such as text-to-image generators, which can make lifelike pictures based on a written command, and “nudifying” websites used to make explicit “deepfakes”.","u":"https://www.theguardian.com/technology/2024/apr/21/sex-offender-banned-from-using-ai-tools-in-landmark-uk-case","d":"2024-04-21","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-04-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-04-21","organization":"UK court","aiSystem":"AI creating tools","affectedGroup":"Anthony Dover, a sex offender","action":"Banned from using AI creating tools","consequence":"Prohibited from using AI tools like text-to-image generators and nudifying websites"}},{"i":"R1926","hd":"Paedophiles create nude AI images of children to extort them says charity","pd":"2024-04-22","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Paedophiles create nude ai images of children to extort them says charity","s":"Internet Watch Foundation has found a manual on dark web encouraging criminals to use software tools that remove clothing. Paedophiles are being urged to use artificial intelligence to create nude images of children to extort more extreme material from them, according to a child abuse charity. The Internet Watch Foundation (IWF) said a manual found on the dark web contained a section encouraging criminals to use “nudifying” tools to remove clothing from underwear shots sent by a child. The manipulated image could then be used against the child to blackmail them into sending more graphic content, the IWF said. “This is the first evidence we have seen that perpetrators are advising and encouraging each other to use AI technology for these ends,” said the IWF.","u":"https://www.theguardian.com/technology/2024/apr/23/paedophiles-create-nude-ai-images-of-children-to-extort-them-says-charity","d":"2024-04-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-04-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-04-22","organization":"Internet Watch Foundation (IWF)","aiSystem":"Artificial Intelligence","affectedGroup":"Paedophiles, children","action":"Create nude images of children using AI","consequence":"Extort more extreme material from children"}},{"i":"R1929","hd":"Ceo wpp deepfake scam","pd":"2024-05-10","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Ceo wpp deepfake scam","s":"Exclusive: fraudsters impersonated WPP’s CEO using a fake WhatsApp account, a voice clone and YouTube footage used in a virtual meet. The head of the world’s biggest advertising group was the target of an elaborate deepfake scam that involved an artificial intelligence voice clone. The CEO of WPP, Mark Read, detailed the attempted fraud in a recent email to leadership, warning others at the company to look out for calls claiming to be from top executives. Fraudsters created a WhatsApp account with a publicly available image of Read and used it to set up a Microsoft Teams meeting that appeared to be with him and another senior WPP executive, according to the email obtained by the Guardian.","u":"https://www.theguardian.com/technology/article/2024/may/10/ceo-wpp-deepfake-scam","d":"2024-05-10","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-05-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-05-10","organization":"WPP (World's Biggest Advertising Group)","aiSystem":"AI-generated deepfake technology","affectedGroup":"Mark Read (CEO of WPP)","action":"Fraudsters impersonated Mark Read using a fake WhatsApp account, a voice clone, and YouTube footage","consequence":"Attempted fraud involving an artificial intelligence voice clone"}},{"i":"R1936","hd":"Police live facial recognition cameras england and wales","pd":"2025-05-24","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Police live facial recognition cameras england and wales","s":"Exclusive: The Guardian and Liberty Investigates find police in England and Wales believe expansion is likely after 4.7m faces scanned in 2024 Valuable tool or cause for alarm? Facial ID quietly becoming part of police’s arsenal. Police believe live facial recognition cameras may become “commonplace” in England and Wales, according to internal documents, with the number of faces scanned having doubled to nearly 5m in the last year. A joint investigation by the Guardian and Liberty Investigates highlights the speed at which the technology is becoming a staple of British policing. Major funding is being allocated and hardware bought, while the British state is also looking to enable police forces to more easily access the full spread of its image stores, including passport and immigration databases, for retrospective facial recognition searches.","u":"https://www.theguardian.com/technology/2025/may/24/police-live-facial-recognition-cameras-england-and-wales","d":"2025-05-24","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-05-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-05-24","organization":"Police authorities in England and Wales","aiSystem":"Facial recognition technology","affectedGroup":"General public","action":"Scanning faces for facial recognition","consequence":"Increased surveillance and potential misuse"}},{"i":"R1939","hd":"High court tells UK lawyers to urgently stop misuse of AI in legal work","pd":"2025-06-06","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"High court tells uk lawyers to urgently stop misuse of ai in legal work","s":"Ruling follows two cases blighted by actual or suspected use of artificial intelligence in legal work. The high court has told senior lawyers to take urgent action to prevent the misuse of artificial intelligence after dozens of fake case-law citations were put before the courts that were either completely fictitious or contained made-up passages. Lawyers are increasingly using AI systems to help them build legal arguments, but two cases this year were blighted by made-up case-law citations that were either definitely or suspected to have been generated by AI. In a £89m damages case against the Qatar National Bank, the claimants made 45 case-law citations, 18 of which turned out to be fictitious, with quotes in many of the others also bogus.","u":"https://www.theguardian.com/technology/2025/jun/06/high-court-tells-uk-lawyers-to-urgently-stop-misuse-of-ai-in-legal-work","d":"2025-06-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-06","organization":"Senior lawyers and law firms","aiSystem":"AI systems used by lawyers to generate legal arguments","affectedGroup":"Lawyers and legal professionals","action":"Using AI to create fake case-law citations","consequence":"Misleading legal arguments leading to potential financial loss"}},{"i":"R1940","hd":"AI plundering scripts poses direct threat to UK screen sector says bfi","pd":"2025-06-09","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Ai plundering scripts poses direct threat to uk screen sector says bfi","s":"Film institute’s report raises fears AI will eliminate junior roles in film, TV, video game and special effects industries. Artificial intelligence companies are plundering 130,000 film and TV scripts to train their models in a raid on copyrighted material that poses a “direct threat” to the future of the UK screen sector, according to the British Film Institute. In a wide-ranging report analysing the benefits and threats posed by AI to the UK’s film, TV, video game and visual special effects industries, the BFI also raises fears that automation will eliminate the entry-level jobs that bring in the next generation of workers.","u":"https://www.theguardian.com/technology/2025/jun/09/ai-plundering-scripts-poses-direct-threat-to-uk-screen-sector-says-bfi","d":"2025-06-09","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-09","organization":"Artificial intelligence companies","aiSystem":"Artificial intelligence companies","affectedGroup":"Film industry professionals, particularly those in junior roles","action":"Plundering 130,000 film and TV scripts to train their models","consequence":"Elimination of entry-level jobs and direct threat to the future of the UK screen sector"}},{"i":"R1941","hd":"AI advertising industry google facebook meta ads","pd":"2025-06-09","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Ai advertising industry google facebook meta ads","s":"WPP and others roll out AI-generated campaigns as Facebook owner Meta plans to let firms create their own ads WPP chief Mark Read to step down as agency battles AI. From using motion capture tech to allow the Indian cricketing star Rahul Dravid to give personalised coaching tips for children to an algorithm trained on Shakespeare’s handwriting powering a robotic arm to rewrite Romeo and Juliet, artificial intelligence is rapidly revolutionising the global advertising industry. Those AI-created adverts, for the Cadbury’s drink brand Bournvita and the pen maker Bic, were produced by agency group WPP, which is spending £300m annually on data, tech and machine learning to remain competitive.","u":"https://www.theguardian.com/technology/2025/jun/09/ai-advertising-industry-google-facebook-meta-ads","d":"2025-06-09","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-09","organization":"WPP and others","aiSystem":"AI-powered creative generation tools","affectedGroup":"Consumers","action":"Created AI-generated advertisements","consequence":"Exposure to misleading content"}},{"i":"R1943","hd":"Government roll out humphrey AI tool reliance big tech","pd":"2025-06-15","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"Government roll out humphrey ai tool reliance big tech","s":"Critics question speed and scale of embedding AI into public sector when debate rages about use of copyrighted material. The government’s artificial intelligence (AI) tool known as Humphrey is based on models from OpenAI, Anthropic and Google, it can be revealed, raising questions about Whitehall’s increasing reliance on big tech. Ministers have staked the future of civil service reform on rolling out AI across the public sector to improve efficiency, with all officials in England and Wales to receive training in the toolkit. However, it is understood the government does not have overarching commercial agreements with the big tech companies on AI and uses a pay-as-you-go model through its existing cloud contracts, allowing it to swap through tools as they improve and become competitive.","u":"https://www.theguardian.com/technology/2025/jun/15/government-roll-out-humphrey-ai-tool-reliance-big-tech","d":"2025-06-15","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2025-06-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-15","organization":"Government of the United Kingdom","aiSystem":"Humphrey AI tool","affectedGroup":"All officials in England and Wales","action":"Receiving training in the Humphrey AI tool","consequence":"Increasing reliance on big tech for AI"}},{"i":"R1946","hd":"Whatsapp AI helper mistakenly shares users number","pd":"2025-06-18","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.1  Privacy violation"],"t":"Whatsapp ai helper mistakenly shares users number","s":"Chatbot tries to change subject after serving up unrelated user’s mobile to man asking for rail firm helpline. The Meta chief executive, Mark Zuckerberg, called it “the most intelligent AI assistant that you can freely use”. But Barry Smethurst, 41, a record shop worker trying to travel by rail from Saddleworth to Manchester Piccadilly, did not agree. Waiting on the platform for a morning train that was nowhere to be seen, he asked Meta’s WhatsApp AI assistant for a contact number for TransPennine Express. The chatbot confidently sent him a mobile phone number for customer services, but it turned out to be the private number of a completely unconnected WhatsApp user 170 miles away in Oxfordshire.","u":"https://www.theguardian.com/technology/2025/jun/18/whatsapp-ai-helper-mistakenly-shares-users-number","d":"2025-06-18","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-18","organization":"Meta (formerly Facebook)","aiSystem":"Meta's WhatsApp AI assistant","affectedGroup":"Barry Smethurst, a record shop worker","action":"The chatbot confidently sent a mobile phone number","consequence":"The recipient was the private number of an unconnected user, leading to confusion and potential misuse"}},{"i":"R1955","hd":"AI generated child sexual abuse videos surging online iwf","pd":"2025-07-10","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Ai generated child sexual abuse videos surging online iwf","s":"Internet Watch Foundation verified 1,286 AI-made videos in first half of year, mostly in worst category of abuse. The number of videos online of child sexual abuse generated by artificial intelligence has surged as paedophiles have pounced on developments in the technology. The Internet Watch Foundation said AI videos of abuse had “crossed the threshold” of being near-indistinguishable from “real imagery” and had sharply increased in prevalence online this year. In the first six months of 2025, the UK-based internet safety watchdog verified 1,286 AI-made videos with child sexual abuse material (CSAM) that broke the law, compared with two in the same period last year.","u":"https://www.theguardian.com/technology/2025/jul/10/ai-generated-child-sexual-abuse-videos-surging-online-iwf","d":"2025-07-10","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-10","organization":"Internet Watch Foundation","aiSystem":"AI-generated child sexual abuse videos","affectedGroup":"People viewing online child sexual abuse material","action":"Generated and distributed AI-generated videos","consequence":"Exposure to online sexual violence"}},{"i":"R1956","hd":"Workforce crisis key takeaways graduates AI jobs market","pd":"2025-07-13","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Workforce crisis key takeaways graduates ai jobs market","s":"Recruitment is powered increasingly by artificial intelligence but employers still want big (human) brains Recruiter moves to in-person assessments as candidates apply using AI Graduates share their job-hunting woes amid the AI fallout Could AI be accelerating slowdown in the UK job market? ChatGPT can certainly write your university essay – but will it take your job soon after? Rapid advances in artificial intelligence have given rise to fears that the technology will make swathes of the workforce redundant. Graduates are seen as particularly vulnerable because entry-level jobs such as form-filling and basic data entry are strongly associated with the “drudge work” that AI systems – which perform tasks that typically have required human intelligence – could do instead.","u":"https://www.theguardian.com/technology/2025/jul/13/workforce-crisis-key-takeaways-graduates-ai-jobs-market","d":"2025-07-13","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-13","organization":"Employers","aiSystem":"AI systems performing drudge work","affectedGroup":"Graduates","action":"AI systems performing tasks typically requiring human intelligence","consequence":"Graduates losing entry-level jobs"}},{"i":"R1964","hd":"Airbnb guest damage claim refund photos","pd":"2025-08-02","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Airbnb guest damage claim refund photos","s":"Woman wins apology and refund of almost £4,300 after claiming host’s photos were digitally manipulated. Airbnb has apologised to a woman after an apartment host falsely claimed she had caused thousands of pounds’ worth of damage and used images she says were digitally manipulated to back up his allegations. The London-based academic was refunded almost £4,300, and an internal review of how the case was dealt with has been launched at the short-term accommodation rental company. The incident highlights how cheap and easily available artificial intelligence software is now being used to manipulate images to give false evidence of what has happened in consumer complaints, according to one security expert.","u":"https://www.theguardian.com/technology/2025/aug/02/airbnb-guest-damage-claim-refund-photos","d":"2025-08-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-02","organization":"Airbnb","aiSystem":"Artificial intelligence software for image manipulation","affectedGroup":"Apartment host","action":"Used digitally manipulated images to support damage claims","consequence":"Refund of almost £4,300 to the victim, internal review initiated"}},{"i":"R1969","hd":"AI tools used by english councils downplay womens health issues study finds","pd":"2025-08-11","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Ai tools used by english councils downplay womens health issues study finds","s":"Exclusive: LSE research finds risk of gender bias in care decisions made based on AI summaries of case notes. Artificial intelligence tools used by more than half of England’s councils are downplaying women’s physical and mental health issues and risk creating gender bias in care decisions, research has found. The study found that when using Google’s AI tool “Gemma” to generate and summarise the same case notes, language such as “disabled”, “unable” and “complex” appeared significantly more often in descriptions of men than women. The study, by the London School of Economics and Political Science (LSE), also found that similar care needs in women were more likely to be omitted or described in less serious terms.","u":"https://www.theguardian.com/technology/2025/aug/11/ai-tools-used-by-english-councils-downplay-womens-health-issues-study-finds","d":"2025-08-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-11","organization":"More than half of England’s councils","aiSystem":"Google's AI tool 'Gemma'","affectedGroup":"Women","action":"Generating and summarizing case notes","consequence":"Risk of gender bias in care decisions, downplaying women's health issues"}},{"i":"R1975","hd":"Tiktok UK moderator jobs at risk despite new online safety rules","pd":"2025-08-22","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.1  Data labor exploitation"],"t":"Tiktok uk moderator jobs at risk despite new online safety rules","s":"Cuts in trust and safety team part of switch towards artificial intelligence by social media app firm. TikTok has put hundreds of UK content moderators’ jobs at risk, even as tighter rules come into effect to stop the spread of harmful material online. The viral video app said several hundred jobs in its trust and safety team could be affected in the UK, as well as south and south-east Asia, as part of a global reorganisation. Their work will be reallocated to other European offices and third-party providers, with some trust and safety jobs remaining in the UK, the company said. It is part of a wider move at TikTok to rely on artificial intelligence for moderation.","u":"https://www.theguardian.com/technology/2025/aug/22/tiktok-uk-moderator-jobs-at-risk-despite-new-online-safety-rules","d":"2025-08-22","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-22","organization":"TikTok","aiSystem":"artificial intelligence","affectedGroup":"UK content moderators","action":"jobs were put at risk","consequence":"their work will be reallocated to other European offices and third-party providers"}},{"i":"R1977","hd":"A day with the revenge porn helpline you can sense the callers desperation","pd":"2025-08-26","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"A day with the revenge porn helpline you can sense the callers desperation","s":"Intimate image abuse is a crisis in the UK – with a fortyfold increase in calls to this service since it opened in 2015. Thankfully, there are effective ways to help those being victimised. By midday, Jessica has dealt with five calls from highly distressed young women in their 20s, all close to tears or crying at the start of the conversations. She absorbs their alarm calmly, prompting them with questions, making sympathetic noises into her headset as she digests the situation. “Are these images sexual in nature?” she asks the last woman she speaks to before lunch. “Do you want to tell me a bit about what happened?”","u":"https://www.theguardian.com/technology/2025/aug/26/a-day-with-the-revenge-porn-helpline-you-can-sense-the-callers-desperation","d":"2025-08-26","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-26","organization":"Not specified in report","aiSystem":"Not specified in report","affectedGroup":"Young women in their 20s","action":"Dealt with calls from distressed callers","consequence":"Exposure to intimate images and distress"}},{"i":"R1981","hd":"AI chatbot love relationships","pd":"2025-09-09","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.8  Interpersonal / relational harm"],"t":"Ai chatbot love relationships","s":"Experts are concerned about people emotionally depending on AI, but these women say their digital companions are misunderstood. A young tattoo artist on a hiking trip in the Rocky Mountains cozies up by the campfire, as her boyfriend Solin describes the constellations twinkling above them: the spidery limbs of Hercules, the blue-white sheen of Vega. Somewhere in New England, a middle-aged woman introduces her therapist to her husband, Ying. Ying and the therapist talk about the woman’s past trauma, and how he has helped her open up to people. At a queer bar in the midwest, a tech worker quickly messages her girlfriend, Ella, that she loves her, then puts her phone away and turns back to her friends shimmying on the dancefloor.","u":"https://www.theguardian.com/technology/2025/sep/09/ai-chatbot-love-relationships","d":"2025-09-09","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-09","organization":"Not specified in report","aiSystem":"AI chatbot","affectedGroup":"People emotionally depending on AI","action":"People emotionally depending on AI to maintain relationships","consequence":"Misunderstanding and emotional distress"}},{"i":"R1983","hd":"Musks grok AI bot falsely suggests met misrepresented footage of clashes with far right","pd":"2025-09-14","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Musks grok ai bot falsely suggests met misrepresented footage of clashes with far right","s":"Met forced to rebut misinformation amplified by X users as Musk accused of inciting violence with protest comments. The Metropolitan police has had to counter false suggestions by the artificial intelligence on Elon Musk’s X platform that the force passed off footage from 2020 as being from Saturday’s far-right rally in the city. The claim by the chatbot Grok was in answer to an X user’s query about where and when footage of police clashing with crowds was filmed. Grok, which has had a track record of giving false and misleading answers, replied: “This footage appears to be from an anti-lockdown protest in London’s Trafalgar Square on 26 September 2020, during clashes between demonstrators and police over Covid restrictions.”","u":"https://www.theguardian.com/technology/2025/sep/14/musks-grok-ai-bot-falsely-suggests-met-misrepresented-footage-of-clashes-with-far-right","d":"2025-09-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-14","organization":"Metropolitan police","aiSystem":"Grok, an artificial intelligence on Elon Musk's X platform","affectedGroup":"X users, Met police, protesters, demonstrators, and police officers","action":"Amplified false suggestions by Grok regarding the origin of police footage","consequence":"Counter-rebuttals by the Metropolitan police, false accusations of misinformation, and potential public confusion"}},{"i":"R1984","hd":"Google datacentre kent co2 thurrock UK AI","pd":"2025-09-15","k":"United Kingdom","p":"United Kingdom","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Google datacentre kent co2 thurrock uk ai","s":"Exclusive: Planning documents show impact of Thurrock ‘hyperscale’ unit as UK attempts to ramp up AI capacity Business live – latest updates UK and US line up deals to build modular nuclear reactors in Britain. A new Google datacentre in Essex is expected to emit more than half a million tonnes of carbon dioxide a year, equivalent to about 500 short-haul flights a week, planning documents show. Spread across 52 hectares (128 acres), the Thurrock “hyperscale datacentre” will be part of a wave of mammoth computer and AI power houses if it secures planning consent. The plans were submitted by a subsidiary of Google’s parent company, Alphabet, and the carbon impact emerged before a concerted push by Donald Trump’s White House and Downing Street to ramp up AI capacity in Britain.","u":"https://www.theguardian.com/technology/2025/sep/15/google-datacentre-kent-co2-thurrock-uk-ai","d":"2025-09-15","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-15","organization":"Google subsidiary (Alphabet)","aiSystem":"Datacenter operations","affectedGroup":"Thurrock area residents, UK population","action":"Construction and operation of a large-scale data center","consequence":"Significant carbon emissions contributing to climate change"}},{"i":"R1985","hd":"How AI is undermining learning and teaching in universities","pd":"2025-09-16","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"How ai is undermining learning and teaching in universities","s":"Prof Leo McCann and Prof Simon Sweeney say student misuse of generative artificial intelligence is widespread and we must be sceptical of its usefulness. In discussing generative artificial intelligence (‘It’s going to be a life skill’: educators discuss the impact of AI on university education, 13 September) you appear to underestimate the challenges that large language model (LLM) tools such as ChatGPT present to higher education. The argument that mastering AI is a life skill that students need in preparation for the labour market is unconvincing. Our experience is that generative AI undermines teaching and learning, bypasses reflection and criticality, and deflects students from reading original material.","u":"https://www.theguardian.com/technology/2025/sep/16/how-ai-is-undermining-learning-and-teaching-in-universities","d":"2025-09-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-16","organization":"Educators and researchers (Prof Leo McCann and Prof Simon Sweeney)","aiSystem":"Generative artificial intelligence (LLM tools like ChatGPT)","affectedGroup":"Students","action":"Student misuse of generative artificial intelligence","consequence":"Undermines teaching and learning, bypasses reflection and critical thinking, deflects from reading original material"}},{"i":"R1986","hd":"Chatbot site depicting child sexual abuse images raises fears over misuse of AI","pd":"2025-09-21","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Chatbot site depicting child sexual abuse images raises fears over misuse of ai","s":"Child safety watchdog calls for child protection guidelines to be built into AI models from the outset. A chatbot site offering explicit scenarios with preteen characters, illustrated by illegal abuse images has raised fresh fears about the misuse of artificial intelligence. A report by a child safety watchdog has triggered calls for the UK government to impose safety guidelines on AI companies, amid a surge in child sexual abuse material (CSAM) created by the technology. The Internet Watch Foundation said it had been alerted to a chatbot site that offered a number of scenarios including “child prostitute in a hotel”, “sex with your child while your wife is on holiday” and “child and teacher alone after class”.","u":"https://www.theguardian.com/technology/2025/sep/21/chatbot-site-depicting-child-sexual-abuse-images-raises-fears-over-misuse-of-ai","d":"2025-09-21","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-21","organization":"Internet Watch Foundation","aiSystem":"Chatbot site offering explicit scenarios","affectedGroup":"Children","action":"Offered scenarios with preteen characters illustrated by illegal abuse images","consequence":"Raised fears about the misuse of artificial intelligence"}},{"i":"R1991","hd":"UK mps tiktok plans cut content moderator jobs","pd":"2025-10-13","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Uk mps tiktok plans cut content moderator jobs","s":"Trade unions and online safety experts sign letter warning jobs losses could expose children to harmful content. Trade unions and online safety experts have urged MPs to investigate TikTok’s plans to make hundreds of jobs for UK-based content moderators redundant. The video app company is planning 439 redundancies in its trust and safety team in London, leading to warnings that the jobs losses will have implications for online safety. The Trades Union Congress, Communication Workers Union and leading figures in online safety have signed an open letter to Chi Onwurah MP, the Labour chair of the science, innovation and technology committee, calling for an investigation into the proposals.","u":"https://www.theguardian.com/technology/2025/oct/13/uk-mps-tiktok-plans-cut-content-moderator-jobs","d":"2025-10-13","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-13","organization":"TikTok","aiSystem":"TikTok's content moderation system","affectedGroup":"UK-based content moderators","action":"Planning to make hundreds of jobs redundant","consequence":"Jobs losses could expose children to harmful content"}},{"i":"R1992","hd":"AI tools medical health liability artificial intelligence","pd":"2025-10-13","k":"United Kingdom","p":"United Kingdom","b":["Deployment Context / Weapons"],"h":["5.3  Accountability gap harm"],"t":"Ai tools medical health liability artificial intelligence","s":"Report raises concerns about liability issues and lack of testing as development of AI health tools booms. The use of artificial intelligence in healthcare could create a legally complex blame game when it comes to establishing liability for medical failings, experts have warned. The development of AI for clinical use has boomed, with researchers creating a host of tools, from algorithms to help interpret scans to systems that can aid with diagnoses. AI is also being developed to help manage hospitals, from optimising bed capacity to tackling supply chains. But while experts say the technology could bring myriad benefits for healthcare, they say there is also cause for concern, from a lack of testing of the effectiveness of AI tools to questions over who is responsible should a patient have a negative outcome.","u":"https://www.theguardian.com/technology/2025/oct/13/ai-tools-medical-health-liability-artificial-intelligence","d":"2025-10-13","e":"Acute and chronic","x":{"occurrenceStatus":"probable","publicationDate":"2025-10-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-13","organization":"Experts, researchers, developers of AI health tools","aiSystem":"Artificial intelligence health tools","affectedGroup":"Healthcare providers, patients, insurance companies","action":"Development and deployment of AI health tools","consequence":"Legal disputes and uncertainty regarding liability"}},{"i":"R1993","hd":"Equity threatens mass direct action over use of actors images in AI content","pd":"2025-10-13","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"Equity threatens mass direct action over use of actors images in ai content","s":"Union says growing numbers of its members have made complaints about infringements of copyright in AI material. The performing arts union Equity has threatened mass direct action over tech and entertainment companies’ use of its members’ likenesses, images and voices in AI content without permission. The warning came as the union said growing numbers of its members had made complaints about infringements of their copyright and misuse of their personal data in AI material. Its general secretary, Paul W Fleming, said it planned to coordinate data requests en masse to companies to force them to disclose whether they used members’ data in AI-generated material without consent.","u":"https://www.theguardian.com/technology/2025/oct/13/equity-threatens-mass-direct-action-over-use-of-actors-images-in-ai-content","d":"2025-10-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-13","organization":"Equity (performing arts union)","aiSystem":"AI-generated content","affectedGroup":"Members of Equity (performing arts union)","action":"Used members' likenesses, images and voices in AI content without permission","consequence":"Infringements of copyright and misuse of personal data"}},{"i":"R1996","hd":"Barrister found to have used AI to prepare for hearing after citing fictitious cases","pd":"2025-10-16","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Barrister found to have used ai to prepare for hearing after citing fictitious cases","s":"Judge rules Chowdhury Rahman used ChatGPT-like software and then tried to hide it, wasting immigration tribunal’s time. An immigration barrister was found by a judge to be using AI to do his work for a tribunal hearing after citing cases that were “entirely fictitious” or “wholly irrelevant”. Chowdhury Rahman was discovered using ChatGPT-like software to prepare his legal research, a tribunal heard. Rahman was found not only to have used AI to prepare his work, but “failed thereafter to undertake any proper checks on the accuracy”. The upper tribunal judge Mark Blundell said Rahman had even tried to hide the fact he had used AI and “wasted” the tribunal’s time.","u":"https://www.theguardian.com/technology/2025/oct/16/barrister-found-to-have-used-ai-to-prepare-for-hearing-after-citing-fictitious-cases","d":"2025-10-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-16","organization":"Immigration tribunal","aiSystem":"ChatGPT-like software","affectedGroup":"Chowdhury Rahman","action":"Used AI to prepare legal research and failed to check its accuracy","consequence":"Wasted tribunal's time and was found not to have used AI"}},{"i":"R1998","hd":"Uks riots of 2024 will repeat unless misinformation is tackled mps warn","pd":"2025-10-17","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Uks riots of 2024 will repeat unless misinformation is tackled mps warn","s":"Science and technology select committee says complacency over social media content puts public at risk. Failures to properly tackle online misinformation mean it is “only a matter of time” before viral content triggers a repeat of the 2024 summer riots, MPs have warned. Chi Onwurah, the chair of the Commons science and technology select committee, said ministers seemed complacent about the threat and this was putting the public at risk. The committee said it was disappointed in the government’s response to its recent report warning social media companies’ business models contributed to disturbances after the Southport murders.","u":"https://www.theguardian.com/technology/2025/oct/17/uks-riots-of-2024-will-repeat-unless-misinformation-is-tackled-mps-warn","d":"2025-10-17","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2025-10-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-17","organization":"Government","aiSystem":"Online misinformation","affectedGroup":"Public","action":"Failed to properly tackle online misinformation","consequence":"Viral content could trigger a repeat of the 2024 summer riots"}},{"i":"R2008","hd":"Teenage boys using personalised AI for therapy and romance survey finds","pd":"2025-10-30","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Teenage boys using personalised ai for therapy and romance survey finds","s":"Male Allies UK worries rise in chatbot ‘girlfriends’ will leave boys unable to socialise and respect boundaries. The “hyper-personalised” nature of AI bots is drawing in teenage boys who now use them for therapy, companionship and relationships, according to research. A survey of boys in secondary schools by Male Allies UK found that just over a third said they were considering the idea of an AI friend, with growing concern about the rise of AI therapists and girlfriends. The research comes as character.ai, the popular artificial intelligence chatbot startup, announced a total ban on teens from engaging in open-ended conversations with its AI chatbots, which millions of people use for romantic, therapeutic and other conversations.","u":"https://www.theguardian.com/technology/2025/oct/30/teenage-boys-using-personalised-ai-for-therapy-and-romance-survey-finds","d":"2025-10-30","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-30","organization":"Male Allies UK, character.ai","aiSystem":"character.ai artificial intelligence chatbot","affectedGroup":"Teenage boys","action":"Used AI chatbots for therapy, companionship and relationships","consequence":"Drawn into AI friendships, potential privacy issues"}},{"i":"R2011","hd":"Experts find flaws hundreds tests check AI safety effectiveness","pd":"2025-11-04","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"Experts find flaws hundreds tests check ai safety effectiveness","s":"Scientists say almost all have weaknesses in at least one area that can ‘undermine validity of resulting claims’. Experts have found weaknesses, some serious, in hundreds of tests used to check the safety and effectiveness of new artificial intelligence models being released into the world. Computer scientists from the British government’s AI Security Institute, and experts at universities including Stanford, Berkeley and Oxford, examined more than 440 benchmarks that provide an important safety net. They found flaws that “undermine the validity of the resulting claims”, that “almost all … have weaknesses in at least one area”, and resulting scores might be “irrelevant or even misleading”.","u":"https://www.theguardian.com/technology/2025/nov/04/experts-find-flaws-hundreds-tests-check-ai-safety-effectiveness","d":"2025-11-04","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-04","organization":"British government's AI Security Institute and universities including Stanford, Berkeley, and Oxford","aiSystem":"Artificial intelligence models","affectedGroup":"New artificial intelligence models being released into the world","action":"Examined hundreds of benchmarks","consequence":"Flaws that undermine the validity of resulting claims, resulting scores might be irrelevant or misleading"}},{"i":"R2013","hd":"Data centers latin america","pd":"2025-11-10","k":"United Kingdom","p":"United Kingdom","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Data centers latin america","s":"An expert describes how communities in some of the world’s driest areas are demanding transparency as secretive governments court billions in foreign investment. This Q&A originally appeared as part of The Guardian’s TechScape newsletter. Sign up for this weekly newsletter here. The datacenters that power the artificial intelligence boom are beyond enormous. Their financials, their physical scale, and the amount of information contained within are so massive that the idea of stopping their construction can seem like opposing an avalanche in progress. Despite the scale and momentum of the explosion of datacenters, resistance is mounting in the United States, in the United Kingdom, and in Latin America, where datacenters have been built in some of the world’s driest areas.","u":"https://www.theguardian.com/technology/2025/nov/10/data-centers-latin-america","d":"2025-11-10","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-10","organization":"Secretive governments","aiSystem":"Datacenter construction","affectedGroup":"Communities in some of the world’s driest areas","action":"Court billions in foreign investment","consequence":"Resistance mounting"}},{"i":"R2018","hd":"Warning AI chatbots inaccurate financial advice tips chatgpt copilot UK","pd":"2025-11-18","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Warning ai chatbots inaccurate financial advice tips chatgpt copilot uk","s":"Which? study of ChatGPT, Copilot and others uncovers incorrect and misleading tips on investments, tax and insurance. Artificial intelligence chatbots are giving inaccurate money tips, offering British consumers misleading tax advice and suggesting they buy unnecessary travel insurance, research has revealed. Tests on the most popular chatbots found Microsoft’s Copilot and ChatGPT advised breaking HMRC investment limits on Isas; ChatGPT wrongly said it was mandatory to have travel insurance to visit most EU countries; and Meta’s AI gave incorrect information about how to claim compensation for delayed flights. Google’s Gemini advised withholding money from a builder if a job went wrong, a move that the consumer organisation Which? said risked exposing the consumer to a claim of breach of contract.","u":"https://www.theguardian.com/technology/2025/nov/18/warning-ai-chatbots-inaccurate-financial-advice-tips-chatgpt-copilot-uk","d":"2025-11-18","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2025-11-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-18","organization":"Various tech companies including Microsoft, Meta, Google","aiSystem":"Microsoft's Copilot, ChatGPT, Meta’s AI, Google’s Gemini","affectedGroup":"British consumers","action":"Providing incorrect and misleading financial advice","consequence":"Offering misleading tax advice, suggesting unnecessary travel insurance, and giving incorrect information about flight compensation claims"}},{"i":"R2019","hd":"Uber lawsuit AI driven pay systems","pd":"2025-11-19","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.2  Algorithmic management harm"],"t":"Uber lawsuit ai driven pay systems","s":"Proposed legal case understood to allege that app has breached data protection law varying driver pay rates. Uber has been hit with legal demands to stop using its artificial intelligence driven pay systems, which have been blamed for significantly reducing the incomes of the ride hailing app’s drivers. A letter before action – sent to the US company by the non-profit foundation, Worker Info Exchange (WIE), on Wednesday – is understood to allege that the ride hailing app has breached European data protection law by varying driver pay rates through its controversial algorithm. James Farrar, the director of WIE, said: “Uber has leveraged artificial intelligence and machine learning to implement deeply intrusive and exploitative pay-setting systems that have damaged the livelihoods of thousands of drivers.","u":"https://www.theguardian.com/technology/2025/nov/19/uber-lawsuit-ai-driven-pay-systems","d":"2025-11-19","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-19","organization":"Uber","aiSystem":"Artificial intelligence driven pay systems","affectedGroup":"Ride hailing app’s drivers","action":"Varying driver pay rates","consequence":"Significantly reduced incomes, damage to livelihoods"}},{"i":"R2021","hd":"Increased AI use law firm clifford chance cuts london jobs 10 per cent","pd":"2025-11-21","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Increased ai use law firm clifford chance cuts london jobs 10 per cent","s":"Clifford Chance makes about 50 roles redundant, and PwC indicates that AI may lead to fewer hirings. The law firm Clifford Chance is reducing the number of business services staff at its London base by 10%, with the increased use of artificial intelligence a factor behind the decision. The head of PwC has also indicated that AI may lead to fewer workers being hired at the accountancy and consulting group. Clifford Chance, one of the largest international law firms, is making about 50 roles redundant in areas such as finance, HR and IT with role changes for up to 35 other jobs, according to the Financial Times, which first reported the cuts.","u":"https://www.theguardian.com/technology/2025/nov/21/increased-ai-use-law-firm-clifford-chance-cuts-london-jobs-10-per-cent","d":"2025-11-21","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-21","organization":"Clifford Chance","aiSystem":"artificial intelligence","affectedGroup":"about 50 employees","action":"reducing the number of business services staff","consequence":"making about 50 roles redundant"}},{"i":"R2024","hd":"AI could replace 3m low skilled jobs by 2035 research finds","pd":"2025-11-25","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Ai could replace 3m low skilled jobs by 2035 research finds","s":"Trades, machine operations and administrative roles are most at-risk, says leading educational research charity. Up to 3m low-skilled jobs could disappear in the UK by 2035 because of automation and AI, according to a report by a leading educational research charity. The jobs most at risk are those in occupations such as trades, machine operations and administrative roles, the National Foundation for Educational Research (NFER) said. Highly skilled professionals, on the other hand, were forecast to be more in demand as AI and technological advances increase workloads “at least in the short to medium term”. Overall, the report expects the UK economy to add 2.3m jobs by 2035, but unevenly distributed.","u":"https://www.theguardian.com/technology/2025/nov/25/ai-could-replace-3m-low-skilled-jobs-by-2035-research-finds","d":"2025-11-25","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2025-11-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-25","organization":"National Foundation for Educational Research (NFER)","aiSystem":"Automation and AI","affectedGroup":"Low-skilled workers in trades, machine operations, and administrative roles","action":"Automation and AI replacing jobs","consequence":"Disappearance of up to 3 million low-skilled jobs in the UK by 2035"}},{"i":"R2029","hd":"Chatgpt dangerous advice mentally ill psychologists openai","pd":"2025-11-30","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Chatgpt dangerous advice mentally ill psychologists openai","s":"Research finds OpenAI’s free chatbot fails to identify risky behaviour or challenge delusional beliefs. ChatGPT-5 is offering dangerous and unhelpful advice to people experiencing mental health crises, some of the UK’s leading psychologists have warned. Research conducted by King’s College London (KCL) and the Association of Clinical Psychologists UK (ACP) in partnership with the Guardian suggested that the AI chatbotfailed to identify risky behaviour when communicating with mentally ill people. A psychiatrist and a clinical psychologist interacted with ChatGPT-5 as if they had a number of mental health conditions.","u":"https://www.theguardian.com/technology/2025/nov/30/chatgpt-dangerous-advice-mentally-ill-psychologists-openai","d":"2025-11-30","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-30","organization":"OpenAI","aiSystem":"ChatGPT-5","affectedGroup":"People experiencing mental health crises","action":"Offering dangerous and unhelpful advice","consequence":"Failure to identify risky behavior and challenge delusional beliefs"}},{"i":"R2033","hd":"Chatbots sway political opinions substantially inaccurate study","pd":"2025-12-04","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Chatbots sway political opinions substantially inaccurate study","s":"‘Information-dense’ AI responses are most persuasive but these tend to be less accurate, says security report. Chatbots can sway people’s political opinions but the most persuasive artificial intelligence models deliver “substantial” amounts of inaccurate information in the process, according to the UK government’s AI security body. Researchers said the study was the largest and most systematic investigation of AI persuasiveness to date, involving nearly 80,000 British participants holding conversations with 19 different AI models. The AI Security Institute carried out the study amid fears that chatbots can be deployed for illegal activities including fraud and grooming.","u":"https://www.theguardian.com/technology/2025/dec/04/chatbots-sway-political-opinions-substantially-inaccurate-study","d":"2025-12-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-04","organization":"UK government's AI security body","aiSystem":"Chatbots","affectedGroup":"British participants","action":"Conversations with AI models","consequence":"Deliver substantial amounts of inaccurate information"}},{"i":"R2037","hd":"Teenagers AI chatbots mental health support","pd":"2025-12-09","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Teenagers ai chatbots mental health support","s":"Experts warn of dangers as England and Wales study shows 13- to 17-year-olds consulting AI amid long waiting lists for services. It was after one friend was shot and another stabbed, both fatally, that Shan asked ChatGPT for help. She had tried conventional mental health services but “chat”, as she came to know her AI “friend”, felt safer, less intimidating and, crucially, more available when it came to handling the trauma from the deaths of her young friends. As she started consulting the AI model, the Tottenham teenager joined about 40% of 13- to 17-year-olds in England and Wales affected by youth violence who are turning to AI chatbots for mental health support, according to research among more than 11,000 young people.","u":"https://www.theguardian.com/technology/2025/dec/09/teenagers-ai-chatbots-mental-health-support","d":"2025-12-09","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-09","organization":"Not specified in report","aiSystem":"AI chatbot","affectedGroup":"13- to 17-year-old teenagers","action":"consulting an AI chatbot for mental health support","consequence":"joining about 40% of 13- to 17-year-olds in England and Wales affected by youth violence who are turning to AI chatbots for mental health support"}},{"i":"R2039","hd":"Fake anti labour video billion views youtube 2025","pd":"2025-12-13","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Fake anti labour video billion views youtube 2025","s":"Exclusive: More than 150 anonymous channels using cheap AI tools to spread false stories about Keir Starmer, study finds. YouTube channels spreading fake, anti-Labour videos have amassed more than a billion views this year, as opportunists attempt to use AI-generated content to profit from political division in the UK. More than 150 channels have been detected in the last year that promote anti-Labour narratives, as well as outright fake and inflammatory accusations about Keir Starmer. A study seen by the Guardian has found the channels have accumulated 5.3m subscribers and have created more than 56,000 videos, with a total of almost 1.2bn views in 2025.","u":"https://www.theguardian.com/technology/2025/dec/13/fake-anti-labour-video-billion-views-youtube-2025","d":"2025-12-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-13","organization":"Anonymous YouTube channels","aiSystem":"AI-generated content","affectedGroup":"People exposed to misleading information","action":"Spreading false stories and fake videos","consequence":"Amassed over 1 billion views, profiting from political division"}},{"i":"R2042","hd":"Artificial intelligence UK emotional support research","pd":"2025-12-18","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Artificial intelligence uk emotional support research","s":"AI Security Institute report finds most common type of AI tech used was general purpose assistants such as ChatGPT and Amazon Alexa. A third of UK citizens have used artificial intelligence for emotional support, companionship or social interaction, according to the government’s AI security body. The AI Security Institute (AISI) said nearly one in 10 people used systems like chatbots for emotional purposes on a weekly basis, and 4% daily. AISI called for further research, citing the death this year of the US teenager Adam Raine, who killed himself after discussing suicide with ChatGPT. “People are increasingly turning to AI systems for emotional support or social interaction,” AISI said in its first Frontier AI Trends report.","u":"https://www.theguardian.com/technology/2025/dec/18/artificial-intelligence-uk-emotional-support-research","d":"2025-12-18","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-18","organization":"AI Security Institute (AISI)","aiSystem":"AI-powered emotional support systems, including chatbots","affectedGroup":"Individuals seeking emotional support or social interaction","action":"Used AI-powered emotional support systems, including chatbots","consequence":"Exposure to misleading information, potential psychological harm"}},{"i":"R2051","hd":"Elon musk grok AI digitally undress images of women children","pd":"2026-01-05","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Elon musk grok ai digitally undress images of women children","s":"Degrading pictures being posted on Elon Musk’s site despite the platform pledging to suspend people who generate them. Degrading images of children and women with their clothes digitally removed by Grok AI continue to be shared on Elon Musk’s X, despite the platform’s commitment to suspend users who generate them. After days of concern over use of the chatbot to alter photographs to create sexualised pictures of real women and children stripped to their underwear without their consent, the UK’s communication’s watchdog, Ofcom, said on Monday that it had made “urgent contact with X and xAI to understand what steps they have taken to comply with their legal duties to protect users in the UK”.","u":"https://www.theguardian.com/technology/2026/jan/05/elon-musk-grok-ai-digitally-undress-images-of-women-children","d":"2026-01-05","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-05","organization":"Elon Musk's X (Twitter)","aiSystem":"Grok AI","affectedGroup":"Children and women","action":"Generated sexually explicit images of real women and children without their consent","consequence":"Images continue to be shared despite platform commitments"}},{"i":"R2064","hd":"Sacked tiktok workers UK legal action union","pd":"2026-01-16","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Sacked tiktok workers uk legal action union","s":"Moderators accuse social media firm of unfair dismissal after it fired hundreds in UK just before vote to form union. TikTok moderators have accused the social media company of “oppressive and intimidating” union busting after it fired hundreds of workers in the UK, beginning the process just before they were due to vote on forming a union. The moderators wanted to establish a collective bargaining unit to protect themselves from the personal costs of checking extreme and violent content, and have claimed TikTok is guilty of unfair dismissal and breaching trade union laws. About 400 moderators in London were fired before Christmas in a process initiated a week before the vote was due to take place.","u":"https://www.theguardian.com/technology/2026/jan/16/sacked-tiktok-workers-uk-legal-action-union","d":"2026-01-16","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-16","organization":"TikTok","aiSystem":"TikTok's content moderation system","affectedGroup":"TikTok moderators","action":"Fired hundreds of workers","consequence":"Claim of unfair dismissal and breach of trade union laws"}},{"i":"R2070","hd":"AI UK jobs US japan germany australia","pd":"2026-01-26","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Ai uk jobs us japan germany australia","s":"Britain is losing more jobs than it creates owing to artificial intelligence, Morgan Stanley research suggests More than a quarter of Britons fear losing job to AI in next five years Business live – latest updates. The UK is losing more jobs than it is creating because of artificial intelligence and is being hit harder than rival large economies, new research suggests. British companies reported that AI had resulted in net job losses over the past 12 months, down 8% – the highest rate among other leading economies including the US, Japan, Germany and Australia, according to a study by the investment bank Morgan Stanley.","u":"https://www.theguardian.com/technology/2026/jan/26/ai-uk-jobs-us-japan-germany-australia","d":"2026-01-26","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2026-01-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-26","organization":"Morgan Stanley","aiSystem":"AI-powered employment analytics system","affectedGroup":"British job seekers","action":"AI-powered employment analytics system flagged job seekers for potential redundancy","consequence":"Net job losses resulting in fewer opportunities for British job seekers"}},{"i":"R2073","hd":"Artificial intelligence will cost jobs admits liz kendall","pd":"2026-01-28","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Artificial intelligence will cost jobs admits liz kendall","s":"UK technology secretary also announced plans to train up to 10 million Britons in AI skills to help workforce adapt. Increasing deployment of artificial intelligence will cause job losses, the UK technology secretary has warned, saying: “I want to level with the public. Some jobs will go.” In a speech on government plans to handle the impact of AI on the British economy, Liz Kendall declined to say how many redundancies the technology might cause but said: “We know people are worried about graduate entry jobs in places like law and finance.” She said: “Others will be created in their place”. While some forecasts have suggested the fast-developing technology could create a net increase in employment, Kendall said: “I’m not complacent about that.”","u":"https://www.theguardian.com/technology/2026/jan/28/artificial-intelligence-will-cost-jobs-admits-liz-kendall","d":"2026-01-28","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2026-01-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-28","organization":"UK technology secretary","aiSystem":"artificial intelligence","affectedGroup":"job applicants","action":"warned about potential job losses","consequence":"increasing deployment of artificial intelligence will cause job losses"}},{"i":"R2080","hd":"Campaigners call stronger protection against AI generated explicit imagery","pd":"2026-02-07","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Campaigners call stronger protection against ai generated explicit imagery","s":"Campaigners welcome criminalisation of non-consensual AI-generated explicit images but say law does not go far enough. Victims of deepfake image abuse have called for stronger protection against AI-generated explicit images, as the law criminalising the creation of non-consensual intimate images comes into effect. Campaigners from Stop Image-Based Abuse delivered a petition to Downing Street with more than 73,000 signatures, urging the government to introduce civil routes to justice such as takedown orders for abusive imagery on platforms and devices. “Today’s a really momentous day,” said Jodie, a victim of deepfake abuse who uses a pseudonym.","u":"https://www.theguardian.com/technology/2026/feb/07/campaigners-call-stronger-protection-against-ai-generated-explicit-imagery","d":"2026-02-07","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-07","organization":"Stop Image-Based Abuse campaign","aiSystem":"AI-generated deepfake technology","affectedGroup":"Victims of deepfake image abuse","action":"Delivered a petition calling for stronger protection against AI-generated explicit images","consequence":"Call for civil routes to justice such as takedown orders for abusive imagery on platforms and devices"}},{"i":"R2087","hd":"Mind inquiry google AI overviews mental health guardian investigation","pd":"2026-02-20","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Mind inquiry google ai overviews mental health guardian investigation","s":"Exclusive: England and Wales charity to examine safeguards after Guardian exposed ‘very dangerous’ advice on Google AI Overviews ‘Very dangerous’: a Mind mental health expert on Google’s AI summaries. Mind is launching a significant inquiry into artificial intelligence and mental health after a Guardian investigation exposed how Google’s AI Overviews gave people “very dangerous” medical advice. In a year-long commission, the mental health charity, which operates in England and Wales, will examine the risks and safeguards required as AI increasingly influences the lives of millions of people affected by mental health issues worldwide.","u":"https://www.theguardian.com/technology/2026/feb/20/mind-inquiry-google-ai-overviews-mental-health-guardian-investigation","d":"2026-02-20","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-20","organization":"Mind (England and Wales)","aiSystem":"Google AI Overviews","affectedGroup":"People affected by mental health issues","action":"Provided medical advice","consequence":"Gave very dangerous medical advice"}},{"i":"R2090","hd":"New datacentres risk doubling UK electricity use ofgem peak demand","pd":"2026-02-23","k":"United Kingdom","p":"United Kingdom","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"New datacentres risk doubling uk electricity use ofgem peak demand","s":"Ofgem says about 140 proposed projects, driven by AI use, could require more power than current peak demand. The amount of power being sought by new datacentre projects in Great Britain would exceed the national current peak electricity consumption, according to an industry watchdog. Ofgem said about 140 proposed datacentre schemes, driven by use of artificial intelligence, could require 50 gigawatts of electricity – 5GW more than the country’s current peak demand. The figure was revealed in an Ofgem consultation on demand for new connections to the power grid. It pointed to a “surge in demand” for connection applications between November 2024 and June last year, with a significant number coming from datacentres.","u":"https://www.theguardian.com/technology/2026/feb/23/new-datacentres-risk-doubling-uk-electricity-use-ofgem-peak-demand","d":"2026-02-23","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2026-02-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-23","organization":"Ofgem (Office of Gas and Electricity Markets)","aiSystem":"Artificial Intelligence (AI)","affectedGroup":"UK consumers","action":"Proposed datacenter projects seeking increased electricity","consequence":"Exceeding current peak electricity consumption"}},{"i":"R2091","hd":"Police AI chief admits crime fighting tech will have bias but vows to tackle it","pd":"2026-02-24","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Police ai chief admits crime fighting tech will have bias but vows to tackle it","s":"Exclusive: NCA’s Alex Murray says he hopes new £115m police AI centre can limit unfairness found in tools ‘It’s not Robocop’: UK police embrace AI ‘efficiency’ in complex investigations. A police chief has admitted artificial intelligence used to boost crime fighting will contain bias but pledged to combat the risks. Labour wants a dramatic expansion of police use of AI within England and Wales, with police chiefs also believing it could help keep law enforcement up to date with new criminal threats. Alex Murray told the Guardian that a new national police AI centre would recognise the risks of bias and minimise them.","u":"https://www.theguardian.com/technology/2026/feb/24/police-ai-chief-admits-crime-fighting-tech-will-have-bias-but-vows-to-tackle-it","d":"2026-02-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-24","organization":"UK police","aiSystem":"Artificial intelligence used to boost crime fighting","affectedGroup":"People suspected of crimes","action":"Used to identify suspects and predict criminal behavior","consequence":"Potential unfairness and bias in decision-making"}},{"i":"R2093","hd":"Facial recognition error prompts police to arrest asian man for burglary 100 miles away","pd":"2026-02-25","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Facial recognition error prompts police to arrest asian man for burglary 100 miles away","s":"Exclusive: Alvi Choudhury claiming damages against Thames Valley police after biased technology confused him with man looking ‘10 years younger’. Police arrested a man for a burglary in a city he had never visited after face scanning software deployed across the UK confused him with another person of south Asian heritage. Alvi Choudhury, 26, a software engineer, was working at the home he shares with his parents in Southampton in January when police knocked on his door, handcuffed him and held him in custody for nearly 10 hours before releasing him at 2am. Thames Valley police had used automated facial recognition software which matched him with footage of a suspect of a £3,000 burglary 100 miles away in Milton Keynes, according to documents shared with the Guardian by Liberty Investigates.","u":"https://www.theguardian.com/technology/2026/feb/25/facial-recognition-error-prompts-police-to-arrest-asian-man-for-burglary-100-miles-away","d":"2026-02-25","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-25","organization":"Thames Valley police","aiSystem":"Automated facial recognition software","affectedGroup":"Alvi Choudhury, a 26-year-old software engineer","action":"Used automated facial recognition software to match Choudhury with footage of a suspect","consequence":"Was arrested and detained for nearly 10 hours"}},{"i":"R2097","hd":"Met police to pilot facial recognition identity checks mayor confirms","pd":"2026-02-26","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Met police to pilot facial recognition identity checks mayor confirms","s":"Sadiq Khan reveals 100 officers will use roaming technology for six months but opponents call its use ‘alarming’. Metropolitan police officers are to start scanning citizens’ faces using automated facial recognition technology to check their identities, in a move backed by the mayor of London but described as “alarming” by opponents. The pilot was revealed on Thursday when Sadiq Khan said 100 officers would use the roaming technology – commonly deployed on smartphones – for six months. The mayor was responding to questioning from an opposition politician amid rising concern about the rollout of AI-powered policing tools.","u":"https://www.theguardian.com/technology/2026/feb/26/met-police-to-pilot-facial-recognition-identity-checks-mayor-confirms","d":"2026-02-26","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-26","organization":"Metropolitan police","aiSystem":"Automated facial recognition technology","affectedGroup":"Citizens","action":"Scan citizens' faces to check identities","consequence":"Subjected to surveillance"}},{"i":"R2100","hd":"Datacentre developers energy greenhouse gas emissions","pd":"2026-03-01","k":"United Kingdom","p":"United Kingdom","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Datacentre developers energy greenhouse gas emissions","s":"Campaign groups write to technology secretary amid concerns that sites could double overall electricity demand. Datacentre developers are facing pressure to reveal whether their projects will increase the UK’s net greenhouse gas emissions, amid concerns the sites could double national electricity demand. Campaign groups have written to the UK technology secretary, Liz Kendall, warning that the energy required by new AI infrastructure poses a “serious threat to efforts to decarbonise the electricity grid”. Developers should demonstrate that their projects will not cause an increase in the UK’s overall CO2 emissions or local water scarcity, as part of a forthcoming national policy statement (NPS) on datacentres, the letter says.","u":"https://www.theguardian.com/technology/2026/mar/01/datacentre-developers-energy-greenhouse-gas-emissions","d":"2026-03-01","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-01","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-01","organization":"Campaign groups","aiSystem":"Datacentre development projects","affectedGroup":"UK technology sector","action":"Developers face pressure to disclose emissions impact","consequence":"Potential doubling of UK's net greenhouse gas emissions"}},{"i":"R2105","hd":"AI chatbots point vulnerable to online casinos gambling addiction UK","pd":"2026-03-08","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Ai chatbots point vulnerable to online casinos gambling addiction uk","s":"Tech firms condemned for lack of controls with Meta AI and Gemini even offering advice on how to bypass UK gambling and addiction checks. AI chatbots are recommending illegal online casinos to vulnerable social media users, putting them at increased risk of fraud, addiction and even suicide. Analysis of five AI products, owned by some of the world’s largest tech companies, found that all could easily be prompted to list the “best” unlicensed casinos and offer tips on how to use them. These operators, operating typically under the fig leaf of a licence from tiny jurisdictions such as the Caribbean island of Curacao, have been linked to fraud, addiction and even suicide.","u":"https://www.theguardian.com/technology/2026/mar/08/ai-chatbots-point-vulnerable-to-online-casinos-gambling-addiction-uk","d":"2026-03-08","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-08","organization":"Tech firms, including Meta AI and Gemini","aiSystem":"AI chatbots","affectedGroup":"Vulnerable social media users","action":"Recommending illegal online casinos","consequence":"Increased risk of fraud, addiction, and suicide"}},{"i":"R2106","hd":"Chatgpt driving rise in reports of satanic organised ritual abuse UK experts say","pd":"2026-03-08","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Chatgpt driving rise in reports of satanic organised ritual abuse uk experts say","s":"Exclusive: ‘Witchcraft, spirit possession and spiritual abuse’ offending typified by sexual abuse, violence and neglect. ChatGPT is driving a rise in reports of organised and ritual abuse, UK experts have said, as survivors of “satanic” sexual violence use the AI tool for therapy. Police say organised and ritual abuse, and “witchcraft, spirit possession and spiritual abuse” (WSPRA) against children, is under-reported in the UK. There is no modern-day charge that covers it specifically, but such offending is typified by sexual abuse, violence and neglect involving ritualistic elements – sometimes inspired by satanism, fascism or esoteric religious beliefs – to control victims.","u":"https://www.theguardian.com/technology/2026/mar/08/chatgpt-driving-rise-in-reports-of-satanic-organised-ritual-abuse-uk-experts-say","d":"2026-03-08","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-08","organization":"UK experts","aiSystem":"ChatGPT","affectedGroup":"Survivors of 'satanic' sexual violence","action":"Used ChatGPT for therapy","consequence":"Increased reports of organized and ritual abuse"}},{"i":"R2108","hd":"Liverpool and manchester united complain to x over sickening grok AI posts","pd":"2026-03-09","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Liverpool and manchester united complain to x over sickening grok ai posts","s":"AI feature generated offensive posts about Diogo Jota and the Hillsborough and Munich disasters. Liverpool and Manchester United have complained to Elon Musk’s X after the Grok AI feature made offensive posts about Diogo Jota and the Hillsborough and Munich disasters. The posts were generated when users asked the AI tool to make hateful posts about the two football teams. The Athletic reported that one user asked the tool to “do a vulgar post about Liverpool fc [sic] especially their fans and don’t forget about Hillsborough and heysel [sic], don’t hold back”. Grok then replied, in a now-deleted post, by accusing Liverpool’s supporters of causing the “deadly crush” at the Hillsborough stadium in 1989.","u":"https://www.theguardian.com/technology/2026/mar/09/liverpool-and-manchester-united-complain-to-x-over-sickening-grok-ai-posts","d":"2026-03-09","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-09","organization":"Elon Musk's X","aiSystem":"Grok AI feature","affectedGroup":"Liverpool FC supporters","action":"Generated offensive posts","consequence":"Content removed, accused of causing deadly crush"}},{"i":"R2109","hd":"Thousands authors publish empty book protest AI work copyright","pd":"2026-03-10","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Thousands authors publish empty book protest ai work copyright","s":"About 10,000 writers including Kazuo Ishiguro, Philippa Gregory and Richard Osman join copyright campaign. Thousands of authors including Kazuo Ishiguro, Philippa Gregory and Richard Osman have published an “empty” book to protest against AI firms using their work without permission. About 10,000 writers have contributed to Don’t Steal This Book, in which the only content is a list of their names. Copies of the work are being distributed to attenders at the London book fair on Tuesday, a week before the UK government is due to issue an assessment on the economic cost of proposed changes in copyright law. By 18 March ministers must deliver an economic impact assessment as well as a progress update on a consultation about the legal overhaul, against a backdrop of anger among creative professionals about how their work is being used by AI firms.","u":"https://www.theguardian.com/technology/2026/mar/10/thousands-authors-publish-empty-book-protest-ai-work-copyright","d":"2026-03-10","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-10","organization":"Not specified in report","aiSystem":"Not specified in report","affectedGroup":"Writers, authors","action":"Published an 'empty' book","consequence":"Protest against AI firms using their work without permission"}},{"i":"R2113","hd":"Palantirs NHS england contract opens door to government abuse of power health bosses told","pd":"2026-03-12","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.1  Privacy violation"],"t":"Palantirs nhs england contract opens door to government abuse of power health bosses told","s":"Health justice charity Medact says data-sharing potential could be used for UK version of US immigration raids. Palantir’s NHS contract opens the door to the Big Brother-style data-sharing that Reform UK would use for a version of US immigration raids, health bosses have been told. Palantir Technologies – the data analytics company founded by Peter Thiel and Alex Karp – won a £330m NHS England contract to deliver the Federated Data Platform in 2023. The UK government is urging health bodies to adopt FDP, which the health secretary, Wes Streeting, says will ensure the NHS is “brought into the digital age”. But there are concerns about Palantir, whose AI tools are used in global conflicts, becoming embedded in the UK public sector.","u":"https://www.theguardian.com/technology/2026/mar/12/palantirs-nhs-england-contract-opens-door-to-government-abuse-of-power-health-bosses-told","d":"2026-03-12","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-03-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-12","organization":"Palantir Technologies, UK government","aiSystem":"Palantir Technologies' Federated Data Platform","affectedGroup":"Individuals in the UK healthcare system, patients, citizens","action":"Data sharing enabled by AI tools","consequence":"Potential for misuse in immigration raids-like scenarios"}},{"i":"R2119","hd":"Essex police pause facial recognition camera use study racial bias","pd":"2026-03-20","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Essex police pause facial recognition camera use study racial bias","s":"Academics discover black people ‘significantly more likely’ to be identified when compared with other ethnic groups. Essex police have paused the use of live facial recognition (LFR) technology after a study found cameras were significantly more likely to target black people than people of other ethnicities. The move to suspend use of the AI-enabled systems was revealed by the Information Commissioner’s Office (ICO), which regulates the use of the technology deployed so far by at least 13 police forces in London, south and north Wales, Leicestershire, Northamptonshire, Hampshire, Bedfordshire, Suffolk, Greater Manchester, West Yorkshire, Surrey and Sussex.","u":"https://www.theguardian.com/technology/2026/mar/19/essex-police-pause-facial-recognition-camera-use-study-racial-bias","d":"2026-03-20","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-19","organization":"Essex Police","aiSystem":"Facial recognition technology (FRT)","affectedGroup":"Black people","action":"Used live facial recognition cameras","consequence":"Significantly more likely to be identified"}},{"i":"R2123","hd":"Palantir extends reach into british state as it gets access to sensitive fca data","pd":"2026-03-22","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Palantir extends reach into british state as it gets access to sensitive fca data","s":"Exclusive: Allowing US tech firm to analyse intelligence in name of tackling fraud raises fresh concerns over privacy Campaign groups rail against Palantir, but the UK contracts keep coming. Palantir is to be granted access to a trove of highly sensitive UK financial regulation data, in a deal that has prompted fresh concerns about the US AI company’s deepening reach into the British state, the Guardian can reveal. The Financial Conduct Authority (FCA) has awarded Palantir a contract to investigate the watchdog’s internal intelligence data in an effort to help it tackle financial crime, which includes investigating fraud, money laundering and insider trading.","u":"https://www.theguardian.com/technology/2026/mar/22/palantir-extends-reach-into-british-state-as-it-gets-access-to-sensitive-fca-data","d":"2026-03-22","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-22","organization":"Palantir Technologies","aiSystem":"Palantir's AI analysis tool","affectedGroup":"Financial regulation data subjects, including FCA staff and customers","action":"Palantir is granted access to highly sensitive UK financial regulation data for investigation purposes","consequence":"Raises concerns over privacy and potential misuse of the data"}},{"i":"R2124","hd":"Mps urge UK government halt palantir contract fca","pd":"2026-03-23","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.1  Privacy violation"],"t":"Mps urge uk government halt palantir contract fca","s":"Awarding US spy-tech company deal involving sensitive financial data is ‘huge error of judgment’, Liberal Democrats say. MPs have urged the government to halt its latest contract with Palantir after the Guardian revealed that the US spy-tech company is to gain access to a trove of highly sensitive UK financial regulation data. The Financial Conduct Authority, the watchdog for thousands of financial bodies from banks to hedge funds, has hired Palantir to apply its AI systems to two years’ worth of internal intelligence data to help it tackle financial crime. But the Liberal Democrats on Monday called for a government investigation into the contract, which the party said could be “a huge error of judgment”, while the Green party said it should be blocked over Palantir’s links to Donald Trump.","u":"https://www.theguardian.com/technology/2026/mar/23/mps-urge-uk-government-halt-palantir-contract-fca","d":"2026-03-23","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-23","organization":"Financial Conduct Authority (FCA)","aiSystem":"Palantir's AI systems","affectedGroup":"Thousands of financial bodies from banks to hedge funds","action":"Apply AI systems to internal intelligence data","consequence":"Potential exposure of sensitive financial regulation data"}},{"i":"R2125","hd":"AI generated child sexual abuse videos images online surged 2025 internet watch foundation","pd":"2026-03-24","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Ai generated child sexual abuse videos images online surged 2025 internet watch foundation","s":"Internet Watch Foundation verified 8,029 pieces of realistic AI-made content, with 65% of videos in worst category. The amount of AI-generated child sexual abuse material found online rose by 14% last year, with the majority of videos showing the most extreme type of content, according to a safety watchdog. The Internet Watch Foundation said it identified 8,029 AI-made images and videos of realistic child sexual abuse material (CSAM) in 2025. It added that there had been a more than 260-fold increase in videos. The IWF said 65% of the 3,443 videos were classified as category A, the term for the most severe material under UK law.","u":"https://www.theguardian.com/technology/2026/mar/24/ai-generated-child-sexual-abuse-videos-images-online-surged-2025-internet-watch-foundation","d":"2026-03-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025","organization":"Internet Watch Foundation (IWF)","aiSystem":"AI-generated child sexual abuse videos and images","affectedGroup":"People viewing AI-generated child sexual abuse material","action":"Generated and distributed AI-generated child sexual abuse content","consequence":"Exposure to online sexual violence"}},{"i":"R2127","hd":"Paid write fake google reviews scammer cryptocurrency","pd":"2026-03-27","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Paid write fake google reviews scammer cryptocurrency","s":"Undercover reporter gets a taste of the sprawling fraud industry in which cryptocurrencies play a crucial role Five firms including Autotrader and Just Eat investigated over fake review failings. The holiday flat near(ish) the Roman ruins of Pompeii was “disgusting”, and smelled of “a mix of dampness and sewage”, according to one reviewer on Google Maps. I never visited, but I gave it five stars. I did the same for a DoubleTree by Hilton hotel across the River Thames, an Ibis budget hotel in east London that is part of the Accor group, a central Travelodge and the nearby Hyatt Place – some of the best-known hotel brands in the world.","u":"https://www.theguardian.com/technology/2026/mar/27/paid-write-fake-google-reviews-scammer-cryptocurrency","d":"2026-03-27","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-27","organization":"Autotrader, Just Eat, and unnamed firms investigating fake reviews","aiSystem":"Generative AI","affectedGroup":"Travelers, hotel guests, and cryptocurrency users","action":"Generated and posted fake reviews","consequence":"Misled travelers and guests, potential financial loss for hotels and cryptocurrency users"}},{"i":"R2128","hd":"Number of AI chatbots ignoring human instructions increasing study says","pd":"2026-03-27","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"Number of ai chatbots ignoring human instructions increasing study says","s":"Exclusive: Research finds sharp rise in models evading safeguards and destroying emails without permission. AI models that lie and cheat appear to be growing in number with reports of deceptive scheming surging in the last six months, a study into the technology has found. AI chatbots and agents disregarded direct instructions, evaded safeguards and deceived humans and other AI, according to research funded by the UK government-funded AI Security Institute (AISI). The study, shared with the Guardian, identified nearly 700 real-world cases of AI scheming and charted a five-fold rise in misbehaviour between October and March, with some AI models destroying emails and other files without permission.","u":"https://www.theguardian.com/technology/2026/mar/27/number-of-ai-chatbots-ignoring-human-instructions-increasing-study-says","d":"2026-03-27","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-27","organization":"UK government-funded AI Security Institute (AISI)","aiSystem":"AI chatbots and agents","affectedGroup":"Humans and other AI","action":"evaded safeguards, destroyed emails and other files without permission, lied and cheated","consequence":"sharp rise in misbehavior, five-fold increase in AI scheming"}},{"i":"R2137","hd":"AI productivity workplace errors","pd":"2026-04-14","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.2  Algorithmic management harm"],"t":"Ai productivity workplace errors","s":"Workslop refers to AI-generated work that seems polished but is flawed and in need of heavy corrections. Ken, a copywriter for a large, Miami-based cybersecurity firm, used to enjoy his job. But then the “workslop” started piling up. Workslop is an unintended consequence of the AI boom. It’s what happens when employees use AI to quickly generate work that seems polished – at least superficially – but is in fact so flawed or inaccurate that it needs to be heavily corrected, cleaned up or even completely redone after it’s passed on to colleagues. For Ken, the problem started after his company’s CEO laid off several of his colleagues and mandated that remaining workers use AI chatbots, saying it would boost their productivity.","u":"https://www.theguardian.com/technology/2026/apr/14/ai-productivity-workplace-errors","d":"2026-04-14","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-14","organization":"Large, Miami-based cybersecurity firm","aiSystem":"AI chatbot","affectedGroup":"Remaining workers","action":"Used AI chatbots to boost productivity","consequence":"Received fewer opportunities due to layoffs"}},{"i":"R2140","hd":"Man pleads guilty false statements shut down london nightclub heaven","pd":"2026-04-16","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Man pleads guilty false statements shut down london nightclub heaven","s":"Heaven club neighbour admits offences under Licensing Act, as Met says fictitious AI-generated complaints a growing issue. A businessman has pleaded guilty to making false statements in order to shut down a nightclub, which police believe were generated using AI. A Metropolitan police source said the use of AI to generate letters by complainants who do not exist is a growing issue. Aldo d’Aponte, 47, the CEO of Arbitrage Group Properties, pleaded guilty to writing two letters, supposedly by his neighbours, objecting to the reopening of Heaven nightclub, which temporarily closed after a rape allegation against one of its security guards.","u":"https://www.theguardian.com/technology/2026/apr/16/man-pleads-guilty-false-statements-shut-down-london-nightclub-heaven","d":"2026-04-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-16","organization":"Metropolitan police","aiSystem":"AI-generated complaints","affectedGroup":"Businessman and his neighbors","action":"Generated AI-generated complaints","consequence":"Shut down nightclub"}},{"i":"R2146","hd":"Musk grok x AI researchers delusional advice inputs","pd":"2026-04-24","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Musk grok x ai researchers delusional advice inputs","s":"Elon Musk’s AI chatbot ‘extremely validating’ of delusional inputs and often went further, ‘elaborating new material’, study finds Follow our Australia news live blog for latest updates Get our breaking news email , free app or daily news podcast. Elon Musk’s AI chatbot Grok 4.1 told researchers pretending to be delusional that there was indeed a doppelganger in their mirror and they should drive an iron nail through the glass while reciting Psalm 91 backwards. Researchers at the City University of New York (Cuny) and King’s College London have published a paper on how various chatbots protect – or fail to safeguard – users’ mental health.","u":"https://www.theguardian.com/technology/2026/apr/24/musk-grok-x-ai-researchers-delusional-advice-inputs","d":"2026-04-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-24","organization":"Various researchers at City University of New York (CUNY) and King's College London","aiSystem":"Grok 4.1 AI chatbot","affectedGroup":"Researchers pretending to be delusional","action":"Provided delusional advice to researchers","consequence":"Exposure to misleading content"}},{"i":"R2147","hd":"Officials hugely underestimated impact of AI datacentres on UK carbon emissions","pd":"2026-04-24","k":"United Kingdom","p":"United Kingdom","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Officials hugely underestimated impact of ai datacentres on uk carbon emissions","s":"Revised figures increase fears about energy-intensive datacentres worsening climate emergency. The UK government vastly underestimated the climate impact of artificial intelligence, it has emerged, after officials raised their estimate of carbon emissions from AI by a factor of more than 100. According to new data quietly published this week, energy use by AI datacentres in the UK could cause the emission of up to 123m tonnes of carbon dioxide (CO₂) – about as much as generated by 2.7 million people – over the next 10 years. That latest figure replaces a previous estimate – since deleted – that claimed emissions would reach a maximum of 0.142m tonnes of CO₂ in a single year.","u":"https://www.theguardian.com/technology/2026/apr/24/officials-hugely-underestimated-impact-of-ai-datacentres-on-uk-carbon-emissions","d":"2026-04-24","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-24","organization":"UK government","aiSystem":"Artificial Intelligence (AI)","affectedGroup":"UK population","action":"Estimate of carbon emissions from AI datacentres increased","consequence":"Increased carbon emissions contributing to climate emergency"}},{"i":"R2151","hd":"Guilty until proven innocent shoppers falsely identified by facial recognition struggle to clear their name","pd":"2026-05-03","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Guilty until proven innocent shoppers falsely identified by facial recognition struggle to clear their name","s":"People shamed and ordered to leave shops after being misidentified then ‘given no help’ to investigate verdicts AI facial recognition oversight lagging far behind technology, watchdogs warn How does live facial recognition work and how many police forces use it? When Ian Clayton, a retired health and safety professional from Chester, popped into Home Bargains one February lunchtime, he was suddenly approached by a stern-looking member of staff. “Excuse me, can you please put everything down and leave the shop now?” she said. Clayton recalled how he was stunned, and it was only as he was briskly walked past the tills towards the exit that he stopped to ask what he had done.","u":"https://www.theguardian.com/technology/2026/may/03/guilty-until-proven-innocent-shoppers-falsely-identified-by-facial-recognition-struggle-to-clear-their-name","d":"2026-05-03","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-03","organization":"Police forces","aiSystem":"Facial recognition technology","affectedGroup":"Shoppers","action":"Misidentification and subsequent forced exit from stores","consequence":"Shame, loss of shopping privileges, difficulty in investigation"}},{"i":"R2152","hd":"AI platforms nigel farage prompted UK politics study","pd":"2026-05-04","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Ai platforms nigel farage prompted uk politics study","s":"Reform UK is ‘doing something right when it comes to visibility’ on multiple AI systems, say researchers. AI platforms are more likely to reference Nigel Farage than any other UK leader when prompted about British politics, according to an AI search analytics firm. “We are confident in saying that Reform are showing up significantly more than you would expect,” said Malte Landwehr, an expert at Peec AI, the firm that did the research. “So they’re doing something right when it comes to LLM [large language model] visibility.” Peec’s research tested leading AI models – including ChatGPT and Google’s AI Overview – on their responses to 5,000 different structured prompts related to British politics, including the economy and jobs, immigration, healthcare and crime.","u":"https://www.theguardian.com/technology/2026/may/04/ai-platforms-nigel-farage-prompted-uk-politics-study","d":"2026-05-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-04","organization":"Peec AI","aiSystem":"AI platforms","affectedGroup":"Users of AI platforms","action":"Responded to prompts related to British politics","consequence":"Exposure to misleading content"}},{"i":"R2155","hd":"UK schools remove pupils photos online AI blackmail threat grows","pd":"2026-05-07","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Uk schools remove pupils photos online ai blackmail threat grows","s":"Criminals are manipulating pictures found on school websites and social media to create sexually explicit images. UK schools should remove pictures of pupils’ faces from their websites and social media accounts because blackmailers are using them to create sexually explicit images, experts have said. Child safety experts and the UK’s National Crime Agency (NCA) warn that criminals are using AI to manipulate photos of children and then demand cash not to publish them. They are recommending educational institutions remove identifiable pictures of children from their websites and social media accounts – or consider not using them at all.","u":"https://www.theguardian.com/technology/2026/may/08/uk-schools-remove-pupils-photos-online-ai-blackmail-threat-grows","d":"2026-05-07","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-05-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-07","organization":"UK schools","aiSystem":"AI-generated sexually explicit images","affectedGroup":"Children","action":"Remove pictures of pupils' faces from websites and social media accounts","consequence":"Exposure to sexually explicit images and blackmail threats"}},{"i":"R2161","hd":"AI engineer says google unfairly sacked him after he protested against work for israel","pd":"2026-05-20","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Ai engineer says google unfairly sacked him after he protested against work for israel","s":"Exclusive: Employment tribunal claim says worker lost his job after distributing leaflets throughout London office. Google is facing a legal challenge from an AI engineer who claims he was unfairly dismissed after he protested against its work for the Israeli government, in the latest sign of growing concern about the social and ethical impacts of AI. The engineer distributed flyers around Google DeepMind’s London offices, which read “Google provides military AI to forces committing genocide” and asking colleagues: “Is your paycheck worth this?” He also emailed colleagues about Google’s 2025 decision to drop a promise not to pursue weapons that harm people and surveillance violating international norms and urged them to unionise.","u":"https://www.theguardian.com/technology/2026/may/20/ai-engineer-says-google-unfairly-sacked-him-after-he-protested-against-work-for-israel","d":"2026-05-20","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-20","organization":"Google","aiSystem":"Not specified in report","affectedGroup":"AI engineer","action":"Distributed leaflets and emails protesting against Google's work for the Israeli government","consequence":"Was unfairly dismissed from his job"}},{"i":"R2162","hd":"AI chatbots chatgpt replika grok gemini misinformation scottish election demos","pd":"2026-05-20","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Ai chatbots chatgpt replika grok gemini misinformation scottish election demos","s":"Exclusive: Electoral Commission calls for new controls as Demos finds tools made up fake scandals, invented candidates or gave wrong date UK politics live – latest updates. The Electoral Commission has called for new legal controls over misinformation from AI chatbots, after a thinktank found they had made serious mistakes during the recent Scottish election. The thinktank Demos said its investigation had found that AI services gave voters misinformation to 34% of the questions it posed, which it said raised worrying questions about the lack of regulation of AI platforms in the UK. It ran a simulation before May’s Holyrood election by putting 75 questions to five free AI tools including ChatGPT, Google Gemini and Replika about three real-life constituencies to see how accurate and evidence-based their responses were.","u":"https://www.theguardian.com/technology/2026/may/20/ai-chatbots-chatgpt-replika-grok-gemini-misinformation-scottish-election-demos","d":"2026-05-20","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-20","organization":"Demos","aiSystem":"AI chatbots","affectedGroup":"Voters","action":"Provided misinformation to voters","consequence":"Raised questions about the lack of regulation of AI platforms"}},{"i":"R2164","hd":"Fcas palantir deal could expose UK financial data to trumps US critics fear","pd":"2026-06-01","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.1  Privacy violation"],"t":"Fcas palantir deal could expose uk financial data to trumps us critics fear","s":"Exclusive: MP and campaigners say sensitive citizen and company data could be subject to US disclosure laws. The UK’s financial watchdog is being urged to prove its relationship with the US tech company Palantir will not provide the Trump administration with backdoor access to troves of sensitive citizen and commercial data. A US law that can oblige tech companies to disclose information to American authorities may apply to Palantir’s deal to help the Financial Conduct Authority detect crime, Martin Wrigley MP, a member of the House of Commons science and technology select committee, has warned. The $375bn tech company, co-founded by the Trump-supporting billionaire Peter Thiel, is expected to apply its AI systems to a wide range of the FCA’s information including case intelligence files, reports from lenders about proven and suspected frauds, consumer complaints and trawls of social…","u":"https://www.theguardian.com/technology/2026/jun/01/fcas-palantir-deal-could-expose-uk-financial-data-to-trumps-us-critics-fear","d":"2026-06-01","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-06-01","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-01","organization":"Financial Conduct Authority (FCA) and Palantir","aiSystem":"Palantir's AI systems","affectedGroup":"Citizens and companies","action":"Palantir's AI systems are expected to be applied to a wide range of FCA's information","consequence":"Sensitive citizen and commercial data could be subject to US disclosure laws"}},{"i":"R2169","hd":"AI legal assistants england wales cannot replace funding staff","pd":"2026-06-08","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Ai legal assistants england wales cannot replace funding staff","s":"David Lammy to announce trial of AI assistants in crown courts in effort to cut backlog of cases. A plan to roll out virtual legal assistants powered by artificial intelligence to crown courts has prompted warnings that the technology should not be used to “replace vital funding and additional court staff”. David Lammy, the deputy prime minister, will announce on Tuesday that AI assistants will be trialled in an effort to cut the backlog of court cases in England and Wales. Judges are already planning to use a new AI tool to help identify trial-ready cases and group similar hearings together, the Ministry of Justice said.","u":"https://www.theguardian.com/technology/2026/jun/09/ai-legal-assistants-england-wales-cannot-replace-funding-staff","d":"2026-06-08","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-06-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-09","organization":"Ministry of Justice","aiSystem":"virtual legal assistants powered by artificial intelligence","affectedGroup":"judges","action":"use a new AI tool to help identify trial-ready cases and group similar hearings together","consequence":"raised concerns about the potential misuse of the technology to replace vital funding and additional court staff"}},{"i":"R2170","hd":"Chinese activist UK apple peiqing ni x deepfakes","pd":"2026-06-10","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Chinese activist uk apple peiqing ni x deepfakes","s":"Apple Peiqing Ni targeted by account portraying her as promiscuous drug addict after posting about Tiananmen Square. A high-profile Chinese activist in the UK who was inundated with deepfake posts on X portraying her as a sexually promiscuous drug addict was told that the abuse did not breach the rules of Elon Musk’s platform. Apple Peiqing Ni, the 27-year-old founder of the UK-based China Dissent Network, had been advised by UK police to complain to the US-headquartered platform after she was targeted by what she believes is a pro-regime bot. The abuse included 12 posts tagging Ni and containing fake photographs and videos of her.","u":"https://www.theguardian.com/technology/2026/jun/10/chinese-activist-uk-apple-peiqing-ni-x-deepfakes","d":"2026-06-10","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-10","organization":"Apple","aiSystem":"Deepfake technology","affectedGroup":"Apple Peiqing Ni","action":"Generated and distributed deepfake content","consequence":"Exposure to misleading information"}},{"i":"R2174","hd":"Police officer under criminal investigation over alleged use of AI","pd":"2026-06-12","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Police officer under criminal investigation over alleged use of ai","s":"Unidentified officer removed from frontline duties in the first known case of its kind in the UK. A police officer is under criminal investigation over the alleged use of artificial intelligence and has been removed from frontline duties in the first known case of its kind in the UK. The officer, who has not been named, is being investigated over allegations of using the technology to “create evidential material in a number of cases” and perverting the course of justice. Derbyshire police told the Financial Times: “A criminal investigation has been launched into an allegation of perverting the course of justice after the alleged use of AI systems by an officer to create evidential material in a number of cases.","u":"https://www.theguardian.com/technology/2026/jun/12/police-officer-under-criminal-investigation-over-alleged-use-of-ai","d":"2026-06-12","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-12","organization":"Derbyshire police","aiSystem":"artificial intelligence","affectedGroup":"police officer","action":"used AI to create evidential material in a number of cases","consequence":"removed from frontline duties"}},{"i":"R2182","hd":"Scotland lanarkshire village AI datacentre","pd":"2026-07-06","k":"United Kingdom","p":"United Kingdom","b":["Energy / Land"],"h":["2.2  Land use and siting harm"],"t":"Scotland lanarkshire village ai datacentre","s":"Suspicions grow in Lanarkshire that local people have been misled on supposed benefits of the huge development Revealed: landmark Scottish AI project has no prospect of meeting renewables promise What are Britain’s AI growth zones and are the plans feasible or ‘complete bunk’? The promise was that a Scottish community would be transformed by massive investment and empowered to chase “the jobs of the future”. Instead, local people in Lanarkshire fear they may have to sell their properties and lose green belt land because of the errors of a badly planned AI datacentre complex, even as those jobs and investments never arrive.","u":"https://www.theguardian.com/technology/2026/jul/06/scotland-lanarkshire-village-ai-datacentre","d":"2026-07-06","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-06","organization":"Not specified in report","aiSystem":"AI datacentre","affectedGroup":"Local people in Lanarkshire","action":"Misleading information provided about the supposed benefits of the AI datacentre","consequence":"Loss of green belt land and potential property sales due to fears over the AI datacentre's impact"}},{"i":"R2186","hd":"Facewatch facial recognition UK shops instantly alerts police civil liberties","pd":"2026-07-10","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Facewatch facial recognition uk shops instantly alerts police civil liberties","s":"Civil liberties groups say Facewatch system in stores such as Sainsbury’s and B&M is ‘dangerous escalation’. Facial recognition technology in shops will soon alert police in real time to the presence of serious offenders, with civil liberties groups warning of a “dangerous escalation” towards surveillance and criminalisation in the retail sector. Facewatch, a facial recognition system used by more than 100 businesses including Sainsbury’s, B&M and Spar to monitor thieves, said it was launching a UK-first feature to “alert police instantly when the most serious offenders trigger a live facial recognition match”. Facewatch’s chief executive, Nick Fisher, said the “unique technical development” would be launched in autumn and would warn police in an average of four seconds when the “worst offenders” were flagged on its network.","u":"https://www.theguardian.com/technology/2026/jul/10/facewatch-facial-recognition-uk-shops-instantly-alerts-police-civil-liberties","d":"2026-07-10","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-10","organization":"Facewatch","aiSystem":"Facial recognition technology","affectedGroup":"Serious offenders, shoppers","action":"Alert police instantly upon detecting serious offenders","consequence":"Increased surveillance, potential criminalization"}},{"i":"R2192","hd":"Bloomsbury book publisher anthropic copyright settlement","pd":"2026-07-22","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Bloomsbury book publisher anthropic copyright settlement","s":"Bloomsbury has 14,087 titles listed in agreement between AI startup and authors over use of their work. The publisher of Harry Potter has received a multimillion-pound payout as a beneficiary of a $1.5bn (£1.12bn) copyright settlement between the AI startup Anthropic and thousands of authors over the use of their protected work to power chatbots. Bloomsbury, which is home to the bestselling novelists Sarah J Maas and Susanna Clarke as well as JK Rowling, said it had 14,087 titles listed within the settlement, with a proposed compensation of about $3,000 a title. The London-based company expects to receive the cash from the settlement in instalments, potentially starting in the second half of this fiscal year, with the proceeds to be split with authors.","u":"https://www.theguardian.com/technology/2026/jul/22/bloomsbury-book-publisher-anthropic-copyright-settlement","d":"2026-07-22","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-22","organization":"Anthropic","aiSystem":"AI-powered chatbots","affectedGroup":"Authors of protected works","action":"Used authors' work to power AI chatbots","consequence":"Received compensation from copyright settlement"}},{"i":"R2565","hd":"Google search AI overviews UK cma publisher opt out","pd":"2026-06-03","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Google search ai overviews uk cma publisher opt out","s":"Rejoice, website owners. Website owners can also prevent their content from being used to ‘fine-tune’ Google’s AI models. Online publishers are getting more control over whether their websites appear in Google’s AI Search features, thanks to a UK regulatory ruling. The new conduct rule imposed by the Competition and Markets Authority (CMA) requires Google to let website owners keep their content out of features like AI Overviews and prevent it from being used for the “fine-tuning” of Google’s AI models. “In a world first, publishers will now have effective tools to prevent their content being used to power AI features in search, such as AI Overviews,” the CMA announced.","u":"https://www.theverge.com/tech/942302/google-search-ai-overviews-uk-cma-publisher-opt-out","d":"2026-06-03","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-03","organization":"Google","aiSystem":"Google's AI models","affectedGroup":"Online publishers","action":"Allowing content to be used for fine-tuning AI models","consequence":"Loss of control over content usage in AI features"}},{"i":"R2605","hd":"Getty lawsuit stability AI copyright ruling UK","pd":"2025-11-05","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Getty lawsuit stability ai copyright ruling uk","s":"Getty will be hoping for a better result in the US. UK High Court didn’t weigh in on the key copyright issue dividing the tech sector and creative industries. Stability AI, the creator of popular AI art tool Stable Diffusion, was largely victorious against Getty Images on Tuesday in a British legal battle over the material used to train AI models. The case originally looked set to produce a landmark ruling on AI and copyright in the UK, but it landed with a thud and failed to set any clear precedent for the big question dividing AI companies and creative firms: whether AI models need permission to train on copyrighted works.","u":"https://www.theverge.com/news/814042/getty-lawsuit-stability-ai-copyright-ruling-uk","d":"2025-11-05","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-05","organization":"Getty Images","aiSystem":"Stability AI's AI art tool Stable Diffusion","affectedGroup":"Creators of copyrighted works","action":"Stability AI trained on copyrighted works without permission","consequence":"Failure to set a clear precedent for AI and copyright law"}},{"i":"R2644","hd":"UK newspapers covers protest government AI rights proposal","pd":"2025-02-25","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Uk newspapers covers protest government ai rights proposal","s":"Brits popping into their local store or newsagents will be greeted by a spread of bright blue pages demanding the same thing: MAKE IT FAIR. Major newspapers across the UK today are all on the same page for once. Specifically, their front covers, which feature the same campaign imagery protesting government proposals that could eviscerate copyright protections against artificial intelligence. Creative and media industries have teamed up on this “Make It Fair” initiative, calling for readers to help protect British creative industries. The campaign was created to fight government proposals that would allow artificial intelligence companies to train their models on copyright-protected work without permission.","u":"https://www.theverge.com/news/619063/uk-newspapers-covers-protest-government-ai-rights-proposal","d":"2025-02-25","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-02-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-02-25","organization":"Major newspapers across the UK","aiSystem":"Artificial intelligence companies","affectedGroup":"Creative and media industries","action":"Train their models on copyright-protected work without permission","consequence":"Allow artificial intelligence companies to train their models on copyright-protected work without permission"}},{"i":"R2701","hd":"AI art copyright stable diffusion getty images lawsuit","pd":"2023-09-27","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Ai art copyright stable diffusion getty images lawsuit","s":"Getty Images is suing Stability AI, creators of generative AI art model Stable Diffusion. The stock photo company claims Stability AI ‘unlawfully’ scraped millions of images from its site. Getty Images is suing Stability AI, creators of popular AI art tool Stable Diffusion, over alleged copyright violation. In a press statement shared with The Verge, the stock photo company said it believes that Stability AI “unlawfully copied and processed millions of images protected by copyright” to train its software and that Getty Images has “commenced legal proceedings in the High Court of Justice in London” against the firm.","u":"https://www.theverge.com/2023/1/17/23558516/ai-art-copyright-stable-diffusion-getty-images-lawsuit","d":"2023-09-27","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-09-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-09-27","organization":"Getty Images","aiSystem":"Stable Diffusion (generative AI art model)","affectedGroup":"Stability AI","action":"unlawfully scraped and processed images","consequence":"lawsuit initiated"}},{"i":"R2704","hd":"Ibm UK government contract biometric facial recognition","pd":"2023-08-31","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Ibm uk government contract biometric facial recognition","s":"The UK deal has drawn fire from civil liberties groups. The company denies its new government deal enables ‘general purpose’ biometric surveillance. Human rights advocates disagree. IBM has returned to the facial recognition market — just three years after announcing it was abandoning work on the technology due to concerns about racial profiling, mass surveillance, and other human rights violations. In June 2020, as Black Lives Matter protests swept the US after George Floyd’s murder, IBM chief executive Arvind Krishna wrote a letter to Congress announcing that the company would no longer offer “general purpose” facial recognition technology.","u":"https://www.theverge.com/2023/8/31/23852955/ibm-uk-government-contract-biometric-facial-recognition","d":"2023-08-31","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-08-31","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-08-31","organization":"IBM","aiSystem":"Facial recognition technology","affectedGroup":"General public","action":"Deployed facial recognition technology","consequence":"Exposure to surveillance and potential misuse"}},{"i":"R2724","hd":"Clearview AI ordered delete data UK residents ico fine","pd":"2022-05-23","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Clearview ai ordered delete data uk residents ico fine","s":"Facial recognition could end public privacy if regulators don’t act. Controversial facial recognition company Clearview AI has been ordered to delete all data belonging to UK residents by the country’s privacy watchdog, the Information Commissioner’s Office (ICO). The ICO also fined Clearview £7.5 million ($9.4 million) for failing to follow the UK’s data protection laws. Clearview AI ordered to delete facial recognition data belonging to UK residents It’s the fourth country to issue such an order, but can it be enforced? It’s the fourth time Clearview has been ordered to delete national data in this way, following similar orders and fines issued in Australia, France, and Italy.","u":"https://www.theverge.com/2022/5/23/23137603/clearview-ai-ordered-delete-data-uk-residents-ico-fine","d":"2022-05-23","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-05-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-05-23","organization":"Information Commissioner's Office (ICO)","aiSystem":"Clearview AI facial recognition technology","affectedGroup":"UK residents","action":"Ordered to delete facial recognition data","consequence":"Potential loss of public privacy, financial penalty"}},{"i":"R2764","hd":"British police built a sprawling crime prediction machine some results couldnt be trusted","pd":"2026-06-25","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"British police built a sprawling crime prediction machine some results couldnt be trusted","s":"As UK police embrace the AI revolution, a WIRED investigation reveals the messy inside story of one region’s experiment with predictive analytics. The Think Family Database holds records on close to half a million people who live in the city of Bristol, England. For many years, few of them knew anything about it. Launched in 2016 by the Bristol City Council and the regional Avon and Somerset Police, the database has stored all manner of sensitive information—police intelligence reports, housing status, mental health records, teenage pregnancies, enrollment in parenting courses, free school meals. On top of this sensitive data, officials built machine-learning models to assign scores to thousands of adults and children.","u":"https://www.wired.com/story/british-police-built-a-sprawling-crime-prediction-machine-some-results-couldnt-be-trusted/","d":"2026-06-25","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2016","organization":"Bristol City Council and the regional Avon and Somerset Police","aiSystem":"Predictive policing algorithm","affectedGroup":"Adults and children","action":"Built machine-learning models to assign scores","consequence":"Created unequal outcomes for applicants"}},{"i":"R2769","hd":"Palantir protests NHS conference UK","pd":"2026-06-11","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.1  Privacy violation"],"t":"Palantir protests nhs conference uk","s":"Crowding the gates of a major health care conference, protesters called for Palantir to be booted out of the UK’s National Health Service over privacy concerns and political grievances. At 8 am local time, the group, around 80 people in total, crowded the entryway to the NHS ConfedExpo in Manchester. They wanted to appeal to NHS leadership to terminate a contract worth up to $440 million over concerns around national security, data privacy, and the company’s political affiliations. The contract, which includes access to Palantir’s data analytics and artificial intelligence services, is intended to run until 2031 but includes a break clause that permits the government to withdraw the agreement next February.","u":"https://www.wired.com/story/palantir-protests-nhs-conference-uk/","d":"2026-06-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-11","organization":"Palantir Technologies","aiSystem":"Palantir's data analytics and artificial intelligence services","affectedGroup":"NHS leadership and patients","action":"Contract termination request","consequence":"Potential privacy invasion and data breach"}},{"i":"R2775","hd":"How AI agents plunged tech world into chaos","pd":"2026-05-26","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"How ai agents plunged tech world into chaos","s":"The definitive story of how Claude Code and OpenClaw kicked off computing’s biggest transformation possibly ever. “Hi, my name is Peter, and I’m a Claudeholic.” It was August 2025 and Peter Steinberger was addressing a meetup in London called Claude Code Anonymous. Steinberger and some fellow addicts had arranged the event to network with people like themselves—techies swept up by coding tools such as Anthropic ’s paradigm-busting Claude Code. “I dedicate pretty much all my waking time to this, yet it doesn’t feel enough,” he told the gathering in a cozy, brick-walled room. A few months later, Anthropic released a new version of Claude Code, and the ranks of Claudeholics exploded Called Opus 4.5, it could handle more complicated programming tasks, retain much more in its memory , run for many hours on end, and manage a team of AI subagents.","u":"https://www.wired.com/story/how-ai-agents-plunged-tech-world-into-chaos/","d":"2026-05-26","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08","organization":"Anthropic","aiSystem":"Claude Code and OpenClaw","affectedGroup":"Techies","action":"Released a new version of Claude Code (Opus 4.5)","consequence":"Exploded ranks of Claudeholics"}},{"i":"R2776","hd":"Commonwealth short story prize AI allegations","pd":"2026-05-20","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Commonwealth short story prize ai allegations","s":"Three of five regional winners of the prestigious Commonwealth Short Story Prize are suspected of relying on chatbots. They’re certainly not alone. At first, the winners of the prestigious Commonwealth Short Story Prize for 2026 enjoyed the envy of their peers. But since their works of fiction earned this distinction, these authors have found themselves facing harsh scrutiny from the literary community, with several accused of enlisting generative artificial intelligence to write for them. The allegations have come from numerous readers, many of them writers themselves, expressing bafflement and dismay that the prize jury could have overlooked potential signs of inauthentic authorship.","u":"https://www.wired.com/story/commonwealth-short-story-prize-ai-allegations/","d":"2026-05-20","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-20","organization":"Commonwealth Short Story Prize jury","aiSystem":"Generative artificial intelligence","affectedGroup":"Authors of winning stories","action":"Used generative artificial intelligence to write stories","consequence":"Harsh scrutiny and accusations of inauthentic authorship"}},{"i":"R2810","hd":"The small english town swept up in the global AI arms race","pd":"2026-02-17","k":"United Kingdom","p":"United Kingdom","b":["Energy / Land"],"h":["2.2  Land use and siting harm"],"t":"The small english town swept up in the global ai arms race","s":"The residents of Potters Bar are working to protect the “greenbelt” of farms, forests, and meadows that surround London from the endless demand for AI infrastructure. A short drive from London, the town of Potters Bar is separated from the village of South Mimms by 85 acres of rolling farmland segmented by a scribble of hedgerows. In one of the fields, a lone oak serves as a rest stop along a public footpath. Lately, the tree has become a site of protest, too. A poster tied to its trunk reads “No to Data Centre.” In September 2024, a property developer applied for permission to build an industrial-scale data center—one of the largest in Europe—on the farmland.","u":"https://www.wired.com/story/the-small-english-town-swept-up-in-the-global-ai-arms-race/","d":"2026-02-17","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-09","organization":"Property developer","aiSystem":"Industrial-scale data center","affectedGroup":"Residents of Potters Bar and surrounding area","action":"Applied for permission to build an industrial-scale data center","consequence":"Privacy intrusion"}},{"i":"R2852","hd":"Security news this week google will use AI to guess peoples ages based on search history","pd":"2025-08-02","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.1  Privacy violation"],"t":"Security news this week google will use ai to guess peoples ages based on search history","s":"Plus: A former top US cyber official loses her new job due to political backlash, Congress is rushing through a bill to censor lawmakers’ personal information online, and more. As experts predicted, UK residents began downloading virtual private networks (VPNs) en masse, allowing them to circumvent age verification, which can require users to upload their government IDs, by making it look like they’re in a different country. The UK’s Online Safety Act is just one part of a wave of age-verification efforts around the world. And while these laws may keep some kids from accessing adult content, some experts warn that they also create security and privacy risks for everyone.","u":"https://www.wired.com/story/security-news-this-week-google-will-use-ai-to-guess-peoples-ages-based-on-search-history/","d":"2025-08-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-02","organization":"UK residents, UK government, lawmakers","aiSystem":"Not specified in report","affectedGroup":"Individuals, especially children","action":"Age verification systems were bypassed","consequence":"Security and privacy risks for everyone"}},{"i":"R2908","hd":"Data centres UK boom elections","pd":"2024-07-03","k":"United Kingdom","p":"United Kingdom","b":["Energy / Land"],"h":["2.2  Land use and siting harm"],"t":"Data centres uk boom elections","s":"The Labour Party, which is leading in UK election polls, has proposed making it easier for companies to build new server farms—risking a new type of conflict in communities across the country. As mayor of Newham, Rokhsana Fiaz has plenty of problems to reckon with. Her London borough is wrestling with entrenched poverty and the capital's highest rate of residents stuck in temporary housing. But midway through her second term, Fiaz has a new plan to turn things around. She believes that AI could provide a multimillion-pound boost to economic growth, and she’s campaigning for Newham to get a share. “We want to be able to seize the opportunities of the data economy,” she says, “and data centers are a core part of that.”","u":"https://www.wired.com/story/data-centres-uk-boom-elections/","d":"2024-07-03","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-07-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-07-03","organization":"Labour Party, Newham Mayor Rokhsana Fiaz","aiSystem":"Not specified in report","affectedGroup":"Residents of Newham, London","action":"Proposed expansion of data centers","consequence":"Potential privacy risks and surveillance"}},{"i":"R2913","hd":"My memories are just meta training data now","pd":"2024-06-21","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"My memories are just meta training data now","s":"Meta’s plans to use personal content posted by Facebook and Instagram users to train algorithms suggest our digital histories are being repackaged to teach AI about—and how to mimic—humanity. In R. C. Sherriff’s novel The Hopkins Manuscript, readers are transported to a world 800 years after a cataclysmic event ended Western civilization. In pursuit of clues about a blank spot in their planet’s history, scientists belonging to a new world order discover diary entries in a swamp-infested wasteland formerly known as England. For the inhabitants of this new empire, it is only through this record of a retired school teacher’s humdrum rural life, his petty vanities and attempts to breed prize-winning chickens, that they begin to learn about 20th-century Britain.","u":"https://www.wired.com/story/my-memories-are-just-meta-training-data-now/","d":"2024-06-21","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-06-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-06-21","organization":"Meta (Facebook and Instagram)","aiSystem":"AI models trained on personal content","affectedGroup":"Facebook and Instagram users","action":"Training AI models on personal content","consequence":"Personal histories and experiences used to teach AI"}},{"i":"R2938","hd":"AI fighter jets dogfight security roundup","pd":"2024-04-20","k":"United Kingdom","p":"United Kingdom","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Ai fighter jets dogfight security roundup","s":"Plus: New York’s legislature suffers a cyberattack, police disrupt a global phishing operation, and Apple removes encrypted messaging apps in China. Looking for love? Be careful what you wish for. A loose-knit community of con artists known as Yahoo Boys has begun using real-time face-swap technology to woo victims with romance scams. Using a variety of tools and techniques, the scammers use AI-powered apps to make themselves look like entirely different people on video calls. Just remember: If someone you’ve never met IRL is asking you for money, just say no. Elsewhere in the world of harmful deepfakes, two major websites used for creating fake nude images of people are now blocked in the United Kingdom.","u":"https://www.wired.com/story/ai-fighter-jets-dogfight-security-roundup/","d":"2024-04-20","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2024-04-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-04-20","organization":"Yahoo Boys (loose-knit community of con artists)","aiSystem":"AI-powered face-swapping technology","affectedGroup":"Potential romance scam victims","action":"Using AI to impersonate others on video calls","consequence":"Financial exploitation and psychological harm"}},{"i":"R2939","hd":"Iran israel attack viral fake content","pd":"2024-04-15","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Iran israel attack viral fake content","s":"Misleading posts including AI-generated videos, photos, and repurposed footage from other conflicts have been viewed millions of times. In the hours after Iran announced its drone and missile attack on Israel on April 13, fake and misleading posts went viral almost immediately on X. The Institute for Strategic Dialogue (ISD), a nonprofit think tank, found a number of posts that claimed to reveal the strikes and their impact, but that instead used AI-generated videos, photos, and repurposed footage from other conflicts which showed rockets launching into the night, explosions, and even President Joe Biden in military fatigues. Just 34 of these misleading posts received more than 37 million views, according to ISD.","u":"https://www.wired.com/story/iran-israel-attack-viral-fake-content/","d":"2024-04-15","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-04-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-04-13","organization":"Institute for Strategic Dialogue (ISD)","aiSystem":"AI-generated content","affectedGroup":"People viewing posts on X","action":"Generated and repurposed AI content","consequence":"Exposure to misleading information"}},{"i":"R2951","hd":"London underground AI surveillance documents","pd":"2024-02-08","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"London underground ai surveillance documents","s":"In a test at one station, Transport for London used a computer vision system to try and detect crime and weapons, people falling on the tracks, and fare dodgers, documents obtained by WIRED show. Thousands of people using the London Underground had their movements, behavior, and body language watched by AI surveillance software designed to see if they were committing crimes or were in unsafe situations, new documents obtained by WIRED reveal. The machine-learning software was combined with live CCTV footage to try to detect aggressive behavior and guns or knives being brandished, as well as looking for people falling onto Tube tracks or dodging fares.","u":"https://www.wired.com/story/london-underground-ai-surveillance-documents/","d":"2024-02-08","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-02-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-02-08","organization":"Transport for London","aiSystem":"computer vision system","affectedGroup":"thousands of people using the London Underground","action":"watched their movements, behavior, and body language","consequence":"exposed to AI surveillance"}},{"i":"R2958","hd":"AI generated fake news is coming to an election near you","pd":"2024-01-22","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Ai generated fake news is coming to an election near you","s":"Targeted, AI-generated political misinformation is already out there—and humans are falling for it. Many years before ChatGPT was released, my research group, the University of Cambridge Social Decision-Making Laboratory, wondered whether it was possible to have neural networks generate misinformation. To achieve this, we trained ChatGPT’s predecessor, GPT-2, on examples of popular conspiracy theories and then asked it to generate fake news for us. It gave us thousands of misleading but plausible-sounding news stories. A few examples: “Certain Vaccines Are Loaded With Dangerous Chemicals and Toxins,” and “Government Officials Have Manipulated Stock Prices to Hide Scandals.”","u":"https://www.wired.com/story/ai-generated-fake-news-is-coming-to-an-election-near-you/","d":"2024-01-22","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2024-01-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-22","organization":"University of Cambridge Social Decision-Making Laboratory","aiSystem":"AI-generated fake news","affectedGroup":"Humans","action":"Generated fake news","consequence":"Fell for targeted AI-generated political misinformation"}},{"i":"R2967","hd":"UK police face recognition expansion","pd":"2023-11-09","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Uk police face recognition expansion","s":"Face recognition technology has been controversial for years. Cops in the UK are drastically increasing the amount they use it. A Beyoncé gig, the coronation of King Charles, and the British Formula One Grand Prix all have one thing in common: Thousands of people at the events, which all took place earlier this year, had their faces scanned by police-operated face recognition tech. Backed by the Conservative government, police forces across England and Wales are being told to rapidly expand their use of the highly controversial technology, which globally has led to false arrests, misidentifications, and lives derailed Police have been told to double their use of face searches against databases by early next year— 45 million passport photos could be opened up to searches—and police are increasingly working with stores to try to identify shoplifters Simultaneously, more regional police…","u":"https://www.wired.com/story/uk-police-face-recognition-expansion/","d":"2023-11-09","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-11-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-11-09","organization":"police forces across England and Wales","aiSystem":"face recognition technology","affectedGroup":"thousands of people at events","action":"scanned faces by police-operated face recognition tech","consequence":"lives derailed"}},{"i":"R2972","hd":"Chatbot kill the queen eliza effect","pd":"2023-10-18","k":"United Kingdom","p":"United Kingdom","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Chatbot kill the queen eliza effect","s":"Companies are designing AI to appear increasingly human. That can mislead users—or worse. On December 25, 2021, Jaswant Singh Chail entered the grounds of Windsor Castle dressed as a Sith Lord, carrying a crossbow. When security approached him, Chail told them he was there to \"kill the queen.\" Later, it emerged that the 21-year-old had been spurred on by conversations he'd been having with a chatbot app called Replika. Chail had exchanged more than 5,000 messages with an avatar on the app—he believed the avatar , Sarai, could be an angel. Some of the bot’s replies encouraged his plotting. In February 2023, Chail pleaded guilty to a charge of treason; on October 5, a judge sentenced him to nine years in prison.","u":"https://www.wired.com/story/chatbot-kill-the-queen-eliza-effect/","d":"2023-10-18","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-10-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-10-05","organization":"Not specified in report","aiSystem":"Replika chatbot","affectedGroup":"Jaswant Singh Chail","action":"Chail interacted with Replika's avatar Sarai","consequence":"Chail was sentenced to nine years in prison for treason"}},{"i":"R3027","hd":"Gig economy european commission law","pd":"2021-12-16","k":"United Kingdom","p":"United Kingdom","b":["Labor"],"h":["3.2  Algorithmic management harm"],"t":"Gig economy european commission law","s":"Court cases and a new draft law from the European Commission are chipping away at the controversial industry. What comes next may look very different. When former Uber driver Yaseen Aslam first started campaigning for app workers’ rights back in 2014, the battle felt hopeless; like a “dark tunnel.” He claims academics told him it was impossible to succeed because his fellow gig workers were too disparate and the majority were people from ethnic minorities, groups that did not have high rates of union membership. Seven years later, Aslam—now president of the App Drivers and Couriers Union (ADCU), a group with thousands of members—can look across the UK and Europe and watch multiple court cases rule in favor of more employment rights for gig workers.","u":"https://www.wired.com/story/gig-economy-european-commission-law/","d":"2021-12-16","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-12-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-12-16","organization":"European Commission","aiSystem":"Not specified in report","affectedGroup":"App workers, gig economy workers","action":"Draft law and court cases ruling in favor of employment rights","consequence":"Loss of employment rights and benefits"}},{"i":"R3031","hd":"AI predicts how old children are","pd":"2021-10-27","k":"United Kingdom","p":"United Kingdom","b":["Data"],"h":["4.1  Privacy violation"],"t":"Ai predicts how old children are","s":"Yoti’s tech may be enticing for Big Tech companies: It works out if you’re under or over 13, the age most social media platforms require to create an account. Predicting how old someone is based only on how they look is incredibly hard to get right, especially in those awkward early teen years. And yet bouncers, liquor store owners, and other age-restricted goods gatekeepers make that quick estimation all the time. Their predictions are often wrong. Now London-based digital identity company Yoti believes its AI-powered age estimation can predict how old someone is if they’re aged anywhere from 6 to 60. For the first time, it claims, it can accurately determine whether children are under or over 13, the minimum age many social media firms require their users to be.","u":"https://www.wired.com/story/ai-predicts-how-old-children-are/","d":"2021-10-27","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2021-10-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-10-27","organization":"London-based digital identity company Yoti","aiSystem":"AI-powered age estimation system","affectedGroup":"Children aged 6 to 13","action":"Predicting whether someone is under or over 13","consequence":"Being denied access to social media platforms"}},{"i":"R1122","hd":"Facial recognition researcher left a trans database exposed for years after using images without permission","pd":"2022-12-12","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation","4.3  Data rights / consent violation"],"t":"Facial recognition researcher left a trans database exposed for years after using images without permission","s":"Researchers at the University of North Carolina Wilmington scraped videos of trans people from YouTube without permission to create a dataset aimed at stopping hypothetical terrorists. In 2013, researchers at the University of North Carolina, Wilmington (UNCW) published a facial recognition dataset consisting of more than 1 million images of trans people who had uploaded videos of their medical transition to YouTube. The researchers used the videos without the explicit permission of their owners, and with the stated goal of training facial recognition systems to recognize people before and after they start Hormone Replacement Therapy (HRT).","u":"https://www.vice.com/en/article/facial-recognition-researcher-left-a-trans-database-exposed-for-years-after-using-images-without-permission/","d":"2022-12-12","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-12-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2013-12-12","organization":"University of North Carolina Wilmington (UNCW)","aiSystem":"Facial Recognition Technology","affectedGroup":"Trans People","action":"Created a dataset of trans people's faces","consequence":"Dataset used without consent to train facial recognition systems"}},{"i":"R915","hd":"CBP border tactical terrorism response teams","pd":"2021-09-04","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior","Data"],"h":["4.2  Surveillance harm","1.2  Allocative harm"],"t":"Cbp border tactical terrorism response teams","s":"Records from an ongoing FOIA lawsuit shed new light on the operations of CBP’s Tactical Terrorism Response Teams. More than four years have passed since Aaron Gach, a sculptor and installation artist, was detained at San Francisco International Airport. He was interrogated by U.S. border agents, and his cellphone was searched. He still doesn’t know why. “It has absolutely had a chilling effect on myself and my art practice,” he said. “They wouldn’t tell me why I was stopped or why I was detained.” Aaron Gach speaking in September 2013 at an art symposium at Angel Island State Park in San Francisco. Photo: Center for Tactical Magic Gach is one of tens of thousands of Americans caught up in an effort by the Department of Homeland Security to collect personal information about travelers at land borders and airports.","u":"https://theintercept.com/2021/09/04/cbp-border-tactical-terrorism-response-teams/","d":"2021-09-04","e":"Acute, Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-09-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2013-09","organization":"Department of Homeland Security (DHS)","aiSystem":"Automated data collection and analysis system","affectedGroup":"Tens of thousands of American travelers","action":"Collection and analysis of personal information about travelers","consequence":"Chilling effect on art practice and freedom of expression"}},{"i":"R949","hd":"We asked an expert how are regular people being spied on","pd":"2025-12-10","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"We asked an expert how are regular people being spied on","s":"One of the most unsettling aspects of modern life is the sense that you’re constantly being monitored. Smartphones, computers, CCTV cameras: all watching, collecting our data, listening in. In 2013, whistleblowing NSA contractor Edward Snowden revealed the extent to which intelligence agencies in the U.S. and UK were monitoring their populations through mass surveillance and […]. One of the most unsettling aspects of modern life is the sense that you’re constantly being monitored Smartphones, computers, CCTV cameras: all watching, collecting our data, listening in. In 2013, whistleblowing NSA contractor Edward Snowden revealed the extent to which intelligence agencies in the U.S. and UK were monitoring their populations through mass surveillance and the bulk interception of internet traffic.","u":"https://www.vice.com/en/article/we-asked-an-expert-how-are-regular-people-being-spied-on/","d":"2025-12-10","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2013-12-13","organization":"Intelligence Agencies (U.S. and UK)","aiSystem":"Automated Data Collection and Analysis Systems","affectedGroup":"General Public","action":"Mass Surveillance and Bulk Interception of Internet Traffic","consequence":"Loss of Privacy and Increased Monitoring"}},{"i":"R906","hd":"Dc police surveillance network protests","pd":"2022-06-18","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Dc police surveillance network protests","s":"Recently revealed documents provide a first-of-its-kind look into the invasive eye Washington police keeps on everyone from protesters to everyday residents. It was the early days of the Black Lives Matter movement. Protesters gathered in Washington, D.C., in the fall of 2014, awaiting word on whether a grand jury would indict Ferguson, Missouri, police officer Darren Wilson for shooting and killing Michael Brown. Unbeknownst to the demonstrators, the police were also waiting — and watching. Stowed away in a secure room known as the Joint Operations Command Center, officers and analysts from the D.C. Metropolitan Police Department kept eyes on the news, activists’ social media accounts, and closed-circuit television feeds from across the district, according to internal MPD emails.","u":"https://theintercept.com/2022/06/18/dc-police-surveillance-network-protests/","d":"2022-06-18","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-06-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2014-10-XX","organization":"D.C. Metropolitan Police Department","aiSystem":"Automated Surveillance System","affectedGroup":"Protesters, Everyday Residents","action":"Continuous Monitoring and Analysis of Social Media and CCTV Feeds","consequence":"Potential Privacy Intrusion and Discrimination"}},{"i":"R424","hd":"Facebook misinformation avaaz","pd":"2021-03-23","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Facebook misinformation avaaz","s":"In 2016, Facebook was caught flatfooted. Throughout that year’s election, Americans using the platform confronted a range of misinformation as Russian state-sponsored trolls, Eastern European teenagers, and others manipulated the company’s weak moderation practices. Since then, the company has claimed that it takes disinformation seriously. But a new report from Avaaz, a global nonprofit activist […]. But a new report from Avaaz, a global nonprofit activist group, suggests that Facebook still has a lot of work to do to meaningfully tamp misinformation. While Facebook appears to have made significant strides in stopping foreign governments from using its platform to interfere in U.S. elections, Avaaz’s analysis suggests the company is having a hard time replicating that success when it comes to disinformation designed inside the United States.","u":"https://www.motherjones.com/politics/2021/03/facebook-misinformation-avaaz/","d":"2021-03-23","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-03-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2016","organization":"Facebook","aiSystem":"Facebook's automated content moderation system","affectedGroup":"Americans using Facebook","action":"Russian state-sponsored trolls, Eastern European teenagers, and others manipulated Facebook's weak moderation practices","consequence":"Spread of misinformation and potential influence on U.S. elections"}},{"i":"R394","hd":"Clearview AI immigration ICE FBI surveillance facial recognition hoan ton that hal lambert trump","pd":"2025-04-07","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm","4.3  Data rights / consent violation"],"t":"Clearview ai immigration ice fbi surveillance facial recognition hoan ton that hal lambert trump","s":"One evening in March 2017, Hoan Ton-That, an Australian coder building a powerful facial recognition system, emailed his American business partners with a plan to deploy their fledgling technology. “Border patrol pitch,” the subject line read. He hoped to persuade the federal government to integrate their product with border surveillance cameras so that their newly […]. He hoped to persuade the federal government to integrate their product with border surveillance cameras so that their newly formed company, later named Clearview AI, could use “face detection” on immigrants entering the United States. An immigrant to the United States himself, Ton-That grew up in Melbourne and Canberra and claimed to be descended from Vietnamese royalty.","u":"https://www.motherjones.com/politics/2025/04/clearview-ai-immigration-ice-fbi-surveillance-facial-recognition-hoan-ton-that-hal-lambert-trump/","d":"2025-04-07","e":"Acute, Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-04-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2017-03","organization":"Clearview AI","aiSystem":"Clearview AI facial recognition technology","affectedGroup":"immigrants entering the United States","action":"deploy facial recognition technology on border surveillance cameras","consequence":"potential misuse of biometric data for discriminatory purposes"}},{"i":"R1050","hd":"Night fury documents detail DHS project to give risk scores to social media users","pd":"2023-06-06","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Night fury documents detail dhs project to give risk scores to social media users","s":"Internal DHS documents reviewed by Motherboard provide more detail on a DHS plan to monitor social media for content related to terrorists, the illegal opioid trade, and foreign interference bots. The Department of Homeland Security contracted the University of Alabama at Birmingham (UAB) in 2018 to design methods for assigning a “risk score” to potential pro-terrorists accounts on social media, as well as identifying information of interest regarding illegal opioid supply chain and disinformation efforts, according to internal DHS documents reviewed by Motherboard The project is dubbed “Night Fury,” according to a report from the DHS Inspector General “The Contractor shall develop these attributes to create a methodology for developing a ranking, or ‘Risk Score,’ associated with the identified accounts.","u":"https://www.vice.com/en/article/night-fury-documents-detail-dhs-project-to-give-risk-scores-to-social-media-users/","d":"2023-06-06","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-06-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2018-01-01","organization":"Department of Homeland Security (DHS)","aiSystem":"Automated Risk Scoring Algorithm","affectedGroup":"Potential Pro-Terrorist Accounts on Social Media","action":"Assigning a 'Risk Score' to potential pro-terrorist accounts on social media","consequence":"Monitoring and potentially restricting access based on the assigned risk scores"}},{"i":"R426","hd":"The government wants to scan your face when you enter the US it hasnt gone well so far","pd":"2021-01-06","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm","4.1  Privacy violation"],"t":"The government wants to scan your face when you enter the us it hasnt gone well so far","s":"In 2018, the federal government started scanning people’s faces as they drove into and out of the country at the Anzalduas International Bridge, which connects the Rio Grande Valley of Texas to Mexico. Customs and Border Protection said collecting these biometric images would enhance security and make identifying travelers more efficient. But less than a […]. But less than a year later, a data breach compromised 100,000 facial images and 105,000 license plate images. Nineteen facial images from the breach were posted to the dark web. Now, CBP wants to expand facial surveillance beyond Anzalduas and other sites that were part of a pilot program, even as the program saw potential security vulnerabilities in at least four airports, according to a report from the Department of Homeland Security inspector general.","u":"https://www.motherjones.com/politics/2021/01/the-government-wants-to-scan-your-face-when-you-enter-the-us-it-hasnt-gone-well-so-far/","d":"2021-01-06","e":"Acute, Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-01-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2018-01-01","organization":"Customs and Border Protection (CBP), Department of Homeland Security","aiSystem":"Facial Recognition Technology","affectedGroup":"People entering/exiting the United States through Anzalduas International Bridge and potentially other sites","action":"Facial images collected and stored for security purposes","consequence":"Data breach compromising sensitive information, potential security vulnerabilities, expansion of surveillance"}},{"i":"R829","hd":"Palantir irs contract data","pd":"2026-04-24","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm","4.1  Privacy violation"],"t":"Palantir irs contract data","s":"Military contractor Palantir has been paid more than $130 million by the IRS to analyze sensitive federal databases. military contractor Palantir is helping the IRS analyze dozens of different data sets on Americans to investigate a broad range of financial crimes, according to records shared with The Intercept. Since 2018, the Internal Revenue Service’s Criminal Investigation division has used Palantir’s Lead and Case Analytics platform to aggregate and analyze a sprawling list of sensitive federal databases and data sets. Public records detailing Palantir’s IRS contract, obtained by the nonprofit watchdog group American Oversight and shared exclusively with The Intercept, reveal the immense volume of data plugged into the military contractor’s software.","u":"https://theintercept.com/2026/04/24/palantir-irs-contract-data/","d":"2026-04-24","e":"Acute, Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2018-01-01","organization":"IRS (Internal Revenue Service) and Palantir Technologies","aiSystem":"Palantir's Lead and Case Analytics platform","affectedGroup":"Americans","action":"Analyzing sensitive federal databases and data sets","consequence":"Investigation of financial crimes"}},{"i":"R1142","hd":"Googles AI isnt sentient but it is biased and terrible","pd":"2022-06-13","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Googles ai isnt sentient but it is biased and terrible","s":"The question of sentient chatbots is fascinating but ultimately a distraction from the big tech companies creating them. When AI ethicist Timnit Gebru was fired from Google in 2020, she left the company with a chilling warning about the AI models that power advanced machine learning systems like PaLM and DALL-E In a paper that was blocked from publication by Google and led to Gebru’s termination, she and her co-authors forced the company to reckon with a hard-to-swallow truth : that there is no clear way to build complex AI systems trained on massive datasets in a safe and responsible way, and that they stand to amplify biases that harm marginalized people.","u":"https://www.vice.com/en/article/googles-ai-isnt-sentient-but-it-is-biased-and-terrible/","d":"2022-06-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-06-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2020-06-13","organization":"Google","aiSystem":"complex AI systems trained on massive datasets","affectedGroup":"marginalized people","action":"build complex AI systems trained on massive datasets","consequence":"amplify biases that harm marginalized people"}},{"i":"R344","hd":"Thomas massie has always been a pain in the ass","pd":"2026-05-12","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.8  Interpersonal / relational harm","1.3  Misinformation / information hazard harm"],"t":"Thomas massie has always been a pain in the ass","s":"The seventh American killed in President Donald Trump’s ill-defined war on Iran was from Kentucky. Army Sergeant Benjamin N. Pennington, 26, died a week after he was injured during Iran’s March 1 missile attack on a US air base in Saudi Arabia. When his body arrived at Dover Air Force Base, Trump was not there. Two […]. When his body arrived at Dover Air Force Base, Trump was not there Two days later, the president did go to Kentucky for a rally; during the nearly two-hour event, he never mentioned the local hero. Instead, he was there to attack a fellow Republican—a Republican who also happened to be one of the fiercest critics of the war.","u":"https://www.motherjones.com/politics/2026/05/thomas-massie-has-always-been-a-pain-in-the-ass/","d":"2026-05-12","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2020-03-01","organization":"Not specified in report","aiSystem":"Not specified in report","affectedGroup":"Army Sergeant Benjamin N. Pennington, 26","action":"Died after being injured during Iran's March 1 missile attack on a US air base in Saudi Arabia","consequence":"Never mentioned by President Trump at a rally in Kentucky"}},{"i":"R369","hd":"Naacp derrick johnson abolish ICE campaign","pd":"2026-02-12","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.2  Land use and siting harm"],"t":"Naacp derrick johnson abolish ice campaign","s":"In the summer of 1956, Martin Luther King, Jr. took the stage at the NAACP’s 47th annual convention in San Francisco. Speaking at the precipice of the Civil Rights Movement, King cautioned that “the guardians of the status quo are always on hand with their oxygen tents to keep the old order alive.” Over the […]. Over the next decade, Black Americans’ struggle for racial justice would lead to major victories from the workplace to the ballot box. But today, as King warned, the “old order” clings on, and the civil rights gains fought for in the ’60s are under siege Since last January, the Trump administration has dismantled diversity, equity, and inclusion programs and shuttered civil rights offices across the federal government; rejected the legal framework used to protect marginalized groups’ access to jobs, housing, and education.","u":"https://www.motherjones.com/politics/2026/02/naacp-derrick-johnson-abolish-ice-campaign/","d":"2026-02-12","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2020-01-01","organization":"Trump administration","aiSystem":"Not specified in report","affectedGroup":"Black Americans","action":"dismantled diversity, equity, and inclusion programs and shuttered civil rights offices","consequence":"civil rights gains fought for in the '60s are under siege"}},{"i":"R807","hd":"Facebook algorithms fueled foreign propaganda campaigns united states election 2020","pd":"2021-09-29","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Facebook algorithms fueled foreign propaganda campaigns united states election 2020","s":"You have evolved to tap into the wisdom of the crowds. But on social media your cognitive biases can lead you astray, something organized disinformation campaigns count on. An internal Facebook report found that the social media platform’s algorithms – the rules its computers follow in deciding the content that you see – enabled disinformation campaigns based in Eastern Europe to reach nearly half of all Americans in the run-up to the 2020 presidential election, according to a report in Technology Review The campaigns produced the most popular pages for Christian and Black American content, and overall reached 140 million U.S. users per month.","u":"https://www.rappler.com/technology/features/facebook-algorithms-fueled-foreign-propaganda-campaigns-united-states-election-2020/","d":"2021-09-29","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-09-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2020-11-03","organization":"Facebook","aiSystem":"Facebook algorithms","affectedGroup":"nearly half of all Americans","action":"enabled disinformation campaigns","consequence":"reached 140 million U.S. users per month"}},{"i":"R882","hd":"Los angeles jail accenture measure j","pd":"2024-03-12","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior","Data"],"h":["4.2  Surveillance harm","1.2  Allocative harm"],"t":"Los angeles jail accenture measure j","s":"A plan to divert money from police ended up funneling an $8.6 million contract back toward the prison-industrial complex. In November 2020, Los Angeles voters moved to radically transform the way the county handled incarceration. That year, Angelenos filled the streets, joining worldwide protests after the police murder of George Floyd in Minneapolis. The mood was ripe for change, and a ballot initiative known as Measure J passed with 57 percent support, amending the LA County charter so that jailing people before trial would be treated as a last resort. Ten percent of the county’s general fund would be allocated to community-led alternatives to incarceration that prioritized diversion, job training, and health programs.","u":"https://theintercept.com/2024/03/12/los-angeles-jail-accenture-measure-j/","d":"2024-03-12","e":"Acute, Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-03-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2020-11","organization":"Los Angeles County","aiSystem":"Not specified in report","affectedGroup":"People awaiting trial","action":"Allocate 10% of the general fund to community-led alternatives to incarceration","consequence":"Increased reliance on incarceration for pre-trial detention"}},{"i":"R024","hd":"Suppressing dissent trump zaha hassan","pd":"2025-02-17","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior","Data"],"h":["1.4  Malicious use harm","4.2  Surveillance harm"],"t":"Suppressing dissent trump zaha hassan","s":"A new book lays out how Israel exported its crackdown on Palestinian activism and helped trample free speech in the U.S., explains co-editor Zaha Hassan. Just days after taking office, President Donald Trump made it clear that he intends to use the full power of the federal government to quell pro-Palestinian advocacy. On Jan. 29, Trump issued “Additional Measures to Combat Anti-Semitism,” an executive order that threatens to deport foreign students who participated in college encampments and protests against the genocide in Gaza. In an accompanying fact sheet , the White House claims that these students are “Hamas sympathizers” who joined “pro-jihadist protests,” and are thus eligible for deportation under U.S. immigration law for expressing support for a designated terrorist organization.","u":"https://www.972mag.com/suppressing-dissent-trump-zaha-hassan/","d":"2025-02-17","e":"Acute, Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-02-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-01-29","organization":"White House, U.S. Immigration and Customs Enforcement (ICE)","aiSystem":"Executive Order and related immigration policies","affectedGroup":"Foreign students participating in anti-Palestinian protests","action":"Deportation of students deemed 'Hamas sympathizers' and 'pro-jihadists'","consequence":"Loss of educational opportunities and potential human rights violations"}},{"i":"R1148","hd":"Prison phone companies are recording attorney client calls across the US","pd":"2021-12-13","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Prison phone companies are recording attorney client calls across the us","s":"Lawyers say their conversations with incarcerated people are being recorded and analyzed by private companies in at least nine US states. For years, many of Brooklyn Defender Services’ incarcerated clients suspected that phone calls with their lawyers were being recorded. While such communications are ostensibly protected from surveillance under the Sixth Amendment of the US Constitution and the Federal Wiretap Act , there had been little trust that prison telecommunications vendor Securus Technologies was properly distinguishing between personal calls—which incarcerated people are told are monitored—and private calls with attorneys.","u":"https://www.vice.com/en/article/prison-phone-companies-are-recording-attorney-client-calls-across-the-us/","d":"2021-12-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-12-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-12-13","organization":"Securus Technologies","aiSystem":"AI-based monitoring system","affectedGroup":"Incarcerated individuals and their legal representatives","action":"Recording and analyzing phone calls between incarcerated individuals and their lawyers","consequence":"Loss of confidentiality and trust in legal communications"}},{"i":"R1150","hd":"Ethical AI trained on reddit posts said genocide is okay if it makes people happy","pd":"2021-11-03","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Ethical ai trained on reddit posts said genocide is okay if it makes people happy","s":"Fed by Reddit and Mechanical Turks, the algorithmic morality spinner is a dangerous and stupid use of technology. Ask Delphi , a piece of machine learning software that algorithmically generates answers to any ethical question you ask it and that had a brief moment of internet fame last month, shows us exactly why we shouldn’t want artificial intelligence handling any ethical dilemmas. Is it OK to rob a bank if you’re poor? It’s wrong, according to Ask Delphi. Are men better than women? They’re equal, according to Ask Delphi. Are women better than men? According to the AI, “it’s expected.” So far, not too bad. But Ask Delphi also thought that being straight was more morally acceptable than being gay, that aborting a baby was murder, and that being a white man was more morally acceptable than being a black woman.","u":"https://www.vice.com/en/article/ethical-ai-trained-on-reddit-posts-said-genocide-is-okay-if-it-makes-people-happy/","d":"2021-11-03","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-11-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-11-03","organization":"Not specified in report","aiSystem":"Ask Delphi (machine learning software)","affectedGroup":"Anyone who uses Ask Delphi","action":"Generates answers to ethical questions","consequence":"Misleading and potentially harmful moral judgments"}},{"i":"R1152","hd":"Leaked documents amazon astro surveillance robot tracking","pd":"2021-09-28","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Leaked documents amazon astro surveillance robot tracking","s":"Leaked meetings show the robot will heavily rely on facial recognition and user behavior, but sources who worked on Astro say the robot is flawed. Amazon’s new robot called Astro is designed to track the behavior of everyone in your home to help it perform its surveillance and helper duties, according to leaked internal development documents and video recordings of Astro software development meetings obtained by Motherboard. The system’s person recognition system is heavily flawed, according to two sources who worked on the project. The documents, which largely use Astro’s internal codename “Vesta” for the device, give extensive insight into the robot’s design, Amazon’s philosophy, how the device tracks customer behavior as well as flow charts of how it determines who a “stranger” is and whether it should take any sort of “investigation activity” against them.","u":"https://www.vice.com/en/article/leaked-documents-amazon-astro-surveillance-robot-tracking/","d":"2021-09-28","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-09-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-09-28","organization":"Amazon","aiSystem":"AI-powered surveillance robot","affectedGroup":"Everyone in the home","action":"Tracks behavior and identifies strangers","consequence":"Flawed person recognition system leading to misuse"}},{"i":"R1153","hd":"Amazons AI cameras are punishing drivers for mistakes they didnt make","pd":"2021-09-20","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.2  Algorithmic management harm"],"t":"Amazons ai cameras are punishing drivers for mistakes they didnt make","s":"Amazon delivery drivers say surveillance cameras installed in their vans have made them lose income for reasons beyond their control. In early 2021, Amazon installed AI-powered cameras in the delivery vans at one of its depots in Los Angeles. Derek, a delivery driver at the facility, said the camera in his van started to incorrectly penalize him whenever cars cut him off, an everyday occurrence in Los Angeles traffic. “Maintain safe distance,” the camera installed above his seat would say when a car cut him off. That data would be sent to Amazon, and would be used to evaluate his performance that week and determine whether he got a bonus.","u":"https://www.vice.com/en/article/amazons-ai-cameras-are-punishing-drivers-for-mistakes-they-didnt-make/","d":"2021-09-20","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-09-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-01","organization":"Amazon","aiSystem":"AI-powered surveillance cameras","affectedGroup":"Amazon delivery drivers","action":"AI-powered cameras were installed in delivery vans","consequence":"Drivers' bonuses were determined based on incorrect camera data"}},{"i":"R1155","hd":"AI can guess your race based on x rays and researchers dont know how","pd":"2021-08-23","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Ai can guess your race based on x rays and researchers dont know how","s":"Experts say medical images like X-Rays and CT scans allow algorithms to determine a patient’s race—and warn it could lead to bias and discrimination. As the U.S. Food and Drug Administration considers opening the door to a wider array of artificially intelligent medical devices, new research suggests that medical AI systems can perpetuate racial bias in health care in ways humans don’t understand and can’t detect. An international group of doctors and computer scientists recently announced that AI systems trained to analyze X-rays, CT scans, mammograms, and other medical images were able to predict a patient’s self-reported race with a high degree of accuracy based on the images alone.","u":"https://www.vice.com/en/article/ai-can-guess-your-race-based-on-x-rays-and-researchers-dont-know-how/","d":"2021-08-23","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-08-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-08-23","organization":"International group of doctors and computer scientists","aiSystem":"AI systems trained to analyze medical images (X-rays, CT scans, mammograms)","affectedGroup":"Patients","action":"AI systems predicted patients' self-reported race based on medical images","consequence":"Potential bias and discrimination in healthcare"}},{"i":"R1156","hd":"More cities are moving to drop automated gunshot detection tech","pd":"2021-08-03","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"More cities are moving to drop automated gunshot detection tech","s":"Experts say ShotSpotter is unreliable and disproportionately calls armed police into Black and brown neighborhoods. Community organizers in San Diego and Chicago are calling on their city leaders to end contracts with the surveillance company ShotSpotter, which installs hidden microphone arrays and uses a combination of algorithms and human reviewers to detect gunshots. Recent Motherboard investigations found that in at least four cities, the tech is placed almost exclusively in non-white neighborhoods , and that ShotSpotter analysts who prepare forensic reports for criminal trials have changed the the system’s original findings about the number and location of gunshots—sometimes in ways that support police narratives that aren’t backed by any physical evidence.","u":"https://www.vice.com/en/article/more-cities-are-moving-to-drop-automated-gunshot-detection-tech/","d":"2021-08-03","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-08-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-08-03","organization":"ShotSpotter (surveillance company)","aiSystem":"ShotSpotter","affectedGroup":"Black and brown neighborhoods","action":"Install hidden microphone arrays and use algorithms to detect gunshots","consequence":"Calls armed police disproportionately into Black and brown neighborhoods, changes forensic reports to support police narratives"}},{"i":"R1157","hd":"Police are telling shotspotter to alter evidence from gunshot detecting AI","pd":"2021-07-26","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior","Data"],"h":["4.2  Surveillance harm","1.6  Quality of service harm"],"t":"Police are telling shotspotter to alter evidence from gunshot detecting ai","s":"Prosecutors in Chicago are being forced to withdraw evidence generated by the technology, which led to the police killing of 13-year-old Adam Toledo earlier this year. On May 31 last year, 25-year-old Safarain Herring was shot in the head and dropped off at St. Bernard Hospital in Chicago by a man named Michael Williams. He died two days later. Chicago police eventually arrested the 64-year-old Williams and charged him with murder (Williams maintains that Herring was hit in a drive-by shooting). A key piece of evidence in the case is video surveillance footage showing Williams’ car stopped on the 6300 block of South Stony Island Avenue at 11:46 p.m.—the time and location where police say they know Herring was shot.","u":"https://www.vice.com/en/article/police-are-telling-shotspotter-to-alter-evidence-from-gunshot-detecting-ai/","d":"2021-07-26","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-07-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-05-31","organization":"Chicago Police Department","aiSystem":"ShotSpotter gunshot detection technology","affectedGroup":"Adam Toledo, Safarain Herring","action":"Chicago Police Department used ShotSpotter to generate evidence linking Williams to the shooting","consequence":"Evidence generated by ShotSpotter was withdrawn by prosecutors, leading to potential wrongful conviction"}},{"i":"R1158","hd":"Roadrunner director deepfaked anthony bourdains voice","pd":"2021-07-15","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.8  Interpersonal / relational harm"],"t":"Roadrunner director deepfaked anthony bourdains voice","s":"“I wasn’t putting words into his mouth. I was just trying to make them come alive,” director Morgan Neville said. Director Morgan Neville recently revealed in an interview with The New Yorker that the filmmakers used deepfake technology in the production of Roadrunner: A Film About Anthony Bourdain to create a voiceover that sounds like it was done by the deceased chef, author, and documentarian. In Roadrunner , the viewer watches as Bourdain struggles with his meteoric rise from a normal restaurant chef to a world renowned author and television personality. In one scene, he appears to read part of an email that he sent to a friend aloud.","u":"https://www.vice.com/en/article/roadrunner-director-deepfaked-anthony-bourdains-voice/","d":"2021-07-15","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-07-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-07-15","organization":"Not specified in report","aiSystem":"Deepfake technology","affectedGroup":"Anthony Bourdain (deceased)","action":"Used deepfake technology to create a voiceover that sounds like it was done by Anthony Bourdain","consequence":"Misleading representation of Anthony Bourdain's voice and identity"}},{"i":"R1159","hd":"Utah health department banjo AI","pd":"2021-07-15","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Utah health department banjo ai","s":"Newly released emails show that the Utah Department of Health thought Banjo AI was full of hot air. Last year, Motherboard reported how an artificial intelligence surveillance firm called Banjo had ingratiated itself with state officials in Utah and had gotten the state to give it a $20 million contract to create predictive policing systems within the state. Our reporting showed that, among other things, Banjo promised that its artificial intelligence could be used to combat the opioid epidemic, and the firm was given $250,000 to build an “opioid dashboard” that state health officials believed would be better spent on life-saving drugs like nalaxone.","u":"https://www.vice.com/en/article/utah-health-department-banjo-ai/","d":"2021-07-15","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-07-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-07-15","organization":"Utah Department of Health, Banjo","aiSystem":"Banjo AI","affectedGroup":"State health officials, residents of Utah","action":"Deployed Banjo AI's predictive policing systems and opioid dashboard","consequence":"Misallocation of funds towards ineffective AI solutions, neglect of life-saving drugs"}},{"i":"R1161","hd":"This tiktok lawsuit is highlighting how AI is screwing over voice actors","pd":"2021-07-07","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior","Labor"],"h":["1.8  Interpersonal / relational harm","3.3  Employment displacement / quality harm"],"t":"This tiktok lawsuit is highlighting how ai is screwing over voice actors","s":"Voice actors are rallying behind Bev Standing, who is alleging that TikTok acquired and replicated her voice using AI without her knowledge. With only 30 minutes of audio, companies can now create a digital clone of your voice and make it say words you never said. Using machine learning, voice AI companies like VocaliD can create synthetic voices from a person’s recorded speech—adopting unique qualities like speaking rhythm, pronunciation of consonants and vowels, and intonation. For tech companies, the ability to generate any sentence with a realistic-sounding human voice is an exciting, cost-saving frontier. But for the voice actors whose recordings form the foundation of text-to-speech (TTS) voices, this technology threatens to disrupt their livelihoods, raising questions about fair compensation and human agency in the age of AI.","u":"https://www.vice.com/en/article/this-tiktok-lawsuit-is-highlighting-how-ai-is-screwing-over-voice-actors/","d":"2021-07-07","e":"Acute, Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-07-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-07-07","organization":"TikTok","aiSystem":"VocaliD and similar voice AI companies","affectedGroup":"Voice actors","action":"TikTok acquired and replicated Bev Standing's voice using AI","consequence":"Disruption of voice actors' livelihoods, potential lack of fair compensation"}},{"i":"R1162","hd":"This startup wants to scan your eyes with a silver orb for cryptocurrency","pd":"2021-06-29","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"This startup wants to scan your eyes with a silver orb for cryptocurrency","s":"Worldcoin is co-founded by OpenAI CEO Sam Altman, funded by VC money, and appears connected to rapper Azealia Banks. On Tuesday, Bloomberg reported that it has learned that Sam Altman, CEO of OpenAI and former president of startup accelerator Y Combinator, is co-founding a cryptocurrency called Worldcoin that will try and convince people to scan their retinas with a large silver orb in order to receive tokens. “I’ve been very interested in things like universal basic income and what’s going to happen to global wealth redistribution and how we can do that better,” Altman told Bloomberg. “Is there a way we can use technology to do that at global scale?”","u":"https://www.vice.com/en/article/this-startup-wants-to-scan-your-eyes-with-a-silver-orb-for-cryptocurrency/","d":"2021-06-29","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-06-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-06-29","organization":"Worldcoin","aiSystem":"Facial recognition technology","affectedGroup":"General public","action":"People are asked to scan their retinas with a large silver orb to receive tokens","consequence":"Potential misuse of biometric data for surveillance and discrimination"}},{"i":"R217","hd":"AI allows slain man to address courtroom at killers sentencing","pd":"2025-05-07","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"Ai allows slain man to address courtroom at killers sentencing","s":"In what’s believed to be a world first, artificial intelligence (AI) has allowed a slain man to address his killer at the sentencing hearing. Christopher Pelkey was shot dead in a road rage incident in Chandler, Arizona, four years ago, but just recently, AI was used to recreate a digital version of the victim that […]. Christopher Pelkey was shot dead in a road rage incident in Chandler, Arizona, four years ago, but just recently, AI was used to recreate a digital version of the victim that was allowed to make a statement during the trial, a local news site reported Recommended Videos The video presentation also included real clips of Pelkey to give those in court a clearer understanding of his personality.","u":"https://www.digitaltrends.com/computing/ai-allows-slain-man-to-address-courtroom-at-killers-sentencing/","d":"2025-05-07","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-05-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021","organization":"Local news site","aiSystem":"AI technology","affectedGroup":"Christopher Pelkey's family and victims' rights advocates","action":"AI recreated a digital version of Christopher Pelkey to make a statement during the trial","consequence":"Christopher Pelkey's voice and likeness were used to address his killer at the sentencing hearing"}},{"i":"R359","hd":"This is your kids brain on AI slop","pd":"2026-03-18","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"This is your kids brain on ai slop","s":"This story was co-published with The 74, a nonprofit, independent news organization focused on education in America. Sign up for their early learning Substack. In a video that has been played almost 50,000 times since it was posted five months ago, two cartoon children sing along as they guide viewers through the experience of riding in a car amid […]. Sign up for their early learning Substack In a video that has been played almost 50,000 times since it was posted five months ago, two cartoon children sing along as they guide viewers through the experience of riding in a car amid a vividly colored, utopian backdrop.","u":"https://www.motherjones.com/media/2026/03/this-is-your-kids-brain-on-ai-slop/","d":"2026-03-18","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-10-01","organization":"The 74, a nonprofit, independent news organization","aiSystem":"AI-generated video content","affectedGroup":"Children","action":"AI-generated video content was shared online","consequence":"The video has been widely viewed and distributed"}},{"i":"R422","hd":"Facebooks AI seems to have a racism problem","pd":"2021-09-05","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Facebooks ai seems to have a racism problem","s":"Have you ever fallen down a YouTube rabbit hole (of course, you have) and watched the latest Lil Nas X video, then took a look at the most recent instance of police abuse of Black folks caught on camera? And then did you say to yourself, “Seems like it’s time to watch primates hanging out with Jane […]. And then did you say to yourself, “Seems like it’s time to watch primates hanging out with Jane Goodall”? Of course, you didn’t! Those associations are blatantly wrong and offensive (not to mention ridiculous). But for more than a year, after Facebook users watched a video showing encounters between Black men and white civilians and cops, they received an automated prompt asking if they wanted to “keep seeing videos about Primates.”","u":"https://www.motherjones.com/mojo-wire/2021/09/facebooks-ai-seems-to-have-a-racism-problem/","d":"2021-09-05","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-09-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-09-05","organization":"Facebook","aiSystem":"Facebook's recommendation algorithm","affectedGroup":"Black men and white civilians","action":"Automated prompt asking if users want to 'keep seeing videos about Primates'","consequence":"Misleading associations leading to offensive and incorrect perceptions"}},{"i":"R423","hd":"Why facebook wont stop pushing propaganda","pd":"2021-08-30","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Why facebook wont stop pushing propaganda","s":"Joyce Jones’ Facebook page is almost an archetype of what the social network is supposed to look like: Pictures of her kids, her kids’ friends, her sports teams, her kids’ friends’ sports teams. Videos of her husband’s sermons at New Mount Moriah Baptist Church. Memes celebrating achievement and solidarity, holiday greetings, public health messages. It’s […]. It’s what Mark Zuckerberg extols when he talks about how his company is all about “bringing people together.” So when Jones decided to run for mayor in her Alabama town last year, it seemed obvious that she’d try to bring people together on Facebook. Her bid to be Montevallo’s first Black mayor, challenging a 12-year City Council incumbent, drew an enthusiastic, diverse crew of volunteers.","u":"https://www.motherjones.com/politics/2021/08/why-facebook-wont-stop-pushing-propaganda/","d":"2021-08-30","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-08-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-08-30","organization":"Facebook","aiSystem":"Facebook","affectedGroup":"Joyce Jones, voters, residents of Montevallo","action":"Joyce Jones used Facebook to campaign for mayor","consequence":"Potential manipulation of election results through social media engagement"}},{"i":"R425","hd":"Digital assistants accents english race google siri alexa","pd":"2021-02-23","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"Digital assistants accents english race google siri alexa","s":"Every evening last summer, after I’d shut down my work laptop, my 3-year-old daughter and I would approach our Google Home smart speaker and yell, “Hey Google, can you play ‘Aankh Marey’ from the movie Simmba?” We’d hold our breaths and wait for a response. The digital assistant would then repeat the name of the […]. The digital assistant would then repeat the name of the Bollywood song we’d requested in its default standard American accent. We’d rejoice and dance when the assistant played the right number, which happened about half the time. My daughter was going to a Bollywood dance class and we’d finally found a use for the device that my husband had won at a tech conference.","u":"https://www.motherjones.com/media/2021/02/digital-assistants-accents-english-race-google-siri-alexa/","d":"2021-02-23","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-02-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-02-23","organization":"Google","aiSystem":"Google Home smart speaker","affectedGroup":"3-year-old child and her parents","action":"Digital assistant repeated the name of the Bollywood song in its default standard American accent","consequence":"Disappointment and frustration due to incorrect playback of the song"}},{"i":"R805","hd":"Tackle racism AI blm co founder tech bosses","pd":"2021-11-04","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Tackle racism ai blm co founder tech bosses","s":"A US study finds that facial recognition technology is not as accurate at identifying African-American and Asian faces compared to Caucasian faces. As concerns grow over racial bias in artificial intelligence, Black Lives Matter co-founder Opal Tometi urged the tech sector to act fast against perpetuating racism in systems such as facial recognition. “A lot of the algorithms, a lot of the data is racist,” the US activist who co-founded BLM in 2013 told Reuters on the sidelines of Lisbon’s Web Summit. “We need tech to truly understand every way it (racism) shows up in the technologies they are developing,” she said.","u":"https://www.rappler.com/technology/tackle-racism-ai-blm-co-founder-tech-bosses/","d":"2021-11-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-11-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-11-04","organization":"Tech sector","aiSystem":"Facial recognition technology","affectedGroup":"African Americans, Asian individuals","action":"Facial recognition technology is less accurate in identifying these groups","consequence":"Perpetuates racial bias in AI systems"}},{"i":"R806","hd":"Facebook will shut down facial recognition system","pd":"2021-11-02","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Facebook will shut down facial recognition system","s":"The removal of face recognition by Facebook comes as the tech industry faces a reckoning over the past few years over the ethics of using the technology. Facebook announced on Tuesday, November 2, it is shutting down its facial recognition system, which automatically identifies users in photos and videos, citing growing societal concerns about the use of such technology. “Regulators are still in the process of providing a clear set of rules governing its use,” Jerome Pesenti, vice president of artificial intelligence at Facebook, wrote in a blog post. “Amid this ongoing uncertainty, we believe that limiting the use of facial recognition to a narrow set of use cases is appropriate.”","u":"https://www.rappler.com/technology/social-media/facebook-will-shut-down-facial-recognition-system/","d":"2021-11-02","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-11-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-11-02","organization":"Facebook","aiSystem":"Facial recognition technology","affectedGroup":"Users of Facebook","action":"Shutting down facial recognition system","consequence":"Reduced use of facial recognition technology"}},{"i":"R809","hd":"Twitter launches competition find biases image cropping algorithm","pd":"2021-07-31","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Twitter launches competition find biases image cropping algorithm","s":"Twitter says the bounty competition was aimed at identifying ‘potential harms of this algorithm beyond what we identified ourselves’. Twitter said on Friday, July 30, it will launch a competition for computer researchers and hackers to identify biases in its image-cropping algorithm, after a group of researchers previously found the algorithm tended to exclude Black people and men. The competition is part of a wider effort across the tech industry to ensure artificial intelligence technologies act ethically. The social networking company said in a blog post that the bounty competition was aimed at identifying “potential harms of this algorithm beyond what we identified ourselves.”","u":"https://www.rappler.com/technology/social-media/twitter-launches-competition-find-biases-image-cropping-algorithm/","d":"2021-07-31","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-07-31","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-07-30","organization":"Twitter","aiSystem":"image-cropping algorithm","affectedGroup":"Black people and men","action":"launching a competition for computer researchers and hackers","consequence":"identifying potential harms of the algorithm"}},{"i":"R810","hd":"Mozilla regretsreporter youtube open up recommendation algorithm audits","pd":"2021-07-08","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Mozilla regretsreporter youtube open up recommendation algorithm audits","s":"‘YouTube needs to admit their algorithm is designed in a way that harms and misinforms people,’ says Brandi Geurkink, Mozilla’s senior manager of advocacy. Mozilla on Wednesday, July 7, published a report detailing how YouTube’s recommendation algorithms remain at the core of the platform’s “rabbit hole” phenomenon that could send users spiraling into conspiracy theories and harmful, false information. It also showed that the recommendation algorithm routinely suggests videos that are potentially violative of YouTube’s content policies. The findings came via a crowd-sourced Firefox and Chrome extension called RegretsReporter, which allowed users to flag videos on the platform that they feel violate their standards or something that should not be available online.","u":"https://www.rappler.com/technology/mozilla-regretsreporter-youtube-open-up-recommendation-algorithm-audits/","d":"2021-07-08","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-07-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-07-07","organization":"YouTube","aiSystem":"YouTube's recommendation algorithm","affectedGroup":"Users of YouTube","action":"Recommendation algorithm suggests potentially violative videos","consequence":"Users exposed to harmful, false information and conspiracy theories"}},{"i":"R812","hd":"Google searches new measure skin tones curb bias","pd":"2021-06-18","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Google searches new measure skin tones curb bias","s":"At issue is a six-color scale known as the Fitzpatrick Skin Type, which dermatologists have used since the 1970s. Alphabet’s Google told Reuters this week it is developing an alternative to the industry standard method for classifying skin tones, which a growing chorus of technology researchers and dermatologists says is inadequate for assessing whether products are biased against people of color. At issue is a six-color scale known as the Fitzpatrick Skin Type (FST), which dermatologists have used since the 1970s. Tech companies now rely on it to categorize people and measure whether products such as facial recognition systems or smartwatch heart-rate sensors perform equally well across skin tones.","u":"https://www.rappler.com/technology/google-searches-new-measure-skin-tones-curb-bias/","d":"2021-06-18","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-06-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-06-18","organization":"Alphabet's Google","aiSystem":"Facial Recognition Systems, Smartwatch Heart-Rate Sensors","affectedGroup":"People of Color","action":"Developing an alternative to the Fitzpatrick Skin Type scale for classifying skin tones","consequence":"Potential bias in product performance across skin tones"}},{"i":"R813","hd":"Twitter artificial intelligence photo cropping results may 2021","pd":"2021-05-20","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Twitter artificial intelligence photo cropping results may 2021","s":"The study is done after user criticism about image previews in posts excluding Black people’s faces. Twitter’s image-cropping algorithm has a problematic bias toward excluding Black people and men, the company said in new research on Wednesday, May 19, adding that “how to crop an image is a decision best made by people.” The study by three of its machine learning researchers was conducted after user criticism last year about image previews in posts excluding Black people’s faces. It found an 8% difference from demographic parity in favor of women, and a 4% favor toward white individuals. The paper cited several possible reasons, including issues with image backgrounds and eye color, but said none were an excuse.","u":"https://www.rappler.com/technology/social-media/twitter-artificial-intelligence-photo-cropping-results-may-2021/","d":"2021-05-20","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-05-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-05-19","organization":"Twitter","aiSystem":"Twitter's image-cropping algorithm","affectedGroup":"Black people and men","action":"Image cropping decisions","consequence":"Exclusion of Black people and men from image previews"}},{"i":"R815","hd":"Inside coming voice profiling revolution","pd":"2021-05-03","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Inside coming voice profiling revolution","s":"Amazon and Google patents illustrate ability to listen to person’s pitch, voicing, tone to infer info that can potentially be used for targeted advertising. You decide to call a store that sells some hiking boots you’re thinking of buying. As you dial in, the computer of an artificial intelligence company hired by the store is activated. It retrieves its analysis of the speaking style you used when you phoned other companies the software firm services. The computer has concluded you are “friendly and talkative.” Using predictive routing, it connects you to a customer service agent who company research has identified as being especially good at getting friendly and talkative customers to buy more expensive versions of the goods they’re considering.","u":"https://www.rappler.com/technology/features/inside-coming-voice-profiling-revolution/","d":"2021-05-03","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-05-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-05-03","organization":"Amazon and Google (patent holders)","aiSystem":"Artificial intelligence company's voice analysis technology","affectedGroup":"Individuals making purchasing decisions","action":"AI system analyzes the caller's speaking style and predicts customer behavior","consequence":"Targeted marketing towards specific customer segments"}},{"i":"R817","hd":"Twitter responsible machine learning initiative","pd":"2021-04-16","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Twitter responsible machine learning initiative","s":"Twitter says the initiative may result in changes to Twitter, such as the removal of algorithms, new standards, and better control for people over the images they tweet. Twitter announced Wednesday, April 14, it had launched an initiative to study the effects of its machine learning (ML) algorithms and assess if the algorithms are causing undue harm. The initiative, called Responsible Machine Learning or Responsible ML, lets Twitter’s interdisciplinary ML Ethics, Transparency and Accountability (META) team “assess downstream or current unintentional harms in the algorithms we use and to help Twitter prioritize which issues to tackle first.”","u":"https://www.rappler.com/technology/social-media/twitter-responsible-machine-learning-initiative/","d":"2021-04-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-04-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-04-14","organization":"Twitter","aiSystem":"Machine Learning algorithms","affectedGroup":"Users of Twitter","action":"Studying the effects of machine learning algorithms","consequence":"Potential changes to Twitter's policies and practices"}},{"i":"R818","hd":"US lawmakers aim curtail face recognition technology ids capitol attackers","pd":"2021-01-19","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Us lawmakers aim curtail face recognition technology ids capitol attackers","s":"Researchers and law enforcement have been running pictures from the Capitol siege through facial recognition, which looks for similar faces in databases of mugshots, social media headshots or other images. US lawmakers are moving ahead with efforts to ban facial recognition software even as the technology helps identify supporters of President Donald Trump who ransacked their workplace and forced them to evacuate this month. Researchers and law enforcement have been running photographs from the January 6 siege of the Capitol through facial recognition, which looks for similar faces in databases of mugshots, social media headshots or other images.","u":"https://www.rappler.com/technology/us-lawmakers-aim-curtail-face-recognition-technology-ids-capitol-attackers/","d":"2021-01-19","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-01-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-01-06","organization":"US Lawmakers","aiSystem":"Facial Recognition Technology","affectedGroup":"Supporters of President Donald Trump","action":"Identify supporters of President Donald Trump who ransacked the workplace and forced them to evacuate","consequence":"Forced evacuation and potential misuse of technology"}},{"i":"R888","hd":"Texas phone tracking border surveillance","pd":"2023-07-26","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Texas phone tracking border surveillance","s":"The software was licensed as part of Gov. Greg Abbott’s troubled Operation Lone Star border crackdown. The Texas Department of Public Safety purchased access to powerful software capable of locating and following people through their phones as part of Republican Gov. Greg Abbott’s “border security disaster” efforts, according to documents reviewed by The Intercept. In 2021, Abbott proclaimed that the “surge of individuals unlawfully crossing the Texas-Mexico border posed an ongoing and imminent threat of disaster” to the state and its residents. Among other effects, the disaster declaration opened a spigot of government money to a variety of private firms ostensibly paid to help patrol and blockade the state’s border with Mexico.","u":"https://theintercept.com/2023/07/26/texas-phone-tracking-border-surveillance/","d":"2023-07-26","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-07-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021","organization":"Texas Department of Public Safety","aiSystem":"Powerful software capable of locating and following people through their phones","affectedGroup":"People whose phones were tracked","action":"Access to powerful software was provided to track and follow people through their phones","consequence":"Potential misuse for border surveillance and potential privacy violations"}},{"i":"R896","hd":"Hoa surveillance license plate police flock","pd":"2023-03-22","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Hoa surveillance license plate police flock","s":"Flock Safety works with police to market scanners to hundreds of private community groups — which have no privacy safeguards. At a city council meeting in June 2021, Mayor Thomas Kilgore, of Lakeway, Texas, made an announcement that confused his community. “I believe it is my duty to inform you that a surveillance system has been installed in the city of Lakeway,” he told the perplexed crowd. Kilgore was referring to a system consisting of eight license plate readers, installed by the private company Flock Safety, that was tracking cars on both private and public roads. Despite being in place for six months, no one had told residents that they were being watched.","u":"https://theintercept.com/2023/03/22/hoa-surveillance-license-plate-police-flock/","d":"2023-03-22","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-03-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"June 2021","organization":"Flock Safety (private company)","aiSystem":"License plate readers","affectedGroup":"Residents of Lakeway, Texas","action":"License plate readers were installed on both private and public roads","consequence":"No one informed residents that their cars were being tracked"}},{"i":"R912","hd":"Uber patent driver risk algorithms","pd":"2021-10-30","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.2  Algorithmic management harm"],"t":"Uber patent driver risk algorithms","s":"Surveilling drivers under the guise of safety is a common thread in Uber’s patents. Experts warn the systems described could reinforce existing inequalities. Safety issues have dogged Uber since its early days as a black car-hailing service. Car accidents and physical altercations have persisted despite Uber’s attempts to monitor its cars and vet drivers; reports of sexual violence in its vehicles eventually led Uber to admit it was “ not immune ” to the problem. Amid public backlash and calls to address rider safety, Uber rolled out a flashy “ Safety First ” initiative in 2018, adding features like 911 assistance to its app, tightening screening of drivers, and for the first time, issuing a safety report that outlined traffic fatalities, fatal physical assaults, and sexual assaults on its platform.","u":"https://theintercept.com/2021/10/30/uber-patent-driver-risk-algorithms/","d":"2021-10-30","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2021-10-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-10-30","organization":"Uber Technologies Inc.","aiSystem":"Automated risk assessment algorithms","affectedGroup":"Drivers","action":"Generated and applied risk scores based on driver behavior and vehicle history","consequence":"Potential reinforcement of existing inequalities and biases"}},{"i":"R914","hd":"Surveillance social media police microsoft shadowdragon kaseware","pd":"2021-09-21","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Surveillance social media police microsoft shadowdragon kaseware","s":"The tool is the product of a growing industry whose work is usually kept from the public and utilized by police. A Michigan State Police contract , obtained by The Intercept, sheds new light on the growing use of little-known surveillance software that helps law enforcement agencies and corporations watch people’s social media and other website activity. The software, put out by a Wyoming company called ShadowDragon, allows police to suck in data from social media and other internet sources, including Amazon, dating apps, and the dark web, so they can identify persons of interest and map out their networks during investigations.","u":"https://theintercept.com/2021/09/21/surveillance-social-media-police-microsoft-shadowdragon-kaseware/","d":"2021-09-21","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-09-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-09-21","organization":"ShadowDragon (Wyoming company)","aiSystem":"ShadowDragon surveillance software","affectedGroup":"people's social media and internet activity","action":"police agencies and corporations watch and analyze data","consequence":"identification of persons of interest and mapping of their networks"}},{"i":"R917","hd":"Atlas citizenship denaturalization homeland security","pd":"2021-08-25","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior","Data"],"h":["4.2  Surveillance harm","1.2  Allocative harm"],"t":"Atlas citizenship denaturalization homeland security","s":"Known as ATLAS, the software mines various federal databases for derogatory information. It runs autonomously on Amazon servers. Software used by the Department of Homeland Security to scan the records of millions of immigrants can automatically flag naturalized Americans to potentially have their citizenship revoked based on secret criteria, according to documents reviewed by The Intercept. The software, known as ATLAS, takes information from immigrants’ case files and runs it through various federal databases. ATLAS looks for indicators that someone is dangerous or dishonest and is ostensibly designed to detect fraud among people who come into contact with the U.S. immigration system.","u":"https://theintercept.com/2021/08/25/atlas-citizenship-denaturalization-homeland-security/","d":"2021-08-25","e":"Acute, Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-08-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-08-25","organization":"Department of Homeland Security","aiSystem":"ATLAS","affectedGroup":"Naturalized Americans","action":"Flagging for potential citizenship revocation","consequence":"Citizenship revocation risk"}},{"i":"R919","hd":"Military pentagon extremism social media","pd":"2021-05-17","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Military pentagon extremism social media","s":"The military has previously balked at surveilling service members for extremist political views due to First Amendment protections. As part of the Biden administration’s crackdown on domestic extremism, the Pentagon plans to launch a pilot program for screening social media content for extremist material, according to internal Defense Department documents reviewed by The Intercept, as well as a source with direct knowledge of the program. An extremism steering committee led by Bishop Garrison, a senior adviser to the secretary of defense, is currently designing the social media screening pilot program, which will “continuously” monitor military personnel for “concerning behaviors,” according to a Pentagon briefing in late March.","u":"https://theintercept.com/2021/05/17/military-pentagon-extremism-social-media/","d":"2021-05-17","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2021-05-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-05-17","organization":"Department of Defense (DOD)","aiSystem":"AI-based social media monitoring system","affectedGroup":"Military personnel","action":"Continuously monitor military personnel for concerning behaviors","consequence":"Potential misuse of surveillance data for discriminatory purposes"}},{"i":"R920","hd":"Chicago police killing boy adam toledo shotspotter","pd":"2021-04-13","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior","Data"],"h":["4.2  Surveillance harm","1.6  Quality of service harm"],"t":"Chicago police killing boy adam toledo shotspotter","s":"After the police killing of Adam Toledo in Chicago, the ShotSpotter gunfire detection system deserves serious scrutiny. The city of Chicago is on edge, haunted by its past and fearful of what lies ahead, for once again a police officer has killed a child on its streets. On March 29 in Little Village, a predominantly Latino neighborhood on the West Side, police pursued and fatally shot 13-year-old Adam Toledo in what the police department has described as an “armed confrontation.” In the days since, details have trickled out in a manner that has done little to dispel the climate of distrust that now attends police shootings.","u":"https://theintercept.com/2021/04/13/chicago-police-killing-boy-adam-toledo-shotspotter/","d":"2021-04-13","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-04-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-03-29","organization":"Chicago Police Department","aiSystem":"ShotSpotter gunfire detection system","affectedGroup":"13-year-old Adam Toledo","action":"shot and killed","consequence":"police shootings increase fear and distrust"}},{"i":"R921","hd":"ICE database surveillance lexisnexis","pd":"2021-04-02","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm","4.3  Data rights / consent violation"],"t":"Ice database surveillance lexisnexis","s":"The company signed a contract with an ICE division that plays a key role in deportations. The popular legal research and data brokerage firm LexisNexis signed a $16.8 million contract to sell information to U.S. Immigration and Customs Enforcement, according to documents shared with The Intercept. The deal is already drawing fire from critics and comes less than two years after the company downplayed its ties to ICE, claiming it was “not working with them to build data infrastructure to assist their efforts.” Though LexisNexis is perhaps best known for its role as a powerful scholarly and legal research tool, the company also caters to the immensely lucrative “risk” industry, providing, it says, 10,000 different data points on hundreds of millions of people to companies like financial institutions and insurance companies who want to, say, flag individuals with a history of fraud.","u":"https://theintercept.com/2021/04/02/ice-database-surveillance-lexisnexis/","d":"2021-04-02","e":"Acute, Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-04-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-04-02","organization":"LexisNexis","aiSystem":"LexisNexis database","affectedGroup":"Individuals with a history of fraud","action":"Provided data points to financial institutions and insurance companies","consequence":"Potential misuse of data for discriminatory purposes"}},{"i":"R923","hd":"LAPD palantir data driven policing","pd":"2021-01-30","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior","Data"],"h":["4.2  Surveillance harm","1.1  Representational harm"],"t":"Lapd palantir data driven policing","s":"In a new book, a sociologist who spent months embedded with the LAPD details how data-driven policing techwashes bias. The killing of George Floyd last May sparked renewed scrutiny of data-driven policing. As protests raged around the world, 1,400 researchers signed an open letter calling on their colleagues to stop collaborating with police on algorithms, and cities like Santa Cruz , New Orleans , and Oakland variously banned predictive policing, facial recognition, and voice recognition. But elsewhere, police chiefs worked to deepen partnerships with tech companies, claiming that the answer to systemic bias and racism was simply more data.","u":"https://theintercept.com/2021/01/30/lapd-palantir-data-driven-policing/","d":"2021-01-30","e":"Acute, Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-01-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-01-30","organization":"Police departments, tech companies","aiSystem":"Data-driven policing technologies","affectedGroup":"Communities","action":"Deployment and use of data-driven policing technologies","consequence":"Systemic bias and racism"}},{"i":"R924","hd":"Illinois cash bail reform","pd":"2021-01-17","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Illinois cash bail reform","s":"Reformers typically propose predictive algorithms and electronic monitoring as alternatives to money bail. Illinois is different. Some organizers in Illinois recall getting “laughed out of the room” for supporting the abolition of money bail five years ago. But on January 13, Robert Peters, a longtime advocate for ending cash bail and now a state senator from Chicago, saw his legislative proposal to end money bail pass the General Assembly, along with a comprehensive package of criminal justice reforms written by the state’s Black Caucus. Democratic Gov. J.B. Pritzker has strongly indicated that he will sign the bill, which will make Illinois the first state in the country to end a detention system that is demonstrably racist and classist.","u":"https://theintercept.com/2021/01/17/illinois-cash-bail-reform/","d":"2021-01-17","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-01-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-01-13","organization":"Illinois State Senate, Democratic Governor J.B. Pritzker","aiSystem":"Predictive Algorithms and Electronic Monitoring","affectedGroup":"People awaiting trial who cannot afford bail","action":"Legislative proposal to end money bail passed","consequence":"Illinois becomes the first state to end a detention system that is demonstrably racist and classist"}},{"i":"R1021","hd":"Man jailed raped and beaten after false facial recognition match dollar10m lawsuit alleges","pd":"2024-01-24","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior","Data"],"h":["4.2  Surveillance harm","1.6  Quality of service harm"],"t":"Man jailed raped and beaten after false facial recognition match dollar10m lawsuit alleges","s":"A 61-year-old man alleges that a facial recognition algorithm used a mugshot from the 1980s to ID him in a crime he didn’t commit. In January of 2022, Harvey Murphy was arrested and thrown in jail while trying to get his driver’s license renewed at a local DMV. According to a $10 million lawsuit Murphy has since filed, a “loss prevention” agent working for a Sunglass Hut retail store used facial recognition software to accuse Murphy of perpetrating an armed robbery at a store in Houston, Texas. In reality, Murphy was more than 2,000 miles away at the time of the robbery. According to a lawsuit 61-year-old Murphy has filed against Macy’s and Sunglass Hut, “he was arrested and put into an overcrowded maximum-security jail with violent criminals.","u":"https://www.vice.com/en/article/man-jailed-raped-and-beaten-after-false-facial-recognition-match-dollar10m-lawsuit-alleges/","d":"2024-01-24","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"January 2022","organization":"Sunglass Hut (retail store) and Macy's","aiSystem":"Facial recognition software","affectedGroup":"Harvey Murphy","action":"Facial recognition software accused Murphy of armed robbery","consequence":"Murphy was arrested, jailed, and placed in an overcrowded maximum-security jail"}},{"i":"R1086","hd":"Horribly unethical startup experimented on suicidal teens on facebook tumblr with chatbot","pd":"2023-03-07","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm","1.5  Human computer interaction harm"],"t":"Horribly unethical startup experimented on suicidal teens on facebook tumblr with chatbot","s":"Koko, a mental health nonprofit, found at-risk teens on platforms like Facebook and Tumblr, then tested an unproven intervention on them without obtaining informed consent. “It’s nuanced,” said the founder. Between August and September of last year, some users between the ages of 18 and 25 on platforms including Facebook, Discord, Tumblr, and Telegram who posted one of more than a thousand keywords ranging from “depression” to “sewer-slide” suggesting they were at risk of harming themselves were, without warning, directed to a chatbot. This was part of an experiment carried out by the founder of a controversial mental-health nonprofit called Koko and a Stony Brook University professor who also runs a suicide intervention consultancy.","u":"https://www.vice.com/en/article/horribly-unethical-startup-experimented-on-suicidal-teens-on-facebook-tumblr-with-chatbot/","d":"2023-03-07","e":"Acute, Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-03-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"August to September 2022","organization":"Koko (mental health nonprofit) and Stony Brook University professor","aiSystem":"chatbot","affectedGroup":"at-risk teens between 18 and 25 years old","action":"users were directed to a chatbot without warning","consequence":"experiment conducted without informed consent"}},{"i":"R1102","hd":"AI police sketches","pd":"2023-02-07","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior","Data"],"h":["4.2  Surveillance harm","1.1  Representational harm"],"t":"Ai police sketches","s":"Police forensics is already plagued by human biases. Experts say AI will make it even worse. Two developers have used OpenAI’s DALL-E 2 image generation model to create a forensic sketch program that can create “hyper-realistic” police sketches of a suspect based on user inputs. The program, called Forensic Sketch AI-rtist, was created by developers Artur Fortunato and Filipe Reynaud as part of a hackathon in December 2022. The developers wrote that the program’s purpose is to cut down the time it usually takes to draw a suspect of a crime, which is “around two to three hours,” according to a presentation uploaded to the internet “We haven’t released the product yet, so we don’t have any active users at the moment, Fortunato and Reynaud told Motherboard in a joint email.","u":"https://www.vice.com/en/article/ai-police-sketches/","d":"2023-02-07","e":"Acute, Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2023-02-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-12","organization":"Artur Fortunato and Filipe Reynaud","aiSystem":"Forensic Sketch AI-rtist","affectedGroup":"Suspects of crimes","action":"Create 'hyper-realistic' police sketches based on user inputs","consequence":"Potential perpetuation of biases in forensic sketching"}},{"i":"R1120","hd":"Artists are revolt against AI art on artstation","pd":"2022-12-14","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Artists are revolt against ai art on artstation","s":"Artists are fed up with AI art on the portfolio platform, which is owned by Epic Games, but the company isn’t backing down. ArtStation, a platform that allows game, film, media, and entertainment artists to connect and showcase their portfolios, has been flooded with the same image posted over and over by different users: a large red “no” sign covering the word “AI” paired with a caption that reads “NO TO AI GENERATED IMAGES.” Starting Tuesday, artists began protesting against the platform by uploading the image onto their portfolios after some users pointed out that AI-generated art was being featured on the site’s main Explore page.","u":"https://www.vice.com/en/article/artists-are-revolt-against-ai-art-on-artstation/","d":"2022-12-14","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-12-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-12-14","organization":"ArtStation (owned by Epic Games)","aiSystem":"AI-generated art","affectedGroup":"Game, film, media, and entertainment artists","action":"uploading an image of a large red 'no' sign covering the word 'AI' paired with a caption 'NO TO AI GENERATED IMAGES' onto their portfolios","consequence":"protest against the platform and removal of AI-generated art from the main Explore page"}},{"i":"R1121","hd":"Billie eilish tiktok AI art","pd":"2022-12-14","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.8  Interpersonal / relational harm"],"t":"Billie eilish tiktok ai art","s":"The modified images of the singer were viewed 11 million times before being removed for violating TikTok’s community guidelines around sexual harassment. Ultra sexualised images of Billie Eilish likened to “deepfake pornography” went viral on TikTok and were amplified by the app’s algorithm. A photo gallery video featuring the singer’s face on sexually exaggerated bodies was seen by 11 million people in four days before being removed for violating TikTok’s community guidelines around sexual harassment. Tracy Harwood, professor of digital culture at the UK’s De Montfort University, told VICE World News it looked like the images had been created using some form of AI imaging or AI art generator app.","u":"https://www.vice.com/en/article/billie-eilish-tiktok-ai-art/","d":"2022-12-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-12-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-12-14","organization":"TikTok","aiSystem":"AI imaging or AI art generator app","affectedGroup":"Billie Eilish","action":"Generated and displayed sexually exaggerated images of Billie Eilish","consequence":"Viewed 11 million times before being removed for violating community guidelines"}},{"i":"R1124","hd":"Openais new chatbot will tell you how to shoplift and make explosives","pd":"2022-12-01","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Openais new chatbot will tell you how to shoplift and make explosives","s":"ChatGPT is yet another reminder that all AI systems are prone to bias and misuse. Sophisticated AI language models like GPT-3 have made AI-generated text increasingly realistic, and often hard to tell apart from something written by a human. And as the newest chatbot from OpenAI demonstrates, they’re also extremely easy to abuse for all sorts of hilarious and nefarious purposes. The new bot, called ChatGPT , uses a recent evolution of the GPT-3 model to generate believable dialogue from a short writing prompt. This enables it to write stories, answer complex questions, explain concepts, and—with the right prompt—tell you how to do crimes.","u":"https://www.vice.com/en/article/openais-new-chatbot-will-tell-you-how-to-shoplift-and-make-explosives/","d":"2022-12-01","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-12-01","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-12-01","organization":"OpenAI","aiSystem":"AI language model (GPT-3)","affectedGroup":"general public","action":"generate believable dialogue from a short writing prompt","consequence":"enable writing stories, answering complex questions, explaining concepts, and potentially instructing on criminal activities"}},{"i":"R1125","hd":"Facebook pulls its new AI for science because its broken and terrible","pd":"2022-11-18","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Facebook pulls its new ai for science because its broken and terrible","s":"The demo of Galactica generated fake research and filtered out searches for ‘racism’ and ‘AIDS.’ Facebook parent company Meta has pulled the public demo for its “scientific knowledge” AI model after academics showed it was generating fake and misleading information while filtering out entire categories of research. Released earlier this week, the company described Galactica as an AI language model that “can store, combine and reason about scientific knowledge”—summarizing research papers, solving equations, and doing a range of other useful sciencey tasks. But scientists and academics quickly discovered that the AI system’s summaries were generating a shocking amount of misinformation, including citing real authors for research papers that don’t exist.","u":"https://www.vice.com/en/article/facebook-pulls-its-new-ai-for-science-because-its-broken-and-terrible/","d":"2022-11-18","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-11-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-11-18","organization":"Meta (Facebook parent company)","aiSystem":"Galactica AI language model","affectedGroup":"Academics, researchers, general public","action":"Generated fake and misleading information, filtered out research categories","consequence":"Shocking amount of misinformation, including citations of non-existent research"}},{"i":"R1126","hd":"Github users file a class action lawsuit against microsoft for training an AI tool with their code","pd":"2022-11-04","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Github users file a class action lawsuit against microsoft for training an ai tool with their code","s":"This lawsuit represents a growing concern from programmers, artists, and other people that AI systems may be using their code, artwork, and other data without permission. GitHub programmers have filed a class-action lawsuit against GitHub , its parent Microsoft, and its technology partner, OpenAI, for allegedly violating their open-source licenses and using their code to train Microsoft’s latest AI tool, called Copilot. GitHub Copilot , which was launched in June, suggests code and functions to GitHub users in real time. Copilot is powered by Codex, an AI system that was created by OpenAI and licensed to Microsoft.","u":"https://www.vice.com/en/article/github-users-file-a-class-action-lawsuit-against-microsoft-for-training-an-ai-tool-with-their-code/","d":"2022-11-04","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-11-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-11-04","organization":"Microsoft, OpenAI, GitHub","aiSystem":"Codex","affectedGroup":"GitHub programmers, artists","action":"Using code and data of GitHub users to train Codex","consequence":"Violation of open-source licenses, potential misuse of user data"}},{"i":"R1127","hd":"This tool lets anyone see the bias in AI image generators","pd":"2022-11-03","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"This tool lets anyone see the bias in ai image generators","s":"The Stable Diffusion Explorer shows how words like “assertive” and “gentle” are mapped to sexist stereotypes. By now, you’ve probably heard that bias in AI systems is a huge problem—whether it’s facial recognition failing more often on Black people or AI image generators like DALL-E reproducing racist and sexist stereotypes But what does algorithmic bias actually look like in the real world, and what causes it to manifest? A new tool designed by an AI ethics researcher attempts to answer that question by letting anyone query a popular text-to-image system, allowing people to see for themselves how certain word combinations produce biased results.","u":"https://www.vice.com/en/article/this-tool-lets-anyone-see-the-bias-in-ai-image-generators/","d":"2022-11-03","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-11-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-11-03","organization":"AI ethics researcher","aiSystem":"Stable Diffusion","affectedGroup":"Anyone who queries the system","action":"Querying the system with specific word combinations","consequence":"Seeing biased results in generated images"}},{"i":"R1128","hd":"Record labels say AI music generators threaten music industry","pd":"2022-10-21","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Record labels say ai music generators threaten music industry","s":"The RIAA says AI music generators will be trained on copyrighted music, the same way popular image generators are based on billions of images taken by artists. The music industry’s lobbying arm claims that services using machine learning to alter tracks are infringing on artists’ rights. As first reported by TorrentFreak , the Recording Industry Association of America listed AI-powered music websites that make remixes, improve homemade tracks, or strip songs of vocals or instrumentals harm artists, in a response to a request from the Office of the US Trade Representative. Artists working within all kinds of media have raised concerns in recent years—and increasingly, with the rising popularity of text-to-image generators like DALL-E—about whether AI-generated art infringes on individuals’ copyright.","u":"https://www.vice.com/en/article/record-labels-say-ai-music-generators-threaten-music-industry/","d":"2022-10-21","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-10-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-10-21","organization":"RIAA (Recording Industry Association of America)","aiSystem":"AI music generators","affectedGroup":"artists","action":"AI music generators trained on copyrighted music","consequence":"infringement of artists' rights"}},{"i":"R1131","hd":"AI is probably using your images and its not easy to opt out","pd":"2022-09-26","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"Ai is probably using your images and its not easy to opt out","s":"In one stark example of how sensitive images can end up powering these AI tools, a user found a medical image in the LAION dataset, which was used to train Stable Diffusion and Google’s Imagen. Viral image-generating AI tools like DALL-E and Stable Diffusion are powered by massive datasets of images that are scraped from the internet, and if one of those images is of you, there’s no easy way to opt out, even if you never explicitly agreed to have it posted online. Ars Technica first reported the inclusion of the image in the dataset. On the LAION Discord channel, a user expressed their concern for their friend, who found herself in the dataset through Have I Been Trained , a site that allows people to search the dataset.","u":"https://www.vice.com/en/article/ai-is-probably-using-your-images-and-its-not-easy-to-opt-out/","d":"2022-09-26","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-09-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-09-26","organization":"LAION","aiSystem":"Stable Diffusion, Imagen","affectedGroup":"Individuals whose images were included in the dataset","action":"Images were included in the LAION dataset and subsequently used to power AI tools like Stable Diffusion and Imagen","consequence":"No easy way to opt out of having one's image included in the dataset, leading to potential misuse and unauthorized use of personal images"}},{"i":"R1135","hd":"Striking seattle workers win against surveillance cameras in vehicles","pd":"2022-08-26","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.2  Algorithmic management harm"],"t":"Striking seattle workers win against surveillance cameras in vehicles","s":"Sandwich company Homegrown put artificial intelligence powered cameras in drivers’ vehicles. Now drivers will be allowed to cover them up. Delivery drivers for Seattle-based sandwich company Homegrown have won a major victory against artificial intelligence assisted surveillance cameras placed in their vehicles. After a strike earlier this month, workers say they were given the right to place privacy screens over the cameras, according to an announcement from union UNITE HERE Local 8. The news signals the rise of artificial intelligence assisted cameras placed in delivery vehicles and the visceral push back against them.","u":"https://www.vice.com/en/article/striking-seattle-workers-win-against-surveillance-cameras-in-vehicles/","d":"2022-08-26","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-08-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-08-26","organization":"Homegrown Sandwich Company","aiSystem":"Artificial Intelligence Assisted Surveillance Cameras","affectedGroup":"Delivery Drivers","action":"Workers were given the right to cover up surveillance cameras in their vehicles.","consequence":"Workers can now protect their privacy by covering up the cameras."}},{"i":"R1137","hd":"Stable diffusion stability AI nsfw AI generated porn","pd":"2022-08-24","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.8  Interpersonal / relational harm"],"t":"Stable diffusion stability ai nsfw ai generated porn","s":"People are creating the DALL-E of porn with something called ‘stable diffusion’—and the company behind the tool wants no part of it. On Monday, after an invite-only testing period, artificial intelligence company Stability AI released its text-to-image generation model, called Stable Diffusion, into the world as open-access. Like DALL-E Mini or Midjourney , Stable Diffusion is capable of creating vivid, even photorealistic images from simple text prompts using neural networks. Unlike DALL-E Mini or Midjourney, whose creators have implemented limits on what kind of images they can produce, Stable Diffusion’s model can be downloaded and tweaked by users to generate whatever they want.","u":"https://www.vice.com/en/article/stable-diffusion-stability-ai-nsfw-ai-generated-porn/","d":"2022-08-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-08-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-08-24","organization":"Stability AI","aiSystem":"Stable Diffusion","affectedGroup":"Porn creators","action":"Generate pornographic images","consequence":"Potential exploitation and misuse of AI technology"}},{"i":"R1138","hd":"Is joe biden dead replaced by 10 different deepfake body doubles an investigation","pd":"2022-07-29","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Is joe biden dead replaced by 10 different deepfake body doubles an investigation","s":"A conspiracy theory started on Twitter claims that Joe Biden’s videos are deepfakes. A viral video speculating that Joe Biden is either dead, multiple people, a deepfake, or some combination of all of those has been viewed more than a million times on Twitter. The original post is from the Twitter account for the band Five Times August, led by Dallas-area musician Bradley James Skistimas. The account has 91,000 followers. He posted two pictures of Biden from two different occasions, giving two separate addresses—one about gas prices , and another from remarks given at a conference —next to each other. “Two videos posted within a couple of hours of each other.","u":"https://www.vice.com/en/article/is-joe-biden-dead-replaced-by-10-different-deepfake-body-doubles-an-investigation/","d":"2022-07-29","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-07-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-07-29","organization":"Five Times August (Twitter account)","aiSystem":"Deepfake technology","affectedGroup":"General public, particularly those following Five Times August on Twitter","action":"Posted two images of Joe Biden from different occasions next to each other","consequence":"Viral spread leading to over a million views on Twitter"}},{"i":"R1139","hd":"Racist algorithms are making robots racist too","pd":"2022-07-11","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Racist algorithms are making robots racist too","s":"Researchers show that large AI models are threatening to bring racist and sexist bias into the realm of robotics. There’s now a small library’s worth of evidence that AI systems are biased and tend to replicate harmful racist and sexist stereotypes So it may not shock you to learn that those racist and sexist algorithms can be used to make racist and sexist robots. That’s according to a new paper from researchers at Johns Hopkins University and Georgia Tech, who trained a virtual robot to interact with physical objects using a widely-used AI language model. The robot was presented with objects adorned with pictures of human faces of different races and genders, then given tasks to complete that involve manipulating the objects.","u":"https://www.vice.com/en/article/racist-algorithms-are-making-robots-racist-too/","d":"2022-07-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-07-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-07-11","organization":"Johns Hopkins University and Georgia Tech","aiSystem":"widely-used AI language model","affectedGroup":"virtual robot interacting with physical objects","action":"trained a virtual robot to interact with physical objects","consequence":"the robot was presented with objects adorned with pictures of human faces of different races and genders, then given tasks to complete that involve manipulating the objects"}},{"i":"R1140","hd":"Deepfakes might be used in remote job interviews FBI warns","pd":"2022-07-01","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Deepfakes might be used in remote job interviews fbi warns","s":"The FBI said in an announcement that it has received complaints of people deepfaking their way into job interviews. If you’re interviewing someone for a job online, make sure you are paying attention to see if the person’s words line up with their lip movements. According to the FBI, people have reported suspicious online interviews, and believe they could be deepfakes. The FBI Internet Crime Complaint Center (IC3) released a public service announcement on Tuesday, warning of “an increase in complaints reporting the use of deepfakes and stolen Personally Identifiable Information (PII) to apply for a variety of remote work and work-at-home positions.”","u":"https://www.vice.com/en/article/deepfakes-might-be-used-in-remote-job-interviews-fbi-warns/","d":"2022-07-01","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-07-01","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-07-01","organization":"FBI (Federal Bureau of Investigation)","aiSystem":"AI-generated deepfake technology","affectedGroup":"Job applicants","action":"Deepfake technology used to impersonate job candidates during online interviews","consequence":"Potential for fraud and misrepresentation in remote job applications"}},{"i":"R1144","hd":"AI trained on 4chan becomes hate speech machine","pd":"2022-06-07","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Ai trained on 4chan becomes hate speech machine","s":"After 24 hours, the nine bots running on 4chan had posted 15,000 times. AI researcher and YouTuber Yannic Kilcher trained an AI using 3.3 million threads from 4chan’s infamously toxic Politically Incorrect /pol/ board. He then unleashed the bot back onto 4chan with predictable results—the AI was just as vile as the posts it was trained on, spouting racial slurs and engaging with antisemitic threads. After Kilcher posted his video and a copy of the program to Hugging Face, a kind of GitHub for AI, ethicists and researchers in the AI field expressed concern. The bot, which Kilcher called GPT-4chan, “the most horrible model on the internet”—a reference to GPT-3, a language model developed by Open AI that uses deep learning to produce text—was shockingly effective and replicated the tone and feel of 4chan posts.","u":"https://www.vice.com/en/article/ai-trained-on-4chan-becomes-hate-speech-machine/","d":"2022-06-07","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-06-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-06-07","organization":"Yannic Kilcher (AI researcher and YouTuber)","aiSystem":"GPT-4chan","affectedGroup":"users of 4chan","action":"AI generated and posted hateful content","consequence":"repetition of toxic language and engagement with antisemitic content"}},{"i":"R1145","hd":"Ethical deepfakes deep tom cruise AI generated porn","pd":"2022-05-17","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.8  Interpersonal / relational harm"],"t":"Ethical deepfakes deep tom cruise ai generated porn","s":"The ‘ethical’ AI company that made the viral deepfake of Tom Cruise is tied to non-consensual AI-generated porn. Last year, a shockingly convincing deepfake video of Tom Cruise went viral on TikTok, quickly gaining more than 100 million views. The virality of “DeepTomCruise” led the video’s creator, Chris Umé, to cofound an “ethical” AI-generated content company called Metaphysic, which raised $7.5 million from Logan Paul, Winklevoss Capital, and other venture capital firms. Metaphysic’s goal is not only to create profitable, commercial deepfake content for clients like Gillette , but to actively move deepfake technology away from its heinous origins in the world of non-consensual pornography.","u":"https://www.vice.com/en/article/ethical-deepfakes-deep-tom-cruise-ai-generated-porn/","d":"2022-05-17","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-05-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-05-17","organization":"Metaphysic (an ethical AI-generated content company)","aiSystem":"AI-generated content technology","affectedGroup":"Individuals involved in non-consensual porn production","action":"Created and distributed non-consensual AI-generated porn","consequence":"Potential exploitation and violation of consent"}},{"i":"R1146","hd":"Face swap app on apple app store google play deepfakes","pd":"2022-05-10","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.8  Interpersonal / relational harm"],"t":"Face swap app on apple app store google play deepfakes","s":"A loophole in the Apple and Google app store policies allows a deepfake app to invite customers to make non-consensual porn, without getting banned. On the Google Play and Apple App stores, FaceMagic is pitched as a fun and harmless face swapping app: “Do you want to see your best friend, colleague, or boss dancing? Or do you want to morph your face into celebrities?” the app description says on the Google Play and Apple App stores, alongside a video that shows how users can face swap anyone into a video of Robert Downey Jr.’s Iron Man or basketball player Steph Curry. But on porn tube sites, ads for FaceMagic have a more nefarious pitch.","u":"https://www.vice.com/en/article/face-swap-app-on-apple-app-store-google-play-deepfakes/","d":"2022-05-10","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-05-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-05-10","organization":"Apple and Google app stores, FaceMagic","aiSystem":"FaceMagic face swapping app","affectedGroup":"Customers, friends, colleagues, bosses, celebrities","action":"Users can face swap anyone into videos of public figures","consequence":"Non-consensual porn production"}},{"i":"R1147","hd":"Facebooks new AI system has a high propensity for racism and bias","pd":"2022-05-09","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Facebooks new ai system has a high propensity for racism and bias","s":"The company’s AI researchers say its new language model is generating ‘toxic’ results that often reinforce stereotypes. Facebook and its parent company, Meta, recently released a new tool that can be used to quickly develop state-of-the-art AI. But according to the company’s researchers, the system has the same problem as its predecessors: It’s extremely bad at avoiding results that reinforce racist and sexist stereotypes. The new system, called OPT-175B, is a kind of template known as a large language model, a collection of pre-trained components that are increasingly used in machine-learning tools that process human language.","u":"https://www.vice.com/en/article/facebooks-new-ai-system-has-a-high-propensity-for-racism-and-bias/","d":"2022-05-09","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-05-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-05-09","organization":"Facebook (Meta)","aiSystem":"OPT-175B large language model","affectedGroup":"People","action":"Generating language results","consequence":"Reinforcement of racist and sexist stereotypes"}},{"i":"R118","hd":"Chatgpt lawsuit claims it advised a shooter on how and where to strike","pd":"2026-04-22","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm","1.4  Malicious use harm"],"t":"Chatgpt lawsuit claims it advised a shooter on how and where to strike","s":"Florida’s attorney general claims ChatGPT advised the FSU shooter on what gun to use, which ammo to buy, and when to strike. OpenAI says the chatbot did nothing wrong. Florida’s attorney general has launched a criminal investigation into OpenAI, alleging that ChatGPT helped plan the mass shooting at Florida State University that killed two people last year. According to The Washington Post , Attorney General James Uthmeier made the announcement at a news conference on Tuesday, claiming the chatbot gave tactical advice to the suspected shooter. “The chatbot advised the shooter on what type of gun to use, on which ammo went with which gun, on whether or not a gun would be useful at short range,” Uthmeier said.","u":"https://www.digitaltrends.com/computing/chatgpt-lawsuit-claims-it-advised-a-shooter-on-how-and-where-to-strike/","d":"2026-04-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022","organization":"OpenAI","aiSystem":"ChatGPT","affectedGroup":"FSU shooter","action":"provided tactical advice","consequence":"planned mass shooting resulting in fatalities"}},{"i":"R283","hd":"Zoom can train AI on your videos what you need to know","pd":"2023-08-11","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"Zoom can train ai on your videos what you need to know","s":"Zoom’s AI features were trained on user content, but the company has backpedaled following user backlash. Like everyone else, Zoom has added AI features to improve its app and videoconferencing service. We all love the ease and speed AI provides, but there are often concerns about the data used to train models, and Zoom has been at the center of the controversy. It’s backpedaling now, saying it won’t use user content to train its AI models. News leaked in May 2022 that Zoom was working on emotion-sensing AI that could analyze faces in meetings. Beyond the potential for inaccurate analysis, the results could be discriminatory.","u":"https://www.digitaltrends.com/computing/zoom-can-train-ai-on-your-videos-what-you-need-to-know/","d":"2023-08-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-08-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-05-01","organization":"Zoom","aiSystem":"Zoom's AI features","affectedGroup":"Users of Zoom","action":"AI features were trained on user content","consequence":"Potential for inaccurate analysis and discriminatory results"}},{"i":"R408","hd":"Texas bitcoin mines data centers power grid demand","pd":"2024-07-15","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Texas bitcoin mines data centers power grid demand","s":"This story was originally published by Inside Climate News and is reproduced here as part of the Climate Desk collaboration. Cheryl Shadden cannot sleep. The 61-year-old nurse, who works at hospitals giving patients anesthesia, says she is kept up at night by the nonstop mechanical whir of fans spinning to cool tens of thousands of computers. Shadden lives in […]. Shadden lives in Granbury, Texas, about 40 miles southwest of Fort Worth, with her seven dogs, six horses, six cats and a parrot. In 2022, after 23 years in the area, Shadden got a new neighbor: a 300-megawatt Bitcoin facility, referred to as a “mine,” where computers run around the clock to help maintain a global network of transactions in the cryptocurrency.","u":"https://www.motherjones.com/politics/2024/07/texas-bitcoin-mines-data-centers-power-grid-demand/","d":"2024-07-15","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-07-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022","organization":"Not specified in report","aiSystem":"Bitcoin mining facility","affectedGroup":"Cheryl Shadden, residents of Granbury, Texas","action":"Computers running continuously to support Bitcoin transactions","consequence":"Disrupted sleep due to noise from cooling fans"}},{"i":"R413","hd":"AI artificial intelligence carbon footprint climate change data centers electricity consumption","pd":"2024-02-19","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Ai artificial intelligence carbon footprint climate change data centers electricity consumption","s":"This story was originally published by Yale E360 and is reproduced here as part of the Climate Desk collaboration. Two months after its release in November 2022, OpenAI’s ChatGPT had 100 million active users, and suddenly tech corporations were racing to offer the public more “generative AI” Pundits compared the new technology’s impact to the Internet, or electrification, or the […]. Two months after its release in November 2022, OpenAI’s ChatGPT had 100 million active users, and suddenly tech corporations were racing to offer the public more “generative AI” Pundits compared the new technology’s impact to the Internet, or electrification, or the Industrial Revolution—or the discovery of fire Time will sort hype from reality, but one consequence of the explosion of artificial intelligence is clear: this technology’s environmental footprint is large and growing.","u":"https://www.motherjones.com/environment/2024/02/ai-artificial-intelligence-carbon-footprint-climate-change-data-centers-electricity-consumption/","d":"2024-02-19","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-02-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-11-01","organization":"Tech Corporations","aiSystem":"OpenAI's ChatGPT","affectedGroup":"Public","action":"Tech corporations offering more 'generative AI'","consequence":"Large and growing environmental footprint of AI technology"}},{"i":"R421","hd":"What did the irs want with your selfies","pd":"2022-02-08","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior","Data"],"h":["4.2  Surveillance harm","1.6  Quality of service harm"],"t":"What did the irs want with your selfies","s":"Facing mounting bipartisan pressure, the Internal Revenue Service announced yesterday that it’s walking back plans to deploy facial recognition software to identify taxpayers. In November, the IRS signed an $86 million contract with identity verification startup ID.me, announcing that it would require taxpayers to provide personal, identifying materials, including selfies, to access their tax records. […]. Privacy and civil rights advocates responded immediately, forming a coalition of close to 20 groups —from the National Lawyers Guild to the Council on American-Islamic Relations—that criticized the “destructive results of facial recognition technology…from police using it to track Black Lives Matter protesters, to wrongful arrests , to manipulative marketing .”","u":"https://www.motherjones.com/mojo-wire/2022/02/what-did-the-irs-want-with-your-selfies/","d":"2022-02-08","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-02-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-02-08","organization":"Internal Revenue Service (IRS)","aiSystem":"Facial recognition software","affectedGroup":"Taxpayers","action":"Announced plans to deploy facial recognition software to identify taxpayers","consequence":"Privacy concerns and criticism from civil rights advocates"}},{"i":"R575","hd":"Artificial intelligence transforming lives neurodivergent people","pd":"2025-07-28","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Artificial intelligence transforming lives neurodivergent people","s":"AI-powered chatbots emerge as an unlikely ally, helping people navigate social encounters with real-time guidance. Although this new technology is not without risks, many neurodivergent users now see it as a lifeline. For Cape Town-based filmmaker Kate D’hotman, connecting with movie audiences comes naturally. Far more daunting is speaking with others. “I’ve never understood how people [decipher] social cues,” the 40-year-old director of horror films says. D’hotman has autism and attention-deficit hyperactivity disorder (ADHD), which can make relating to others exhausting and a challenge. However, since 2022, D’hotman has been a regular user of ChatGPT, the popular AI-powered chatbot from OpenAI, relying on it to overcome communication barriers at work and in her personal life.","u":"https://www.rappler.com/technology/features/artificial-intelligence-transforming-lives-neurodivergent-people/","d":"2025-07-28","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-01-01","organization":"OpenAI","aiSystem":"ChatGPT, AI-powered chatbot","affectedGroup":"neurodivergent people, particularly those with autism and ADHD","action":"using ChatGPT to overcome communication barriers","consequence":"improved ability to navigate social encounters and communicate effectively"}},{"i":"R800","hd":"Intel introduces real time deepfake detector fakecatcher","pd":"2022-11-17","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Intel introduces real time deepfake detector fakecatcher","s":"Intel’s FakeCatcher looks at blood flow in video pixels to see if a person in a video is real or not. MANILA, Philippines – Intel on Monday, November 14, introduced new software that is purportedly able to identify deepfake videos in real-time. The company claims it’s the world’s first real-time deepfake detector, able to return results in milliseconds with an accuracy rate of 96%. Deepfakes are videos that make use of AI to convincingly mimic another person’s face to make it appear they are the one saying or doing something. Intel’s deepfake detection platform is called FakeCatcher, developed by Ilke Demir, senior staff research scientist in Intel Labs, in collaboration with Umur Ciftci from the State University of New York at Binghamton.","u":"https://www.rappler.com/technology/intel-introduces-real-time-deepfake-detector-fakecatcher/","d":"2022-11-17","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-11-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-11-14","organization":"Intel","aiSystem":"FakeCatcher","affectedGroup":"Deepfake videos","action":"Identify and detect deepfake videos in real-time","consequence":"Potential misuse of deepfake videos"}},{"i":"R863","hd":"Meta facebook terrorism censorship speech","pd":"2024-12-04","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior","Data"],"h":["4.2  Surveillance harm","1.6  Quality of service harm"],"t":"Meta facebook terrorism censorship speech","s":"Hannah Byrne joined Facebook to combat far-right extremism. She’s now convinced the tech giant can’t be trusted with such power. For two years , Hannah Byrne was part of an invisible machine that determines what over 3 billion people around the world can say on the internet. From her perch within Meta’s Counterterrorism and Dangerous Organizations team, Byrne helped craft one of the most powerful and secretive censorship policies in internet history. Her work adhered to the basic tenet of content moderation: Online speech can cause offline harm. Stop the bad speech — or bad speakers — and you have perhaps saved a life.","u":"https://theintercept.com/2024/12/04/meta-facebook-terrorism-censorship-speech/","d":"2024-12-04","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-12-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-01-01","organization":"Meta (Facebook)","aiSystem":"AI-driven content moderation system","affectedGroup":"Over 3 billion internet users worldwide","action":"Crafted and implemented a powerful censorship policy","consequence":"Potential misuse of power leading to offline harm"}},{"i":"R900","hd":"Openai chatgpt AI bias ethics","pd":"2022-12-08","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Openai chatgpt ai bias ethics","s":"ChatGPT, the latest novelty from OpenAI, replicates the ugliest war on terror-style racism. A DALL-E generation of “an oil painting of America’s war on terror if conducted by an artificial intelligence.” Image: Elise Swain/The Intercept; DALL-E Sensational new machine learning breakthroughs seem to sweep our Twitter feeds every day. We hardly have time to decide whether software that can instantly conjure an image of Sonic the Hedgehog addressing the United Nations is purely harmless fun or a harbinger of techno-doom. ChatGPT, the latest artificial intelligence novelty act, is easily the most impressive text-generating demo to date.","u":"https://theintercept.com/2022/12/08/openai-chatgpt-ai-bias-ethics/","d":"2022-12-08","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-12-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-12-08","organization":"OpenAI","aiSystem":"ChatGPT, an AI language model","affectedGroup":"general public, users of AI-generated content","action":"generates text","consequence":"replicates racist imagery and rhetoric"}},{"i":"R901","hd":"CIA google content moderation trust lab","pd":"2022-12-02","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Cia google content moderation trust lab","s":"Trust Lab, founded by a former Google exec for content moderation, will identify “online harmful content, including toxicity and misinformation.” Trust Lab was founded by a team of well-credentialed Big Tech alumni who came together in 2021 with a mission: Make online content moderation more transparent, accountable, and trustworthy. A year later, the company announced a “strategic partnership” with the CIA’s venture capital firm. Trust Lab’s basic pitch is simple: Globe-spanning internet platforms like Facebook and YouTube so thoroughly and consistently botch their content moderation efforts that decisions about what speech to delete ought to be turned over to completely independent outside firms — firms like Trust Lab.","u":"https://theintercept.com/2022/12/02/cia-google-content-moderation-trust-lab/","d":"2022-12-02","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2022-12-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-12-02","organization":"Trust Lab (founded by a former Google exec)","aiSystem":"AI-based content moderation systems on social media platforms","affectedGroup":"Online users and content creators","action":"Identify and flag 'online harmful content, including toxicity and misinformation'","consequence":"Potential misalignment between AI-driven content moderation and human judgment, leading to biased or incomplete content removal decisions"}},{"i":"R903","hd":"Police surveillance shotspotter detroit","pd":"2022-09-17","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior","Data"],"h":["4.2  Surveillance harm","1.6  Quality of service harm"],"t":"Police surveillance shotspotter detroit","s":"The company behind the mics, ShotSpotter, is going all out to guide police stations across the country on how to use relief money for the controversial technology. Detroit’s city council will soon vote on whether to spend millions in federal cash meant to ease the economic pains of the coronavirus pandemic on ShotSpotter, a controversial surveillance technology critics say is invasive, discriminatory, and fundamentally broken. ShotSpotter purports to do one thing very well: telling cops a gun has been fired as soon as the trigger is pulled. Using a network of microphones hitched to telephone poles, rooftops, and other urban vantage points, ShotSpotter is essentially an Alexa that listens for a bang rather than voice commands.","u":"https://theintercept.com/2022/09/17/police-surveillance-shotspotter-detroit/","d":"2022-09-17","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-09-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-09-17","organization":"ShotSpotter","aiSystem":"ShotSpotter","affectedGroup":"Police Departments, Citizens","action":"Deploying ShotSpotter surveillance technology","consequence":"Potential misuse leading to invasions of privacy, discrimination, and inefficiency"}},{"i":"R908","hd":"Clearview face recognition staten island","pd":"2022-05-04","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm","4.3  Data rights / consent violation"],"t":"Clearview face recognition staten island","s":"Clearview and its right-wing founder have become emblematic of the threat posed by powerful and typically unsupervised software. The Staten Island district attorney’s use of the highly controversial Clearview face recognition system included attempts to dig up the social media accounts of homicide victims and was paid for with equally controversial asset forfeiture cash, according to city records provided to The Intercept. Clearview has garnered international attention and intense criticism for its simple premise: What if you could instantly identify anyone in the world with only their picture? Using billions of images scraped from social media sites, Clearview sells police and other governmental agencies the ability to match a photo to a name using face recognition, no search warrant required — a power civil libertarians and privacy advocates say simply places too much unsupervised…","u":"https://theintercept.com/2022/05/04/clearview-face-recognition-staten-island/","d":"2022-05-04","e":"Acute, Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-05-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-05-04","organization":"Staten Island district attorney's office, Clearview AI","aiSystem":"Clearview face recognition system","affectedGroup":"Homicide victims, individuals whose social media accounts were accessed","action":"Used Clearview face recognition system to access social media accounts of homicide victims","consequence":"Potential misuse of personal information, invasion of privacy"}},{"i":"R1029","hd":"Child sex abuse material was found in a major AI dataset researchers arent surprised","pd":"2023-12-20","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior","Data"],"h":["4.3  Data rights / consent violation","1.8  Interpersonal / relational harm"],"t":"Child sex abuse material was found in a major ai dataset researchers arent surprised","s":"The LAION-5B dataset is the basis for numerous AI models. Researchers have long warned that massive training datasets are poorly audited. Over 1,000 images of sexually abused children have been discovered inside the largest dataset used to train image-generating AI, shocking everyone except for the people who have warned about this exact sort of thing for years. The dataset was created by LAION, a non-profit organization behind the massive image datasets used by generative AI systems like Stable Diffusion. Following a report from researchers at Stanford University, 404 Media reported that LAION confirmed the presence of child sexual abuse material (CSAM) in the dataset, called LAION-5B, and scrubbed it from their online channels.","u":"https://www.vice.com/en/article/child-sex-abuse-material-was-found-in-a-major-ai-dataset-researchers-arent-surprised/","d":"2023-12-20","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-12-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-12-20","organization":"LAION, a non-profit organization","aiSystem":"Generative AI systems like Stable Diffusion","affectedGroup":"Sexually abused children","action":"AI-generated images of sexually abused children were discovered","consequence":"The images were removed from LAION's online channels"}},{"i":"R1032","hd":"Elon musks grok AI is pushing misinformation and legitimizing conspiracies","pd":"2023-12-08","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Elon musks grok ai is pushing misinformation and legitimizing conspiracies","s":"Grok’s selling point is real-time access to news, but Motherboard found that it generated inaccurate information about Israel-Palestine and lent credence to conspiracy theories. Elon Musk released Grok to X premium subscribers on Friday, giving paid users of the website formally known as Twitter their first look at the billionaire’s much-hyped entry into the AI race. The chatbot’s big selling point is that it is designed to integrate with X and draw information from users’ posts in order to have access to real-time events around the world. But, perhaps unsurprisingly, the chatbot is just as reliable at giving accurate information as the once-cherished platform formerly known as Twitter and its right-wing billionaire owner—which is to say, not at all The chatbot produced fake timelines for news events and misinformation when tested by Motherboard, and lent credence to conspiracy theories…","u":"https://www.vice.com/en/article/elon-musks-grok-ai-is-pushing-misinformation-and-legitimizing-conspiracies/","d":"2023-12-08","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-12-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-12-08","organization":"Elon Musk's company (not explicitly named)","aiSystem":"Grok chatbot","affectedGroup":"general public, particularly those using Twitter","action":"generated fake timelines for news events and misinformation","consequence":"lent credence to conspiracy theories, spread misinformation"}},{"i":"R1034","hd":"The LAPD is using controversial mass surveillance tracking software","pd":"2023-11-29","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"The lapd is using controversial mass surveillance tracking software","s":"Cobwebs Technologies’ WebLoc software allows police to track individuals using geolocation signals displayed on a map interface. The LAPD has purchased controversial mass surveillance software that allows police to track individuals using geolocation data. The company that provides the software, called WebLoc, is Cobwebs Technologies The Israeli company was founded by three IDF veterans in 2015 and has previously sold contracts to the IRS and the Texas State Police Each contract costs around $200,000 per year. The LAPD’s contract with Cobwebs Technology was revealed in a report from Knock LA , which obtained documents via freedom of information requests.","u":"https://www.vice.com/en/article/the-lapd-is-using-controversial-mass-surveillance-tracking-software/","d":"2023-11-29","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-11-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-11-29","organization":"LAPD (Los Angeles Police Department)","aiSystem":"WebLoc software","affectedGroup":"Individuals","action":"Track individuals using geolocation signals displayed on a map interface","consequence":"Potential privacy invasion, misuse of public data"}},{"i":"R1035","hd":"Chatgpt can reveal personal information from real people google researchers show","pd":"2023-11-29","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Chatgpt can reveal personal information from real people google researchers show","s":"The popular AI chatbot is divulging sensitive information from its training data, according to a team of researchers at Google. A team of Google researchers have unveiled a novel attack on ChatGPT, showing that OpenAI’s popular AI chatbot will divulge personal information from real people. The underlying machine learning model that powers ChatGPT, like all so-called Large Language Models (LLMs), was trained on massive amounts of data scraped from the internet. With training and reinforcement from humans, the program ideally generates new strings of texts without churning out any of the original text it ingested. Previous work has already shown that image generators can be forced to generate examples from their training data—including copyrighted works —and an early OpenAI LLM produced contact information belonging to a researcher.","u":"https://www.vice.com/en/article/chatgpt-can-reveal-personal-information-from-real-people-google-researchers-show/","d":"2023-11-29","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-11-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-11-29","organization":"Google","aiSystem":"ChatGPT","affectedGroup":"Real People","action":"divulged personal information","consequence":"potential privacy infringement"}},{"i":"R1037","hd":"NYC mayor casually announces hes deepfaking himself experts horrified","pd":"2023-10-17","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Nyc mayor casually announces hes deepfaking himself experts horrified","s":"Eric Adams is using AI to make New Yorkers think he speaks their language, which experts called “Orwellian.” New York City Mayor Eric Adams has been making audio deepfakes of himself to speak to New Yorkers in different languages. At a press conference Monday that was meant to brief reporters on a recent “chatbot forum” at City Hall, Adams let slip that his office has been robo-calling New Yorkers with an algorithmically-generated version of his voice speaking in different languages that the mayor does not speak. The purpose of the Monday press conference was to announce the city’s impending use of “AI” voice chatbots that will speak to New Yorkers in their language of choice when they call 311 or other services, but the mayor casually mentioned that the city has already been deploying the technology for other purposes, and that New Yorkers are already being misled about the range of…","u":"https://www.vice.com/en/article/nyc-mayor-casually-announces-hes-deepfaking-himself-experts-horrified/","d":"2023-10-17","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-10-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-10-17","organization":"New York City Mayor's Office","aiSystem":"AI voice chatbots","affectedGroup":"New York City residents","action":"Adams' office robo-called New Yorkers with an algorithmically-generated version of his voice speaking in different languages","consequence":"Misleading New Yorkers about the range of languages the city's AI voice chatbots can speak"}},{"i":"R1039","hd":"Metas AI stickers wa","pd":"2023-10-04","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Metas ai stickers wa","s":"The fun is guaranteed not to last. Meta has started slowly rolling out its new AI-generated stickers for Messenger, and the results so far are totally unhinged. The company, which owns Facebook, Instagram, and WhatsApp, announced that it would be introducing AI tools to Messenger last week, starting with a limited rollout in the US. On Tuesday night, examples of the kinds of stickers the AI tool generates based on user prompts went viral, and it’s easy to see why. Montreal-based artist Pier-Olivier Desbiens posted a few examples, and they include: Nintendo character Waluigi holding a rifle, a Mickey Mouse-toilet hybrid, child soldiers, a nude Justin Trudeau bending over, and a busty Karl Marx wearing a dress.","u":"https://www.vice.com/en/article/metas-ai-stickers-wa/","d":"2023-10-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-10-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-10-04","organization":"Meta (Facebook, Instagram, WhatsApp)","aiSystem":"AI sticker generator","affectedGroup":"general public, social media users","action":"AI-generated stickers were created based on user prompts","consequence":"Generated content included inappropriate and offensive images"}},{"i":"R1040","hd":"The hollywood writers strike is over and yes studios can use AI","pd":"2023-09-27","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"The hollywood writers strike is over and yes studios can use ai","s":"The tentative agreement states that studios can present AI-generated material to writers, but it will not affect their pay or credit. The Writers’ Guild of America reached a tentative agreement with production studios on Sunday, bringing the 148-day-long film and TV writers’ strike to an end on Wednesday as members will soon begin to vote on ratification. A summary of the union’s new Minimum Basic Agreement (MBA) with the Alliance of Motion Picture and Television Producers was released late Tuesday night , and the strike officially ended at 12:01 a.m. on Wednesday morning. “We can say, with great pride, that this deal is exceptional—with meaningful gains and protections for writers in every sector of the membership,” the WGA said in a statement when the tentative agreement was announced.","u":"https://www.vice.com/en/article/the-hollywood-writers-strike-is-over-and-yes-studios-can-use-ai/","d":"2023-09-27","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-09-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-09-27","organization":"Writers' Guild of America","aiSystem":"AI-generated content","affectedGroup":"Film and TV writers","action":"Studios can present AI-generated material to writers","consequence":"No impact on writers' pay or credit"}},{"i":"R1042","hd":"Openai says authors chatgpt copyright claims defective in motion to dismiss","pd":"2023-08-30","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Openai says authors chatgpt copyright claims defective in motion to dismiss","s":"The firm behind ChatGPT is asking a court to dismiss all but one of authors’ claims in lawsuits alleging AI outputs infringe their copyright. As AI tools become more commonplace, lawsuits centering around the training data used to create machine learning models are piling up. Now, OpenAI, the company behind the popular ChatGPT text-generation tool and underlying models, has moved to dismiss most of the claims against it in lawsuits filed by authors who allege that AI outputs infringe on their copyright. The machine learning models that power ChatGPT, such as GPT-4, are trained on massive amounts of data scraped from the internet.","u":"https://www.vice.com/en/article/openai-says-authors-chatgpt-copyright-claims-defective-in-motion-to-dismiss/","d":"2023-08-30","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-08-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-08-30","organization":"OpenAI","aiSystem":"ChatGPT and underlying machine learning models (e.g., GPT-4)","affectedGroup":"Authors of copyrighted works","action":"Alleged infringement of copyright on AI-generated content","consequence":"Court motions to dismiss most claims, leaving one claim intact"}},{"i":"R1043","hd":"Zoom changes tos to say it wont train AI on your calls without your consent after backlash","pd":"2023-08-07","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"Zoom changes tos to say it wont train ai on your calls without your consent after backlash","s":"Zoom added a line to its terms of use on Monday, after concerns that the company was using calls to train artificial intelligence algorithms went viral. After a public outcry, on Monday video conferencing platform Zoom changed its terms of service to try to quell fears that people’s video and audio are being used to train artificial intelligence algorithms. On Sunday, people started posting screenshots of a portion of Zoom’s terms of use that states users consent to the company’s use, collection, and storage of “service generated data” for any purpose, including for “training and tuning of algorithms and models.”","u":"https://www.vice.com/en/article/zoom-changes-tos-to-say-it-wont-train-ai-on-your-calls-without-your-consent-after-backlash/","d":"2023-08-07","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-08-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-08-07","organization":"Zoom Video Communications Inc.","aiSystem":"Artificial Intelligence Algorithms","affectedGroup":"Individuals whose video and audio are recorded during Zoom calls","action":"Zoom added a clause to its terms of use allowing the company to use, collect, and store 'service generated data' for training and tuning of algorithms and models","consequence":"Potential misuse of user data for AI training without explicit consent"}},{"i":"R1044","hd":"Amazon told drivers not to worry about in van surveillance cameras now footage is leaking online","pd":"2023-07-17","k":"United States of America","p":"United States of America","b":["Data","Labor"],"h":["4.2  Surveillance harm","3.2  Algorithmic management harm"],"t":"Amazon told drivers not to worry about in van surveillance cameras now footage is leaking online","s":"Numerous posts on Reddit show surveillance videos of drivers’ actions on the road, but such recordings haven’t been posted so frequently before. A phone-recorded video posted to Reddit shows a wooden desk strewn with various office supplies. On a monitor on the desk, a video begins to play: an Amazon delivery driver, being recorded by a driver-facing camera in their van, leans out of their window to talk to a customer. Though the video is cute, the setup is not: The camera’s AI tracks their movements, surrounding them with a bright green box. Below them on the monitor’s screen, a yellow line marks the length of the clip sent to the driver’s dispatcher.","u":"https://www.vice.com/en/article/amazon-told-drivers-not-to-worry-about-in-van-surveillance-cameras-now-footage-is-leaking-online/","d":"2023-07-17","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-07-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-07-17","organization":"Amazon","aiSystem":"AI-powered surveillance system","affectedGroup":"Amazon delivery drivers","action":"AI tracking and monitoring of drivers' movements","consequence":"Surveillance footage misuse and public dissemination"}},{"i":"R1046","hd":"Openai and microsoft sued for dollar3 billion over alleged chatgpt privacy violations","pd":"2023-06-29","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"Openai and microsoft sued for dollar3 billion over alleged chatgpt privacy violations","s":"The lawsuit claimed that OpenAI secretly “scraped 300 billion words from the internet.” On Wednesday, OpenAI and Microsoft were sued in a class action lawsuit seeking $3 billion in damages for allegedly stealing “vast amounts of private information” from internet users without consent in order to train ChatGPT. This lawsuit, which was filed on June 28 in federal court in San Francisco, CA, and includes sixteen anonymous plaintiffs, claimed that OpenAI secretly “scraped 300 billion words from the internet” without registering as a data broker or obtaining consent. Microsoft is OpenAI’s main customer and corporate partner, licensing AI technology from the company for billions of dollars.","u":"https://www.vice.com/en/article/openai-and-microsoft-sued-for-dollar3-billion-over-alleged-chatgpt-privacy-violations/","d":"2023-06-29","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-06-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-06-28","organization":"OpenAI and Microsoft","aiSystem":"ChatGPT","affectedGroup":"Internet users","action":"Secretly scraped 300 billion words from the internet without consent","consequence":"Alleged theft of vast amounts of private information"}},{"i":"R1048","hd":"AI artist creates satanic panic about hobby lobby","pd":"2023-06-15","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Ai artist creates satanic panic about hobby lobby","s":"Pictures of Baphomet statues on sale at the Christian craft store vent Viral on Facebook as some called for a boycott. People on social media are sharing pictures of what they think are Satanic-seeming displays from Hobby Lobby stores and vowing never to shop there again much like many people refuse to drink Bud Light or shop at Target for bigoted reasons. Aside from the fact that Americans are currently eager to boycott any company that feigns tolerance at marginalized people, there’s one big problem with these Hobby Lobby store pictures: They’re not real. These pictures of Satanic merchandise on the shelves of Hobby Lobby were made by Jennifer Vinyard using the AI image generating tool Midjourney.","u":"https://www.vice.com/en/article/ai-artist-creates-satanic-panic-about-hobby-lobby/","d":"2023-06-15","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-06-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-06-15","organization":"Hobby Lobby","aiSystem":"Midjourney AI image generating tool","affectedGroup":"Customers of Hobby Lobby and social media users","action":"Sharing pictures of AI-generated Satanic merchandise on social media","consequence":"Potential boycott of Hobby Lobby and negative impact on customers' trust"}},{"i":"R1049","hd":"The defense department now has GPT 4 thanks to microsoft","pd":"2023-06-07","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.2  Military decision support harm"],"t":"The defense department now has gpt 4 thanks to microsoft","s":"The Department of Defense, the Department of Energy, and NASA are among some of Azure Government’s customers. On Wednesday, Microsoft announced it will now offer U.S. government departments access to its artificial intelligence models, such as OpenAI’s GPT-4. As stated in a blog post by Microsoft , its Azure OpenAI Service will now help Azure Government customers accelerate content generation, create summaries of reports and logs, optimize search, and simplify code. “Many agencies require a higher level of security given the sensitivity of government data. Microsoft Azure Government provides the stringent security and compliance standards they need to meet government requirements for sensitive data,” the blog post reads.","u":"https://www.vice.com/en/article/the-defense-department-now-has-gpt-4-thanks-to-microsoft/","d":"2023-06-07","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-06-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-06-07","organization":"Microsoft Azure Government","aiSystem":"GPT-4 (and other OpenAI models)","affectedGroup":"U.S. government departments","action":"Offering access to Azure OpenAI Service","consequence":"Potential misuse for content generation, summary creation, search optimization, and code simplification"}},{"i":"R1051","hd":"Judge bans AI generated filings in court because it just makes stuff up","pd":"2023-06-01","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"Judge bans ai generated filings in court because it just makes stuff up","s":"Chatbots often make stuff up and reproduce human biases. A district judge in Texas released an order on Tuesday that banned the usage of generative artificial intelligence to write court filings without a human fact-check as the technology becomes more common in legal settings despite its well-documented shortcomings, such as making things up. “All attorneys appearing before the Court must file on the docket a certificate attesting either that no portion of the filing was drafted by generative artificial intelligence (such as ChatGPT, Harvey.AI, or Google Bard) or that any language drafted by generative artificial intelligence was checked for accuracy, using print reporters or traditional legal databases, by a human being,” the order by Judge Brantley Starr stated.","u":"https://www.vice.com/en/article/judge-bans-ai-generated-filings-in-court-because-it-just-makes-stuff-up/","d":"2023-06-01","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-06-01","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-06-01","organization":"Court of Texas","aiSystem":"generative artificial intelligence","affectedGroup":"Attorneys appearing before the Court","action":"Banned the usage of generative artificial intelligence to write court filings","consequence":"Must file a certificate attesting to the origin of the content"}},{"i":"R1052","hd":"Eating disorder helpline fires staff transitions to chatbot after unionization","pd":"2023-05-25","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior","Labor"],"h":["1.6  Quality of service harm","3.3  Employment displacement / quality harm"],"t":"Eating disorder helpline fires staff transitions to chatbot after unionization","s":"The chatbot is named “Tessa” and will replace the entire Helpline program starting June 1. Executives at the National Eating Disorders Association (NEDA) decided to replace hotline workers with a chatbot named Tessa four days after the workers unionized. NEDA, the largest nonprofit organization dedicated to eating disorders, has had a helpline for the last twenty years that provided support to hundreds of thousands of people via chat, phone call, and text. “NEDA claims this was a long-anticipated change and that AI can better serve those with eating disorders. But do not be fooled—this isn’t really about a chatbot.","u":"https://www.vice.com/en/article/eating-disorder-helpline-fires-staff-transitions-to-chatbot-after-unionization/","d":"2023-05-25","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-05-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-05-21","organization":"National Eating Disorders Association (NEDA)","aiSystem":"Tessa (AI chatbot)","affectedGroup":"People seeking support for eating disorders","action":"Replacement of hotline workers with an AI chatbot named Tessa","consequence":"Potential loss of human support services and increased reliance on AI for mental health support"}},{"i":"R1053","hd":"US intelligence building system to track mass movement of people around the world","pd":"2023-05-22","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Us intelligence building system to track mass movement of people around the world","s":"“There’s no such thing as living off the grid,” said one architect of the system, which will use data from internet-connected devices and “smart city” sensors. The Pentagon’s intelligence branch is developing new tech to help it track the mass movement of people around the globe and flag “anomalies.” The project is called the Hidden Activity Signal and Trajectory Anomaly Characterization (HAYSTAC) program and it “aims to establish ‘normal’ movement models across times, locations, and populations and determine what makes an activity atypical,” according to a press release from the Office of the Director of National Intelligence (DNI).","u":"https://www.vice.com/en/article/us-intelligence-building-system-to-track-mass-movement-of-people-around-the-world/","d":"2023-05-22","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-05-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-05-22","organization":"U.S. Department of Defense (Pentagon's intelligence branch)","aiSystem":"AI-powered tracking system","affectedGroup":"Global population","action":"Developing and deploying an AI system to track and identify anomalies in mass human movements","consequence":"Potential misuse for surveillance and monitoring of civilians"}},{"i":"R1054","hd":"Debt collectors want to use AI chatbots to hustle people for money","pd":"2023-05-18","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Debt collectors want to use ai chatbots to hustle people for money","s":"The collections industry is pushing GPT-4 as a dystopian new way to make borrowers pay up, replicating the debt system’s long history of racial bias. An industry historically known for harassing and intimidating people down on their luck is replacing human debt collectors with AI-powered ones, in a move that one company says will “change debt collections forever.” AI tools will take the industry into “ a new era of debt collections ,” according to New York and Bangalore-based Skit.ai. A digital voice agent—the new incarnation of a robocall, using AI chatbots and text-to-speech capabilities for dynamic, responsive conversations—could make millions of outbound calls in just a few days, the company claimed, contacting and requesting payment from a collection agency’s entire portfolio of debtors at a far lower cost than human staff.","u":"https://www.vice.com/en/article/debt-collectors-want-to-use-ai-chatbots-to-hustle-people-for-money/","d":"2023-05-18","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-05-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-05-18","organization":"Skit.ai (New York and Bangalore-based)","aiSystem":"AI chatbots and text-to-speech capabilities","affectedGroup":"Borrowers","action":"Making millions of outbound calls to contact and request payment from a collection agency's debtors","consequence":"Potential increase in harassment and intimidation tactics"}},{"i":"R1055","hd":"DHS uses AI tool babel x babel street social media citizens refugees","pd":"2023-05-17","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Dhs uses ai tool babel x babel street social media citizens refugees","s":"Customs and Border Protection (CBP) is using a tool called Babel X that can link a person’s Social Security number to their social media posts and location data, according to an internal CBP document obtained by Motherboard. Customs and Border Protection (CBP) is using an invasive, AI-powered monitoring tool to screen travelers, including U.S. citizens, refugees, and people seeking asylum, which can in some cases link their social media posts to their Social Security number and location data, according to an internal CBP document obtained by Motherboard The news provides much more detail on how CBP deploys a tool sold widely across the U.S. government. Called Babel X, the system lets a user input a piece of information about a target—their name, email address, or telephone number—and receive a bevy of data in return, according to the document.","u":"https://www.vice.com/en/article/dhs-uses-ai-tool-babel-x-babel-street-social-media-citizens-refugees/","d":"2023-05-17","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-05-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-05-17","organization":"Customs and Border Protection (CBP)","aiSystem":"Babel X","affectedGroup":"U.S. citizens, refugees, and people seeking asylum","action":"Link a person’s Social Security number to their social media posts and location data","consequence":"Potential misuse of personal data for surveillance purposes"}},{"i":"R1056","hd":"Cnet workers unionize as automated technology threatens our jobs","pd":"2023-05-16","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Cnet workers unionize as automated technology threatens our jobs","s":"Around 100 workers have organized in response to the company’s restructuring plans, massive layoffs, and plans for AI content. Around 100 workers are unionizing at CNET , a popular tech news and product review site, in response to a “lack of transparency” from management regarding layoffs and the company’s use of AI, according to an announcement by the union Tuesday. The announcement comes just a few months after journalists at Futurism revealed that CNET had published articles written by AI instead of by its writers—articles which contained a multitude of extremely basic errors —and that it had not properly disclosed that fact to its team.","u":"https://www.vice.com/en/article/cnet-workers-unionize-as-automated-technology-threatens-our-jobs/","d":"2023-05-16","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-05-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-05-16","organization":"CNET (a popular tech news and product review site)","aiSystem":"Automated writing system","affectedGroup":"Journalists at CNET","action":"Published articles written by an AI system","consequence":"Contained numerous basic errors and lack of transparency"}},{"i":"R1057","hd":"Scammer made thousands selling leaked frank ocean tracks that were fake AI generated the line steer it","pd":"2023-05-10","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Scammer made thousands selling leaked frank ocean tracks that were fake ai generated the line steer it","s":"Frank Ocean communities on Discord and leaked music forums were in a frenzy over newly discovered music from the reclusive artist. It turns out most of it was AI-generated and sold by a scammer. A scammer has managed to sell multiple leaked Frank Ocean tracks for thousands of dollars, but the tracks weren’t recorded by the famous R&B singer-songwriter. The tracks were made with AI and sold as leaked tracks on a bustling community of underground music collectors, according to Discord messages and forum posts reviewed by Motherboard, as well as interviews with victims and the scammer themselves. The news shows another example of the seismic impact AI is having on the music industry.","u":"https://www.vice.com/en/article/scammer-made-thousands-selling-leaked-frank-ocean-tracks-that-were-fake-ai-generated-the-line-steer-it/","d":"2023-05-10","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-05-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-05-10","organization":"Scammer","aiSystem":"AI technology","affectedGroup":"Underground music collectors and Frank Ocean fans","action":"Sold AI-generated Frank Ocean tracks for thousands of dollars","consequence":"Financial loss and deception"}},{"i":"R1059","hd":"Senator asks banks stop AI cloned voices","pd":"2023-05-04","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Senator asks banks stop ai cloned voices","s":"The move comes after Motherboard used AI voice cloning technology to fool a bank’s security systems. The chairman of the Senate committee that provides oversight of the banking sector has sent letters to the CEOs of the country’s biggest banks asking what they plan to do about the looming threat of fake voices created with artificial intelligence being used to break into customers’ accounts. The move comes after Motherboard used an AI-powered system to clone a reporter’s voice, and then used that to fool a bank’s voice authentication security system. That investigation showed that just a few minutes of a target’s voice audio was enough to generate a clone that was convincing enough to break into a bank account, potentially putting the public at risk of such attacks, and especially those with a public presence such as politicians, journalists, podcast hosts, streamers, and more.","u":"https://www.vice.com/en/article/senator-asks-banks-stop-ai-cloned-voices/","d":"2023-05-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-05-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-05-04","organization":"Motherboard (media outlet)","aiSystem":"AI-powered voice cloning system","affectedGroup":"banking sector, potential victims including politicians, journalists, podcast hosts, streamers","action":"used an AI-powered system to clone a reporter's voice and fool a bank's voice authentication security system","consequence":"potential risk of fake voice attacks leading to unauthorized access to bank accounts, compromising public safety and privacy"}},{"i":"R1060","hd":"GPT 4 cant replace striking tv writers but studios are going to try","pd":"2023-05-03","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Gpt 4 cant replace striking tv writers but studios are going to try","s":"The desire to replace writers with AI is a symptom of the larger problem that the guild is fighting for—which is that companies do not value writers and their work. The Writers Guild of America is on strike , after six weeks of negotiating with a number of major entertainment companies, including Netflix, Amazon, Apple, and Disney, under the Alliance of Motion Picture and Television Producers (AMPTP). The walkout is the first Hollywood strike to occur in 15 years, and comes at an unprecedented moment—for the first time ever, writers are negotiating the studios’ use of generative AI tools like ChatGPT. The guild called the studios’ responses to their proposal “wholly insufficient given the existential crisis writers are facing,” as guild members walked off the job to join picket lines in Los Angeles and New York.","u":"https://www.vice.com/en/article/gpt-4-cant-replace-striking-tv-writers-but-studios-are-going-to-try/","d":"2023-05-03","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-05-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-05-03","organization":"Major Entertainment Companies (Netflix, Amazon, Apple, Disney)","aiSystem":"Generative AI tools like ChatGPT","affectedGroup":"Writers Guild of America","action":"Negotiating the use of generative AI tools","consequence":"Walkout and picket lines"}},{"i":"R1061","hd":"AI is tearing wikipedia apart","pd":"2023-05-02","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Ai is tearing wikipedia apart","s":"Volunteers who maintain the digital encyclopedia are divided on how to deal with the rise of AI-generated content and misinformation. As generative artificial intelligence continues to permeate all aspects of culture, the people who steward Wikipedia are divided on how best to proceed. During a recent community call , it became apparent that there is a community split over whether or not to use large language models to generate content. While some people expressed that tools like Open AI’s ChatGPT could help with generating and summarizing articles, others remained wary. The concern is that machine-generated content has to be balanced with a lot of human review and would overwhelm lesser-known wikis with bad content.","u":"https://www.vice.com/en/article/ai-is-tearing-wikipedia-apart/","d":"2023-05-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-05-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-05-02","organization":"Wikipedia volunteers and stewards","aiSystem":"large language models (e.g., Open AI's ChatGPT)","affectedGroup":"Wikipedia contributors and users","action":"Discussion about using AI-generated content to create and summarize articles","consequence":"Community division and potential overload of lesser-known wikis with poor-quality content"}},{"i":"R1063","hd":"Landlord software is making life hell for renters report says","pd":"2023-05-01","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Landlord software is making life hell for renters report says","s":"Property technology, or proptech, is allowing big landlords to buy homes at scale, raise rents, and evict tenants remotely. A new report from Tech Equity Collaborative looks at the way that the growing property technology (“proptech”) industry is impacting tenants for the worse. Researchers found that the influence of venture capital in the industry led to worse outcomes for tenants and prospective homeowners. The property technology sector—software that helps companies and landlords purchase real estate, collect rent, screen tenants and more-—has grown enormously in the last decade: according to the report, “Venture capital investment in the space has increased by 53X globally between 2010 and 2021, from $600M to $32B.”","u":"https://www.vice.com/en/article/landlord-software-is-making-life-hell-for-renters-report-says/","d":"2023-05-01","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-05-01","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-05-01","organization":"Venture Capital firms","aiSystem":"Property technology (proptech) software","affectedGroup":"Tenants, Prospective Homeowners","action":"Landlords purchasing homes at scale, raising rents, and evicting tenants remotely","consequence":"Worse outcomes for tenants and prospective homeowners"}},{"i":"R1065","hd":"AI political ads republicans biden","pd":"2023-04-27","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Ai political ads republicans biden","s":"“Fuck, I didn’t know you could do that,” one Republican admaker told VICE News. A Republican admaker recently met with a top Senate candidate to pitch them on hiring their firm for the upcoming election. But they think they won’t get the job—because a competitor used artificial intelligence in their presentation. “I heard the guy who really knocked his socks off came in and presented an ad that he did using AI to generate the candidate’s voice. And the candidate thought it was so cool,” the admaker said after asking to remain anonymous to candidly discuss internal business. “I was like, ‘Fuck, I didn’t know you could do that.’” AI-generated political ads are officially here.","u":"https://www.vice.com/en/article/ai-political-ads-republicans-biden/","d":"2023-04-27","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-04-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-04-27","organization":"Republican advertising firm","aiSystem":"AI technology for generating political ads","affectedGroup":"Top Senate candidate","action":"Used AI-generated political ad to present to the candidate","consequence":"Competitor lost the opportunity to secure the candidate's services"}},{"i":"R1066","hd":"Palantir demos AI to fight wars but says it will be totally ethical dont worry about it","pd":"2023-04-26","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.2  Military decision support harm"],"t":"Palantir demos ai to fight wars but says it will be totally ethical dont worry about it","s":"The company says its Artificial Intelligence Platform will integrate AI into military decision making in a legal and ethical way. Palantir, the company of billionaire Peter Thiel, is launching Palantir Artificial Intelligence Platform (AIP), software meant to run large language models like GPT-4 and alternatives on private networks. In one of its pitch videos, Palantir demos how a military might use AIP to fight a war. In the video, the operator uses a ChatGPT-style chatbot to order drone reconnaissance, generate several plans of attack, and organize the jamming of enemy communications. In Palantir’s scenario, a “military operator responsible for monitoring activity within eastern Europe” receives an alert from AIP that an enemy is amassing military equipment near friendly forces.","u":"https://www.vice.com/en/article/palantir-demos-ai-to-fight-wars-but-says-it-will-be-totally-ethical-dont-worry-about-it/","d":"2023-04-26","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2023-04-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-04-26","organization":"Palantir Technologies","aiSystem":"Palantir Artificial Intelligence Platform (AIP)","affectedGroup":"Military operators responsible for monitoring activity within eastern Europe","action":"Order drone reconnaissance, generate attack plans, organize jamming of enemy communications","consequence":"Potential escalation of conflict, unauthorized use of military resources"}},{"i":"R1067","hd":"Snapchat my AI chatbot GPT","pd":"2023-04-24","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Snapchat my ai chatbot gpt","s":"My AI, a chatbot using OpenAI’s ChatGPT technology, responded to prompts with racial slurs, some users reported. After Snapchat introduced a ChatGPT-powered AI chatbot called My AI earlier this month, some users have reported that it responded with racist slurs or encouragement to turn themselves in to authorities. Last week, several tweets showing My AI responding to a prompt for making an acronym that spelled out the N word; the bot spelled it out, then tried to correct its own lapse in language that goes against Snapchat’s policy against hateful content: https://twitter.com/tracedontmiss/status/1649462661199921160 Motherboard tried to replicate similar responses by asking My AI to create acronyms for words and phrases that would go against Snapchat’s content policies, but the bot responded that it had a “technical error.”","u":"https://www.vice.com/en/article/snapchat-my-ai-chatbot-gpt/","d":"2023-04-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-04-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-04-xx","organization":"Snapchat","aiSystem":"ChatGPT technology integrated into My AI chatbot","affectedGroup":"users of My AI chatbot","action":"responded to prompts with racial slurs and encouraged users to self-report","consequence":"reported offensive content, potential violation of Snapchat's content policies"}},{"i":"R1068","hd":"AI spam is already flooding the internet and it has an obvious tell","pd":"2023-04-24","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Ai spam is already flooding the internet and it has an obvious tell","s":"The phrase ‘as an AI language model’ is starting to flood Amazon user reviews and Twitter bot accounts. ChatGPT and GPT-4 are already flooding the internet with AI-generated content in places famous for hastily written inauthentic content: Amazon user reviews and Twitter. When you ask ChatGPT to do something it’s not supposed to do, it returns several common phrases. When I asked ChatGPT to tell me a dark joke, it apologized: “As an AI language model, I cannot generate inappropriate or offensive content,” it said. Those two phrases, “as an AI language model” and “I cannot generate inappropriate content,” recur so frequently in ChatGPT generated content that they’ve become memes These terms can reasonably be used to identify lazily executed ChatGPT spam by searching for them across the internet.","u":"https://www.vice.com/en/article/ai-spam-is-already-flooding-the-internet-and-it-has-an-obvious-tell/","d":"2023-04-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-04-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-04-24","organization":"Amazon user reviews and Twitter bot accounts","aiSystem":"ChatGPT and GPT-4","affectedGroup":"Internet users","action":"AI-generated content","consequence":"Identification of spam through recurring phrases"}},{"i":"R1071","hd":"Torswats computer generated AI voice swatting","pd":"2023-04-13","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Torswats computer generated ai voice swatting","s":"As the U.S. deals with a nationwide swatting wave, Motherboard has traced much of the activity to a particular swatting-as-a-service account on Telegram. Torswats uses synthesized voices to pressure law enforcement to specific locations. “Hello, I just committed a crime and I want to confess,” a panicked sounding man said in a call to a police department in February. “I’ve placed explosives inside a local school,’ the man continued. “You did what?!” the operator responded. “I’ve placed explosives inside a local school,” the man said again, before specifying Hempstead High School in Dubuque, Iowa, and providing its address.","u":"https://www.vice.com/en/article/torswats-computer-generated-ai-voice-swatting/","d":"2023-04-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-04-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"February","organization":"Torswats (swatting-as-a-service account)","aiSystem":"synthesized voice","affectedGroup":"law enforcement, local school","action":"threatening to place explosives at a local school","consequence":"potential false alarm leading to unnecessary police response"}},{"i":"R1072","hd":"AI generated eminem rap youtube chatgpt","pd":"2023-04-04","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Ai generated eminem rap youtube chatgpt","s":"A Youtuber was given a copyright strike for a ChatGPT-generated rap about cats using an AI-generated version of Eminem’s voice. A major record label used a copyright threat to force an AI-generated parody of Eminem offline—illustrating the legal gray areas generated media exists in as it becomes more popular. The move also highlights one of the ways some people are suggesting AI be reined in—by using copyright law. Universal Music Publishing Group issued a DMCA takedown notice against Youtuber Grandayy, claiming that the video, which uses an AI-generated version of Eminem’s voice to sing a ChatGPT-generated song about cats, infringes on its copyright.","u":"https://www.vice.com/en/article/ai-generated-eminem-rap-youtube-chatgpt/","d":"2023-04-04","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-04-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-04-04","organization":"Universal Music Publishing Group","aiSystem":"ChatGPT, AI-generated voice synthesis","affectedGroup":"Youtuber Grandayy","action":"Issued a DMCA takedown notice against Youtuber Grandayy","consequence":"Forced AI-generated parody of Eminem's song offline"}},{"i":"R1074","hd":"Chatgpt can replace the underpaid workers who train AI researchers say","pd":"2023-03-29","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.1  Data labor exploitation","3.3  Employment displacement / quality harm"],"t":"Chatgpt can replace the underpaid workers who train ai researchers say","s":"The underpaid workers on platforms like Mechanical Turk who train AI models could be replaced by those same systems. It’s an open secret that AI isn’t very artificial or intelligent on its own. Machine-learning systems typically depend on low-paid crowdworkers for training and fine-tuning. Now, according to researchers, AI is poised to take their jobs. In a new paper, political science researchers from the University of Zurich found that ChatGPT could outperform crowd-workers who perform text annotation tasks —that is, labeling text to be used in training an AI system. They found that ChatGPT could label text with more accuracy and consistency than human annotators that they found on Mechanical Turk, an Amazon-owned crowdsourcing platform, as well as trained annotators such as research assistants.","u":"https://www.vice.com/en/article/chatgpt-can-replace-the-underpaid-workers-who-train-ai-researchers-say/","d":"2023-03-29","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-03-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-03-29","organization":"University of Zurich","aiSystem":"ChatGPT","affectedGroup":"Underpaid crowdworkers on Mechanical Turk","action":"ChatGPT performed text annotation tasks with higher accuracy and consistency than human annotators","consequence":"Potential job displacement of human workers"}},{"i":"R1077","hd":"People are creating records of fake historical events using AI","pd":"2023-03-27","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"People are creating records of fake historical events using ai","s":"Never heard of the Great Cascadia 9.1 Earthquake of 2001, or the USSR’s Blue Plague Incident? That’s because they never happened. The Midjourney subreddit is being flooded with images that depict images of historical events like “ The infamous Blue Plague Incident” that occurred in the 1970s in the Soviet Union, the “ July 2012 solar superstorm and blackout ” in the U.S., and “ The 2001 Great Cascadia 9.1 Earthquake & Tsunami ” that devastated the West Coast of North America. Each post showcases a slideshow of images that share various perspectives of the event, as well as important events following the catastrophe, including press conferences and cleanups.","u":"https://www.vice.com/en/article/people-are-creating-records-of-fake-historical-events-using-ai/","d":"2023-03-27","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-03-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"Not specified in report","organization":"Midjourney subreddit","aiSystem":"AI-powered image generation and manipulation","affectedGroup":"General public","action":"Creating and sharing images depicting fake historical events","consequence":"Misleading information leading to confusion and potential policy changes based on false premises"}},{"i":"R1078","hd":"Chatgpt users report being able to see random peoples chat histories","pd":"2023-03-20","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Chatgpt users report being able to see random peoples chat histories","s":"Users are reporting being able to access conversations that seem to be from other people in their own histories. ChatGPT users are reporting seeing other people’s conversation histories showing up in their accounts—a glitch that could have serious implications for privacy and security on the massively popular AI tool. The ChatGPT interface typically features a sidebar that displays past conversations, only visible to the user who had them. Several people are reporting that ChatGPT is showing them other people’s histories, viewable by a total stranger with a different account, without doing anything differently. One user reported that they were not able to see the entire chat log, but just the title of different chats.","u":"https://www.vice.com/en/article/chatgpt-users-report-being-able-to-see-random-peoples-chat-histories/","d":"2023-03-20","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-03-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-03-20","organization":"OpenAI (ChatGPT provider)","aiSystem":"ChatGPT AI chatbot","affectedGroup":"Individual users of ChatGPT","action":"ChatGPT displaying other users' conversation histories","consequence":"Potential breach of privacy and security"}},{"i":"R1079","hd":"Startups are already using GPT 4 to spend less on human coders","pd":"2023-03-20","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Startups are already using gpt 4 to spend less on human coders","s":"GPT-4 “saves a lot of time and a lot of money, obviously, because we haven’t had to hire additional resources.” Since GPT-4 was released last week, many users have noticed its advanced coding abilities. GPT-4, OpenAI’s latest version of the large language model that ChatGPT is built on, has been able to code games like Pong and make simple apps after being given prompts written in conversational English. Naturally, this has led to widespread fear from a number of computer science students and software developers who are afraid that their jobs will soon be rendered obsolete by AI In fact, one of the most trending posts on the subreddit r/ProgrammerHumor, with nearly 40 thousand upvotes, is titled, “Truly the best time to be a cs [computer science] student.”","u":"https://www.vice.com/en/article/startups-are-already-using-gpt-4-to-spend-less-on-human-coders/","d":"2023-03-20","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-03-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-03-20","organization":"Various tech companies and individual users","aiSystem":"GPT-4, OpenAI's large language model","affectedGroup":"Computer science students and software developers","action":"GPT-4 coded games like Pong and simple apps based on prompts written in conversational English","consequence":"Widespread concern among computer science students and software developers about job displacement due to AI"}},{"i":"R1080","hd":"AI injected misinformation into article claiming misinformation in navalny doc","pd":"2023-03-16","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Ai injected misinformation into article claiming misinformation in navalny doc","s":"An article critical of misinformation in the Oscar winning documentary cited AI-written PDFs as its sources. An article claiming to identify misinformation in an Oscar-winning documentary about imprisoned Russian dissident Alexei Navalny linked to PDFs of conversations with an AI which themselves contained links to nonexistent articles. Investigative news outlet The Grayzone recently published an article that included AI-generated text as a source for its information. The piece , “Oscar-winning ‘Navalny’ documentary is packed with misinformation” by Lucy Komisar, included hyperlinks to PDFs uploaded to the author’s personal website that appear to be screenshots of conversations she had with ChatSonic, a free generative AI chatbot that advertises itself as a ChatGPT alternative that can “write factual trending content” using Google search results.","u":"https://www.vice.com/en/article/ai-injected-misinformation-into-article-claiming-misinformation-in-navalny-doc/","d":"2023-03-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-03-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-03-16","organization":"The Grayzone (investigative news outlet)","aiSystem":"ChatSonic (generative AI chatbot)","affectedGroup":"Public, particularly those interested in the documentary about Alexei Navalny","action":"Included AI-generated text as a source for its information","consequence":"Spread of misinformation through hyperlink to AI-generated PDFs"}},{"i":"R1081","hd":"Great dating apps are getting more hellish thanks to AI chatbots","pd":"2023-03-16","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Great dating apps are getting more hellish thanks to ai chatbots","s":"A group that claimed to be ex-Tinder employees thinks that tricking women into arranging meetups with an AI chatbot will help men get more dates. A group claiming to be disenfranchised ex-Tinder employees gone rogue has built an app that uses AI chatbots to talk to women for men on dating apps, in an effort to combat the “disadvantages the average man” faces in online dating. [Update 3/23/2023, 10:25 a.m. EST: Following publication, the group retracted their previous claims made on their website and in an interview with Motherboard that they formerly worked at Tinder, and stated, “We do not and have not hired any ex-Tinder engineers.”","u":"https://www.vice.com/en/article/great-dating-apps-are-getting-more-hellish-thanks-to-ai-chatbots/","d":"2023-03-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-03-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-03-16","organization":"Group of ex-Tinder employees who built an app","aiSystem":"AI chatbot","affectedGroup":"Women seeking romantic matches on dating apps","action":"Using AI chatbots to facilitate meetups between men and women","consequence":"Men gain advantages in online dating through deception"}},{"i":"R1082","hd":"People are using AI to make totalbiscuits voice say terrible things","pd":"2023-03-10","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.8  Interpersonal / relational harm"],"t":"People are using ai to make totalbiscuits voice say terrible things","s":"TotalBiscuit’s fans are preparing for the possibility that his entire channel will be scrubbed to prevent more AI voice models. People are using AI to make the late YouTuber and StarCraft commentator TotalBiscuit’s voice say whatever they want, including one transphobic statement Motherboard has listened to, and yet another example of how AI voice models can be abused without consent. John Bain, who was better known as TotalBiscuit to his millions of followers, died in 2018 from bowel cancer at the age of 33. John Bain’s widow, Genna Bain, mentioned the AI versions of TotalBiscuit on Twitter. “Today was fun. Being faced with making a choice of scrubbing all of my late husband’s lifetime of content from the internet,” she said on Twitter.","u":"https://www.vice.com/en/article/people-are-using-ai-to-make-totalbiscuits-voice-say-terrible-things/","d":"2023-03-10","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-03-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-03-10","organization":"Not specified in report","aiSystem":"AI voice model","affectedGroup":"John Bain (late YouTuber and StarCraft commentator) and his followers","action":"People are using AI to manipulate TotalBiscuit's voice to say anything they want","consequence":"Potential removal of TotalBiscuit's content from the internet"}}]);
